    // ---------- ⑩ 자동 백업 내려받기 ----------
    // ==========================================================
    //  단어 빈도 분석 — 중요어 히트맵 (Task 31)
    //  자주 나온 낱말일수록 진한 파랑으로 물들여, 문서의 핵심어를
    //  한눈에 알아볼 수 있게 한다. (화면 표시 전용 · 원문 변경 없음)
    // ==========================================================
    // 화면 색칠용 <span class="wf"> 를 걷어내 원래 글자로 되돌린다.
    // (저장 경로에서 항상 통과시켜 색이 문서에 스며들지 않게 한다)
    function stripWF(html){
        if(!html||html.indexOf('class="wf')<0&&html.indexOf("class='wf")<0) return html;
        const d=document.createElement('div');
        d.innerHTML=html;
        d.querySelectorAll('span.wf').forEach(s=>{
            s.replaceWith(document.createTextNode(s.textContent));
        });
        d.normalize();
        return d.innerHTML;
    }

    // 조사·접속사 등 뜻이 옅은 말은 세지 않는다
    const WF_STOP=new Set([
        '그리고','그러나','하지만','그래서','또한','또는','및','등','수','것','때','더','좀','매우',
        '하다','한다','했다','합니다','입니다','이다','있다','없다','되다','된다','같다','통해','대한',
        '위해','대해','에서','에게','으로','까지','부터','보다','처럼','이런','저런','그런','어떤',
        '우리','저희','당신','자신','여기','거기','저기','오늘','내일','어제','정말','아주','너무',
        '이것','그것','저것','이때','그때','경우','가지','통한','따라','따른','관련','기타','이상','이하',
        '때문','대하','위하','그림','다음','이번','지금','모두','각각','서로','다시','먼저','또','즉',
        'the','and','for','are','but','not','you','all','any','can','has','had','was','were',
        'this','that','with','from','have','will','your','they','their','then','than','into',
        'been','when','what','which','also','more','some','such','only','over','very','just'
    ]);

    // 한글은 조사를 떼어 어간을 얻는다 (형태소 분석기 없이 쓰는 간단한 방법)
    // ※ 긴 것부터 검사해야 '으로서'가 '로'로 잘못 잘리지 않는다.
    const WF_JOSA=['으로서','으로써','에서는','에게서','이라고','라고는','까지도','부터는',
                   '에서도','에게는','으로는','이라는','에게도','으로도','만으로','라는',
                   '에서','에게','께서','으로','로서','로써','이라','까지','부터','마다',
                   '조차','밖에','처럼','보다','하고','이나','거나','와의','과의','에는','에도',
                   '의','를','을','이','가','은','는','에','도','만','로','과','와','랑'];
    // 용언 어미 (검토하였습니다 → 검토). 긴 것부터.
    const WF_VERB=['하였습니다','되었습니다','하겠습니다','되겠습니다','했습니다','합니다','됩니다',
                   '하였다','되었다','하였고','하였으며','시켰다','시키는','하려는','하려고','하면서',
                   '하기로','했지만','하지만','했었다','되어야','해야만',
                   '했다','한다','하고','하는','하며','하면','해서','해야','했던','하러','하자','하지',
                   '되는','되어','된다','됐다','되고','되며','있다','있는','없다','없는'];
    // 그 자체가 통째로 기능어인 말 (조사·어미를 떼면 껍데기만 남는 것)
    const WF_FUNC=new Set(['것이다','것이','것은','것을','수가','수는','수를','있다','없다',
        '되었습니다','하였습니다','합니다','됩니다','했습니다','이었다','이라','에서','으로']);
    function wfStem(w){
        if(!/[가-힣]/.test(w)) return wfStemEn(w);
        if(WF_FUNC.has(w)) return '';        // 통째로 버린다
        let prev=w;
        // 어미 → 조사 순으로 각 1회 (분석하였다 → 분석)
        for(let pass=0;pass<2;pass++){
            for(const v of WF_VERB){
                if(prev.length>v.length+1 && prev.endsWith(v)){ prev=prev.slice(0,-v.length); break; }
            }
            for(const j of WF_JOSA){
                if(prev.length>j.length+1 && prev.endsWith(j)){ prev=prev.slice(0,-j.length); break; }
            }
        }
        // 복수 접미사 '들' (학생들 → 학생)
        if(prev.length>2 && prev.endsWith('들')) prev=prev.slice(0,-1);
        return prev;
    }
    // 영문은 단·복수와 흔한 어미를 합쳐 같은 말로 센다 (Systems = system)
    function wfStemEn(w){
        const s=w.toLowerCase();
        if(s.length<4) return s;
        if(/[^aeiou]ies$/.test(s)) return s.slice(0,-3)+'y';   // studies → study
        if(/(s|x|z|ch|sh)es$/.test(s)) return s.slice(0,-2);   // analyses → analys
        if(/[^s]s$/.test(s)) return s.slice(0,-1);             // systems → system
        return s;
    }
    // 뜻이 옅어 세어도 의미 없는 말 (조사를 뗀 뒤에도 남는 것들)
    const WF_THIN=new Set(['것','수','때','곳','점','바','줄','things','thing','way','ways']);
    function wfValid(w){
        if(!w) return false;
        const s=w.toLowerCase();
        if(WF_STOP.has(s)||WF_THIN.has(s)) return false;
        if(/^[0-9]+$/.test(s)) return false;             // 숫자만
        if(/^[0-9]+[a-z가-힣]?$/.test(s)) return false;   // 1, 2쪽 같은 것
        if(/[가-힣]/.test(w)) return w.length>=2;         // 한글은 2글자 이상
        return /[a-z]/i.test(w) && w.length>=3;           // 영문은 3글자 이상
    }
    // 글자에서 낱말을 뽑는다 → [{raw, key, start}]
    function wfTokens(text){
        const out=[];
        const re=/[0-9A-Za-z가-힣]+/g;
        let m;
        while((m=re.exec(text))){
            const raw=m[0];
            const key=wfStem(raw).toLowerCase();
            if(wfValid(wfStem(raw))) out.push({raw,key,start:m.index,len:raw.length});
        }
        return out;
    }

    // 문서 전체를 훑어 낱말별 등장 횟수를 센다
    function wfAnalyze(){
        const count=new Map(), label=new Map();
        doc.pages.forEach(pg=>{
            (pg.els||[]).forEach(el=>{
                if(el.type!=='text') return;
                wfTokens(elPlainText(el)).forEach(t=>{
                    count.set(t.key,(count.get(t.key)||0)+1);
                    // 보여 줄 이름은 조사를 뗀 기본형 (보고서를 → 보고서)
                    if(!label.has(t.key)) label.set(t.key,wfStem(t.raw));
                });
            });
        });
        wfStats=[...count.entries()]
            .map(([k,n])=>({key:k,word:label.get(k),n}))
            .sort((a,b)=>b.n-a.n||a.word.localeCompare(b.word));
        wfMap=new Map(wfStats.map(s=>[s.key,s.n]));
        wfBuildLevels();
        return wfStats;
    }
    // 횟수 → 파랑 농도 (적으면 연하게, 많으면 진하게)
    // 등장 횟수 → 0~1 단계값.
    // 횟수만 쓰면 '5번'과 '4번'이 거의 같은 색이 되어 구분이 안 된다.
    // → 실제 존재하는 '횟수의 종류'를 줄 세워 단계를 고르게 벌린다.
    let wfLevels=[];              // [2,3,4,6,9] 처럼 오름차순
    function wfBuildLevels(){
        wfLevels=[...new Set(wfStats.filter(s=>s.n>=wfMin).map(s=>s.n))].sort((a,b)=>a-b);
    }
    function wfTone(n){
        if(!wfLevels.length) return 1;
        // 단계가 하나뿐이면 가장 진하게
        if(wfLevels.length===1) return 1;
        const i=wfLevels.indexOf(n);
        const rank=i<0?wfLevels.length-1:i;
        // 순위를 0~1 로 고르게 편다 (최저=연한 하늘, 최고=짙은 남색)
        let t=rank/(wfLevels.length-1);
        // 단계가 많으면 아래쪽이 몰려 보이므로 살짝 밀어 올려 대비를 키운다
        if(wfLevels.length>4) t=Math.pow(t,0.78);
        return t;
    }
    // 0~1 → 파랑 그라데이션.
    //  · 가장 적게 나온 말  = 아주 연한 하늘색
    //  · 가장 많이 나온 말  = 짙은 남색
    // 사이 단계도 확실히 구분되도록 밝기를 큰 폭으로 벌린다.
    // (완전한 검정까지는 가지 않아 본문 검은 글자와 구분된다)
    const WF_RAMP=[
        [0.00,[168,214,255]],   // 아주 연한 하늘
        [0.20,[109,178,250]],   // 하늘
        [0.40,[56,130,246]],    // 파랑
        [0.60,[29,86,214]],     // 진한 파랑
        [0.80,[18,48,140]],     // 감청
        [1.00,[10,22,72]]       // 짙은 남색
    ];
    function wfColor(n,max){
        const t=wfTone(n);
        let a=WF_RAMP[0], b=WF_RAMP[WF_RAMP.length-1];
        for(let i=0;i<WF_RAMP.length-1;i++){
            if(t>=WF_RAMP[i][0]&&t<=WF_RAMP[i+1][0]){ a=WF_RAMP[i]; b=WF_RAMP[i+1]; break; }
        }
        const k=(t-a[0])/Math.max(.0001,(b[0]-a[0]));
        const rgb=[0,1,2].map(i=>Math.round(a[1][i]+(b[1][i]-a[1][i])*k));
        // 굵기도 함께 5단계로 → 색과 겹쳐 차이가 더 또렷해진다
        const w = t>=.85?900 : t>=.65?800 : t>=.45?700 : t>=.22?600 : 500;
        return {c:`rgb(${rgb.join(',')})`, w, t};
    }

    function toggleWordFreq(){ wfOn?wfOff():wfRun(); }
    function wfRun(){
        if(!doc){ return; }
        commitEditingText(); deselectAll(true); clearMulti();
        wfAnalyze();
        const rep=wfStats.filter(s=>s.n>=wfMin);
        if(!wfStats.length){ toast('분석할 글자가 없습니다',2000); return; }
        wfOn=true; wfPick=null;
        document.getElementById('editorView').classList.add('wf-on');
        document.querySelectorAll('.js-wf').forEach(b=>b.classList.add('active'));
        wfPaint();
        document.getElementById('wfBar').classList.add('show');
        // 심플하게: 가장 많이 나온 말 하나만
        document.getElementById('wfInfo').innerHTML=
            `<b>${esc(wfStats[0].word)}</b> ${wfStats[0].n}번 · 낱말 ${rep.length}개`;
        if(sidePanel!=='words') openPanel('words'); else renderPanel();
    }
    function wfOff(){
        wfOn=false; wfPick=null;
        document.getElementById('editorView').classList.remove('wf-on');
        document.querySelectorAll('.js-wf').forEach(b=>b.classList.remove('active'));
        document.getElementById('wfBar').classList.remove('show');
        wfClear();
        if(sidePanel==='words') renderPanel();
    }
    // 색칠 제거 → 원래 글자 그대로 다시 그린다
    function wfClear(){
        if(!doc) return;
        // 가상화된 빈 종이까지 전부 다시 그리지 않고 현재 DOM에 있는 쪽만 복원한다.
        Array.from(renderedPages).forEach(i=>renderPageEls(i));
        maintainPageWindow(curPageIdx,true);
    }
    // 화면의 글자에만 색을 입힌다 (문서 데이터는 절대 건드리지 않음)
    function wfPaintPage(pi){
        if(!doc||!wfMap||!wfOn) return;
        const pg=doc.pages[pi]; if(!pg) return;
        const paper=paperAt(pi); if(!paper) return;
        const max=wfStats.length?wfStats[0].n:1;
        (pg.els||[]).forEach(el=>{
            if(el.type!=='text') return;
            const node=paper.querySelector(`.tb[data-id="${el.id}"] .tb-content`);
            if(!node) return;
            wfPaintNode(node,max);
        });
    }
    function wfPaint(){
        if(!doc||!wfMap) return;
        // 500쪽을 전부 훑지 않는다 — 지금 화면에 올라와 있는 쪽만 칠하고,
        // 나머지는 그 쪽이 다시 그려질 때(renderPageEls) 자동으로 칠해진다.
        Array.from(mountedShells.keys()).forEach(pi=>wfPaintPage(pi));
    }
    function wfPaintNode(root,max){
        const texts=[];
        const walk=(n)=>{
            for(const ch of Array.from(n.childNodes)){
                if(ch.nodeType===3){ if(ch.nodeValue.trim()) texts.push(ch); }
                else if(ch.nodeType===1 && !ch.classList.contains('wf')) walk(ch);
            }
        };
        walk(root);
        texts.forEach(tn=>{
            const text=tn.nodeValue;
            const toks=wfTokens(text).filter(t=>(wfMap.get(t.key)||0)>=wfMin);
            if(!toks.length) return;
            const frag=document.createDocumentFragment();
            let at=0;
            toks.forEach(t=>{
                if(t.start>at) frag.appendChild(document.createTextNode(text.slice(at,t.start)));
                const n=wfMap.get(t.key)||0;
                const col=wfColor(n,max);
                const s=document.createElement('span');
                s.className='wf'+(col.t>=.75?' top':col.t>=.45?' hot':'')
                            +(wfPick===t.key?' pick':'');
                s.dataset.k=t.key;
                s.style.color=col.c;
                s.style.fontWeight=col.w;
                s.title=`'${wfStats.find(x=>x.key===t.key)?.word||t.raw}' · ${n}번 나옴`;
                s.textContent=text.substr(t.start,t.len);
                frag.appendChild(s);
                at=t.start+t.len;
            });
            if(at<text.length) frag.appendChild(document.createTextNode(text.slice(at)));
            tn.parentNode.replaceChild(frag,tn);
        });
    }
    // 특정 낱말만 노랗게 집어내기
    function wfPickWord(key){
        if(!wfOn) wfRun();
        wfPick=(wfPick===key)?null:key;
        document.querySelectorAll('.wf').forEach(s=>
            s.classList.toggle('pick', !!wfPick && s.dataset.k===wfPick));
        if(sidePanel==='words') renderPanel();
        if(wfPick){
            const first=document.querySelector(`.wf.pick`);
            if(first){
                const wrap=first.closest('.page-wrap');
                const pi=wrap?+wrap.dataset.pageIdx:curPageIdx;
                goToPage(pi+1);
            }
            const s=wfStats.find(x=>x.key===wfPick);
            if(s) toast(`'${s.word}' · 문서에서 ${s.n}번 나왔습니다`,2400);
        }
    }
    // 최소 등장 횟수 조절
    function wfSetMin(v){
        wfMin=Math.max(1,Math.min(9,v));
        wfBuildLevels();
        if(wfOn){ wfClear(); wfPaint(); renderPanel(); }
        const lb=document.getElementById('wfMinLbl');
        if(lb) lb.textContent=wfMin+'번';
    }
    // ---------- 패널 ----------
    function panelWords(){
        if(!doc) return '';
        if(!wfStats.length) wfAnalyze();
        const list=wfStats.filter(s=>s.n>=wfMin);
        const max=wfStats.length?wfStats[0].n:1;
        let html=`<div class="wf-top">
                    <button class="wf-toggle${wfOn?' on':''}" onclick="toggleWordFreq()">
                      <i class="ri-${wfOn?'eye-off-line':'contrast-2-line'}"></i>${wfOn?'색칠 끄기':'색칠하기'}</button>
                    <span class="wf-min">
                      <button class="sp-mini" onclick="wfSetMin(wfMin-1)">−</button>
                      <b>${wfMin}</b>번↑
                      <button class="sp-mini" onclick="wfSetMin(wfMin+1)">＋</button>
                    </span>
                  </div>`;
        if(!list.length)
            return html+'<div class="sp-empty">여러 번 나온 낱말이 없습니다</div>';
        list.slice(0,60).forEach((s,i)=>{
            const col=wfColor(s.n,max);
            html+=`<div class="wf-item${wfPick===s.key?' on':''}" onclick="wfPickWord('${s.key}')">
                     <span class="bar" style="width:${Math.max(6,(s.n/max)*100)}%"></span>
                     <span class="wf-rank">${i+1}</span>
                     <span class="w" style="color:${col.c};font-weight:${col.w}">${esc(s.word)}</span>
                     <span class="c">${s.n}</span>
                   </div>`;
        });
        if(list.length>60) html+=`<div class="sp-item sp-dim">… 외 ${list.length-60}개</div>`;
        return html;
    }

    function openTableModal(){
        const v=prompt('표 크기를 입력하세요 (행 x 열)','3 x 3');
        if(!v) return;
        const m=String(v).match(/(\d+)\s*[x\u00d7,\s]\s*(\d+)/);
        if(!m){ toast('예: 3 x 4 형식으로 입력해 주세요',2200); return; }
        beginTablePlacement(+m[1],+m[2]);
    }
    function beginTablePlacement(rows,cols){
        const dim=tableInsertSize(rows,cols),g=document.getElementById('tableGhost');
        setTextTool(false);
        if(penActive) finishDrawing();
        cancelPlaceMode();
        tablePlace=dim;
        if(!g) return;
        g.style.setProperty('--tbl-rows',dim.rows);
        g.style.setProperty('--tbl-cols',dim.cols);
        g.style.display='block';
        const lb=document.getElementById('tableGhostLabel');
        if(lb) lb.textContent=dim.rows+' × '+dim.cols+' 표';
        document.body.classList.add('placing-table');
        const p=paperAt(curPageIdx),r=p&&p.getBoundingClientRect();
        moveTableGhost(r?r.left+r.width/2:innerWidth/2,
                       r?r.top+Math.min(r.height*.25,200):innerHeight/2);
        toast('종이에서 원하는 위치를 눌러 표를 배치하세요',2200);
    }
    function moveTableGhost(clientX,clientY){
        const g=document.getElementById('tableGhost'); if(!g||!tablePlace) return;
        // 포인터 아래 종이의 실제 화면 배율을 사용한다. 브라우저 90% zoom이나
        // 사용자 확대 상태에서도 클릭 후 만들어지는 표와 픽셀 단위로 일치한다.
        // ★ r.left/k 와 sc.x 의 /k 는 viewport px → CSS px 변환에 필수.
        //   자세한 원리는 moveTextGhost 주석 참조.
        const hit=typeof document.elementFromPoint==='function'
            ?document.elementFromPoint(clientX,clientY):null;
        const paper=(hit&&hit.closest&&hit.closest('.paper'))||paperAt(curPageIdx);
        if(!paper) return;
        const pi=+paper.dataset.pageIdx;
        const p=pageLocal({clientX,clientY},pi);
        const origin=clampTableOrigin(tablePlace,p.x-tablePlace.w/2,p.y-tablePlace.h/2);
        const r=paper.getBoundingClientRect(),sc=uiPageScale(pi),k=uiCssZoom();
        g.style.width=Math.round(tablePlace.w*sc.x)+'px';
        g.style.height=Math.round(tablePlace.h*sc.y)+'px';
        // 종이 원점(화면 px)도 고스트가 쓰는 CSS px 로 바꾼 뒤 문서 좌표를 더한다.
        g.style.left=Math.round(r.left/k+origin.x*sc.x)+'px';
        g.style.top=Math.round(r.top/k+origin.y*sc.y)+'px';
        g.dataset.pageIdx=String(pi);
    }
    // 텍스트 상자 고스트 — '눌렀을 때 실제로 생길 자리'를 그대로 미리 보인다.
    // 삽입 경로(pageLocal → clampEl → addTextBox)와 같은 계산을 쓰기 때문에
    // 배율이 몇 %이든, 커서가 종이 어디에 있든 고스트 = 만들어질 상자 다.
    // 예전엔 커서 clientX 를 곧장 style.left 에 넣고 화면 가장자리로 clamp 해서
    //  · 사이트 기본 배율(90%) 만큼 커서에서 어긋나고
    //  · 확대가 클수록 화면 끝에서 고스트만 안으로 밀려
    // 만들어진 상자와 고스트가 서로 다른 자리에 있었다.
    //
    // ★ 좌표 변환 원리 (moveTableGhost, movePlaceGhost 도 동일):
    //   r.left          = 종이 좌상단의 viewport px
    //   o.x             = 문서 px (pageLocal → clampEl 결과)
    //   sc.x            = 문서 px → CSS px 배율 = (r.width/s.w) / k
    //   r.left / k      = 종이 좌상단의 CSS px  ← ★ /k 필수!
    //   o.x * sc.x      = 문서 px → CSS px 변환
    //   합계             = 고스트의 style.left (CSS px)
    //
    //   /k 를 빼면 r.left 가 viewport px 채로 style.left 에 들어가서
    //   html{zoom:.9} 에서 고스트가 커서보다 ≈11% 오른쪽으로 밀린다.
    //   종이 안의 실제 요소는 종이 좌표를 쓰므로 /k 가 필요 없다 —
    //  둘 다 최종 화면 위치는 같다.
    function moveTextGhost(clientX,clientY){
        const g=document.getElementById('textGhost'); if(!g||!textToolActive) return;
        const hit=typeof document.elementFromPoint==='function'
            ?document.elementFromPoint(clientX,clientY):null;
        const over=hit&&hit.closest&&hit.closest('.paper');
        const paper=over||paperAt(curPageIdx);
        if(!paper) return;
        const pi=+paper.dataset.pageIdx, s=paperSize();
        // 종이 밖(도구막대 위 등)에서는 지금 쪽 위쪽 중앙에 '준비' 미리보기를 둔다.
        const p=over?pageLocal({clientX,clientY},pi):{x:s.w/2,y:Math.min(s.h*.22,180)};
        const dim=textBoxDefaultSize();
        const o=clampEl(p.x-dim.w/2,p.y-dim.h/2,dim.w,dim.h);
        const r=paper.getBoundingClientRect(),sc=uiPageScale(pi),k=uiCssZoom();
        g.style.width=Math.round(dim.w*sc.x)+'px';
        g.style.height=Math.round(dim.h*sc.y)+'px';
        const c=g.querySelector('.tg-caret');
        if(c) c.style.height=Math.round((curFontSize*1.4)*sc.y)+'px';
        g.style.left=Math.round(r.left/k+o.x*sc.x)+'px';
        g.style.top=Math.round(r.top/k+o.y*sc.y)+'px';
        g.dataset.pageIdx=String(pi);
    }
    function cancelTablePlacement(){
        tablePlace=null;
        const g=document.getElementById('tableGhost'); if(g) g.style.display='none';
        document.body.classList.remove('placing-table');
    }

    // ============ 요소 배치 모드 (그림·수식) ============
    // 예전엔 텍스트 상자·표만 '누른 자리 = 생기는 자리' 보정(pageLocal)이 돼 있었고
    //  · 그림은 도구막대에서 넣으면 늘 쪽 한가욵데에,
    //  · 수식은 마우스가 마지막으로 스쳐 지나간 자리(오래된 lastMouse)에 들어갔다.
    // 사이트 기본 배율(html zoom 90%) 아래서는 기준점과 결과의 단위가 엇갈려
    // '커서보다 한 뼘(≈1cm) 오른쪽에 생긴다'고 느껴지던 것의 실제 원인이다.
    // 그림·수식도 상자·표와 같은 방식으로 바꾼다: 커서를 따라다니는 고스트를
    // 문서 좌표로 그리고(moveTextGhost 와 같은 변환), 누른 그 지점에 똑같이 넣는다.
    let placeMode=null;   // {kind:'image',items:[{file,url,box}],idx,w,h}
                          // {kind:'latex',src,display,fontSize,w,h}
    function beginImgPlacement(items){
        if(!items||!items.length) return;
        cancelPlaceMode();
        if(penActive) finishDrawing();
        setTextTool(false); if(tablePlace) cancelTablePlacement();
        if(pinMode) togglePinMode();
        deselectAll();
        placeMode={kind:'image',items,idx:0,w:items[0].box.w,h:items[0].box.h};
        placeGhostShow();
        toast(items.length>1
            ? `종이를 눌러 그림을 차례로 배치하세요 (총 ${items.length}장)`
            : '종이에서 원하는 위치를 눌러 그림을 배치하세요',2200);
    }
    function beginLatexPlacement(src,display){
        cancelPlaceMode();
        if(penActive) finishDrawing();
        setTextTool(false); if(tablePlace) cancelTablePlacement();
        if(pinMode) togglePinMode();
        deselectAll();
        placeMode={kind:'latex',src,display,
            w:display?400:230, h:display?82:48, fontSize:display?22:18};
        placeGhostShow();
        toast('종이에서 원하는 위치를 눌러 수식을 배치하세요',2200);
    }
    function placeGhostShow(){
        const pm=placeMode, g=document.getElementById('placeGhost');
        if(!pm||!g) return;
        const body=document.getElementById('placeGhostBody');
        const ic=document.getElementById('placeGhostIcon'), lb=document.getElementById('placeGhostLabel');
        if(pm.kind==='image'){
            const it=pm.items[pm.idx];
            pm.w=it.box.w; pm.h=it.box.h;
            if(ic) ic.className='ri-image-add-line';
            if(lb) lb.textContent=pm.items.length>1?`그림 ${pm.idx+1}/${pm.items.length}`:'그림 넣기';
            body.innerHTML=`<div class="pg-scale" style="width:${it.box.w}px;height:${it.box.h}px;`+
                `background-image:url('${it.url}')"></div>`;
        }else{
            if(ic) ic.className='ri-function-line';
            if(lb) lb.textContent='수식 넣기';
            body.innerHTML=`<div class="pg-scale pg-latex" style="width:${pm.w}px;height:${pm.h}px;`+
                `font-size:${pm.fontSize}px;line-height:1.05">${latexHTML(pm.src,pm.display)}</div>`;
        }
        g.style.display='block';
        document.body.classList.add('placing-el');
        // 첫 위치: 현재 쪽 위쪽 중앙 (상자·표 고스트와 같은 규칙)
        const p=paperAt(curPageIdx), r=p&&p.getBoundingClientRect();
        movePlaceGhost(r?r.left+r.width/2:innerWidth/2,
                       r?r.top+Math.min(r.height*.22,200):innerHeight/3);
    }
    function movePlaceGhost(clientX,clientY){
        const g=document.getElementById('placeGhost'); if(!g||!placeMode) return;
        // moveTextGhost 와 같은 변환: 포인터 아래 종이의 실제 화면 사각형을 기준으로
        // 문서 좌표를 구하고, 고스트는 화면 UI CSS px 로 놓는다. 배율이 몇 %이든
        // 고스트 = 만들어질 요소 다.
        // ★ r.left/k 와 sc.x 의 /k 는 viewport px → CSS px 변환에 필수.
        //   자세한 원리는 moveTextGhost 주석 참조.
        const hit=typeof document.elementFromPoint==='function'
            ?document.elementFromPoint(clientX,clientY):null;
        const over=hit&&hit.closest&&hit.closest('.paper');
        const paper=over||paperAt(curPageIdx);
        if(!paper) return;
        const pi=+paper.dataset.pageIdx, s=paperSize();
        const p=over?pageLocal({clientX,clientY},pi):{x:s.w/2,y:Math.min(s.h*.22,180)};
        const o=clampEl(p.x-placeMode.w/2,p.y-placeMode.h/2,placeMode.w,placeMode.h);
        const r=paper.getBoundingClientRect(),sc=uiPageScale(pi),k=uiCssZoom();
        g.style.width=Math.round(placeMode.w*sc.x)+'px';
        g.style.height=Math.round(placeMode.h*sc.y)+'px';
        g.style.left=Math.round(r.left/k+o.x*sc.x)+'px';
        g.style.top=Math.round(r.top/k+o.y*sc.y)+'px';
        g.dataset.pageIdx=String(pi);
        const inner=g.querySelector('.pg-scale');
        if(inner) inner.style.transform=`scale(${sc.x})`;
    }
    // 배치 모드에서 종이를 눌렀다 — 미리보기와 똑같은 문서 좌표에 넣는다.
    // ★ x,y 는 pageLocal 로 구한 문서 px. /uiCssZoom() 하지 않는다.
    //   고스트(movePlaceGhost)는 position:fixed 이므로 /k 로 CSS px 변환하지만,
    //  둘 다 최종 화면 위치는 같다. (자세한 원리는 moveTextGhost 주석 참조)
    function commitPlaceAt(pi,x,y){
        const pm=placeMode; if(!pm) return;
        if(pm.kind==='image'){
            const it=pm.items[pm.idx];
            if(it) placeImgItem(it,pi,x,y);
            pm.idx++;
            commitImagesNow();
            if(pm.idx>=pm.items.length){ cancelPlaceMode(); toast('그림을 넣었습니다',1300); }
            else placeGhostShow();      // 다음 장 크기·미리보기로 교체
            return;
        }
        if(pm.kind==='latex'){
            pushHistory();
            const c=clampEl(x-pm.w/2,y-pm.h/2,pm.w,pm.h);
            doc.pages[pi].els.push({type:'latex',id:uid('m'),latex:pm.src,
                x:Math.round(c.x),y:Math.round(c.y),w:pm.w,h:pm.h,
                fontSize:pm.fontSize,displayMath:pm.display?1:0});
            if(renderedPages.has(pi)) renderPageEls(pi);
            saveDoc(); cancelPlaceMode(); toast('수식을 넣었습니다',1300);
            return;
        }
        cancelPlaceMode();
    }
    function cancelPlaceMode(){
        if(!placeMode) return;
        // v3 · 아직 배치하지 않은 그림은 이미 서버에 올라가 있다 — 주인이 없는
        //   업로드는 서버에서도 지운다 (고아 파일 방지).
        if(placeMode.kind==='image'&&placeMode.items){
            try{ discardImgItems(placeMode.items.slice(placeMode.idx)); }catch(e){}
        }
        placeMode=null;
        const g=document.getElementById('placeGhost');
        if(g){ g.style.display='none'; const b=document.getElementById('placeGhostBody'); if(b) b.innerHTML=''; }
        document.body.classList.remove('placing-el');
    }

    function toggleTextTool(){ setTextTool(!textToolActive); }
    function setTextTool(on){
        textToolActive=!!on;
        if(on&&tablePlace) cancelTablePlacement();
        if(on) cancelPlaceMode();
        if(on&&penActive) finishDrawing();
        const g=document.getElementById('textGhost');
        g.style.display=on?'block':'none';
        document.body.classList.toggle('placing-text',!!on);
        document.getElementById('textToolBtn').classList.toggle('active',on);
        if(on){
            // 마우스를 아직 움직이지 않아도 현재 종이 위쪽 중앙에 미리보기를 보인다.
            // (좌표는 화면 px → 아래 moveTextGhost 가 문서 좌표로 바꿔 똑같이 놓는다)
            const p=paperAt(curPageIdx), r=p&&p.getBoundingClientRect();
            moveTextGhost(r?r.left+r.width/2:(lastMouse.clientX||innerWidth/2),
                          r?r.top+Math.min(r.height*.22,180):(lastMouse.clientY||innerHeight/2));
        }
    }
    // 배율이 바뀌면 고스트를 '지금 커서 자리'에 크기와 위치 모두 다시 맞춘다.
    // 예전엔 pageScale 로 크기만 다시 쟀다 — 위치는 clientX 를 그대로 style.left 에
    // 넣어 둔 값이라 배율 전환 뒤에도 어긋난 채로 남아 있었다.
    function sizeTextGhost(){
        if(textToolActive) moveTextGhost(lastMouse.clientX||0,lastMouse.clientY||0);
        if(tablePlace) moveTableGhost(lastMouse.clientX||0,lastMouse.clientY||0);
        if(placeMode) movePlaceGhost(lastMouse.clientX||0,lastMouse.clientY||0);
    }
    const TB_W=200, TB_H=48;
    function textBoxDefaultSize(fontSize){
        const fs=Math.max(2,Math.min(200,Math.round(fontSize||curFontSize||16)));
        // 기본 글상자는 현재 툴바 글자 크기가 한 줄 들어갈 높이를 우선 보장한다.
        // 큰 글씨를 고른 뒤 만들면 48px 고정 상자가 아니라 그 글씨에 맞춰 시작한다.
        return {
            w:Math.max(TB_W,Math.round(Math.min(420,fs*8))),
            h:Math.max(TB_H,Math.round(fs*1.45+22))
        };
    }

    // ============ 뒤로가기(브라우저 히스토리) 처리 ============
    // 에디터·폴더·모달을 열 때 히스토리 항목을 쌓아, 뒤로가기를 누르면
    // 사이트를 빠져나가는 대신 열려 있던 화면/모달이 닫히게 한다.
    const _nav=[];
    function openNav(close){ _nav.push({close}); try{ history.pushState({sdy:_nav.length},''); }catch(e){} }
    function navDrop(close){ const i=_nav.findIndex(x=>x.close===close); if(i>=0) _nav.splice(i,1); }
    function navBack(){
        if(!_nav.length) return;
        try{ history.back(); }
        catch(e){ const it=_nav.pop(); if(it&&it.close){ try{ it.close(); }catch(err){} } }
    }
    window.addEventListener('popstate',(e)=>{
        const target=(e.state&&typeof e.state.sdy==='number')?e.state.sdy:0;
        while(_nav.length>target){
            const it=_nav.pop();
            if(it&&it.close){ try{ it.close(); }catch(err){} }
        }
    });
    // 열려 있는 것 중 가장 위를 닫는다 (Esc / 뒤로가기 공용). 닫았으면 true.
    function closeTopOverlay(){
        if(ctxMenuOpen()){ closeCtxMenu(); return true; }
        if(presentOn){ endPresent(); return true; }
        if(wfOn){ wfOff(); return true; }
        if(document.getElementById('pinPop').classList.contains('show')){ closePin(); return true; }
        if(document.getElementById('latexModal').style.display==='flex'){ closeLatexModal(); return true; }
        if(pinMode){ togglePinMode(); return true; }
        if(findOpen){ closeFind(); return true; }
        if(tablePlace){ cancelTablePlacement(); return true; }
        if(placeMode){ cancelPlaceMode(); return true; }
        if(activeTbl){ clearActiveTbl(); return true; }
        if(focusMode){ toggleFocus(); return true; }
        if(sidePanel){ closePanel(); return true; }
        if(document.getElementById('viewer').style.display==='flex'){document.getElementById('viewer').style.display='none';return true;}
        if(textToolActive){ setTextTool(false); return true; }
        if(penActive){ finishDrawing(); return true; }
        // 변환 중에는 닫지 않는다
        if(document.getElementById('importProg').style.display==='flex') return false;
        // 주요 모달·에디터는 히스토리와 함께 닫는다 (뒤로가기와 일관)
        if(document.getElementById('cpModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('exportModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('pwModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('createModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('vaultModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('folderStyleModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('keyModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('delModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('setModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('stickerModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('infoModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('trashModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('editorView').classList.contains('open')){ navBack(); return true; }
        if(curFolder){ openFolder(folderParent(curFolder), true); return true; }
        return false;
    }

    document.addEventListener('keydown',e=>{
        // 발표 모드 조작
        if(presentOn){
            if(e.key==='ArrowRight'||e.key===' '||e.key==='PageDown'){ e.preventDefault(); presentStep(1); return; }
            if(e.key==='ArrowLeft'||e.key==='PageUp'){ e.preventDefault(); presentStep(-1); return; }
            if(e.key==='Escape'){ e.preventDefault(); endPresent(); return; }
        }
        if(e.ctrlKey&&!e.shiftKey&&(e.key==='h'||e.key==='H')){
            if(document.getElementById('editorView').classList.contains('open')){
                e.preventDefault();
                if(!findOpen) openFind();
                const bar=document.getElementById('findBar');
                if(!bar.classList.contains('rep')) toggleReplace();
                else document.getElementById('repInput').focus();
                return;
            }
        }
        if(e.ctrlKey&&e.shiftKey&&(e.key==='c'||e.key==='C')){
            if(document.getElementById('editorView').classList.contains('open')){
                e.preventDefault(); countSelection(); return;
            }
        }
        if(e.ctrlKey&&!e.shiftKey&&(e.key==='f'||e.key==='F')){
            if(document.getElementById('editorView').classList.contains('open')){
                e.preventDefault(); openFind(); return;
            }
        }
        // ===== 스프레드시트식: 편집 중 Enter/Tab/Escape (커밋 + 셀 이동) =====
        {
            const ae=document.activeElement;
            const inContent=!!(ae&&ae.classList&&ae.classList.contains('tb-content'));
            // 18.9 · Escape 는 '글상자 편집 중'이면 언제나 편집만 끝낸다.
            //   예전엔 포커스가 정확히 .tb-content 에 있을 때만 그렇게 했고,
            //   툴바 글자 크기칸을 만졌다가 Escape 를 누르면 편집 중인데도
            //   아래의 closeTopOverlay() 가 걸려 **노트 자체가 닫혀** 버렸다.
            const w=inContent?ae.closest('.tb'):document.querySelector('.tb.edit');
            // 한글 IME 조합 중에는 Enter(확정)를 가로채면 입력이 깨진다 → 그대로 둠
            const composing=e.isComposing||e.keyCode===229;
            if(w){
                if(e.key==='Tab' && inContent && !composing){
                    e.preventDefault();
                    exitEditKeepSel(w);
                    moveCellFrom(w, e.shiftKey?'prev':'next');
                    return;
                }
                if(e.key==='Escape' && !composing){
                    e.preventDefault();
                    if(!inContent && ae && ae.blur) ae.blur();   // 툴바 입력칸에서 빠져나온다
                    exitEditKeepSel(w);
                    return;
                }
            }
        }
        if(e.key==='Escape'){
            if(closeTopOverlay()) return;
        }
        // 표 셀 범위: 방향키로 이동, Shift+방향키로 직사각형 확장.
        // Delete는 표 전체를 제거하고 Backspace는 선택한 칸의 내용만 비운다.
        if(tblCellSelection&&!document.querySelector('.tb.edit')&&doc
           &&document.getElementById('editorView').classList.contains('open')
           &&!/^(INPUT|TEXTAREA|SELECT)$/.test((document.activeElement||{}).tagName||'')){
            const dirs={ArrowLeft:[0,-1],ArrowRight:[0,1],ArrowUp:[-1,0],ArrowDown:[1,0]};
            if(dirs[e.key]){
                e.preventDefault(); moveTblCellSelection(dirs[e.key][0],dirs[e.key][1],e.shiftKey); return;
            }
            if(e.key==='Tab'){
                e.preventDefault();
                const s=tblCellSelection,t=findTbl(s.pageIdx,s.tid),n=t&&t.cw.length;
                if(t&&n){
                    const total=t.ch.length*n;
                    const at=Math.max(0,Math.min(total-1,s.r1*n+s.c1+(e.shiftKey?-1:1)));
                    s.r0=s.r1=Math.floor(at/n); s.c0=s.c1=at%n;
                    setActiveTbl(s.pageIdx,s.tid,s.r1,s.c1); paintTblCellSelection();
                }
                return;
            }
            if(e.key==='Enter'||e.key==='F2'){ e.preventDefault(); editTblSelectionCell(); return; }
            if(e.key==='Delete'){
                e.preventDefault();
                const s=tblCellSelection;
                tblDelAll(true,s.tid,s.pageIdx);
                return;
            }
            if(e.key==='Backspace'){ e.preventDefault(); clearTblCellContents(); return; }
        }
        // 단축키 도움말
        // 사용법은 설정에서만 연다 (노트 안에서는 뜨지 않음)
        if((e.key==='?'||e.key==='F1')
           && !document.getElementById('editorView').classList.contains('open')
           && !/^(INPUT|TEXTAREA|SELECT)$/.test((document.activeElement||{}).tagName||'')){
            e.preventDefault();
            document.getElementById('keyModal').style.display==='flex'?closeKeys():openKeys();
            return;
        }
        // 방향키: 단일 텍스트 상자 = 스프레드시트식 셀 이동, 그 외/Shift·Alt = 미세 이동
        if(/^Arrow(Up|Down|Left|Right)$/.test(e.key) && !document.querySelector('.tb.edit')
           && (selected||multiSel.length) && doc
           && document.getElementById('editorView').classList.contains('open')
           && !/^(INPUT|TEXTAREA|SELECT)$/.test((document.activeElement||{}).tagName||'')){
            const _curBox=currentSelText();
            if(_curBox && !e.shiftKey && !e.altKey){
                e.preventDefault();
                const _dir={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down'}[e.key];
                const _nb=nearestBox(_curBox,_dir);
                if(_nb){ selectTextBoxById(_nb.pi,_nb.id); try{_nb.node.scrollIntoView({block:'nearest'});}catch(_e){} }
                return;
            }
            e.preventDefault();
            const step=e.shiftKey?10:1;
            const dx=e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0;
            const dy=e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0;
            if(!nudgeTimer) pushHistory();
            clearTimeout(nudgeTimer);
            nudgeTimer=setTimeout(()=>{ nudgeTimer=null; saveDoc(); },500);
            const move=(id,pi,node)=>{
                const el=findEl(pi,id); if(!el) return;
                if(el.type==='stroke'){
                    el.dx=(el.dx||0)+dx; el.dy=(el.dy||0)+dy;
                    node.setAttribute('transform',`translate(${el.dx},${el.dy})`);
                }else{
                    const c=clampEl(el.x+dx,el.y+dy,el.w,el.h);
                    el.x=Math.round(c.x); el.y=Math.round(c.y);
                    node.style.left=el.x+'px'; node.style.top=el.y+'px';
                }
            };
            if(multiSel.length) multiSel.forEach(m=>move(m.id,m.pageIdx,m.node));
            else move(selected.el.dataset.id,+selected.el.dataset.pageIdx,selected.el);
            return;
        }
        // ===== 스프레드시트식: 셀 선택 상태에서 Tab/Enter/F2 =====
        if(!document.querySelector('.tb.edit') && doc
           && document.getElementById('editorView').classList.contains('open')
           && !/^(INPUT|TEXTAREA|SELECT)$/.test((document.activeElement||{}).tagName||'')){
            const curBox=currentSelText();
            if(curBox){
                if(e.key==='Tab'){
                    e.preventDefault();
                    const nb=nextBoxInOrder(curBox, e.shiftKey?-1:1);
                    if(nb){ selectTextBoxById(nb.pi,nb.id); try{nb.node.scrollIntoView({block:'nearest'});}catch(_e){} }
                    return;
                }
                if(e.key==='Enter' || e.key==='F2'){
                    e.preventDefault();
                    enterEdit(curBox.node, true);
                    return;
                }
            }
        }
        // ── 입력칸에 포커스가 있으면 이 아래 노트 단축키들은 접는다 ──
        //   이 아래는 전부 '노트(캔버스)를 다루는' 단축키다 — Ctrl+A(전체 선택)·
        //   Ctrl+C/X/J(요소 복사·잘라내기·복제)·Delete/Backspace(요소 삭제)·
        //   Ctrl+D/E/P/Enter(쪽 복제·내보내기·새 쪽)·Ctrl+Z/Y(되돌리기).
        //   그런데 해돌이 검색창(#aiQ)처럼 글자를 치는 칸에 포커스가 있을 때도
        //   그대로 가로챘다 — Ctrl+A 를 누르면 칸 안의 글이 아니라 노트 전체가
        //   선택되고, Ctrl+Z 는 방금 친 글이 아니라 노트를 되돌렸다.
        //   그래서 노트 본문(.tb-content) 편집 중이 아닌 '바깥 입력칸'에서는
        //   브라우저·입력칸 기본 동작에 맡긴다. (Ctrl+S 저장은 예외로 살린다.
        //   찾기 Ctrl+F·바꿔치기 Ctrl+H·Esc 는 이 가드보다 위에서 먼저 본다.)
        {
            const _ae=document.activeElement, _tag=(_ae&&_ae.tagName)||'';
            const _inField=(_tag==='INPUT'||_tag==='TEXTAREA'||_tag==='SELECT')
                ||!!(_ae&&_ae.isContentEditable&&!_ae.classList.contains('tb-content'));
            if(_inField&&!((e.ctrlKey||e.metaKey)&&(e.key==='s'||e.key==='S'))) return;
        }
        // 요소 복사 / 잘라내기 / 붙여넣기 / 복제
        if((e.ctrlKey||e.metaKey)&&!document.querySelector('.tb.edit')&&doc
           && document.getElementById('editorView').classList.contains('open')){
            const k=e.key.toLowerCase();
            // 텍스트가 드래그 선택돼 있으면 '글자 복사'가 우선 (요소 복사로 가로채지 않는다)
            const _sel=window.getSelection();
            const textPicked=_sel&&!_sel.isCollapsed&&String(_sel).trim().length>0
                             &&_sel.anchorNode&&_sel.anchorNode.parentElement
                             &&_sel.anchorNode.parentElement.closest('.tb-content');
            if((k==='c'||k==='x')&&textPicked){
                // 아래 copy 리스너가 '순수 글자'만 클립보드에 넣는다
                if(k==='c') setTimeout(()=>toast('텍스트 복사됨',1200),0);
                return;
            }
            // 텍스트 상자를 골라 Ctrl+C → 안의 '글자만' 선택한 순서대로 복사.
            // 상자 1개만 골랐을 때도 똑같이 글자를 준다 (예전엔 요소 복사로 빠졌다).
            if(k==='c'&&(multiSel.length||selected)){
                const _ms=selectedElsData();
                if(_ms.length&&_ms.every(x=>x.type==='text')){
                    e.preventDefault(); copySelectedTextAsText(_ms); return;
                }
            }
            if(k==='c'&&(selected||multiSel.length)){ e.preventDefault(); copyElements(false); return; }
            if(k==='x'&&(selected||multiSel.length)){ e.preventDefault(); copyElements(true);  return; }
            if(k==='j'&&(selected||multiSel.length)){e.preventDefault(); duplicateSelection();  return; }
            if(k==='a'){
                e.preventDefault(); selectAllOnPage(); return;
            }
        }
        // 표가 선택된 상태면 Delete 로 표 통째 삭제
        if((e.key==='Delete'||e.key==='Backspace')&&tblSelectedForDelete()
           && !/^(INPUT|TEXTAREA|SELECT)$/.test((document.activeElement||{}).tagName||'')){
            e.preventDefault(); tblDelAll(true); return;
        }
        if((e.key==='Delete'||e.key==='Backspace')&&multiSel.length&&!document.querySelector('.tb.edit')){
            e.preventDefault(); deleteMulti(); return;
        }
        if(e.key==='Escape'&&multiSel.length){ clearMulti(); return; }
        if((e.key==='Delete'||e.key==='Backspace')&&selected&&!document.querySelector('.tb.edit')){
            e.preventDefault();
            const lid=selected.el.dataset.id, lpi=+selected.el.dataset.pageIdx;
            const hel=findEl(lpi,lid);
            if(hel&&tblOf(hel)){
                tblDelAll(true, tblOf(hel), lpi);
                return;
            }
            if(isElLocked(lpi,lid)){ toast('잠긴 요소는 지울 수 없습니다',1800); return; }
            pushHistory();
            const id=lid, pi=lpi;
            const gone=(doc.pages[pi].els||[]).filter(x=>x.id===id);
            doc.pages[pi].els=doc.pages[pi].els.filter(x=>x.id!==id);
            selected.el.remove(); selected=null; saveDoc();
            purgeElements(gone);
        }
        if(e.ctrlKey&&(e.key==='s'||e.key==='S')){
            e.preventDefault();
            // input 디바운스(300ms)가 아직 끝나기 전에도 Ctrl+S는 현재
            // contenteditable 내용을 먼저 문서에 반영해야 한다.
            // 자동 저장은 조용히, 수동 저장(Ctrl+S)만 결과를 저장 상태 글자로 보여 준다.
            if(doc){
                commitEditingText();
                flushSaveDoc();
                flushSync({manual:true}).catch(()=>{});
            }
            return;
        }
        if(e.ctrlKey&&(e.key==='d'||e.key==='D')){
            if(doc&&!document.querySelector('.tb.edit')){ e.preventDefault(); duplicatePage(); }
            return;
        }
        if(e.ctrlKey&&(e.key==='e'||e.key==='E')){
            if(doc){ e.preventDefault(); openExportModal(); }
            return;
        }
        if(e.ctrlKey&&(e.key==='p'||e.key==='P')){
            if(doc){ e.preventDefault(); exportPDF(); }
            return;
        }
        if(e.ctrlKey&&e.key==='Enter'){
            if(doc){ e.preventDefault(); addPage(); }
            return;
        }
        if((e.ctrlKey||e.metaKey)&&(e.key==='z'||e.key==='Z')){
            const editContent=document.querySelector('.tb.edit')&&document.activeElement&&document.activeElement.classList&&document.activeElement.classList.contains('tb-content');
            if(editContent&&!_scriptEditUndoable) return;
            e.preventDefault();
            _scriptEditUndoable=false;
            if(e.shiftKey) redo(); else undo();
            return;
        }
        if((e.ctrlKey||e.metaKey)&&(e.key==='y'||e.key==='Y')){
            const editContent=document.querySelector('.tb.edit')&&document.activeElement&&document.activeElement.classList&&document.activeElement.classList.contains('tb-content');
            if(editContent&&!_scriptEditUndoable) return;
            e.preventDefault(); _scriptEditUndoable=false; redo(); return;
        }
    });

    // ============ 펜 / 지우개 ============
    let penActive=false, eraserActive=false, drawColor=CLASSIC_DRAW_COLORS[0], drawSize=2;
    let shapeMode='free', markerMode=false;
    let drawing=false, curPts=null, curPathNode=null, drawPageIdx=0;
    const ERASER_MULT=6;   // 지우개 반경 = drawSize * ERASER_MULT

    function eraserRadius(){ return (drawSize*ERASER_MULT)/2; }

    function syncDrawModeButtons(){
        const p=document.getElementById('penBtn');
        const h=document.getElementById('highlighterBtn');
        if(p) p.classList.toggle('active',!!penActive&&!markerMode);
        if(h) h.classList.toggle('active',!!penActive&&!!markerMode);
        const legacy=document.getElementById('markerBtn');
        if(legacy) legacy.classList.toggle('active',!!markerMode);
    }
    function startDrawMode(asMarker){
        setTextTool(false);
        cancelPlaceMode();
        deselectAll();
        penActive=true; eraserActive=false; drawing=false; markerMode=!!asMarker;
        const er=document.getElementById('eraserBtn'); if(er) er.classList.remove('active');
        const bar=document.getElementById('drawToolbar'); if(bar) bar.style.display='flex';
        editorPapers().forEach(p=>p.classList.add('drawing'));
        syncDrawModeButtons();
        updateToolCursor();
        try{ saveDrawCfg(); }catch(e){}
    }
    function togglePen(){
        if(penActive&&!markerMode){ finishDrawing(); return; }
        startDrawMode(false);
        toast('펜 모드',900);
    }
    function toggleHighlighter(){
        if(penActive&&markerMode){ finishDrawing(); return; }
        startDrawMode(true);
        toast('형광펜 모드 (반투명·굵게)',1100);
    }
    function finishDrawing(){
        clearMorphTimer();
        penActive=false; eraserActive=false; drawing=false;
        syncDrawModeButtons();
        const er=document.getElementById('eraserBtn'); if(er) er.classList.remove('active');
        const bar=document.getElementById('drawToolbar'); if(bar) bar.style.display='none';
        editorPapers().forEach(p=>p.classList.remove('drawing'));
        const tc=document.getElementById('toolCursor'); if(tc) tc.style.display='none';
        saveDoc();
    }
    function setShape(m){
        shapeMode=m; eraserActive=false;
        document.getElementById('eraserBtn').classList.remove('active');
        document.querySelectorAll('.shp').forEach(b=>b.classList.remove('active'));
        const map={free:'shpFree',line:'shpLine',arrow:'shpArrow',rect:'shpRect',ellipse:'shpEllipse'};
        const b=document.getElementById(map[m]); if(b) b.classList.add('active');
        updateToolCursor();
        try{ saveDrawCfg(); }catch(e){}
    }
    // 14.17 · 펜 색·굵기·도형·형광펜을 브라우저에 기억해 두면 모바일/데스크톱
    //   모두 '다음에 펜을 열 때도 같은 설정'으로 바로 그릴 수 있다.
    const DRAW_CFG_KEY='sdy_draw_cfg';
    // 14.18.4 · localStorage 에 남아 있던 예전 기본색/파스텔 펜 색도 지금의
    //   세련된 진한 팔레트로 맞춘다. 사용자가 임의로 고른 다른 색은 그대로 둔다.
    function saveDrawCfg(){
        try{ localStorage.setItem(DRAW_CFG_KEY, JSON.stringify({color:drawColor,size:drawSize,shape:shapeMode,marker:markerMode})); }catch(e){}
    }
    function restoreDrawCfg(){
        try{
            const c=JSON.parse(localStorage.getItem(DRAW_CFG_KEY)||'null');
            if(!c) return;
            if(c.color){
                c.color=_classicPaletteColor('draw',c.color);
                drawColor=c.color;
                const pc=document.getElementById('penCustom');
                if(pc){ pc.value=c.color; pc.style.setProperty('--custom-color',c.color); }
                let hit=false;
                document.querySelectorAll('.color-pick[data-c]').forEach(x=>{
                    const on=String(x.dataset.c).toLowerCase()===String(c.color).toLowerCase();
                    x.classList.toggle('sel',on); if(on) hit=true;
                });
                if(pc) pc.classList.toggle('sel',!hit);
            }
            if(c.size){
                drawSize=+c.size||drawSize;
                document.querySelectorAll('.size-opt').forEach(x=>x.classList.toggle('sel',+x.dataset.s===drawSize));
            }
            if(c.shape&&['free','line','arrow','rect','ellipse'].includes(c.shape)){
                shapeMode=c.shape;
                document.querySelectorAll('.shp').forEach(b=>b.classList.remove('active'));
                const b=document.getElementById({free:'shpFree',line:'shpLine',arrow:'shpArrow',rect:'shpRect',ellipse:'shpEllipse'}[c.shape]);
                if(b) b.classList.add('active');
            }
            if(typeof c.marker==='boolean') markerMode=c.marker;
            syncDrawModeButtons();
        }catch(e){}
    }
    function toggleMarker(){
        // 하위 호환용: 예전 툴바 안 형광펜 버튼이 호출하던 함수.
        if(penActive&&markerMode) startDrawMode(false);
        else startDrawMode(true);
        toast(markerMode?'형광펜 모드 (반투명·굵게)':'펜 모드',1200);
    }
    function setDrawColorVal(v){
        drawColor=v; eraserActive=false;
        document.querySelectorAll('.color-pick').forEach(c=>c.classList.remove('sel'));
        const pc=document.getElementById('penCustom');
        if(pc){ pc.classList.add('sel'); pc.style.setProperty('--custom-color',v); }
        const er=document.getElementById('eraserBtn'); if(er) er.classList.remove('active');
        updateToolCursor();
        try{ saveDrawCfg(); }catch(e){}
    }
    function setDrawColor(el){
        drawColor=el.dataset.c; eraserActive=false;
        const pc=document.getElementById('penCustom');
        if(pc){ pc.value=el.dataset.c; pc.classList.remove('sel'); pc.style.setProperty('--custom-color',el.dataset.c); }
        document.querySelectorAll('.color-pick').forEach(c=>c.classList.remove('sel'));
        el.classList.add('sel');
        const er=document.getElementById('eraserBtn'); if(er) er.classList.remove('active');
        updateToolCursor();
        try{ saveDrawCfg(); }catch(e){}
    }
    function setDrawSize(el){
        drawSize=+el.dataset.s;
        document.querySelectorAll('.size-opt').forEach(s=>s.classList.remove('sel'));
        el.classList.add('sel');
        updateToolCursor();
        try{ saveDrawCfg(); }catch(e){}
    }
    function toggleEraser(){
        eraserActive=!eraserActive;
        document.getElementById('eraserBtn').classList.toggle('active',eraserActive);
        updateToolCursor();
    }

    // 펜촉/지우개 크기를 화면 배율에 맞춰 '실제 크기' 그대로 표시
    function updateToolCursor(){
        const tc=document.getElementById('toolCursor');
        if(!penActive){ tc.style.display='none'; return; }
        const d=(eraserActive? eraserRadius()*2 : effSize())*pageScale;
        const px=Math.max(eraserActive?10:4, d);
        tc.style.width=px+'px'; tc.style.height=px+'px';
        tc.className='tool-cursor '+(eraserActive?'eraser':(markerMode?'marker':'pen'));
        // 펜에서 설정한 인라인 색이 지우개에 남지 않도록 매번 초기화
        if(eraserActive){ tc.style.background=''; tc.style.borderColor=''; }
        else { tc.style.background=hexA(drawColor,.35); tc.style.borderColor=drawColor; }
        tc.querySelector('.dot').style.display=(!eraserActive&&px<6)?'block':'none';
        tc.style.display='block';
    }
    function hexA(hex,a){
        const h=hex.replace('#',''); const f=h.length===3?h.split('').map(c=>c+c).join(''):h;
        const n=parseInt(f,16);
        return `rgba(${(n>>16)&255},${(n>>8)&255},${n&255},${a})`;
    }
    try{ restoreDrawCfg(); }catch(e){}
    const _toolCursorMove=('PointerEvent' in window)?'pointermove':'mousemove';
    document.addEventListener(_toolCursorMove,e=>{
        if(!penActive) return;
        const points=typeof e.getCoalescedEvents==='function'?e.getCoalescedEvents():null;
        const p=points&&points.length?points[points.length-1]:e;
        const tc=document.getElementById('toolCursor');
        // left/top을 계속 바꾸면 레이아웃이 매번 다시 계산되어 고주사율 포인터가
        // 버벅였다. 최신 좌표만 GPU transform 변수로 넘긴다.
        tc.style.setProperty('--cursor-x',uiCss(p.clientX)+'px');
        tc.style.setProperty('--cursor-y',uiCss(p.clientY)+'px');
    },{passive:true});

    function surfacePos(e,pageIdx){
        const t=(e.touches&&e.touches[0])?e.touches[0]:e;
        return pageLocal(t,pageIdx);
    }

    let shapeStart=null, curShapeKind=null, drawMorphTimer=0, drawMorphAnim=0;
    const DRAW_MORPH_HOLD_MS=620;
    function effSize(){ return markerMode? drawSize*4 : drawSize; }
    function effOpacity(){ return markerMode? 0.4 : 1; }
    function clearMorphTimer(){
        if(drawMorphTimer){ clearTimeout(drawMorphTimer); drawMorphTimer=0; }
        if(drawMorphAnim){ cancelAnimationFrame(drawMorphAnim); drawMorphAnim=0; }
    }
    function scheduleMorphHold(){
        if(shapeMode!=='free'||eraserActive||curShapeKind) return;
        if(!curPts||curPts.length<4) return;
        if(drawMorphTimer) clearTimeout(drawMorphTimer);
        drawMorphTimer=setTimeout(()=>{ drawMorphTimer=0; morphCurrentStroke(); },DRAW_MORPH_HOLD_MS);
    }
    function drawPtsBBox(pts){
        let x1=Infinity,y1=Infinity,x2=-Infinity,y2=-Infinity;
        (pts||[]).forEach(p=>{ const x=p[0],y=p[1]; if(x<x1)x1=x; if(y<y1)y1=y; if(x>x2)x2=x; if(y>y2)y2=y; });
        return isFinite(x1)?{x1,y1,x2,y2,w:x2-x1,h:y2-y1,cx:(x1+x2)/2,cy:(y1+y2)/2}:null;
    }
    function ptDist(a,b){ return Math.hypot((a[0]||0)-(b[0]||0),(a[1]||0)-(b[1]||0)); }
    function lineDist(p,a,b){
        const vx=b[0]-a[0], vy=b[1]-a[1], wx=p[0]-a[0], wy=p[1]-a[1];
        const l=vx*vx+vy*vy; let t=l?((wx*vx+wy*vy)/l):0; t=Math.max(0,Math.min(1,t));
        return Math.hypot(p[0]-(a[0]+vx*t),p[1]-(a[1]+vy*t));
    }
    function rdpPts(pts,eps){
        if(!pts||pts.length<=2) return (pts||[]).slice();
        let best=0,idx=-1,a=pts[0],b=pts[pts.length-1];
        for(let i=1;i<pts.length-1;i++){ const d=lineDist(pts[i],a,b); if(d>best){ best=d; idx=i; } }
        if(best<=eps||idx<0) return [a,b];
        const left=rdpPts(pts.slice(0,idx+1),eps), right=rdpPts(pts.slice(idx),eps);
        return left.slice(0,-1).concat(right);
    }
    function pathLenPts(pts){
        let L=0; for(let i=1;i<(pts||[]).length;i++) L+=ptDist(pts[i-1],pts[i]); return L;
    }
    function resamplePts(pts,n){
        pts=(pts||[]).filter(Boolean);
        if(!pts.length) return [];
        if(pts.length===1||n<=1) return Array.from({length:Math.max(1,n)},()=>[pts[0][0],pts[0][1]]);
        const total=pathLenPts(pts)||1, step=total/(n-1), out=[[pts[0][0],pts[0][1]]];
        let seg=1, segStart=pts[0], segLen=ptDist(pts[0],pts[1]), walked=0;
        for(let i=1;i<n-1;i++){
            const target=step*i;
            while(seg<pts.length-1 && walked+segLen<target){ walked+=segLen; segStart=pts[seg]; seg++; segLen=ptDist(pts[seg-1],pts[seg]); }
            const prev=pts[seg-1], next=pts[seg];
            const t=segLen?Math.max(0,Math.min(1,(target-walked)/segLen)):0;
            out.push([prev[0]+(next[0]-prev[0])*t, prev[1]+(next[1]-prev[1])*t]);
        }
        const last=pts[pts.length-1]; out.push([last[0],last[1]]);
        return out;
    }
    function canonicalShapePoints(kind,bb){
        if(!bb) return null;
        let x1=bb.x1,y1=bb.y1,x2=bb.x2,y2=bb.y2;
        if(kind==='square'||kind==='circle'){
            const d=Math.max(bb.w,bb.h), cx=bb.cx, cy=bb.cy;
            x1=cx-d/2; x2=cx+d/2; y1=cy-d/2; y2=cy+d/2;
        }
        const a={x:round1(x1),y:round1(y1)}, b={x:round1(x2),y:round1(y2)};
        if(kind==='rect'||kind==='square') return shapePoints(a,b,'rect',false);
        if(kind==='ellipse'||kind==='circle') return shapePoints(a,b,'ellipse',false);
        if(kind==='triangle'){
            const cx=round1((x1+x2)/2);
            return [[cx,round1(y1)],[round1(x2),round1(y2)],[round1(x1),round1(y2)],[cx,round1(y1)]];
        }
        if(kind==='diamond'){
            const cx=round1((x1+x2)/2), cy=round1((y1+y2)/2);
            return [[cx,round1(y1)],[round1(x2),cy],[cx,round1(y2)],[round1(x1),cy],[cx,round1(y1)]];
        }
        return null;
    }
    function recognizeMorphShape(pts){
        pts=(pts||[]).filter(p=>p&&isFinite(p[0])&&isFinite(p[1]));
        if(pts.length<4) return null;
        const bb=drawPtsBBox(pts); if(!bb) return null;
        const diag=Math.hypot(bb.w,bb.h); if(diag<18) return null;
        const first=pts[0], last=pts[pts.length-1];
        const closed=ptDist(first,last)<=Math.max(18,diag*.22);
        if(!closed){
            const end=ptDist(first,last);
            if(end<18) return null;
            let maxD=0; pts.forEach(p=>{ maxD=Math.max(maxD,lineDist(p,first,last)); });
            if(maxD<=Math.max(5,end*.16)) return {shape:'line',pts:[[round1(first[0]),round1(first[1])],[round1(last[0]),round1(last[1])]]};
            return null;
        }
        if(bb.w<12||bb.h<12) return null;
        const body=pts.slice();
        if(ptDist(body[0],body[body.length-1])<Math.max(8,diag*.08)) body.pop();
        const nearEdge=body.filter(p=>Math.min(Math.abs(p[0]-bb.x1),Math.abs(p[0]-bb.x2),Math.abs(p[1]-bb.y1),Math.abs(p[1]-bb.y2))<=Math.max(4,diag*.075)).length/body.length;
        const simp=rdpPts(body.concat([body[0]]),Math.max(5,diag*.075)).slice(0,-1)
            .filter((p,i,a)=>i===0||ptDist(p,a[i-1])>Math.max(5,diag*.06));
        const ratio=bb.w&&bb.h?Math.min(bb.w,bb.h)/Math.max(bb.w,bb.h):0;
        if(nearEdge>.52){
            const target=canonicalShapePoints(ratio>.82?'square':'rect',bb);
            return target?{shape:ratio>.82?'square':'rect',pts:target}:null;
        }
        if(simp.length>=3&&simp.length<=4){
            if(simp.length===3){
                const target=canonicalShapePoints('triangle',bb);
                return target?{shape:'triangle',pts:target}:null;
            }
            // 마름모는 꼭짓점이 위/오른쪽/아래/왼쪽 주변에 하나씩 있을 때만 잡는다.
            const cx=bb.cx, cy=bb.cy;
            const buckets={top:0,right:0,bottom:0,left:0};
            simp.forEach(p=>{
                const ax=Math.abs(p[0]-cx), ay=Math.abs(p[1]-cy);
                if(ay>=ax && p[1]<cy) buckets.top++;
                else if(ay>=ax && p[1]>=cy) buckets.bottom++;
                else if(p[0]>=cx) buckets.right++;
                else buckets.left++;
            });
            if(buckets.top&&buckets.right&&buckets.bottom&&buckets.left){
                const target=canonicalShapePoints('diamond',bb);
                return target?{shape:'diamond',pts:target}:null;
            }
        }
        // 원/타원: 중심 기준 반지름 편차가 작으면 곡선 도형으로 다듬는다.
        const rx=bb.w/2, ry=bb.h/2; if(rx<6||ry<6) return null;
        let err=0,cnt=0;
        body.forEach(p=>{ const q=Math.hypot((p[0]-bb.cx)/rx,(p[1]-bb.cy)/ry); if(isFinite(q)){ err+=Math.abs(q-1); cnt++; } });
        err=cnt?err/cnt:9;
        if(err<.32||simp.length>5){
            const kind=ratio>.82?'circle':'ellipse';
            const target=canonicalShapePoints(kind,bb);
            return target?{shape:kind,pts:target}:null;
        }
        return null;
    }
    function morphCurrentStroke(){
        if(!drawing||!penActive||eraserActive||shapeMode!=='free'||curShapeKind||!curPts||!curPathNode) return false;
        const guess=recognizeMorphShape(curPts);
        if(!guess||!guess.pts||guess.pts.length<2) return false;
        const from=resamplePts(curPts,guess.pts.length).map(p=>[p[0],p[1]]);
        const to=guess.pts.map(p=>[p[0],p[1]]);
        curShapeKind=guess.shape;
        curPts=to;
        const sharp=!(guess.shape==='ellipse'||guess.shape==='circle');
        const t0=performance.now?performance.now():Date.now();
        const dur=170;
        const step=now=>{
            if(!curPathNode||!curPathNode.isConnected){ drawMorphAnim=0; return; }
            const t=Math.min(1,((now||Date.now())-t0)/dur);
            const ease=1-Math.pow(1-t,3);
            const mix=to.map((p,i)=>[round1(from[i][0]+(p[0]-from[i][0])*ease),round1(from[i][1]+(p[1]-from[i][1])*ease)]);
            curPathNode.setAttribute('d',strokePath(mix,sharp));
            if(t<1) drawMorphAnim=requestAnimationFrame(step);
            else { drawMorphAnim=0; curPathNode.setAttribute('d',strokePath(to,sharp)); }
        };
        if(drawMorphAnim) cancelAnimationFrame(drawMorphAnim);
        drawMorphAnim=requestAnimationFrame(step);
        try{ toast(({line:'직선',rect:'사각형',square:'정사각형',ellipse:'타원',circle:'원',triangle:'삼각형',diamond:'마름모'}[guess.shape]||'도형')+'으로 다듬었습니다',900); }catch(e){}
        return true;
    }

    // ── 14.18.3 · 그리기 되돌리기 재설계 ──────────────────────────────────────
    //  예전 문제 ①  drawStart 의 pushHistory 가 250ms 묶음에 걸려 빠르게 연속으로
    //    그린 획들이 한 덩어리로 취급 → 되돌리기 한 번에 여러 획이 통째로 사라졌다.
    //  예전 문제 ②  지우개는 pushHistory 를 '첫 획을 지운 뒤' 에야 남겼다 → 스냅샷이
    //    이미 지워진 상태라 되돌려도 그 첫 획은 영영 돌아오지 않았다.
    //  예전 문제 ③  되돌리기(undo)가 종이를 다시 그리면서 펜 모드(.drawing)가 풀렸다.
    //  이제 ① 획·지우개 제스처마다 묶음 없이 '작업 전' 상태를 남기고, ② 아무 변화가
    //  없었던 제스처(헛클릭·헛친 지우개)의 스냅샷은 도로 치워 되돌리기가 헛돌지
    //  않게 하며, ③ 되돌린 뒤에도 펜 모드를 새 종이에 다시 붙인다.
    let _drawSnap=null;       // 이번 그리기 제스처에서 남겨 둔 '작업 전' 스냅샷
    let _eraseRemoved=false;  // 이번 지우개 제스처에서 실제로 지운 획이 있는가
    function _dropDrawSnap(){
        if(_drawSnap==null) return;
        if(history.length&&history[history.length-1]===_drawSnap) history.pop();
        _drawSnap=null;
    }
    function drawStart(e,pageIdx){
        if(!penActive) return;
        e.preventDefault();
        curPageIdx=pageIdx; updatePageInfo();
        drawPageIdx=pageIdx;
        const p=surfacePos(e,pageIdx);
        if(eraserActive){
            drawing=true; lastErase=null; _eraseRemoved=false;
            _drawSnap=pushHistory(true);      // 지우기 '전' 상태부터 보존
            eraseSweep(p,pageIdx); return;
        }
        _drawSnap=pushHistory(true);          // 획마다 개별 되돌리기 보장
        clearMorphTimer();
        drawing=true;
        shapeStart={x:round1(p.x),y:round1(p.y)};
        curShapeKind=shapeMode!=='free'?shapeMode:null;
        curPts=[[round1(p.x),round1(p.y)]];
        const svg=paperQ(pageIdx,'.layer-stroke');
        if(!svg){ drawing=false; return; }
        curPathNode=document.createElementNS('http://www.w3.org/2000/svg','path');
        curPathNode.setAttribute('fill','none');
        curPathNode.setAttribute('stroke',drawColor);
        curPathNode.setAttribute('stroke-width',effSize());
        curPathNode.setAttribute('stroke-opacity',effOpacity());
        curPathNode.setAttribute('stroke-linecap','round');
        curPathNode.setAttribute('stroke-linejoin','round');
        svg.appendChild(curPathNode);
    }
    function drawMove(e){
        if(!drawing||!penActive) return;
        e.preventDefault();
        const p=surfacePos(e,drawPageIdx);
        if(eraserActive){ eraseSweep(p,drawPageIdx); return; }
        if(shapeMode!=='free'){
            // 도형: 시작점~현재점으로 매번 다시 계산
            curShapeKind=shapeMode;
            curPts=shapePoints(shapeStart,{x:round1(p.x),y:round1(p.y)},shapeMode,e.shiftKey);
            curPathNode.setAttribute('d',strokePath(curPts,!(shapeMode==='ellipse'||shapeMode==='circle')));
            return;
        }
        // 길게 눌러 이미 도형으로 다듬어진 뒤에는 같은 포인터의 잔여 move 가
        // 다시 자유선 점을 덧붙이지 않게 한다.
        if(curShapeKind) return;
        const last=curPts[curPts.length-1];
        if(Math.abs(p.x-last[0])<0.7&&Math.abs(p.y-last[1])<0.7) return;
        curPts.push([round1(p.x),round1(p.y)]);
        curPathNode.setAttribute('d',strokePath(curPts));
        scheduleMorphHold();
    }
    function drawEnd(){
        // rAF 대기 중에 mouseup/touchend 가 먼저 온 경우, 마지막 포인트를 놓치지 않고
        // 미리 반영한다. (특히 지우개는 몇 ms 만에 끝날 수 있어 이 flush 가 없으면
        //  빠른 스와이프가 안 지워진다)
        if(drawing && (_drawEv || _drawEvT)){
            try{ if(_drawEvT) drawMove(_drawEvT); else if(_drawEv) drawMove(_drawEv); }catch(e){}
            _drawEv=null; _drawEvT=null;
        }
        lastErase=null;
        if(!drawing) return;
        drawing=false;
        clearMorphTimer();
        if(eraserActive){ if(!_eraseRemoved) _dropDrawSnap(); saveDoc(); return; }
        if(!curPts||curPts.length<1){ if(curPathNode)curPathNode.remove(); _dropDrawSnap(); return; }
        const shape=curShapeKind||(shapeMode!=='free'?shapeMode:null);
        const el={type:'stroke',id:uid('s'),pts:curPts,color:drawColor,size:effSize(),dx:0,dy:0};
        if(markerMode) el.opacity=0.4;
        if(shape){
            el.shape=shape;
            if(shape!=='ellipse'&&shape!=='circle') el.sharp=1;
            if(shape==='rect'||shape==='square'||shape==='ellipse'||shape==='circle'||shape==='triangle'||shape==='diamond') el.closed=1;
        }
        doc.pages[drawPageIdx].els.push(el);
        if(curPathNode) curPathNode.remove();
        const svg=paperQ(drawPageIdx,'.layer-stroke');
        if(svg) svg.appendChild(buildStrokeEl(el,drawPageIdx));
        curPts=null; curPathNode=null;
        _drawSnap=null;      // 획이 실제로 추가됐다 → '작업 전' 스냅샷을 되돌림 사다리에 그대로 둔다
        saveDoc();
    }
    function round1(v){ return Math.round(v*10)/10; }

    // 도형을 점 배열로 (스트로크 모델을 그대로 재사용 → 선택/이동/내보내기 전부 호환)
    function shapePoints(a,b,mode,shift){
        let x2=b.x, y2=b.y;
        if(shift||mode==='circle'||mode==='square'){
            if(mode==='line'||mode==='arrow'){
                const dx=x2-a.x, dy=y2-a.y;
                if(Math.abs(dx)>Math.abs(dy)) y2=a.y; else x2=a.x;
            }else{
                const d=Math.max(Math.abs(x2-a.x),Math.abs(y2-a.y));
                x2=a.x+Math.sign(x2-a.x||1)*d;
                y2=a.y+Math.sign(y2-a.y||1)*d;
            }
        }
        const r=v=>Math.round(v*10)/10;
        if(mode==='line') return [[a.x,a.y],[r(x2),r(y2)]];
        if(mode==='arrow'){
            const ang=Math.atan2(y2-a.y,x2-a.x);
            const L=Math.max(9,Math.min(22,Math.hypot(x2-a.x,y2-a.y)*0.22));
            const p1=[r(x2-L*Math.cos(ang-0.42)), r(y2-L*Math.sin(ang-0.42))];
            const p2=[r(x2-L*Math.cos(ang+0.42)), r(y2-L*Math.sin(ang+0.42))];
            return [[a.x,a.y],[r(x2),r(y2)],p1,[r(x2),r(y2)],p2];
        }
        if(mode==='rect'||mode==='square') return [[a.x,a.y],[r(x2),a.y],[r(x2),r(y2)],[a.x,r(y2)],[a.x,a.y]];
        if(mode==='triangle') return [[r((a.x+x2)/2),a.y],[r(x2),r(y2)],[a.x,r(y2)],[r((a.x+x2)/2),a.y]];
        if(mode==='diamond') return [[r((a.x+x2)/2),a.y],[r(x2),r((a.y+y2)/2)],[r((a.x+x2)/2),r(y2)],[a.x,r((a.y+y2)/2)],[r((a.x+x2)/2),a.y]];
        if(mode==='ellipse'||mode==='circle'){
            const cx=(a.x+x2)/2, cy=(a.y+y2)/2, rx=Math.abs(x2-a.x)/2, ry=Math.abs(y2-a.y)/2;
            const pts=[];
            for(let i=0;i<=36;i++){
                const t=i/36*Math.PI*2;
                pts.push([r(cx+rx*Math.cos(t)), r(cy+ry*Math.sin(t))]);
            }
            return pts;
        }
        return [[a.x,a.y],[r(x2),r(y2)]];
    }

    // 지우개: 획 단위로 지움 (반경 안에 닿은 획 제거)
    // 점(px,py) 과 선분 (ax,ay)-(bx,by) 사이의 최단거리 제곱
    function distSqToSeg(px,py,ax,ay,bx,by){
        const vx=bx-ax, vy=by-ay;
        const wx=px-ax, wy=py-ay;
        const len2=vx*vx+vy*vy;
        let t = len2>0 ? (wx*vx+wy*vy)/len2 : 0;
        t = t<0?0 : t>1?1 : t;
        const dx=px-(ax+t*vx), dy=py-(ay+t*vy);
        return dx*dx+dy*dy;
    }
    // 지우개 원이 획과 실제로 겹치는가 (선분 단위로 검사)
    function eraserHitsStroke(el,p,r){
        const ox=el.dx||0, oy=el.dy||0;
        const pts=el.pts||[];
        if(!pts.length) return false;
        const reach=r+(el.size||1)/2;
        const reach2=reach*reach;
        if(pts.length===1){
            const dx=pts[0][0]+ox-p.x, dy=pts[0][1]+oy-p.y;
            return dx*dx+dy*dy<=reach2;
        }
        // 점 사이가 아무리 멀어도(직선 = 점 2개) 중간에서 지워지도록 선분으로 판정
        for(let i=0;i<pts.length-1;i++){
            const a=pts[i], b=pts[i+1];
            if(distSqToSeg(p.x,p.y, a[0]+ox,a[1]+oy, b[0]+ox,b[1]+oy)<=reach2) return true;
        }
        // 닫힌 도형(사각형/원)은 마지막→처음 변도 검사
        if(el.shape==='rect'||el.shape==='ellipse'||el.closed){
            const a=pts[pts.length-1], b=pts[0];
            if(distSqToSeg(p.x,p.y, a[0]+ox,a[1]+oy, b[0]+ox,b[1]+oy)<=reach2) return true;
        }
        return false;
    }
    // 마우스를 빨리 움직이면 이벤트 사이가 비어 '안 지워지는' 구간이 생긴다.
    // 이전 지점과 현재 지점 사이를 촘촘히 훑어서 지운다.
    let lastErase=null;
    function eraseSweep(p,pageIdx){
        const r=eraserRadius();
        const q=lastErase;
        if(q){
            const dx=p.x-q.x, dy=p.y-q.y;
            const dist=Math.hypot(dx,dy);
            const step=Math.max(2,r*0.7);
            const nSteps=Math.min(120,Math.ceil(dist/step));
            for(let i=1;i<nSteps;i++){
                eraseAt({x:q.x+dx*i/nSteps, y:q.y+dy*i/nSteps}, pageIdx);
            }
        }
        eraseAt(p,pageIdx);
        lastErase={x:p.x,y:p.y};
    }

    function eraseAt(p,pageIdx){
        const r=eraserRadius();
        const els=doc.pages[pageIdx].els||[];
        let removed=false;
        for(let i=els.length-1;i>=0;i--){
            const el=els[i];
            if(el.type!=='stroke') continue;
            if(eraserHitsStroke(el,p,r)){
                els.splice(i,1);
                const g=paperQ(pageIdx,`.stroke-g[data-id="${el.id}"]`);
                if(g) g.remove();
                removed=true;
            }
        }
        if(removed) _eraseRemoved=true;   // 되돌리기 스냅샷은 drawStart 가 '지우기 전'으로 이미 남겼다
    }

    // draw-surface 이벤트 위임 — ★ pointerdown 으로 통합 (터치 300ms 지연 제거)
    sdyAddPointerCompat(document,'pointerdown',e=>{
        const s=e.target.closest('.draw-surface');
        if(s&&penActive) drawStart(e,+s.closest('.paper').dataset.pageIdx);
    },true);
    let _drawRaf=0, _drawEv=null;
    let _drawRafT=0, _drawEvT=null;
    // ★ 펜 호버 필터: Apple Pencil 이 화면 위에 있지만 닿지 않았을 때
    //   (pressure===0, buttons===0) 발생하는 pointermove 를 무시한다.
    //   이렇게 하지 않으면 이전 필기 후 펜을 들어올린 채 움직이면
    //   얇은 잔상 선이 그어진다.
    sdyAddPointerCompat(document,'pointermove',e=>{
        if(!drawing) return;
        if(e.pointerType==='pen' && e.pressure===0 && e.buttons===0) return;
        _drawEv=e;
        if(_drawRaf) return;
        _drawRaf=requestAnimationFrame(()=>{ _drawRaf=0; if(drawing&&_drawEv) drawMove(_drawEv); });
    },{passive:true});
    // ★ pointercancel 추가 — 펜이 화면 밖으로 나가면 그리기 종료
    sdyAddPointerCompat(document,'pointerup',()=>{ if(drawing) drawEnd(); });
    document.addEventListener('pointercancel',()=>{ if(drawing) drawEnd(); });
    document.addEventListener('touchstart',e=>{
        if(e.touches&&e.touches.length>1) return;      // 두 손가락은 확대/축소용
        const s=e.target.closest&&e.target.closest('.draw-surface');
        if(s&&penActive) drawStart(e,+s.closest('.paper').dataset.pageIdx);
    },{passive:false});
    document.addEventListener('touchmove',e=>{
        if(e.touches&&e.touches.length>1){ if(drawing) drawEnd(); return; }
        if(!drawing) return;
        // 스크롤 차단은 이벤트 단계에서 미리 걸고, 실제 경로 계산은 rAF 로 묶어
        // 고주사율 터치(모바일)에서도 프레임마다 부드럽게 그린다.
        try{ if(e.cancelable!==false) e.preventDefault(); }catch(err){}
        _drawEvT=e;
        if(_drawRafT) return;
        _drawRafT=requestAnimationFrame(()=>{ _drawRafT=0; if(drawing&&_drawEvT) drawMove(_drawEvT); });
    },{passive:false});
    document.addEventListener('touchend',()=>{ if(drawing) drawEnd(); });
    document.addEventListener('touchcancel',()=>{ if(drawing) drawEnd(); });

    // ===== 두 손가락 확대/축소 (핀치 줌) =====
    // 예전엔 이 기능이 아예 없고 뷰포트도 user-scalable=no 라 모바일에서
    // 확대가 전혀 안 됐다. 손가락 사이 중점을 화면에 고정한 채 배율만 바꾼다.
    (function(){
        const body=document.getElementById('editorBody');
        const stage=document.getElementById('pagesStage');
        if(!body||!stage) return;
        let piv=null;
        const dist=t=>Math.hypot(t[0].clientX-t[1].clientX, t[0].clientY-t[1].clientY);
        const mid =t=>({x:(t[0].clientX+t[1].clientX)/2, y:(t[0].clientY+t[1].clientY)/2});

        body.addEventListener('touchstart',e=>{
            if(e.touches.length!==2) return;
            const m=mid(e.touches), r=body.getBoundingClientRect();
            piv={
                d0:dist(e.touches), z0:zoomPct,
                // 확대 기준점을 '문서 좌표'로 붙잡아 둔다
                cx:(body.scrollLeft+m.x-r.left)/pageScale,
                cy:(body.scrollTop +m.y-r.top )/pageScale,
                mx:m.x-r.left, my:m.y-r.top
            };
            try{ if(typeof deselectAll==='function') deselectAll(true); }catch(err){}
        },{passive:true});

        // 손가락을 움직이는 동안에는 '값싼' CSS 확대만 한다.
        // layoutPages() 는 쪽마다 DOM 을 만지므로 프레임마다 부르면
        // 손가락을 따라오지 못하고 굼떠 보인다 → 뗄 때 딱 한 번만 부른다.
        let raf=0, want=0;
        const apply=()=>{
            raf=0;
            const k=want/piv.z0;                       // 시작 배율 대비 비율
            stage.style.transformOrigin='0 0';
            stage.style.transform=`scale(${k})`;
            // 붙잡아 둔 지점이 손가락 중점에 계속 붙어 있도록 스크롤 보정
            const sc=pageScale*k;
            body.scrollLeft=piv.cx*sc-piv.mx;
            body.scrollTop =piv.cy*sc-piv.my;
        };
        body.addEventListener('touchmove',e=>{
            if(!piv||e.touches.length!==2) return;
            e.preventDefault();                       // 브라우저 기본 동작 차단
            const d=dist(e.touches);
            if(!d||!piv.d0) return;
            want=Math.max(25,Math.min(400, piv.z0*(d/piv.d0)));
            const m=mid(e.touches), r=body.getBoundingClientRect();
            piv.mx=m.x-r.left; piv.my=m.y-r.top;
            if(!raf) raf=requestAnimationFrame(apply);
        },{passive:false});

        const end=e=>{
            if(!piv) return;
            if(!e.touches||e.touches.length<2){
                if(raf){ cancelAnimationFrame(raf); raf=0; }
                const fin=want||piv.z0, mx=piv.mx, my=piv.my, cx=piv.cx, cy=piv.cy;
                piv=null; want=0;
                // 임시 CSS 확대를 걷어내고 진짜 배율로 한 번에 다시 그린다
                stage.style.transform='';
                zoomPct=fin;
                const was=body.style.scrollBehavior;
                body.style.scrollBehavior='auto';
                layoutPages();
                body.scrollLeft=cx*pageScale-mx;
                body.scrollTop =cy*pageScale-my;
                body.style.scrollBehavior=was;
                try{ sizeTextGhost(); }catch(err){}
                try{ onEditorScroll(); }catch(err){}
            }
        };
        body.addEventListener('touchend',end);
        body.addEventListener('touchcancel',end);

        // iOS Safari 는 페이지 전체를 확대하려 든다 → 에디터 안에서는 막는다
        ['gesturestart','gesturechange','gestureend'].forEach(g=>
            body.addEventListener(g,ev=>ev.preventDefault()));
    })();

    // 두 번 톡톡 → 100% ↔ 화면 폭 맞춤 (모바일에서 빠르게 오가기)
    (function(){
        const body=document.getElementById('editorBody');
        if(!body) return;
        let lastT=0,lastX=0,lastY=0;
        body.addEventListener('touchend',e=>{
            if(e.touches.length||!e.changedTouches.length) return;
            if(penActive||drawing) return;
            const t=e.changedTouches[0], now=Date.now();
            if(now-lastT<300 && Math.hypot(t.clientX-lastX,t.clientY-lastY)<28){
                if(e.target.closest('.tb,.paper-img,.stroke-g')) return;  // 요소 조작은 방해 않기
                lastT=0;
                if(Math.round(zoomPct)===100) zoomFit(); else resetZoom();
            }
            lastT=now; lastX=t.clientX; lastY=t.clientY;
        },{passive:true});
    })();

    // ============ 워드식 글자색 / 형광펜 ============
    // 14.18.4 · 글자색/형광펜 팔레트는 파스텔보다 조금 더 세련된 진한 톤으로 맞춘다.
    //   예전 기본색/파스텔값이 저장돼 있어도 렌더링 때 아래 팔레트 계열로 자연스럽게 맞춘다.
    const TEXT_COLORS=CLASSIC_TEXT_COLORS.slice();
    const HL_COLORS=CLASSIC_HL_COLORS.slice();
    let currentTextColor=TEXT_COLORS[0], currentHlColor=HL_COLORS[0];
    // 실제 브라우저(특히 iOS Safari)는 툴바 버튼 pointerdown 순간 편집기의
    // Selection을 접어 버린다. jsdom 테스트에서 함수를 직접 호출할 때는 드러나지
    // 않는 차이다. pointerdown 전에 저장한 Range를 click handler가 끝날 때까지 잠근다.
    let _toolbarSelLockUntil=0;

    function saveSel(){
        const s=window.getSelection();
        if(!s||!s.rangeCount) return;
        if(_fmtBusy) return;   // 서식 재구축 중의 선택 변화는 저장 상태를 덮지 않는다
        const r=s.getRangeAt(0);
        const host=r.commonAncestorContainer.nodeType===1
            ? r.commonAncestorContainer.closest?.('.tb-content')
            : r.commonAncestorContainer.parentElement?.closest('.tb-content');
        if(!host) return;
        if(s.isCollapsed){
            // 툴바가 포커스를 가져가며 생긴 일시적 collapse로 실제 드래그 범위를
            // 덮어쓰지 않는다. 사용자가 종이에서 직접 캐럿을 옮긴 경우에는 lock이 없다.
            if(savedRange&&savedHost&&Date.now()<_toolbarSelLockUntil) return;
            // 편집 중 캐럿(글자 선택 없음)도 기억한다 — 이때 바꾼 색/글꼴/크기는
            // '상자 전체'가 아니라 '앞으로 입력될 글자'에만 적용하기 위함.
            const w=host.closest('.tb');
            if(w&&w.classList.contains('edit')){
                savedCaret={c:host,r:r.cloneRange()};
                savedRange=null; savedHost=null;   // 캐럿으로 접은 뒤엔 이전 선택은 무효
            }
            return;
        }
        savedRange=r.cloneRange(); savedHost=host;
        savedCaret=null; _typingSpan=null; _pendingTyping=null; // 글자 선택이 생기면 예전 캐럿 서식은 더 이상 우선하지 않는다.
    }
    function restoreSel(){
        if(!savedRange||!savedHost) return null;
        if(!document.body.contains(savedHost)) return null;
        // 저장 Range보다 사용자가 나중에 고른 상자가 우선이다. 메뉴를 여는 동안
        // selectionchange가 늦게 도착하면 이전 상자의 Range가 살아나 새 상자에
        // 적용할 글꼴/크기/색을 가로채는 일이 있었다.
        const rangeBox=savedHost.closest&&savedHost.closest('.tb');
        const picked=multiSel.length
            ? multiSel.map(m=>m.node).filter(n=>n&&n.isConnected&&n.classList.contains('tb'))
            : Array.from(document.querySelectorAll('#pagesStage .tb.sel,#pagesStage .tb.msel'));
        if(picked.length&&picked.indexOf(rangeBox)<0){
            savedRange=null; savedHost=null;
            return null;
        }
        savedHost.contentEditable='true';
        savedHost.focus({preventScroll:true});
        const s=window.getSelection();
        s.removeAllRanges(); s.addRange(savedRange);
        return savedHost;
    }
    document.addEventListener('selectionchange',()=>{ saveSel(); syncCurSel(); });
    function _isFormatToolbarTarget(target){
        return !!(target&&target.closest&&target.closest(
            '#editorView .fmt-group,#fontMenu,#textColorPop,#hlPop'));
    }
    // mousedown만 사용하면 touch/pen에서 저장 시점이 늦다. capture pointerdown은
    // 버튼 기본 포커스보다 먼저 실행되므로 실제 Range/caret를 확실히 보관한다.
    document.addEventListener('pointerdown',e=>{
        if(!_isFormatToolbarTarget(e.target)) return;
        saveSel();
        _toolbarSelLockUntil=Date.now()+1500;
    },true);
    document.addEventListener('click',e=>{
        if(!_isFormatToolbarTarget(e.target)) return;
        // target onclick(applyFont/execFmt 등)이 먼저 끝난 뒤 잠금을 푼다.
        setTimeout(()=>{ _toolbarSelLockUntil=0; },0);
    });
    // 14.13.4 · 글상자 옆에 떠 있던 서식 막대(fmtBar)를 없앴다 — 상단 바와 항목이
    //   중복됐기 때문. 글자 서식(글꼴·크기·굵기·색·형광펜)은 전부 상단 바에서 한다.

    // ===== 글꼴 선택 =====
    // 각 항목을 '해당 글꼴 자체'로 렌더링해 이름만 보고도 어떤 폰트인지 바로 알 수 있게 한다.
    //   좌측: 실제 글꼴로 그린 미리보기 문구 (abc 가나다)
    //   우측: 글꼴 이름 (항상 기본 글꼴로 표시해 항상 가독) + 현재 선택 시 체크
    function buildFontMenu(){
        const m=document.getElementById('fontMenu');
        if(m.dataset.ready==='1') return;
        FONTS.forEach(f=>{
            const it=document.createElement('div');
            it.className='font-item'; it.dataset.f=f.id;
            it.innerHTML=`<span class="fi-sample" style="font-family:${f.css}">abc 가나다</span>`+
                         `<span class="fi-name">${f.label}</span>`+
                         `<i class="ri-checkbox-fill fi-check"></i>`;
            it.onmousedown=e=>e.preventDefault();
            it.onclick=(e)=>{ e.stopPropagation(); applyFont(f.id); closeFontMenu(); };
            m.appendChild(it);
        });
        m.dataset.ready='1';
        // 미리보기가 실제 폰트로 그려지도록, 아직 안 불러온 글꼴은 여기에서 선제 로드
        if(document.fonts&&document.fonts.load){
            FONTS.forEach(f=>{
                const fam=f.css.split(',')[0];           // 주 패밀리 (따옴표 포함)
                try{ document.fonts.load('16px '+fam).catch(()=>{}); }catch(e){}
            });
        }
    }
    function toggleFontMenu(){
        buildFontMenu();
        const m=document.getElementById('fontMenu');
        const willShow=!m.classList.contains('show');
        closePops();
        m.classList.toggle('show',willShow);
        if(willShow){
            // 툴바의 블러(글래스)가 fixed 의 기준점을 바꾸어 위치가 어긋나므로
            // 색 팝오버와 같은 방식으로 body 로 옮긴 뒤 배치한다.
            if(m.parentElement!==document.body) document.body.appendChild(m);
            const r=document.getElementById('fontBtn').getBoundingClientRect();
            const cw=v=>window.sdyUiCss?window.sdyUiCss(v):(Number(v)||0);  // html zoom(.9) 보정
            m.style.left=Math.min(cw(r.left),cw(window.innerWidth)-240)+'px';
            m.style.top=(cw(r.bottom)+6)+'px';
            // 현재 선택된 글꼴 표시 (강조 + 체크)
            m.querySelectorAll('.font-item').forEach(n=>n.classList.toggle('sel',n.dataset.f===curFont));
        }
    }
    function closeFontMenu(){ document.getElementById('fontMenu').classList.remove('show'); }

    // 18.8 · 툴바(글꼴 이름·미리보기·메뉴 체크)를 한 곳에서 갱신한다.
    //   "사용자가 보는 툴바 글꼴 = 지금 입력되는 글꼴" 을 항상 지키기 위한 창구.
    function setToolbarFont(id){
        const f=FONTS.find(x=>x.id===id)||FONTS[0];
        curFont=f.id;
        const lb=document.getElementById('fontLabel');
        const btn=document.getElementById('fontBtn');
        if(lb) lb.textContent=f.label;
        if(btn) btn.style.fontFamily=f.css;
        document.querySelectorAll('#fontMenu .font-item')
            .forEach(n=>n.classList.toggle('sel',n.dataset.f===f.id));
        return f;
    }

    function applyFont(id){
        const f=setToolbarFont(id);
        id=f.id;

        // ① 글자 선택이 있으면 그 부분만 (새 인라인 엔진 사용 — 다른 서식 풀림 없음)
        const host=restoreSel();
        const sel=window.getSelection();
        if(host&&sel&&!sel.isCollapsed){
            pushHistory();
            try{
                wrapSelStyle('fontFamily',f.css);
                const w=host.closest('.tb'); if(w) syncTextEl(w);
                saveSel();
                syncCurSel();
            }catch(e){}
            toast(`글꼴: ${f.label}`,1100);
            return;
        }
        // ② 선택한 표 셀 범위 전체
        if(selectedTblCellEls().length){
            tblCellApply(el=>{ el.font=id; },`선택한 칸 글꼴: ${f.label}`);
            return;
        }
        // 18.5 · 편집 중 캐럿(선택 없음) → 상자 전체가 아니라 앞으로 입력될 글자에만
        if(_typingHost()){
            caretWrapStyle({fontFamily:f.css});
            toast(`앞으로 입력할 글꼴: ${f.label}`,1100);
            return;
        }
        // ③ 선택된 텍스트 상자(들)
        let targets=[];
        if(multiSel.length) targets=multiSel.map(m=>m.node).filter(n=>n.classList.contains('tb'));
        if(!targets.length) targets=Array.from(document.querySelectorAll('#pagesStage .tb.edit,#pagesStage .tb.sel'));
        if(targets.length){
            pushHistory();
            targets.forEach(w=>{
                const el=findEl(+w.dataset.pageIdx,w.dataset.id);
                const c=w.querySelector('.tb-content');
                if(el&&c){
                    el.font=id; c.style.fontFamily=f.css;
                    // 18.8 · 상자 전체 글꼴은 '안쪽 부분 글꼴'보다 세다.
                    //   굵게/색 등을 먼저 입히며 생긴 span 에 옛 글꼴이 박제돼 있어도
                    //   상자 글꼴 변경이 화면에 그대로 보이도록 인라인 글꼴을 걷어낸다.
                    // v2 엔진: 인라인으로 박제된 부분 글꼴만 새 값으로 갱신하고,
                    //   나머지는 상자 값 상속을 유지한다 (글자마다 span 을 깔지 않는다).
                    try{ _fmtApplyBox(c,'fontFamily',f.css,true); }catch(_e){}
                    syncTextEl(w);
                }
            });
            saveDoc();
            setToolbarFont(id);
            toast(`${targets.length}개 상자 글꼴 변경`,1200);
            return;
        }
        toast(`이후 입력 글꼴: ${f.label}`,1200);
    }

    function buildPop(id,colors,kind){
        const pop=document.getElementById(id);
        if(pop.dataset.ready==='1') return;
        const title=document.createElement('div');
        title.className='cp-title';
        title.textContent=kind==='text'?'글자 색':'형광펜 색';
        pop.appendChild(title);
        const grid=document.createElement('div'); grid.className='cp-grid';
        colors.forEach(c=>{
            const b=document.createElement('button');
            b.className='color-swatch'; b.style.background=c; b.dataset.c=c;
            b.onmousedown=e=>e.preventDefault();
            b.onclick=(e)=>{
                e.stopPropagation();
                if(kind==='text'){ currentTextColor=c; document.getElementById('tcBar').style.background=c; document.getElementById('tcGlyph').style.color=c; applyTextColor(c); }
                else { currentHlColor=c; document.getElementById('hlBar').style.background=c; applyHighlight(c); }
                pop.querySelectorAll('.color-swatch').forEach(s=>s.classList.toggle('sel',s.dataset.c===c));
                closePops();
            };
            grid.appendChild(b);
        });
        pop.appendChild(grid);
        const none=document.createElement('button');
        none.className='cp-none';
        none.innerHTML=kind==='text'?'<i class="ri-format-clear"></i> 자동(검정)':'<i class="ri-drop-line"></i> 색 없음';
        none.onmousedown=e=>e.preventDefault();
        none.onclick=(e)=>{ e.stopPropagation(); if(kind==='text') clearTextColor(); else applyHighlight(null); closePops(); };
        pop.appendChild(none);
        pop.dataset.ready='1';
    }
    function togglePop(id){
        const kind=id==='textColorPop'?'text':'hl';
        buildPop(id, kind==='text'?TEXT_COLORS:HL_COLORS, kind);
        const pop=document.getElementById(id);
        const other=document.getElementById(id==='textColorPop'?'hlPop':'textColorPop');
        other.classList.remove('show');
        const willShow=!pop.classList.contains('show');
        pop.classList.toggle('show',willShow);
        if(willShow){
            // 툴바의 overflow 에 잘리지 않도록 body 로 이동 + 버튼 아래에 고정 배치
            if(pop.parentElement!==document.body) document.body.appendChild(pop);
            const btn=document.getElementById(kind==='text'?'textColorWrap':'hlWrap');
            const r=btn.getBoundingClientRect();
            pop.style.left=Math.min(r.left, window.innerWidth-210)+'px';
            pop.style.top=(r.bottom+6)+'px';
        }
    }
    function closePops(){
        document.getElementById('textColorPop').classList.remove('show');
        document.getElementById('hlPop').classList.remove('show');
    }
    document.addEventListener('click',e=>{
        if(!e.target.closest('.split-btn')) closePops();
        if(!e.target.closest('.font-wrap')) closeFontMenu();
    });

    // 서식 연산의 공통 진입 래퍼. 저장해 둔 선택을 살려 fn 에게 host 를 넘기고,
    // 끝나면 저장 사슬(syncTextEl→saveDoc)과 선택·툴바 상태를 맞춘다.
    // 구버전이 여기서 하던 execCommand 보정(captureSelFonts/restoreSelFonts/
    // _keepFontOnSel)은 v2 엔진이 execCommand 를 아예 쓰지 않게 되어 필요 없어졌다.
    function withSelection(fn){
        const host=restoreSel();
        if(!host){ toast('텍스트를 드래그해 선택하세요',1300); return false; }
        fn(host);
        const w=host.closest('.tb');
        if(w) syncTextEl(w);
        saveSel();
        syncCurSel();
        return true;
    }
    // 14.13.4 · 글자 선택 없이 '상자'만 고른 상태 → 상자 전체에 서식을 칠할 대상
    function _boxFmtTargets(){
        let t=multiSel.length
            ? multiSel.map(m=>m.node).filter(n=>n&&n.classList&&n.classList.contains('tb')&&!n.classList.contains('latex-box'))
            : [];
        if(!t.length) t=Array.from(document.querySelectorAll('#pagesStage .tb.sel,#pagesStage .tb.msel,#pagesStage .tb.edit'))
            .filter(n=>!n.classList.contains('latex-box'));
        return t;
    }
    // ═══════════════════════════════════════════════════════════════════
    // 18.10 · SDY-FMT v2 — 인라인 서식 엔진 (2026-09 전면 재설계)
    //
    //   [구조를 갈아엎은 이유]
    //   구버전 엔진은 "선택 조각을 extractContents 로 떼어내고 → 새 span 으로
    //   감싸고 → _stripInlineProp 로 걷어내고 → _cleanupInline 로 치운다" 는
    //   수술형이었다. span 이 중첩될수록 '어느 조상이 어떤 속성을 담당하는지'
    //   상태가 꼬여서, 일부 글꼴을 바꾼 뒤 굵게가 안 먹히는 식의
    //   순서·환경 의존 버그가 계속 재발했다. execCommand 병행 경로와 그 오류를
    //   감싸는 보정(captureSelFonts·restoreSelFonts·_keepFontOnSel)까지 얹혀
    //   구조가 더 복잡해졌다.
    //
    //   [v2 · 선언형 재구축(rebuild)]
    //     1) 상자(.tb-content) 안 글자를 '문자 오프셋 지도'로 잰다.
    //     2) 편집 범위와 겹치는 문단(리프 블록)마다 토큰 스트림을 만든다.
    //        토큰 = 글자 세그먼트{텍스트, 유효 스타일, 링크} / <br> / <img> 같은
    //        원자 노드 / 빈 타이핑 마커 span(.sdy-type).
    //     3) 편집은 토큰의 스타일 사전을 고치는 것뿐이다. DOM 수술이 없다.
    //     4) 문단을 정규형으로 다시 그린다(_fmtRender): 유효 스타일이 같은 이웃
    //        세그먼트는 하나의 <span style="..."> 로 합친다. 링크는 <a> 로 감싸고,
    //        <br>·<img>·타이핑 마커는 원본 노드를 그대로 옮긴다.
    //     5) 문자 오프셋으로 선택(캐럿)을 복원한다(_fmtRestoreSelection).
    //
    //   - 같은 연산을 여러 번 겹쳐도 항상 평탄한 정규형으로 수렴한다(멱등).
    //     → "글꼴 바꾼 뒤 굵게가 안 먹힘" 같은 상태 누적 버그가 원천 차단된다.
    //   - 글자 서식에 execCommand 를 전혀 쓰지 않는다(브라우저/웹뷰 편차 제거).
    //   - 상자 전체 서식도 같은 경로(전체 범위 적용)라 특수 처리가 없다.
    //   - 굵게 해제 시에도 '상자 자체가 굵게'인 경우에만 중립값(400)을 적는다.
    //     평범한 글자는 속성을 삭제해 상속으로 되돌린다(font-weight:400 덧대기 제거).
    // ═══════════════════════════════════════════════════════════════════
    const FMT_PROPS=['fontWeight','fontStyle','textDecoration','color','backgroundColor','fontFamily','fontSize','verticalAlign'];
    const INLINE_STYLE_PROPS=FMT_PROPS;          // 하위 호환 이름
    const FMT_BLOCK_TAGS=new Set(['DIV','P','H1','H2','H3','H4','H5','H6','LI','BLOCKQUOTE','PRE','UL','OL','TABLE','TR','TD','TH','SECTION','ARTICLE']);
    const FMT_ATOMIC_TAGS=new Set(['IMG','SVG','CANVAS','VIDEO','AUDIO','IFRAME','HR','INPUT','TEXTAREA','SELECT','BUTTON','OBJECT','EMBED']);
    let _fmtBusy=false;    // 재구축 중 selectionchange 가 저장 선택을 덮지 않게 하는 잠금

    // 의미 태그(b/i/u/s/mark)가 뜻하는 canonical 스타일
    function _tagStyle(tag){
        tag=String(tag||'').toUpperCase();
        if(tag==='B'||tag==='STRONG') return {fontWeight:'700'};
        if(tag==='I'||tag==='EM')     return {fontStyle:'italic'};
        if(tag==='U')                 return {textDecoration:'underline'};
        if(tag==='S'||tag==='STRIKE') return {textDecoration:'line-through'};
        if(tag==='MARK')              return {backgroundColor:'#ffff00'};
        if(tag==='SUB')               return {verticalAlign:'sub'};
        if(tag==='SUP')               return {verticalAlign:'super'};
        return null;
    }
    function _fwVal(v){
        v=String(v||'').toLowerCase();
        if(v==='bold'||v==='bolder') return 700;
        const n=parseInt(v,10);
        if(!isNaN(n)) return n;
        return 0;
    }
    function _propMatch(prop,actual,desired){
        actual=String(actual||'').toLowerCase();
        desired=String(desired||'').toLowerCase();
        if(!actual) return false;
        if(prop==='fontWeight'){
            const a=_fwVal(actual),d=_fwVal(desired);
            if(a>=600&&d>=600) return true;
            return a===d&&a>0;
        }
        if(prop==='textDecoration'){
            const toks=actual.split(/\s+/);
            return toks.indexOf(desired)>=0;
        }
        return actual===desired;
    }
    function _kebabProp(prop){ return String(prop||'').replace(/([A-Z])/g,'-$1').toLowerCase(); }
    // prop=value 를 요소 style 에 적는다 (textDecoration 은 토큰 병합)
    function _setInlineProp(el,prop,value){
        if(!el||!el.style) return;
        if(prop==='textDecoration'){
            const toks=String(value||'').split(/\s+/).filter(t=>t&&t!=='none');
            el.style.textDecoration=[...new Set(toks)].join(' ');
        }else{
            el.style[prop]=value;
        }
    }
    // 요소 style 에서 prop 을 지운다 (textDecoration 토큰 제거 지원)
    function _clearInlineProp(el,prop,value){
        if(!el||!el.style) return;
        if(prop==='textDecoration'&&value){
            const toks=String(el.style.textDecoration||'').split(/\s+/).filter(t=>t&&t!==value);
            if(toks.length) el.style.textDecoration=toks.join(' ');
            else el.style.removeProperty('text-decoration');
            return;
        }
        const kebab=_kebabProp(prop);
        try{ el.style.removeProperty(kebab); }catch(e){}
        try{ el.style[prop]=''; }catch(e){}
    }

    // ── 경계(boundary) 아래 인라인 조상들만의 유효 스타일 ──────────────
    //   재구축 시 세그먼트에 '다시 선언할' 속성만 모은다. 상자(.tb-content)
    //   레벨 스타일은 여기에 넣지 않는다 — 상자 글꼴/크기는 상속으로 그대로
    //   흘러야 나중에 '상자 전체 글꼴 바꾸기'가 막히지 않는다. (18.8 규칙 유지)
    function _fmtChainStyle(tn,boundary){
        const styles={};
        const chain=[];
        let p=tn.parentElement;
        while(p&&p!==boundary){ if(p.nodeType===1) chain.push(p); p=p.parentElement; }
        for(let i=chain.length-1;i>=0;i--){
            const el=chain[i];
            const t=_tagStyle(el.tagName);
            if(t) for(const k in t) if(!(k in styles)) styles[k]=t[k];
            if(el.style) for(const k of FMT_PROPS){ const v=el.style[k]; if(v&&!(k in styles)) styles[k]=v; }
            if(el.tagName==='FONT'&&el.getAttribute){
                const face=el.getAttribute('face'); if(face&&!styles.fontFamily) styles.fontFamily=face;
                const fc=el.getAttribute('color'); if(fc&&!styles.color) styles.color=fc;
            }
        }
        return styles;
    }
    // 텍스트 노드에 상속되는 유효 스타일 (상자 레벨 포함) — 판정/표시용.
    // 구버전과 같은 시맨틱을 유지해 툴바 상태·토글 판정이 그대로 동작한다.
    function _inheritedStyles(tn,host){
        const styles=_fmtChainStyle(tn,host);
        let link=null;
        let p=tn.parentElement;
        while(p&&p!==host){ if(p.nodeType===1&&p.tagName==='A'&&!link) link=p; p=p.parentElement; }
        if(host&&host.nodeType===1&&host.style){
            for(const k of FMT_PROPS){
                if(!(k in styles)){
                    const v=host.style[k];
                    if(v) styles[k]=v;
                }
            }
        }
        return {styles,link};
    }

    // ── 선택/범위 기본 도구 ─────────────────────────────────────────
    function _selContacts(r){
        const out=[];
        if(!r) return out;
        const root=r.commonAncestorContainer;
        const walkRoot=root.nodeType===3?root.parentNode:root;
        if(!walkRoot) return out;
        try{
            const tw=document.createTreeWalker(walkRoot,NodeFilter.SHOW_TEXT);
            let n;
            while(n=tw.nextNode()){
                if(!r.intersectsNode(n)) continue;
                let s=0,e=n.nodeValue.length;
                if(r.startContainer===n) s=r.startOffset;
                if(r.endContainer===n) e=r.endOffset;
                if(s>=e) continue;
                out.push({node:n,s,e});
            }
        }catch(e){}
        return out;
    }
    function _selectionCtx(){
        const s=window.getSelection();
        if(!s||s.isCollapsed||!s.rangeCount) return null;
        const r=s.getRangeAt(0);
        const root=r.commonAncestorContainer;
        const el=root.nodeType===1?root:root.parentElement;
        const host=el&&el.closest&&el.closest('.tb-content');
        if(!host) return null;
        try{
            const sc=r.startContainer.nodeType===1?r.startContainer:r.startContainer.parentElement;
            const ec=r.endContainer.nodeType===1?r.endContainer:r.endContainer.parentElement;
            if((sc&&!host.contains(sc)&&sc!==host)||(ec&&!host.contains(ec)&&ec!==host)) return null;
        }catch(e){}
        return {sel:s,range:r,host};
    }

    // ── ① 문자 오프셋 지도 ─────────────────────────────────────────
    //   host 안 모든 텍스트 노드를 문서 순으로 [start,end) 절대 오프셋과 함께.
    function _fmtTextMap(host){
        const map=[]; let off=0;
        try{
            const tw=document.createTreeWalker(host,NodeFilter.SHOW_TEXT);
            let n;
            while(n=tw.nextNode()){
                const len=String(n.nodeValue||'').length;
                if(len>0){ map.push({node:n,start:off,end:off+len}); off+=len; }
            }
        }catch(e){}
        map.total=off;
        return map;
    }
    function _fmtTextLen(host){ return _fmtTextMap(host).total; }
    // '어떤 지점(컨테이너,오프셋)' → host 기준 문자 오프셋.
    //   지점~host 끝까지의 텍스트 길이를 재서 total 에서 빼는 방식이라
    //   요소 경계/텍스트 중간 어디서 시작해도 정확하다.
    function _fmtOffsetAt(host,container,offset){
        try{
            const total=_fmtTextLen(host);
            const r=document.createRange();
            r.setStart(container,offset);
            r.setEnd(host,host.childNodes.length);
            const tail=String(r.toString()).length;
            return Math.max(0,total-tail);
        }catch(e){ return 0; }
    }
    function _fmtOffsets(host,range){
        const start=_fmtOffsetAt(host,range.startContainer,range.startOffset);
        let end=_fmtOffsetAt(host,range.endContainer,range.endOffset);
        if(end<start) end=start;
        return {start,end};
    }
    // 문자 오프셋 → (노드,노드오프셋). 경계에서는 '다음 글자의 시작'을 택해
    // 뒤이어 입력할 글자가 앞 서식 span 안으로 들어가지 않게 한다.
    function _fmtPointFromOffset(host,offset){
        const map=_fmtTextMap(host);
        for(const t of map){
            if(offset<t.end) return {node:t.node,offset:offset-t.start};
        }
        const last=map[map.length-1];
        if(last) return {node:last.node,offset:last.node.nodeValue.length};
        return {node:host,offset:host.childNodes.length};
    }
    function _fmtRestoreSelection(host,start,end){
        try{
            const a=_fmtPointFromOffset(host,start), b=_fmtPointFromOffset(host,end);
            const nr=document.createRange();
            nr.setStart(a.node,a.offset);
            nr.setEnd(b.node,b.offset);
            const s=window.getSelection();
            s.removeAllRanges(); s.addRange(nr);
            savedRange=nr.cloneRange(); savedHost=host;
        }catch(e){}
    }

    // ── ② 리프 블록(문단) 찾기 ─────────────────────────────────────
    //   텍스트 노드가 속한 '가장 안쪽 블록'. 블록이 없으면 host 자체(암시 영역).
    function _fmtLeafBlock(node,host){
        let p=(node.nodeType===3)?node.parentElement:node;
        while(p&&p!==host){
            if(FMT_BLOCK_TAGS.has(p.tagName)) return p;
            p=p.parentElement;
        }
        return host;
    }
    // [start,end) 와 글자가 겹치는 리프 블록들을 문서 순으로 그룹핑.
    //   host 암시 영역은 블록 요소 사이의 '연속 구간'마다 별개 그룹이 된다.
    function _fmtGroups(host,map,start,end){
        const groups=[];
        for(const t of map){
            if(t.end<=start||t.start>=end) continue;
            const blk=_fmtLeafBlock(t.node,host);
            const g=groups[groups.length-1];
            if(g&&g.el===blk) g.last=t.node;
            else groups.push({el:blk,first:t.node,last:t.node});
        }
        return groups;
    }

    // ── ③ 문단 토큰화 ──────────────────────────────────────────────
    //   block 하위를 문서 순으로 walk 해 토큰 스트림을 만든다.
    //   block===host 이면 다른 블록 요소 안으로는 내려가지 않는다(암시 영역만).
    function _fmtTokens(block,host){
        const tokens=[];
        (function walk(el,link){
            for(let k=el.firstChild;k;k=k.nextSibling){
                if(k.nodeType===3){ tokens.push({t:'text',node:k,link:link||null}); continue; }
                if(k.nodeType!==1) continue;
                const tag=k.tagName;
                if(block===host&&FMT_BLOCK_TAGS.has(tag)) continue;
                if(tag==='BR'){ tokens.push({t:'br',node:k}); continue; }
                if(FMT_ATOMIC_TAGS.has(tag)){ tokens.push({t:'atom',node:k,link:link||null}); continue; }
                const hasInner=!!(String(k.textContent||'').length
                    ||(k.querySelector&&k.querySelector('img,br,svg,canvas,video,audio,iframe,hr')));
                if(!hasInner){
                    // 빈 span. 입력 대기 마커(.sdy-type)만 원자 토큰으로 살려 둔다.
                    if(k.classList&&k.classList.contains('sdy-type')) tokens.push({t:'type',node:k});
                    continue;
                }
                walk(k, tag==='A'?k:(link||null));
            }
        })(block,null);
        return tokens;
    }

    // ── ④ 세그먼트 편집 + 정규형 렌더 ──────────────────────────────
    function _fmtStyleKey(style){
        const keys=Object.keys(style||{}).filter(k=>String(style[k]||'').trim()!=='');
        keys.sort();
        return keys.map(k=>k+'='+_normComparable(k,style[k])).join('|');
    }
    function _fmtLinkKey(l){
        if(!l) return '';
        return l.el
            ? 'E|'+(l.el.getAttribute('href')||'')+'|'+(l.el.getAttribute('target')||'')
            : 'N|'+(l.href||'')+'|'+(l.target||'');
    }
    function _fmtLinkClone(l){
        let a;
        if(l&&l.el&&l.el.cloneNode) a=l.el.cloneNode(false);
        else{
            a=document.createElement('a');
            a.setAttribute('href',(l&&l.href)||'#');
            a.setAttribute('target',(l&&l.target)||'_blank');
            a.setAttribute('rel',(l&&l.rel)||'noopener');
        }
        return a;
    }
    // 토큰(이미 편집 완료된 세그먼트) → DOM. 같은 스타일+같은 링크의 이웃
    // 세그먼트는 하나의 text node(+span)로 합쳐 span 이 누적되지 않는다.
    function _fmtRender(tokens){
        const frag=document.createDocumentFragment();
        const flush=grp=>{
            if(!grp) return;
            let parent=frag;
            if(grp.link){ const a=_fmtLinkClone(grp.link); frag.appendChild(a); parent=a; }
            const style=grp.style||{};
            const cssKeys=Object.keys(style).filter(k=>String(style[k]||'').trim()!=='');
            const tn=document.createTextNode(grp.texts.join(''));
            if(cssKeys.length){
                const sp=document.createElement('span');
                // CSSOM 으로 적는다 — setAttribute 문자열 대신 쓰면 브라우저·jsdom 이
                // 같은 방식으로 값을 정규화·직렬화한다(#fff59d → rgb(255,245,157) 등).
                for(const k of cssKeys){
                    try{ sp.style.setProperty(_kebabProp(k),String(style[k]).trim()); }catch(_e){}
                }
                sp.appendChild(tn);
                parent.appendChild(sp);
            }else parent.appendChild(tn);
        };
        let grp=null;
        for(const tk of tokens){
            if(tk.t==='text'){
                const key=_fmtStyleKey(tk.style)+'\u0000'+_fmtLinkKey(tk.link);
                if(grp&&grp.key===key){ grp.texts.push(tk.text); continue; }
                flush(grp);
                grp={key,style:tk.style,link:tk.link,texts:[tk.text]};
            }else{
                flush(grp); grp=null;
                const n=tk.node;
                if(tk.link){ const a=_fmtLinkClone(tk.link); a.appendChild(n); frag.appendChild(a); }
                else frag.appendChild(n);
            }
        }
        flush(grp);
        return frag;
    }

    // 문단 하나를 다시 그린다. op 는 {type:'set'|'remove'|'clear'|'link'|'unlink', ...}
    function _fmtRebuildBlock(host,g,map,start,end,op){
        const block=g.el;
        const isHost=(block===host);
        let tokens=_fmtTokens(block,host);
        const byNode=new Map();
        for(const t of map) byNode.set(t.node,t);
        for(const tk of tokens){
            if(tk.t!=='text') continue;
            const m=byNode.get(tk.node);
            tk.start=m?m.start:0;
            tk.end=tk.start+String(tk.node.nodeValue||'').length;
            tk.style=_fmtChainStyle(tk.node,block);   // 상자(블록) 레벨 스타일은 재선언하지 않는다
        }
        let kids=null,i0=0,i1=-1;
        if(isHost){
            // 암시 영역: 이 그룹이 속한 '연속된 비블록 구간(암시 문단)' 전체를
            //   다시 그린다. 선택된 글자의 직계 범위만 바꾸면 문단 나머지 글자가
            //   밖에 고립돼 이웃 세그먼트와 합쳐지지 않은 채 남는다.
            kids=Array.from(host.childNodes);
            const topIdx=n=>{
                let p=n;
                while(p&&p.parentNode!==host) p=p.parentNode;
                return kids.indexOf(p);
            };
            const isBlk=n=>n.nodeType===1&&FMT_BLOCK_TAGS.has(n.tagName);
            i0=topIdx(g.first); i1=topIdx(g.last);
            if(i0<0||i1<0||i1<i0) return false;
            while(i0>0&&!isBlk(kids[i0-1])) i0--;
            while(i1<kids.length-1&&!isBlk(kids[i1+1])) i1++;
            tokens=tokens.filter(tk=>{ const i=topIdx(tk.node); return i>=i0&&i<=i1; });
        }
        // 세그먼트 분할 + 연산 적용
        const out=[];
        for(const tk of tokens){
            if(tk.t!=='text'){ out.push(tk); continue; }
            const s=tk.start,e=tk.end,v=String(tk.node.nodeValue||'');
            if(e<=s||!v) continue;
            if(e<=start||s>=end){
                out.push({t:'text',text:v,style:tk.style,link:tk.link});
                continue;
            }
            const a=Math.max(s,start), b=Math.min(e,end);
            if(a>s) out.push({t:'text',text:v.slice(0,a-s),style:tk.style,link:tk.link});
            const st=Object.assign({},tk.style);
            let lk=tk.link;
            if(op.type==='set'||op.type==='setbox'){
                const had=Object.prototype.hasOwnProperty.call(st,op.prop);
                if(op.prop==='textDecoration'){
                    // 밑줄+취소선처럼 여러 토큰이 한 세그먼트에 공존한다 (토큰 병합)
                    const toks=new Set(String(st.textDecoration||'').split(/\s+/).filter(t=>t&&t!=='none'));
                    String(op.value||'').split(/\s+/).filter(t=>t&&t!=='none').forEach(t=>toks.add(t));
                    st.textDecoration=[...toks].join(' ');
                }else{
                    st[op.prop]=op.value;
                }
                if(op.type==='setbox'&&!had){
                    // setbox(상자 전체 값 교체)는 인라인 오버라이드가 없던 글자를
                    // 새로 만들지 않는다 — 상자 값 상속을 유지하기 위함.
                    delete st[op.prop];
                }
            }
            else if(op.type==='remove'){
                if(op.prop==='textDecoration'&&op.value){
                    const toks=String(st.textDecoration||'').split(/\s+/).filter(t=>t&&t!==op.value);
                    if(toks.length) st.textDecoration=toks.join(' ');
                    else delete st.textDecoration;
                }
                else if(op.neutral) st[op.prop]=op.neutral;   // 상자 상속을 끊는 명시적 중립값
                else delete st[op.prop];
            }
            else if(op.type==='clear'){ FMT_PROPS.forEach(p=>{ delete st[p]; }); }
            else if(op.type==='unlink') lk=null;
            else if(op.type==='link') lk={href:op.href,target:'_blank',rel:'noopener'};
            out.push({t:'text',text:v.slice(a-s,b-s),style:st,link:lk});
            if(b<e) out.push({t:'text',text:v.slice(b-s),style:tk.style,link:tk.link});
        }
        // 타이핑 마커 span 도 연산을 함께 받는다 (다음 입력 글자의 서식 유지)
        if(op&&op.type!=='unlink'&&op.type!=='link'){
            out.forEach(tk=>{
                if(tk.t!=='type') return;
                if(op.type==='set') _setInlineProp(tk.node,op.prop,op.value);
                else if(op.type==='remove') _clearInlineProp(tk.node,op.prop,op.value);
                else if(op.type==='clear') FMT_PROPS.forEach(p=>_clearInlineProp(tk.node,p,''));
            });
        }
        const frag=_fmtRender(out);
        // 다시 끼우기
        if(isHost){
            const ref=kids[i1+1]||null;
            for(let i=i0;i<=i1;i++){ if(kids[i].parentNode===host) host.removeChild(kids[i]); }
            host.insertBefore(frag,ref);
        }else{
            while(block.firstChild) block.removeChild(block.firstChild);
            block.appendChild(frag);
        }
        return true;
    }

    // ── ⑤ 실행기 ───────────────────────────────────────────────────
    //   범위 연산 (선택 복원 없음 — 상자 전체/맞춤 검사 등에서 사용)
    function _fmtRunRange(host,start,end,op){
        if(!host||end<=start) return false;
        const map=_fmtTextMap(host);
        if(!map.total) return false;
        const groups=_fmtGroups(host,map,start,end);
        if(!groups.length) return false;
        _fmtBusy=true;
        try{
            groups.forEach(g=>_fmtRebuildBlock(host,g,map,start,end,op));
        }finally{ _fmtBusy=false; }
        return true;
    }
    //   현재 선택 구간 연산 + 선택 복원
    function _fmtApply(op){
        const ctx=_selectionCtx();
        if(!ctx) return false;
        const host=ctx.host;
        const o=_fmtOffsets(host,ctx.range);
        if(o.end<=o.start) return false;
        const map=_fmtTextMap(host);
        const groups=_fmtGroups(host,map,o.start,o.end);
        if(!groups.length) return false;
        _fmtBusy=true;
        try{
            groups.forEach(g=>_fmtRebuildBlock(host,g,map,o.start,o.end,op));
            _fmtRestoreSelection(host,o.start,o.end);
        }finally{ _fmtBusy=false; }
        return true;
    }
    //   굵게/기울임 '해제'가 상자 레벨 상속과 충돌할 때만 중립값을 쓴다.
    function _fmtNeutralFor(host,prop){
        if(!host||!host.style) return '';
        if(prop==='fontWeight'&&_fwVal(host.style.fontWeight)>=600) return '400';
        if(prop==='fontStyle'&&String(host.style.fontStyle||'').toLowerCase()==='italic') return 'normal';
        return '';
    }

    // ── ⑥ 선택 구간 공개 API (기존 호출부와 이름 호환) ─────────────
    function _applyToSelection(prop,value){
        return _fmtApply({type:'set',prop,value});
    }
    function _removeFromSelection(prop,value){
        const ctx=_selectionCtx();
        const neutral=ctx?_fmtNeutralFor(ctx.host,prop):'';
        return _fmtApply({type:'remove',prop,value:String(value||''),neutral});
    }
    // 선택 영역이 전부 해당 스타일인가? (토글 off 판정)
    function _selHasAll(prop,value){
        const s=window.getSelection();
        if(!s||s.isCollapsed||!s.rangeCount) return false;
        const r=s.getRangeAt(0);
        const hostEl=r.commonAncestorContainer.nodeType===1?r.commonAncestorContainer:r.commonAncestorContainer.parentElement;
        const host=hostEl&&hostEl.closest&&hostEl.closest('.tb-content');
        if(!host) return false;
        const contacts=_selContacts(r);
        if(!contacts.length) return false;
        for(const c of contacts){
            const {styles}=_inheritedStyles(c.node,host);
            if(!_propMatch(prop,styles[prop]||'',value)) return false;
        }
        return true;
    }
    // 선택 영역이 하나라도 해당 스타일을 갖고 있는가?
    function _selHasAny(prop,value){
        const s=window.getSelection();
        if(!s||s.isCollapsed||!s.rangeCount) return false;
        const r=s.getRangeAt(0);
        const hostEl=r.commonAncestorContainer.nodeType===1?r.commonAncestorContainer:r.commonAncestorContainer.parentElement;
        const host=hostEl&&hostEl.closest&&hostEl.closest('.tb-content');
        if(!host) return false;
        const contacts=_selContacts(r);
        for(const c of contacts){
            const {styles}=_inheritedStyles(c.node,host);
            if(_propMatch(prop,styles[prop]||'',value)) return true;
        }
        return false;
    }
    // 워드프로세서 규칙: 전부 켜져 있으면 끄고, 아니면 (부분이든) 켠다.
    // v2 재구축이라 '일부만 적용된 상태에서 켜기'도 항상 통일된 결과를 낸다.
    function toggleSelStyle(prop,value){
        const all=_selHasAll(prop,value);
        if(all) _removeFromSelection(prop,value);
        else _applyToSelection(prop,value);
        syncCurSel();
    }
    function wrapSelStyle(prop,value){
        try{ _applyToSelection(prop,value); }catch(e){}
        syncCurSel();
    }
    function clearSelStyle(prop){
        try{ _removeFromSelection(prop); }catch(e){}
        syncCurSel();
    }
    function clearSelBg(){
        try{ _removeFromSelection('backgroundColor'); }catch(e){}
        syncCurSel();
    }
    // 선택 영역에서 글자색 제거 (상속으로 되돌리기)
    function clearSelColor(){
        try{ _removeFromSelection('color'); }catch(e){}
        syncCurSel();
    }

    // ── ⑦ 링크 ─────────────────────────────────────────────────────
    //   execCommand(createLink/unlink) 없이 엔진 경로 하나로 처리한다.
    //   링크 중간 일부만 골라 해제해도 그 조각만 벗겨진다.
    function _fmtLinkSelection(href){
        return _fmtApply({type:'link',href:String(href||'')});
    }
    function _unlinkSelection(){
        return _fmtApply({type:'unlink'});
    }

    // ── ⑧ 문단 정렬 ────────────────────────────────────────────────
    //   execCommand(justify*) 대신 대상 블록에 text-align 을 직접 적는다.
    function _fmtAlignRange(host,start,end,dir){
        if(!host) return false;
        const map=_fmtTextMap(host);
        const blocks=new Set();
        for(const t of map){
            if(t.end<=start||t.start>=end) continue;
            blocks.add(_fmtLeafBlock(t.node,host));
        }
        if(!blocks.size) return false;
        blocks.forEach(b=>{
            b.style.textAlign=dir;
            if(b===host){
                // 암시 영역(블록 요소 없이 상자에 바로 든 글)은 상자 정렬로 기록
                const w=b.closest&&b.closest('.tb');
                const el=w?findEl(+w.dataset.pageIdx,w.dataset.id):null;
                if(el) el.align=dir;
            }
        });
        return true;
    }
    function _fmtAlignSelection(dir){
        const ctx=_selectionCtx();
        if(!ctx) return false;
        const o=_fmtOffsets(ctx.host,ctx.range);
        return _fmtAlignRange(ctx.host,o.start,o.end,dir);
    }

    // ── ⑨ 상자 전체 연산 (선택 없이 상자만 골랐을 때) ──────────────
    //   구버전의 _applyOne/_removeOne 루프+걷어내기를 버리고, 엔진의 전체
    //   범위 적용 하나로 통일했다. 부분 서식(span)이 있어도 문단 정규형으로
    //   다시 그려지므로 덮어쓰기/보존이 항상 정확하다.
    function _fmtUnpaintWF(host){
        // 중요어 색칠(.wf)은 저장되지 않는 임시 레이어다. 서식 연산 전에 원문으로
        // 되돌려 색칠 span 이 서식 결과에 섞이지 않게 한다(enterEdit 과 같은 규칙).
        try{
            if(host.querySelector&&host.querySelector('.wf')){
                const w=host.closest&&host.closest('.tb');
                const el=w?findEl(+w.dataset.pageIdx,w.dataset.id):null;
                if(el) host.innerHTML=el.html||'';
            }
        }catch(e){}
    }
    function _fmtApplyBox(c,prop,value,override){
        if(!c) return false;
        _fmtUnpaintWF(c);
        // override=true : 상자 전체 값(글꼴·크기) 변경 — 이미 인라인 오버라이드가
        //   있는 부분만 갱신하고 나머지는 상자 값 상속을 유지한다.
        // override=false : 상자 전체 덧칠(굵게·색 등) — 모든 글자에 값을 심는다.
        const type=override?'setbox':'set';
        return _fmtRunRange(c,0,_fmtTextLen(c),{type,prop,value});
    }
    function _fmtRemoveBox(c,prop,value){
        if(!c) return false;
        _fmtUnpaintWF(c);
        return _fmtRunRange(c,0,_fmtTextLen(c),{type:'remove',prop,value:String(value||''),neutral:''});
    }

    // ── 값 정규화 비교 (툴바 표시·토글 판정이 쓰는 공용 도구) ──────
    function _normFontCSS(v){
        return String(v||'').toLowerCase().replace(/["']/g,'').replace(/\s*,\s*/g,',').replace(/\s+/g,' ').trim();
    }
    function _fontIdFromCSS(css){
        const n=_normFontCSS(css);
        if(!n) return '';
        const f=FONTS.find(x=>_normFontCSS(x.css)===n || n.indexOf(_normFontCSS(x.css).split(',')[0])===0);
        return f?f.id:'';
    }
    function _colorToHex(v){
        v=String(v||'').trim().toLowerCase();
        if(!v||v==='inherit'||v==='initial') return '';
        if(v==='transparent'||v==='rgba(0, 0, 0, 0)'||v==='rgba(0,0,0,0)') return 'transparent';
        if(/^#[0-9a-f]{3}$/i.test(v)) return '#'+v.slice(1).split('').map(ch=>ch+ch).join('').toLowerCase();
        if(/^#[0-9a-f]{6}$/i.test(v)) return v.toLowerCase();
        const m=v.match(/^rgba?\(([^)]+)\)$/i);
        if(m){
            const parts=m[1].split(',').map(x=>x.trim());
            if(parts.length>=4 && parseFloat(parts[3])===0) return 'transparent';
            const nums=parts.slice(0,3).map(x=>Math.max(0,Math.min(255,parseInt(x,10)||0)));
            return '#'+nums.map(n=>n.toString(16).padStart(2,'0')).join('');
        }
        return v;
    }
    function _normComparable(prop,v){
        if(prop==='color'||prop==='backgroundColor') return _colorToHex(v);
        if(prop==='fontFamily') return _normFontCSS(v);
        if(prop==='fontSize'){
            const n=parseFloat(v); return isNaN(n)?String(v||'').trim().toLowerCase():String(Math.round(n*100)/100)+'px';
        }
        if(prop==='fontWeight') return _fwVal(v)>=600?'700':String(v||'').trim().toLowerCase();
        if(prop==='textDecoration'){
            return String(v||'').toLowerCase().split(/\s+/).filter(t=>t&&t!=='none').sort().join(' ');
        }
        return String(v||'').trim().toLowerCase();
    }
    // 선택한 모든 글자가 한 속성값을 공유하는가? (툴바에 단일 값으로 표시할지 판정)
    function _selUniformStyle(prop){
        const ctx=_selectionCtx();
        if(!ctx) return {ok:false};
        const contacts=_selContacts(ctx.range);
        if(!contacts.length) return {ok:false};
        let firstNorm=null, firstVal='', any=false;
        for(const c of contacts){
            const seg=String(c.node.nodeValue||'').slice(c.s,c.e);
            if(!seg.length) continue;
            const {styles}=_inheritedStyles(c.node,ctx.host);
            let v=styles[prop]||'';
            if((prop==='fontFamily'||prop==='fontSize'||prop==='color') && !v && ctx.host.style) v=ctx.host.style[prop]||'';
            const norm=_normComparable(prop,v);
            if(!any){ firstNorm=norm; firstVal=v; any=true; }
            else if(norm!==firstNorm) return {ok:false,mixed:true};
        }
        return any?{ok:true,value:firstVal,norm:firstNorm}:{ok:false};
    }

    // ── ⑩ 정규화 (기존 _cleanupInline 역할) ────────────────────────
    //   스크립트가 만든 DOM(붙여넣기 등)의 빈 span/빈 서식 태그를 풀고
    //   인접 텍스트 노드를 합친다. 본격적인 정규형 병합은 엔진 재구축이 한다.
    function _cleanupInline(host){
        if(!host||!host.querySelectorAll) return;
        const toRemove=[];
        host.querySelectorAll('span,b,strong,i,em,u,s,strike,mark,font').forEach(el=>{
            if(!el.textContent&&!el.querySelector('img,br,svg,canvas')){ toRemove.push(el); return; }
            if(el.tagName==='SPAN'){
                const style=el.getAttribute('style')||'';
                if(!style.trim()&&!el.getAttribute('class')){
                    const p=el.parentNode;
                    while(el.firstChild) p.insertBefore(el.firstChild,el);
                    toRemove.push(el);
                }
            }
        });
        toRemove.forEach(el=>{ if(el.parentNode) el.parentNode.removeChild(el); });
        try{ host.normalize(); }catch(e){}
    }
    // 선택 영역의 현재 스타일 상태를 툴바 버튼에 반영
    // 18.7 · '지금 서식'을 판단하는 대상: ① 실제 글자 선택 → 선택 전체가 같은가,
    //   없으면 ② 편집 중 캐럿(앞으로 입력될 글자) ③ 선택된 텍스트 상자 전체.
    //   아무것도 아니면 전부 꺼진 상태로 정리한다. (보고 이슈⑥)
    function _activeToggleStates(){
        // ② 캐럿(선택 없음) → 앞으로 입력될 글자 기준
        if(_typingHost()){
            return {
                bold:_caretHasStyle('fontWeight','700'),
                italic:_caretHasStyle('fontStyle','italic'),
                underline:_caretHasStyle('textDecoration','underline'),
                strike:_caretHasStyle('textDecoration','line-through'),
            };
        }
        // ③ 선택된/편집 중 텍스트 상자 → 상자 전체 서식 기준
        let node=null;
        if(selected&&selected.type==='text'&&selected.el) node=selected.el;
        if(!node&&multiSel.length===1) node=multiSel[0].node;
        if(!node) node=document.querySelector('#pagesStage .tb.edit,#pagesStage .tb.sel,#pagesStage .tb.msel');
        if(node&&node.classList&&node.classList.contains('tb')){
            const pageIdx=+node.dataset.pageIdx, id=node.dataset.id;
            const el=(!isNaN(pageIdx)&&id)?findEl(pageIdx,id):null;
            const c=node.querySelector('.tb-content');
            // 상자 단위 서식은 wrapper(.tb)가 아니라 실제 글자가 있는 .tb-content
            // 또는 글자별 span 에 남는다. 예전엔 node.style 만 봐서 상자 전체를
            // 굵게/기울임/밑줄로 만든 뒤 다시 선택하면 툴바 불이 꺼져 보였다.
            const fw=el&&el.fontWeight?el.fontWeight:(c&&c.style?c.style.fontWeight:'');
            const fst=el&&el.fontStyle?el.fontStyle:(c&&c.style?c.style.fontStyle:'');
            const dec=el&&el.textDecoration?el.textDecoration:(c&&c.style?c.style.textDecoration:'');
            return {
                bold:_propMatch('fontWeight',fw,'700') || _boxHasAllStyle(node,'fontWeight','700'),
                italic:_propMatch('fontStyle',fst,'italic') || _boxHasAllStyle(node,'fontStyle','italic'),
                underline:_propMatch('textDecoration',dec,'underline') || _boxHasAllStyle(node,'textDecoration','underline'),
                strike:_propMatch('textDecoration',dec,'line-through') || _boxHasAllStyle(node,'textDecoration','line-through'),
            };
        }
        return {bold:false,italic:false,underline:false,strike:false};
    }
    // 18.8 · 캐럿(앞으로 입력될 글자) 자리에서 실제로 먹고 있는 인라인 스타일 값
    function _caretStyleValue(prop){
        try{
            const t=_typingHost(); if(!t) return '';
            let p=t.r.startContainer;
            p=(p&&p.nodeType===3)?p.parentElement:p;
            while(p&&p!==t.c){
                if(p.style&&p.style[prop]) return p.style[prop];
                if(prop==='fontFamily'&&p.tagName==='FONT'&&p.getAttribute('face')) return p.getAttribute('face');
                p=p.parentElement;
            }
            if(t.c&&t.c.style&&t.c.style[prop]) return t.c.style[prop];
        }catch(e){}
        return '';
    }
    // 18.8 · "툴바에 보이는 글꼴·크기 = 지금 입력되는 글꼴·크기" 를 지킨다.
    //   글자 선택이 없을 때(캐럿 / 상자 선택)의 툴바 동기화 담당.
    function syncToolbarFromCaret(){
        try{
            const t=_typingHost();
            if(t){
                const fam=_caretStyleValue('fontFamily');
                const fid=fam?_fontIdFromCSS(fam):'';
                if(fid) setToolbarFont(fid);
                else{
                    // 상자 자체 글꼴(el.font)이 기준
                    const w=t.c&&t.c.closest?t.c.closest('.tb'):null;
                    const el=w?findEl(+w.dataset.pageIdx,w.dataset.id):null;
                    if(el&&el.font) setToolbarFont(el.font);
                }
                const fs=parseFloat(_caretStyleValue('fontSize'));
                if(fs) setToolbarFS(fs);
                return true;
            }
            // 캐럿이 없으면 '고른 상자' 기준
            syncFSFromTarget();
            return true;
        }catch(e){}
        return false;
    }
    function syncCurSel(){
        try{
            const ctx=_selectionCtx();
            const btnOn=(sel,on)=>{
                const b=document.querySelector(sel);
                if(b) b.classList.toggle('active',!!on);
            };
            if(!ctx){
                // 텍스트(글자) 선택이 없는 화면 → 눌려 있던 서식 버튼을 정리한다.
                //   사용자 이전 설정(글꼴·크기·색·형광펜)은 유지하되, '켜짐' 상태만
                //   실제 캐럿/상자 서식에 맞춘다. (보고 이슈⑥)
                const st=_activeToggleStates();
                btnOn('.tb-bold',st.bold);
                btnOn('.tb-italic',st.italic);
                btnOn('.tb-under',st.underline);
                btnOn('.tb-strike',st.strike);
                // 18.8 · 글꼴·크기는 '지금 입력될 자리' 기준으로 계속 맞춘다.
                syncToolbarFromCaret();
                return;
            }
            // 선택한 모든 글자가 같은 속성을 공유할 때만 툴바에 단일 값으로 표시한다.
            // 섞여 있으면 기존 선택값을 그대로 두어 잘못된 단일 값 표시를 피한다.
            const states={
                bold:_selHasAll('fontWeight','700'),
                italic:_selHasAll('fontStyle','italic'),
                underline:_selHasAll('textDecoration','underline'),
                strike:_selHasAll('textDecoration','line-through'),
            };
            btnOn('.tb-bold',states.bold);
            btnOn('.tb-italic',states.italic);
            btnOn('.tb-under',states.underline);
            btnOn('.tb-strike',states.strike);

            const fU=_selUniformStyle('fontFamily');
            if(fU.ok && fU.norm){
                const id=_fontIdFromCSS(fU.value||fU.norm);
                if(id) setToolbarFont(id);
            }
            const fsU=_selUniformStyle('fontSize');
            if(fsU.ok && fsU.norm){
                const n=parseFloat(fsU.value||fsU.norm);
                if(!isNaN(n)){
                    curFontSize=Math.round(n);
                    const inp=document.getElementById('fsInput');
                    if(inp){ inp.value=curFontSize; inp.classList.remove('mixed'); inp.removeAttribute('aria-label'); }
                }
            }else if(fsU.mixed){
                // Word처럼 선택 범위에 서로 다른 크기가 있으면 임의의 한 값을
                // 보여 주지 않고 '-'로 표시한다. curFontSize는 유지해 +/- 동작의
                // 기준값을 잃지 않으며, 사용자가 숫자를 입력하면 즉시 단일 크기로 바뀐다.
                const inp=document.getElementById('fsInput');
                if(inp&&document.activeElement!==inp){
                    inp.value='-'; inp.classList.add('mixed');
                    inp.setAttribute('aria-label','여러 글자 크기가 선택됨');
                }
            }
            const cU=_selUniformStyle('color');
            if(cU.ok){
                const hex=_colorToHex(cU.value||cU.norm)||'#000000';
                if(hex&&hex!=='transparent'){
                    currentTextColor=hex;
                    const bar=document.getElementById('tcBar'), glyph=document.getElementById('tcGlyph');
                    if(bar) bar.style.background=hex;
                    if(glyph) glyph.style.color=hex;
                    document.querySelectorAll('#textColorPop .color-swatch').forEach(n=>n.classList.toggle('sel',_colorToHex(n.dataset.c)===hex));
                }
            }
            const hU=_selUniformStyle('backgroundColor');
            if(hU.ok){
                const hex=_colorToHex(hU.value||hU.norm);
                const bar=document.getElementById('hlBar');
                if(hex&&hex!=='transparent'){
                    currentHlColor=hex;
                    if(bar) bar.style.background=hex;
                    document.querySelectorAll('#hlPop .color-swatch').forEach(n=>n.classList.toggle('sel',_colorToHex(n.dataset.c)===hex));
                }else if(bar){
                    bar.style.background='transparent';
                }
            }
        }catch(e){}
    }
    // 상자 안 내용 전체에 스타일을 입힌다 (prop=null 이면 형광펜 전체 지우기)
    // 편집 모드 여부와 무관하게 DOM 을 직접 고치므로 글꼴이 풀리지 않는다.
    function _boxTextNodes(c){
        const tw=document.createTreeWalker(c,NodeFilter.SHOW_TEXT);
        const nodes=[]; let n;
        while(n=tw.nextNode()){ if(String(n.nodeValue||'').trim()) nodes.push(n); }
        return nodes;
    }
    // 상자 전체가 해당 스타일로 덮여 있는가 (상자 레벨 + 글자별 span 모두 고려)
    function _boxHasAllStyle(w,prop,value){
        const c=w&&w.querySelector('.tb-content'); if(!c) return false;
        const nodes=_boxTextNodes(c); if(!nodes.length) return false;
        return nodes.every(tn=>_propMatch(prop, _inheritedStyles(tn,c).styles[prop]||'', value));
    }
    // 상자 안 내용 전체에 스타일을 입힌다 (prop=null 이면 형광펜 전체 지우기)
    // v2 엔진의 전체 범위 적용을 쓴다 — 세그먼트 재구축이라 부분 서식(중첩 span)과
    // 겹쳐도 덮어쓰기/보존이 항상 정확하다.
    function _paintBoxAll(w,prop,value){
        const c=w.querySelector('.tb-content'); if(!c) return;
        if(!prop){
            c.querySelectorAll('*').forEach(n=>{
                const bg=n.style&&n.style.backgroundColor;
                if(bg&&bg!=='transparent'&&bg!=='rgba(0, 0, 0, 0)')
                    n.style.removeProperty('background-color');
            });
            if(c.style) c.style.removeProperty('background-color');
            // 구버전 문서/표 셀은 배경색이 el.cellBg 로 저장돼 있었다.
            // 화면 DOM 만 지우면 다시 렌더링하거나 저장 후 열 때 배경이 되살아난다.
            const el=findEl(+w.dataset.pageIdx,w.dataset.id);
            if(el) delete el.cellBg;
            syncTextEl(w);
            return;
        }
        _fmtApplyBox(c,prop,value);
        syncTextEl(w);
    }
    // 상자 전체에서 스타일 제거 (box-level el.fontStyle 같은 옛 데이터도 치운다)
    function _clearBoxStyleAll(w,prop,value){
        const c=w&&w.querySelector('.tb-content'); if(!c) return;
        if(c.style){
            if(prop==='textDecoration'){
                const toks=String(c.style.textDecoration||'').split(/\s+/).filter(t=>t&&t!=='none'&&t!==value);
                if(toks.length) c.style.textDecoration=toks.join(' ');
                else c.style.removeProperty('text-decoration');
            }else c.style.removeProperty(prop);
        }
        const el=findEl(+w.dataset.pageIdx,w.dataset.id);
        if(el){
            if(prop==='textDecoration'){
                const toks=String(el.textDecoration||'').split(/\s+/).filter(t=>t&&t!=='none'&&t!==value);
                if(toks.length) el.textDecoration=toks.join(' ');
                else delete el.textDecoration;
            }else{
                const key={fontWeight:'fontWeight',fontStyle:'fontStyle',color:'textColor',backgroundColor:'cellBg'}[prop];
                if(key) delete el[key];
            }
        }
        _fmtRemoveBox(c,prop,value);
        syncTextEl(w);
    }
    // 상자 전체 토글: 전부 켜져 있으면 끄고, 아니면 전체 적용 (선택 서식과 동일 규칙)
    function _toggleBoxAllStyle(w,prop,value){
        if(_boxHasAllStyle(w,prop,value)) _clearBoxStyleAll(w,prop,value);
        else _paintBoxAll(w,prop,value);
    }
    // 14.13.7 · 순서: ① 표 셀 → ② 글자 선택 범위(저장된 선택 포함) → ③ 상자만 고른 상태(상자 전체)
    function applyTextColor(c){
        currentTextColor=c;
        document.getElementById('tcBar').style.background=c;
        document.getElementById('tcGlyph').style.color=c;
        if(selectedTblCellEls().length){ tblCellApply(el=>{ el.textColor=c; },'선택한 칸 글자색 적용'); return; }
        if(hasInlineTextSel()){
            pushHistory();
            withSelection(()=>wrapSelStyle('color',c));
            return;
        }
        // 18.6 · 캐럿(선택 없음) → 앞으로 입력될 글자에만
        if(_typingHost()){ caretWrapStyle({color:c}); return; }
        const targets=_boxFmtTargets();
        if(targets.length){
            pushHistory();
            targets.forEach(w=>_paintBoxAll(w,'color',c));
            saveDoc();
            toast(targets.length>1?targets.length+'개 상자 글자색 적용':'상자 전체 글자색 적용',1000);
            return;
        }
        toast('텍스트를 드래그하거나 상자를 고르세요',1300);
    }
    function applyHighlight(c){
        if(c){ currentHlColor=c; document.getElementById('hlBar').style.background=c; }
        if(selectedTblCellEls().length){ tblCellFill(c||''); return; }
        if(hasInlineTextSel()){
            pushHistory();
            withSelection(()=>{ if(c) wrapSelStyle('backgroundColor',c); else clearSelBg(); });
            return;
        }
        // 18.6 · 캐럿 → 앞으로 입력될 글자에만
        if(_typingHost()){ caretWrapStyle({backgroundColor:c||'transparent'}); return; }
        const targets=_boxFmtTargets();
        if(targets.length){
            pushHistory();
            targets.forEach(w=>_paintBoxAll(w, c?'backgroundColor':null, c||''));
            saveDoc();
            toast(targets.length>1?targets.length+'개 상자 형광펜 적용':'상자 전체 형광펜 적용',1000);
            return;
        }
        toast('텍스트를 드래그하거나 상자를 고르세요',1300);
    }
    // 18.6 · 글자색 지우기 (부모 상속으로 되돌리기)
    function clearTextColor(){
        if(selectedTblCellEls().length){ tblCellApply(el=>{ delete el.textColor; },'선택한 칸 글자색 지움'); return; }
        if(hasInlineTextSel()){
            pushHistory();
            withSelection(()=>clearSelColor());
            return;
        }
        if(_typingHost()){ caretWrapStyle({color:''}); return; }
        const targets=_boxFmtTargets();
        if(targets.length){
            pushHistory();
            targets.forEach(w=>_clearBoxStyleAll(w,'color'));
            saveDoc();
            toast(targets.length>1?targets.length+'개 상자 글자색 지움':'상자 전체 글자색 지움',1000);
        }
    }
    function execFmt(cmd){
        const cells=selectedTblCellEls();
        if(cells.length){
            const spec={bold:['fontWeight','700'],italic:['fontStyle','italic'],underline:['textDecoration','underline'],
                        strike:['textDecoration','line-through']}[cmd];
            if(spec){
                const [key,val]=spec,remove=cells.every(el=>el[key]===val);
                tblCellApply(el=>{ if(remove) delete el[key]; else el[key]=val; },'선택한 칸 글자 서식 적용');
                return;
            }
        }
        const spec={bold:['fontWeight','700'],italic:['fontStyle','italic'],underline:['textDecoration','underline'],
                    strike:['textDecoration','line-through']}[cmd];
        if(spec){
            // ① 글자 선택(드래그·저장된 범위) → 선택 구간만 토글한다.
            //    예전 캐럿(savedCaret)이 남아 있어도 실제 선택이 있으면 항상 선택을 우선한다.
            if(hasInlineTextSel()){
                pushHistory();
                withSelection(()=>toggleSelStyle(spec[0],spec[1]));
                setTimeout(syncCurSel,0);
                return;
            }
            // ② 캐럿(선택 없음) → 앞으로 입력될 글자만 토글
            if(_typingHost()){
                const [key,val]=spec;
                // 18.7 · 캐럿에서 '꺼짐' 상태는 '속성 제거'가 아니라 '중립값'으로 써야 한다.
                //   - 중립값을 가진 빈 span 을 캐럿 자리에 남기면 이후 입력되는 글자가
                //     바로 앞(부모) 서식에 물려(예: 볼드 span 안에 다시 글자를 입력) 같은
                //     서식으로 계속 입력되는 문제를 막는다. (보고 이슈①)
                //   - fontWeight:400 / fontStyle:normal 처럼 '명시적 중립'이 브라우저가
                //     다음 입력 글자를 이전 서식으로 되돌리는 것까지 막아 준다.
                const off={fontWeight:'400',fontStyle:'normal',textDecoration:''}[key];
                // textDecoration 에는 이미 다른 값(underline 등)이 있을 수 있으니
                // 토글 off 시에만 해당 토큰을 빼는 식으로 처리
                if(_caretHasStyle(key,val)){
                    if(key==='textDecoration'){
                        // 토큰 제거
                        const span=_typingSpan;
                        if(span){
                            const toks=String(span.style.textDecoration||'').split(/\s+/).filter(t=>t&&t!=='none'&&t!==val);
                            span.style.textDecoration=toks.join(' ')||'';
                            const host=span.closest&&span.closest('.tb-content');
                            if(host) _rememberTypingStyles(span,host);
                            const w=(span.closest&&span.closest('.tb'))||(_typingHost()&&_typingHost().w);
                            if(w&&w.isConnected) syncTextEl(w);
                        }
                    }else{
                        caretWrapStyle({[key]:off});
                    }
                }else{
                    // 켜기: 기존 textDecoration 에 추가
                    if(key==='textDecoration'&&_typingSpan){
                        const cur=String(_typingSpan.style.textDecoration||'').split(/\s+/).filter(t=>t&&t!=='none');
                        if(cur.indexOf(val)<0) cur.push(val);
                        _typingSpan.style.textDecoration=cur.join(' ');
                        const host=_typingSpan.closest&&_typingSpan.closest('.tb-content');
                        if(host) _rememberTypingStyles(_typingSpan,host);
                        const w=_typingSpan.closest&&_typingSpan.closest('.tb');
                        if(w&&w.isConnected) syncTextEl(w);
                    }else{
                        caretWrapStyle({[key]:val});
                    }
                }
                return;
            }
            // ③ 상자만 고른 상태 → 상자 전체에 덧씌우고, 이미 전체 적용 상태면 뺀다.
            //    (이제 상자를 클릭한 뒤 굵게/기울임/밑줄 버튼이 '안 되는' 일이 없다)
            const targets=_boxFmtTargets();
            if(targets.length){
                pushHistory();
                targets.forEach(w=>_toggleBoxAllStyle(w,spec[0],spec[1]));
                saveDoc();
                toast(targets.length>1?targets.length+'개 상자에 서식 적용':'상자 전체에 서식 적용',1000);
                setTimeout(syncCurSel,0);
                return;
            }
        }
        // ④ 안전망 — 위 어느 경로로도 처리되지 않았는데 글자 선택이 있으면 토글한다.
        //   구버전은 여기서 execCommand(bold/…) 을 썼는데, execCommand 는 환경마다
        //   선택지의 span 을 제멋대로 다시 짜는 원인이었다. v2 엔진으로 통일한다.
        if(spec&&hasInlineTextSel()){
            pushHistory();
            withSelection(()=>toggleSelStyle(spec[0],spec[1]));
            setTimeout(syncCurSel,0);
        }
    }

    // 문단 정렬 — execCommand(justify*) 없이 대상 블록에 text-align 을 직접 적는다.
    //   (justify* 는 브라우저/웹뷰마다 동작 편차가 컸다. v2 엔진 경로로 통일.)
    //   순서: ① 글자 선택 범위의 문단들 → ② 캐럿 문단 → ③ 표 칸 → ④ 선택한 상자 전체
    function setAlign(dir){
        const sel=window.getSelection();
        const live=sel&&!sel.isCollapsed&&document.querySelector('.tb.edit');
        if(live&&hasInlineTextSel()){
            pushHistory();
            withSelection(()=>_fmtAlignSelection(dir));
            toast(({left:'왼쪽',center:'가운데',right:'오른쪽'})[dir]+' 정렬',1000);
            return;
        }
        const t=_typingHost();
        if(t){
            pushHistory();
            const blk=_fmtLeafBlock(t.r.startContainer.nodeType===3?t.r.startContainer.parentElement:t.r.startContainer,t.c);
            blk.style.textAlign=dir;
            if(blk===t.c){
                const w=blk.closest&&blk.closest('.tb');
                const el=w?findEl(+w.dataset.pageIdx,w.dataset.id):null;
                if(el) el.align=dir;
            }
            const w=t.c.closest('.tb'); if(w) syncTextEl(w);
            toast(({left:'왼쪽',center:'가운데',right:'오른쪽'})[dir]+' 정렬',1000);
            return;
        }
        if(selectedTblCellEls().length){ tblCellAlign(dir); return; }
        let targets=multiSel.length
            ? multiSel.map(m=>m.node).filter(nd=>nd.classList.contains('tb'))
            : [];
        if(!targets.length) targets=Array.from(document.querySelectorAll('#pagesStage .tb.edit,#pagesStage .tb.sel'));
        if(!targets.length){ toast('텍스트 상자를 먼저 선택하세요',1300); return; }
        pushHistory();
        targets.forEach(w=>{
            const c=w.querySelector('.tb-content'); if(!c) return;
            c.style.textAlign=dir;
            const el=findEl(+w.dataset.pageIdx,w.dataset.id);
            if(el) el.align=dir;
        });
        saveDoc();
        toast(({left:'왼쪽',center:'가운데',right:'오른쪽'})[dir]+' 정렬',1000);
    }
    // ── 편집 중 '캐럿' 서식 ─────────────────────────────────────────
    // 글자 선택 없이 상자 안에서 입력 중일 때 색/글꼴/크기/볼드 등을 바꾸면
    // '상자 전체'가 아니라 '앞으로 입력될 글자'에만 적용한다.
    // 캐럿 자리에 빈 span 을 넣고 커서를 그 안에 두면 이후 입력이 span 안으로 들어간다.
    function _typingHost(){
        try{
            const s=window.getSelection();
            if(s&&s.rangeCount&&s.isCollapsed){
                const r=s.getRangeAt(0);
                const el=r.startContainer.nodeType===3?r.startContainer.parentElement:r.startContainer;
                const c=el&&el.closest&&el.closest('.tb-content');
                if(c&&c.closest('.tb').classList.contains('edit')) return {c,r};
            }
        }catch(e){}
        if(savedCaret&&savedCaret.c&&document.body.contains(savedCaret.c)){
            const w=savedCaret.c.closest('.tb');
            if(w&&w.classList.contains('edit')) return savedCaret;
        }
        return null;
    }
    // 캐럿 위치가 '이미 그 스타일' 안인가 (토글 판정용)
    function _caretHasStyle(prop,value){
        try{
            const t=_typingHost(); if(!t) return false;
            const tn=t.r.startContainer;
            let p=tn.nodeType===3?tn.parentElement:tn;
            while(p&&p!==t.c){
                const v=p.style&&p.style[prop];
                if(v&&(String(v).toLowerCase()===String(value).toLowerCase()
                    ||(prop==='fontWeight'&&(v==='bold'||Number(v)>=600)))) return true;
                p=p.parentElement;
            }
            // 상자 전체 서식(box-level)이 켜져 있으면 캐럿에서도 '켜진 상태'로 본다.
            if(t.c&&t.c.style){
                const v=t.c.style[prop];
                if(v&&(String(v).toLowerCase()===String(value).toLowerCase()
                    ||(prop==='fontWeight'&&(v==='bold'||Number(v)>=600)))) return true;
            }
        }catch(e){}
        return false;
    }
    function _typingStylesFromNode(node,host){
        const out={};
        let p=node&&(node.nodeType===3?node.parentElement:node);
        while(p&&p!==host){
            if(p.nodeType===1){
                const tag=_tagStyle(p.tagName);
                if(tag) for(const k in tag){ if(!(k in out)) out[k]=tag[k]; }
                for(const k of INLINE_STYLE_PROPS){
                    const v=p.style&&p.style[k];
                    if(v&&!(k in out)) out[k]=v;
                }
            }
            p=p.parentElement;
        }
        return out;
    }
    function _typingStylesAt(span,host){
        return _typingStylesFromNode(span,host);
    }
    function _rememberTypingStyles(span,host){
        if(!span||!host){ _pendingTyping=null; return; }
        const styles=_typingStylesAt(span,host);
        _pendingTyping=Object.keys(styles).length?{host,styles}:null;
    }
    function _restoreTypingRange(host,range){
        if(!host||!range) return false;
        try{ host.contentEditable='true'; }catch(e){}
        try{ if(document.activeElement!==host&&host.focus) host.focus({preventScroll:true}); }catch(e){}
        try{
            const s=window.getSelection();
            if(!s) return false;
            s.removeAllRanges();
            s.addRange(range);
            savedCaret={c:host,r:range.cloneRange()};
            return true;
        }catch(e){ return false; }
    }
    // 브라우저가 빈 span을 없애거나 입력 후 캐럿을 형제 위치로 옮겨도, 별도로 기억한
    // active state를 사용해 입력 직전 같은 스타일 wrapper를 다시 만든다.
    function _ensurePendingTypingSpan(host){
        const p=_pendingTyping;
        if(!p||p.host!==host||!host||!host.isConnected) return false;
        const w=host.closest&&host.closest('.tb');
        if(!w||!w.classList.contains('edit')) return false;
        const s=window.getSelection();
        if(!s||!s.rangeCount||!s.isCollapsed) return false;
        const live=s.getRangeAt(0);
        const point=live.startContainer;
        const inHost=point===host||host.contains(point);
        if(!inHost) return false;
        if(_typingSpan&&_typingSpan.isConnected&&host.contains(_typingSpan)&&
           (point===_typingSpan||_typingSpan.contains(point))){
            savedCaret={c:host,r:live.cloneRange()};
            return true;
        }
        try{
            const span=document.createElement('span');
            span.className='sdy-type';
            for(const k in p.styles) _setInlineProp(span,k,p.styles[k]);
            const r=live.cloneRange();
            r.insertNode(span);
            const nr=document.createRange(); nr.selectNodeContents(span); nr.collapse(false);
            _typingSpan=span;
            _restoreTypingRange(host,nr);
            return true;
        }catch(e){ return false; }
    }
    // 캐럿에 서식 span 삽입 (이미 같은 span 안이면 스타일만 갱신)
    function caretWrapStyle(styles){
        const t=_typingHost(); if(!t) return false;
        const c=t.c;
        try{
            const s=window.getSelection();
            const dot=tn=>tn&&(tn===_typingSpan||(_typingSpan&&_typingSpan.contains(tn)));
            // 빈 span 만 재사용한다. 이미 글자가 들어간 span 을 뒤집으면
            // '앞으로 입력될 글자'뿐 아니라 '이미 입력된 글자'까지 바뀌기 때문.
            const spanEmpty=_typingSpan&&!_typingSpan.textContent&&!_typingSpan.childElementCount;
            let span=null;
            if(spanEmpty&&_typingSpan.isConnected&&c.contains(_typingSpan)){
                const r0=s.rangeCount?s.getRangeAt(0):null;
                if(dot(r0&&r0.startContainer)) span=_typingSpan;
                else if(savedCaret&&savedCaret.c===c&&dot(savedCaret.r.startContainer)) span=_typingSpan;
            }
            if(!span){
                span=document.createElement('span');
                span.className='sdy-type';
                const src=(s.rangeCount?s.getRangeAt(0):t.r).cloneRange();
                // 14.18.4 · 도중 스타일 변경: 새 빈 span 을 만들 때도 직전까지의
                // 캐럿 서식(색·크기·굵기·밑줄·형광펜·부분 글꼴)을 모두 먼저 심어 둔다.
                // 예전엔 font-family 만 옮겨 "크기만 바꾼 뒤 다시 색 변경" 같은 흐름에서
                // 앞에서 고른 24px/굵게가 빠지는 경우가 있었다.
                const seed=(_pendingTyping&&_pendingTyping.host===c&&_pendingTyping.styles)
                    ? _pendingTyping.styles
                    : _typingStylesFromNode(src.startContainer,c);
                for(const k in seed) _setInlineProp(span,k,seed[k]);
                src.insertNode(span);
                const nr=document.createRange();
                nr.selectNodeContents(span); nr.collapse(true);
                _typingSpan=span;
                _restoreTypingRange(c,nr);
            }else{
                // 캐럿을 서식 span 안으로 되돌린다 (툴바 입력창을 쓰다 돌아와도 이어짐)
                const nr=document.createRange();
                nr.selectNodeContents(span); nr.collapse(true);
                _restoreTypingRange(c,nr);
            }
            const _removeStyleSafe=(name)=>{
                // jsdom·일부 WebView 는 camelCase removeProperty 를 무시한다.
                // kebab-case 로 지우면 브라우저·테스트 모두에서 일관되게 동작한다.
                const kebab=String(name||'').replace(/([A-Z])/g,'-$1').toLowerCase();
                try{ span.style.removeProperty(kebab); }catch(_e){}
                try{ span.style.removeProperty(name); }catch(_e){}
            };
            for(const k in styles){
                if(styles[k]===''||styles[k]==null) _removeStyleSafe(k);
                else span.style[k]=styles[k];
            }
            // 서식을 전부 지우면 빈 span 은 남길 이유가 없다 → 풀어낸다.
            //   단, 캐럿이 '이전 서식에 물리지 않도록' 만들려면 스타일이 전부 없더라도
            //   sdy-type 빈 span 을 하나 남겨 두는 편이 안전하다. 여기서는 '진짜 빈
            //   스타일' + '아직 입력 전'일 때만 지우고, '이전 서식 차단용'으로 쓴
            //   중립값(400/normal)이 남아 있으면(즉 cssText 가 있으면) 반드시 유지한다.
            if(span.classList.contains('sdy-type')&&!span.style.cssText&&!span.textContent&&!span.childElementCount){
                span.remove(); _typingSpan=null; savedCaret=null; _pendingTyping=null;
                return true;
            }
            // DOM wrapper와 별도로 이후 입력 상태를 보관한다. 새 글꼴을 고르는 등
            // wrapper가 중첩돼도 조상 bold/color까지 합쳐 다음 글자에 그대로 이어진다.
            _rememberTypingStyles(span,c);
            const w=c.closest('.tb');
            if(w&&w.isConnected) syncTextEl(w);
            return true;
        }catch(e){ return false; }
    }

    function clearBoxFormatting(w){
        const c=w&&w.querySelector&&w.querySelector('.tb-content'); if(!c) return;
        const el=findEl(+w.dataset.pageIdx,w.dataset.id); if(!el) return;
        const fs=Math.max(2,Math.min(200,Math.round(parseFloat(c.style.fontSize)||el.fontSize||curFontSize||16)));
        c.innerHTML=stripFormatting(c.innerHTML);
        c.style.fontSize=fs+'px';
        c.style.fontFamily=fontCSS('pretendard');
        ['color','background-color','font-weight','font-style','text-decoration'].forEach(p=>{
            try{ c.style.removeProperty(p); }catch(e){}
        });
        el.html=c.innerHTML;
        el.fontSize=fs;
        delete el.textColor; delete el.cellBg; delete el.font;
        delete el.fontWeight; delete el.fontStyle; delete el.textDecoration;
        try{ if(doc&&doc.pages[+w.dataset.pageIdx]) doc.pages[+w.dataset.pageIdx].__dirty=true; }catch(e){}
        syncTextEl(w);
    }

    // 서식 지우기 (고도화)
    //  - 텍스트를 드래그해 선택했으면 그 부분만
    //  - 선택이 없으면 텍스트 상자 전체 (여러 개 선택 시 전부)
    function clearFmt(){
        const host=restoreSel();
        const sel=window.getSelection();
        if(host && sel && !sel.isCollapsed){
            pushHistory();
            // 18.9 · execCommand('removeFormat') 은 브라우저/웹뷰마다 동작이 제각각이고
            //   일부 환경(구형 WebView·테스트 DOM)에는 아예 없다. 인라인 엔진으로
            //   선택 구간의 서식 속성을 하나씩 확실히 걷어낸다.
            ['fontWeight','fontStyle','textDecoration','color','backgroundColor',
             'fontFamily','fontSize','verticalAlign'].forEach(p=>{
                try{ _removeFromSelection(p); }catch(e){}
            });
            // 링크 해제도 직접 처리한다. execCommand('unlink') 가 없는 WebView/jsdom 에서도
            // 선택한 링크 글자는 남기고 <a> 만 벗겨야 한다.
            try{ _unlinkSelection(); }catch(e){}   // v2 엔진: <a> 만 벗기고 글자는 남긴다
            const w=host.closest('.tb'); if(w) syncTextEl(w);
            saveSel(); syncCurSel();
            toast('선택 영역 서식 지움',1200);
            return;
        }
        if(selectedTblCellEls().length){
            tblCellApply(el=>{
                el.html=stripFormatting(el.html||''); el.fontSize=curFontSize;
                delete el.textColor; delete el.font; delete el.fontWeight;
                delete el.fontStyle; delete el.textDecoration; delete el.cellBg;
            },'선택한 칸 글자 서식 지움');
            return;
        }
        // 18.5 · 캐럿(선택 없음) → 앞으로 입력될 글자의 서식만 지운다
        if(_typingHost()){
            caretWrapStyle({fontWeight:'',fontStyle:'',textDecoration:'',color:'',
                            backgroundColor:'',fontFamily:'',fontSize:''});
            toast('앞으로 입력될 글자 서식 지움',1000);
            return;
        }
        // 상자 단위
        let targets=[];
        if(multiSel.length) targets=multiSel.map(m=>m.node).filter(n=>n.classList.contains('tb'));
        if(!targets.length){
            targets=Array.from(document.querySelectorAll('#pagesStage .tb.edit,#pagesStage .tb.sel,#pagesStage .tb.msel'));
        }
        if(!targets.length){ toast('텍스트 상자를 선택하거나 글자를 드래그하세요',1800); return; }
        pushHistory();
        targets.forEach(w=>clearBoxFormatting(w));
        saveDoc();
        toast(`${targets.length}개 상자 서식 지움`,1400);
    }

    // 줄바꿈만 남기고 모든 서식 제거
    function stripFormatting(html){
        const box=document.createElement('div');
        box.innerHTML=html||'';
        box.querySelectorAll('br').forEach(b=>b.replaceWith('\n'));
        box.querySelectorAll('div,p,li').forEach(n=>{ n.after('\n'); });
        const text=(box.textContent||'').replace(/\n{3,}/g,'\n\n').replace(/[ \t]+\n/g,'\n').trim();
        return esc(text).replace(/\n/g,'<br>');
    }
    // 14.16 · 툴바의 글자 크기칸과 '지금 보고 있는 글자'를 맞추는 장치
    //  상자를 Alt+휠로 키우거나 다른 상자를 집었을 때 툴바 값이 낡은 채로 남아
    //  '+' 를 누르면 도로 작아지던 것을 막는다.
    function setToolbarFS(v){
        // 18.8 · 잴 대상이 없으면(0/빈 값) 툴바 값을 건드리지 않는다.
        //   예전엔 0 이 들어와도 2 로 깎여 저장되는 바람에, 아무것도 고르지 않은
        //   화면에서 '＋' 를 누르면 2 ↔ 3 만 오가는 버그가 있었다. (보고 이슈③)
        const n=Math.round(Number(v)||0);
        if(!n||n<1) return;
        v=Math.max(2,Math.min(200,n));
        const inp=document.getElementById('fsInput');
        // 같은 숫자여도 직전 상태가 mixed('-')였다면 표시를 반드시 복원한다.
        if(inp){
            inp.classList.remove('mixed'); inp.removeAttribute('aria-label');
            if(document.activeElement!==inp) inp.value=v;
        }
        if(v===curFontSize) return;
        curFontSize=v;
    }
    // 지금 글자 크기를 물어볼 대상: 표 칸 → 편집 중인 상자 → 선택한 상자
    function activeTextFS(){
        try{
            const cells=selectedTblCellEls();
            if(cells.length&&cells[0]&&cells[0].fontSize) return cells[0].fontSize;
        }catch(e){}
        let node=null;
        if(selected&&selected.type==='text'&&selected.el) node=selected.el;   // 편집 중/방금 집은 상자
        if(!node&&multiSel.length===1) node=multiSel[0].node;
        if(!node) node=document.querySelector('#pagesStage .tb.edit');
        if(!node) node=document.querySelector('#pagesStage .tb.sel');
        if(!node||!node.isConnected) return 0;
        const c=node.querySelector('.tb-content'); if(!c) return 0;
        // 화면에 실제로 그려진 크기를 우선한다 (자동 맞춤 상자도 헷갈리지 않게)
        let v=parseFloat(c.style.fontSize);
        if(!v){ try{ const el=findEl(+node.dataset.pageIdx,node.dataset.id); v=el&&el.fontSize; }catch(e){} }
        return Math.round(Number(v)||0);
    }
    // 18.8 · 같은 기준으로 '지금 대상'의 글꼴 id 도 구한다 (툴바 글꼴 동기화)
    function activeTextFont(){
        try{
            const cells=selectedTblCellEls();
            if(cells.length&&cells[0]&&cells[0].font) return cells[0].font;
        }catch(e){}
        let node=null;
        if(selected&&selected.type==='text'&&selected.el) node=selected.el;
        if(!node&&multiSel.length===1) node=multiSel[0].node;
        if(!node) node=document.querySelector('#pagesStage .tb.edit');
        if(!node) node=document.querySelector('#pagesStage .tb.sel');
        if(!node||!node.isConnected||!node.classList.contains('tb')) return '';
        try{
            const el=findEl(+node.dataset.pageIdx,node.dataset.id);
            if(el&&el.font) return el.font;
        }catch(e){}
        const c=node.querySelector('.tb-content');
        return c?_fontIdFromCSS(c.style.fontFamily||''):'';
    }
    function syncFSFromTarget(){
        setToolbarFS(activeTextFS());
        const fid=activeTextFont();
        if(fid) setToolbarFont(fid);
    }
    // 상자 안의 '일부 글자'를 드래그해 골라 둔 상태면 그쪽 크기를 기준으로 삼는다
    function hasInlineTextSel(){
        try{
            const s=window.getSelection();
            if(s&&s.rangeCount&&!s.isCollapsed){
                const r=s.getRangeAt(0);
                const n=r.commonAncestorContainer;
                const host=n.nodeType===1?n:n.parentElement;
                if(host&&host.closest&&host.closest('.tb-content')) return true;
            }
            if(savedRange&&!savedRange.collapsed&&savedHost&&document.body.contains(savedHost)) return true;
        }catch(e){}
        return false;
    }
    function chFS(d){
        if(!hasInlineTextSel()) syncFSFromTarget();   // 지금 보이는 크기에서 증감
        setFS(curFontSize + (curFontSize<=10 ? (d>0?1:-1) : d));
    }
    function setFS(v){
        curFontSize=Math.max(2,Math.min(200,Math.round(v)));
        const fsInput=document.getElementById('fsInput');
        fsInput.value=curFontSize; fsInput.classList.remove('mixed'); fsInput.removeAttribute('aria-label');
        if(selectedTblCellEls().length){
            tblCellApply(el=>{ el.fontSize=curFontSize; },`선택한 칸 글자 ${curFontSize}px`);
            return;
        }
        const host=restoreSel();
        if(host){
            pushHistory();
            try{
                withSelection(()=>wrapSelStyle('fontSize',curFontSize+'px'));
            }catch(e){}
            return;
        }
        // 18.5 · 편집 중 캐럿(선택 없음) → 상자 전체가 아니라 앞으로 입력될 글자에만
        if(_typingHost()){ caretWrapStyle({fontSize:curFontSize+'px'}); return; }
        const targets=multiSel.length
            ? multiSel.map(m=>m.node).filter(n=>n&&n.classList&&n.classList.contains('tb'))
            : [];
        const single=document.querySelector('.tb.sel,.tb.edit');
        if(!targets.length&&single) targets.push(single);
        if(targets.length){
            pushHistory();
            targets.forEach(sel=>{
                const c=sel.querySelector('.tb-content');
                const el=findEl(+sel.dataset.pageIdx,sel.dataset.id);
                if(c){
                    c.style.fontSize=curFontSize+'px';
                    // 18.8 · 상자 전체 크기는 안쪽 부분 크기보다 세다 —
                    //   서식 span 에 박제된 옛 크기를 걷어내야 실제로 커/작아진다.
                    // v2 엔진: 인라인으로 박제된 부분 크기만 새 값으로 갱신하고,
                    //   나머지는 상자 값 상속을 유지한다.
                    try{ _fmtApplyBox(c,'fontSize',curFontSize+'px',true); }catch(_e){}
                }
                if(el) el.fontSize=curFontSize;
                syncTextEl(sel);
            });
            saveDoc();
        }
    }

    // ============ 종이 / 크기 ============
    function setPaper(type){
        if(!doc) return;
        doc.paper=type;
        document.querySelectorAll('.ptool').forEach(b=>b.classList.toggle('active',b.dataset.p===type));
        editorPapers().forEach(p=>{
            p.classList.remove('paper-blank','paper-lined','paper-grid','paper-dotted');
            p.classList.add('paper-'+type);
        });
        saveDoc();
    }
    function changeSizePreset(key){
        if(!doc) return;
        doc.sizePreset=key;
        renderPages(); saveDoc();
    }

    // ============ 이미지 ============
    let _imgPickAnchor=null;   // 우클릭 '사진 넣기'로 연 경우: 그 지점(문서 좌표)
    function triggerImgUpload(anchor){
        if(penActive) finishDrawing();
        setTextTool(false); deselectAll();
        cancelPlaceMode(); if(tablePlace) cancelTablePlacement();
        _imgPickAnchor=(anchor&&Number.isFinite(anchor.x)&&Number.isFinite(anchor.y))?anchor:null;
        document.getElementById('imgInput').click();
    }
    // 파일 선택 결과: 우클릭 지점이 잡혀 있으면 그 자리에 바로, 아니면 배치 모드로.
    // 예전에는 도구막대에서 고륜 파일이 항상 쪽 한가욤데에 들어가 커서와 동떨어져 보였다.
    async function onImgPicked(input){
        const anchor=_imgPickAnchor; _imgPickAnchor=null;
        try{
            const items=await filesToImgItems(input?input.files:null);
            if(!items.length||!doc) return;
            if(anchor&&doc.pages[anchor.pageIdx]){
                for(let i=0;i<items.length;i++)
                    placeImgItem(items[i],anchor.pageIdx,anchor.x+i*16,anchor.y+i*16);
                commitImagesNow();
                toast(items.length>1?`${items.length}장을 넣었습니다`:'그림을 넣었습니다',1300);
            }else{
                beginImgPlacement(items);
            }
        }finally{ if(input) input.value=''; }
    }

    // 원본 비율 그대로 배치 (정사각 고정 제거)
    function fitBox(nw,nh){
        const s=paperSize();
        const maxW=s.w*0.5, maxH=s.h*0.4;
        let w=nw||200, h=nh||150;
        const r=Math.min(maxW/w, maxH/h, 1);
        return {w:Math.max(24,Math.round(w*r)), h:Math.max(24,Math.round(h*r))};
    }
    function imageNaturalSize(src){
        return new Promise(res=>{
            const i=new Image();
            i.onload=()=>res({w:i.naturalWidth||200,h:i.naturalHeight||150});
            i.onerror=()=>res({w:200,h:150});
            i.src=src;
        });
    }

    // ═════════ 이미지 저장 방식 v3 · 업로드-선행(단순·확실) ═════════
    // 원칙: "서버에 올라가 다시 읽힌 사진"만 노트에 존재한다.
    //   ① 사진을 넣으면 배치보다 먼저 /api/upload 로 올린다 (그동안 배지로 진행 표시).
    //   ② 서버가 준 url(/api/img/…)을 실제 GET 으로 검증한다 — "저장됐다"는
    //      말이 아니라 "다시 읽힌다"를 확인한 주소만 쓴다.
    //   ③ 요소는 그 검증된 url 로만 만든다. pending/blob:/data:/IndexedDB/
    //      백그라운드 큐/자가복구 어느 것도 새 업로드에는 없다.
    //   ④ 업로드가 실패하면 아무것도 놓지 않고 실패를 알린다 — 어떤 기기에도
    //      '깨진 자리'가 생길 수 없다 (없거나, 어디서든 보이거나 둘 중 하나).
    //   ⑤ 배치 직후 즉시 저장·즉시 push 한다 (디바운스 대기 없음).
    // 옛 저장물(data: localURL 레거시)은 렌더 호환 + 열 때 1회 재업로드로 복구한다.
    let uploadDone=0, uploadTotal=0;

    function updateUploadBadge(){
        const el=document.getElementById('uploadBadge');
        if(!el) return;
        const left=uploadTotal-uploadDone;
        if(left>0){
            el.style.display='flex';
            el.querySelector('span').textContent=`이미지 업로드 ${uploadDone}/${uploadTotal}`;
        }else{
            el.style.display='none';
            uploadDone=uploadTotal=0;
        }
    }

    // 옛 방식 data: URL → File (레거시 복구 전용)
    function dataURLToFile(dataUrl,name){
        try{
            const [head,b64]=String(dataUrl||'').split(',');
            if(!/^data:/.test(head||'')) return null;
            const mime=(head.match(/^data:([^;]+)/)||[])[1]||'image/png';
            const bin=atob(b64||'');
            const bytes=new Uint8Array(bin.length);
            for(let i=0;i<bin.length;i++) bytes[i]=bin.charCodeAt(i);
            return new File([bytes], name, {type:mime});
        }catch(e){ return null; }
    }

    // 한 장을 확실하게 올린다: 최대 3회 시도, 성공 후 반드시 재-다운로드 검증.
    // 성공 → {url,public_id} / 실패 → null (호출자는 아무것도 배치하지 않는다)
    async function uploadImageStrict(file){
        let f=file;
        for(let attempt=0;attempt<3;attempt++){
            try{
                const fd=new FormData();
                fd.append('file',f); fd.append('quality','78'); fd.append('max_width','1920');
                const r=await fetch('/api/upload',{method:'POST',body:fd});
                if(r.ok){
                    const j=await r.json().catch(()=>null);
                    const url=j&&String(j.url||'');
                    if(url&&!/^(blob|data):/i.test(url)){
                        // 검증: 준 주소가 정말 읽히는지 서버에서 다시 받아본다.
                        try{
                            const v=await fetch(url,{cache:'no-store'});
                            if(v.ok){
                                const b=await v.blob();
                                if(b&&b.size>0) return {url,public_id:j.public_id||''};
                            }
                        }catch(e){}
                    }
                }
            }catch(e){}
            // 원본이 너무 커서 실패했을 수 있다 → 두 번째 시도부터는 압축본으로.
            if(attempt===0){ try{ const c=await compressImg(f); if(c&&c.size) f=c; }catch(e){} }
            await new Promise(res=>setTimeout(res,600*(attempt+1)));
        }
        return null;
    }

    // 파일 목록 → 배치 준비물. **여기서 업로드가 끝난다.**
    // 반환된 item 은 이미 검증된 서버 주소(/api/img/…)를 갖는다.
    async function filesToImgItems(files){
        const list=Array.from(files||[]).filter(f=>f&&f.type&&f.type.startsWith('image/'));
        if(!list.length) return [];
        const items=[]; let failed=0;
        uploadTotal+=list.length; updateUploadBadge();
        for(const f of list){
            const up=await uploadImageStrict(f);
            uploadDone++; updateUploadBadge();
            if(!up){ failed++; continue; }
            const nat=await imageNaturalSize(up.url);
            items.push({url:up.url,public_id:up.public_id,box:fitBox(nat.w,nat.h)});
        }
        if(failed) toast(failed>1
            ?`사진 ${failed}장 업로드 실패 — 네트워크를 확인하고 다시 넣어 주세요`
            :'사진 업로드 실패 — 네트워크를 확인하고 다시 넣어 주세요',3200);
        return items;
    }

    // 배치를 취소한 업로드는 서버에서도 지운다 (고아 파일 방지 — 실패해도 무해)
    function discardImgItems(items){
        (items||[]).forEach(it=>{
            if(!it||!it.url) return;
            try{
                fetch('/api/delete',{method:'POST',headers:{'Content-Type':'application/json'},
                    body:JSON.stringify({url:it.url,public_id:it.public_id||''})});
            }catch(e){}
        });
    }

    // 그림 한 장을 문서 좌표 (cx,cy) 중심에 둔다. item.url 은 이미 확정 주소다.
    function placeImgItem(item,pageIdx,cx,cy){
        pushHistory();
        const c=clampEl(cx-item.box.w/2,cy-item.box.h/2,item.box.w,item.box.h);
        const el={type:'image',id:uid('i'),url:item.url,
            x:Math.round(c.x),y:Math.round(c.y),w:item.box.w,h:item.box.h};
        if(item.public_id) el.public_id=item.public_id;
        doc.pages[pageIdx].els.push(el);
        renderPageEls(pageIdx);
        return el;
    }

    // 배치 직후: 로컬 저장·서버 memo·요소 op 를 디바운스 없이 바로 확정한다.
    function commitImagesNow(){
        try{ flushSaveDoc(); }catch(e){ try{ saveDoc(); }catch(e2){} }
        try{ clearTimeout(opsTimer); pushOps(); }catch(e){}
        try{ if(pendingNB) flushSync(); }catch(e){}
    }

    async function uploadImgs(files,atPoint){
        if(!doc||!curNB) return;
        const _d0=doc,_nb0=curNB.id;
        const items=await filesToImgItems(files);      // ← 업로드-선행
        if(!items.length) return;
        // 업로드 대기 중 노트가 바뀌었으면 엉뚱한 노트에 놓지 않는다.
        if(doc!==_d0||!curNB||curNB.id!==_nb0){ discardImgItems(items); return; }
        const s=paperSize();
        for(let i=0;i<items.length;i++){
            const it=items[i];
            if(atPoint){
                // 붙여넣기면 마우스 위치에 연달아 살짝씩 어긋나게
                const pt=pastePoint(it.box.w,it.box.h);
                placeImgItem(it,pt.pageIdx,pt.x+it.box.w/2+i*16,pt.y+it.box.h/2+i*16);
            }else{
                // 지정 지점이 없으면 현재 페이지 위쪽에 차례로
                placeImgItem(it,curPageIdx,s.w/2,60+i*24+it.box.h/2);
            }
        }
        commitImagesNow();
        const inp=document.getElementById('imgInput'); if(inp) inp.value='';
    }

    // ── 레거시 복구: 옛 저장물에 남은 data: 원본(pending)을 열 때 1회 재업로드 ──
    //   새 방식에서는 생길 수 없는 상태다. 복구도 같은 확실한 경로(uploadImageStrict)로만 한다.
    const _legacyImgFixed=new Set();
    async function repairLegacyImages(){
        if(!doc||!curNB) return;
        const _d0=doc,_nb0=curNB.id;
        const jobs=[];
        (doc.pages||[]).forEach((pg,pi)=>((pg&&pg.els)||[]).forEach(el=>{
            if(!el||el.type!=='image'||_imgRealURL(el)) return;
            const l=String(el.localURL||'');
            if(!l.startsWith('data:image/')) return;
            if(_legacyImgFixed.has(el.id)) return;
            jobs.push({id:el.id,dataUrl:l});
        }));
        if(!jobs.length) return;
        let fixed=0;
        for(const job of jobs){
            if(doc!==_d0||!curNB||curNB.id!==_nb0) return;
            _legacyImgFixed.add(job.id);
            const f=dataURLToFile(job.dataUrl,`repair-${job.id}.png`);
            if(!f) continue;
            const up=await uploadImageStrict(f);
            if(!up){ _legacyImgFixed.delete(job.id); continue; }
            if(doc!==_d0||!curNB||curNB.id!==_nb0) return;
            const loc=findElLoc(job.id); if(!loc) continue;
            const el=doc.pages[loc.i].els[loc.k];
            el.url=up.url; if(up.public_id) el.public_id=up.public_id;
            delete el.pending; delete el.failed; delete el.localURL;
            fixed++;
            if(renderedPages.has(loc.i)){ try{ renderPageEls(loc.i); }catch(e){} }
            try{
                doc.__lastHash.set(el.id,JSON.stringify(el));
                const rev=_nbNow(); doc.__localRev.set(el.id,rev);
                pushOpsFor(_nb0,[{id:el.id,kind:'put',page:loc.i,rev,data:serverImageElement(el),dev:SYNC_DEV}]);
            }catch(e){}
        }
        if(fixed) commitImagesNow();
    }

    function compressImg(file){
        return new Promise(resolve=>{
            if(file.size<500000&&/jpe?g/.test(file.type)){ resolve(file); return; }
            const r=new FileReader();
            r.onload=e=>{
                const img=new Image();
                img.onload=()=>{
                    const c=document.createElement('canvas');
                    let w=img.width,h=img.height;
                    if(w>1920){h=Math.round(h*1920/w);w=1920;}
                    if(h>1920){w=Math.round(w*1920/h);h=1920;}
                    c.width=w;c.height=h;
                    c.getContext('2d').drawImage(img,0,0,w,h);
                    if(file.type==='image/png') c.toBlob(b=>resolve(new File([b],file.name||'image.png',{type:'image/png'})),'image/png');
                    else c.toBlob(b=>resolve(new File([b],(file.name||'image').replace(/\.\w+$/,'')+'.jpg',{type:'image/jpeg'})),'image/jpeg',0.85);
                };
                img.onerror=()=>resolve(file);
                img.src=e.target.result;
            };
            r.onerror=()=>resolve(file);
            r.readAsDataURL(file);
        });
    }

    // 붙여넣기
    document.addEventListener('paste',async e=>{
        if(!doc||!document.getElementById('editorView').classList.contains('open')) return;
        if(document.querySelector('.tb.edit')) return;   // 텍스트 편집 중엔 기본 동작
        // 입력칸(해돌이 검색창 #aiQ · 찾기칸 · 설정 입력칸…)에 붙여넣을 때는
        //   노트에 글상자를 만들지 않는다 — 안 그러면 칸에 붙여야 할 글이
        //   노트 한가운데 상자로 생기면서 정작 칸에는 아무것도 안 들어간다.
        {
            const _tag=((document.activeElement||{}).tagName)||'';
            if(_tag==='INPUT'||_tag==='TEXTAREA'||_tag==='SELECT') return;
        }

        const files=[];
        const items=e.clipboardData?.items||[];
        for(const it of items){
            if(it.type&&it.type.startsWith('image/')){
                const f=it.getAsFile();
                if(f) files.push(new File([f],`paste-${Date.now()}.${(it.type.split('/')[1]||'png')}`,{type:it.type}));
            }
        }
        if(files.length){
            e.preventDefault();
            await uploadImgs(files,true);      // 마우스 위치에 배치
            return;
        }

        // 텍스트 붙여넣기 → 자동으로 텍스트 상자 생성
        const html=e.clipboardData?.getData('text/html');
        const plain=e.clipboardData?.getData('text/plain');
        // 18.9 · 앱에서 복사한 상자를 그대로 붙여넣기 (글꼴·크기·서식·크기 유지)
        if(clipboardEls.length&&plain&&_lastCopyText&&plain.trim()===_lastCopyText.trim()){
            e.preventDefault(); pasteElements(); return;
        }
        if(plain&&plain.trim()){
            e.preventDefault();
            let content;
            if(html&&html.trim()){
                const box=document.createElement('div');
                box.innerHTML=html;
                box.querySelectorAll('script,style,meta,link').forEach(n=>n.remove());
                box.querySelectorAll('*').forEach(n=>{
                    // 서식은 색/굵기/기울임/밑줄/배경만 유지
                    const c=n.style.color,bg=n.style.backgroundColor,
                          fw=n.style.fontWeight,fs=n.style.fontStyle,td=n.style.textDecoration;
                    n.removeAttribute('style'); n.removeAttribute('class'); n.removeAttribute('id');
                    if(c) n.style.color=c;
                    if(bg&&bg!=='transparent'&&!/rgba\(0, 0, 0, 0\)/.test(bg)) n.style.backgroundColor=bg;
                    if(fw&&(fw==='bold'||+fw>=600)) n.style.fontWeight='bold';
                    if(fs==='italic') n.style.fontStyle='italic';
                    if(td&&td.includes('underline')) n.style.textDecoration='underline';
                });
                content=box.innerHTML;
            }else{
                content=esc(plain).replace(/\n/g,'<br>');
            }
            // 글자 수에 따라 상자 크기 어림
            const s=paperSize();
            const lines=plain.split(/\n/).length;
            const w=Math.min(s.w-96, Math.max(220, Math.min(560, plain.length*11)));
            const h=Math.min(s.h-96, Math.max(52, lines*(curFontSize*1.5)+26));
            const pt=pastePoint(w,h);
            pushHistory();
            const el={type:'text',id:uid('t'),x:pt.x,y:pt.y,w:Math.round(w),h:Math.round(h),
                      html:content,fontSize:curFontSize,font:curFont};
            doc.pages[pt.pageIdx].els.push(el);
            renderPageEls(pt.pageIdx);
            saveDoc();
            const node=paperQ(pt.pageIdx,`.tb[data-id="${el.id}"]`);
            if(node){ deselectAll(); node.classList.add('sel'); selected={type:'text',el:node}; }
            toast('텍스트 붙여넣음',1200);
            return;
        }
        // OS 클립보드가 비어 있으면 앱 내부에서 복사한 요소를 붙여넣기
        if(clipboardEls.length){ e.preventDefault(); pasteElements(); }
    });

    // ============ 내보내기 ============
    const dataUrlCache=new Map();
    async function toDataURL(url){
        if(!url||url.startsWith('data:')) return url||'';
        if(dataUrlCache.has(url)) return dataUrlCache.get(url);
        const p=(async()=>{
            try{
                const r=await fetch(url,{mode:'cors',cache:'force-cache'});
                if(r.ok){
                    const b=await r.blob();
                    return await new Promise((res,rej)=>{const fr=new FileReader();fr.onload=()=>res(fr.result);fr.onerror=rej;fr.readAsDataURL(b);});
                }
            }catch(e){}
            try{
                const im=new Image(); im.crossOrigin='anonymous';
                await new Promise((res,rej)=>{im.onload=res;im.onerror=rej;im.src=url;});
                const c=document.createElement('canvas');
                c.width=im.naturalWidth;c.height=im.naturalHeight;
                c.getContext('2d').drawImage(im,0,0);
                return c.toDataURL('image/png');
            }catch(e){ return ''; }
        })();
        dataUrlCache.set(url,p); return p;
    }

    function paperCSSForExport(type){
        if(type==='lined') return 'background-color:#fff;background-image:repeating-linear-gradient(transparent,transparent 31px,#e8e8e8 31px,#e8e8e8 32px);background-position:0 16px;';
        if(type==='grid') return 'background-color:#fff;background-image:linear-gradient(#e8e8e8 1px,transparent 1px),linear-gradient(90deg,#e8e8e8 1px,transparent 1px);background-size:32px 32px;';
        if(type==='dotted') return 'background-color:#fff;background-image:radial-gradient(circle,#cfcfcf 1px,transparent 1px);background-size:24px 24px;';
        return 'background-color:#fff;';
    }

    // 페이지 1장을 캔버스로 (화면 배율과 무관하게 항상 원본 크기)
    // HTML → XHTML 로 정규화.
    // foreignObject 는 '엄격한 XML' 만 받는다. contentEditable 이 만드는
    // <br>, &nbsp;, 안 닫힌 태그 때문에 내보내기가 통째로 실패하던 문제를 여기서 차단한다.
    function htmlToXhtml(html){
        const box=document.createElement('div');
        box.innerHTML=html||'';
        // XMLSerializer 는 항상 well-formed XML 을 만들어 준다
        let xml=new XMLSerializer().serializeToString(box);
        xml=xml.replace(/^<div[^>]*>/,'').replace(/<\/div>$/,'');
        // 숫자 참조만 남기고 명명 엔티티(&nbsp; 등)는 XML 에서 미정의라 치환
        xml=xml.replace(/&nbsp;/g,'\u00a0');
        return xml;
    }
    function escXml(t){
        return String(t==null?'':t)
            .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
            .replace(/"/g,'&quot;');
    }

    async function svgToImage(svg){
        const url='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);
        const img=new Image();
        await new Promise((res,rej)=>{
            img.onload=res;
            img.onerror=()=>rej(new Error('svg render fail'));
            img.src=url;
        });
        if(img.decode){ try{ await img.decode(); }catch(e){} }
        return img;
    }

    // 다크모드에서 저장된 밝은 글자색을 인쇄용으로 어둡게 보정
    function fixDarkColors(html){
        if(!html) return html;
        const box=document.createElement('div');
        box.innerHTML=html;
        box.querySelectorAll('[style]').forEach(n=>{
            const c=n.style.color;
            if(!c) return;
            const m=c.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
            if(m){
                const lum=(+m[1]*0.299 + +m[2]*0.587 + +m[3]*0.114);
                if(lum>210) n.style.color='#111111';   // 흰색 계열 → 검정
            }else if(/^#(fff|ffffff|eee|eeeeee)$/i.test(c.trim())){
                n.style.color='#111111';
            }
        });
        return box.innerHTML;
    }

    // ===== 선택한 것들을 스티커(SVG 벡터)로 만들기 =====
    // 14.16.7 · PNG 래스터 대신 SVG 로 굽는다 — 아무리 확대해도 선·글자가 깨지지 않는다.
    //   내보내기·화면 렌더가 검증된 조립을 그대로 쓴다:
    //     · 펜 획  → <path>      (화면 렌더와 같은 strokePath 지오메트리)
    //     · 글자   → <foreignObject> + htmlToXhtml (서식 유지)
    //     · 이미지 → <image>     (가능하면 data: 로 인라인 — SVG 안에서는 외부 참조가 안 열린다)
    //     · 수식   → KaTeX HTML (화면과 같은 마크업)
    //   SVG 굽기가 실패하면 예전 캔버스 PNG 경로로 저장한다(폴백).
    async function bakeStickerSVG(items,pi,rx,ry,rw,rh){
        const ids=new Set(items.map(i=>i.id));
        const list=(doc.pages[pi].els||[]).filter(e=>ids.has(e.id));
        let drew=0, imgs='', paths='', body='';
        for(const el of list){
            if(el.type==='image'&&el.url){
                // SVG 는 <img> 로 열면 외부 그림을 못 가져오므로 data: 로 인라인한다
                const href=await toDataURL(el.url);
                if(!href) continue;
                imgs+=`<image x="${el.x}" y="${el.y}" width="${el.w}" height="${el.h}"`+
                      ` href="${escXml(href)}" xlink:href="${escXml(href)}"/>`;
                drew++;
            }else if(el.type==='stroke'){
                const d=strokePath(el.pts, el.sharp&&!isEllipsePts(el.pts));
                if(!d) continue;
                paths+=`<path d="${d}" fill="none" stroke="${escXml(el.color||'#111111')}"`+
                       ` stroke-width="${el.size||2}" stroke-linecap="round" stroke-linejoin="round"`+
                       ((el.dx||el.dy)?` transform="translate(${el.dx||0},${el.dy||0})"`:'')+
                       (el.opacity!=null?` opacity="${el.opacity}"`:'')+`/>`;
                drew++;
            }
        }
        // 글자·수식 — 내보내기와 같은 foreignObject 조립 (좌표는 스티커 영역 기준)
        const texts=list.filter(e=>e.type==='text'&&(e.html||'').trim());
        const formulas=list.filter(e=>e.type==='latex'&&(e.latex||'').trim());
        texts.forEach(el=>{
            const inner=el.tight
                ? `width:100%;height:100%;padding:0;box-sizing:border-box;`+
                  `font-size:${el.fontSize||16}px;line-height:1;color:${el.__c||'#111111'};`+
                  `overflow:visible;font-family:${fontCSS(el.font||'pretendard')};`+
                  `text-align:${el.align||'left'};position:relative;`
                : `width:100%;height:100%;padding:8px 12px;box-sizing:border-box;`+
                  `font-size:${el.fontSize||16}px;line-height:1.5;color:${el.__c||'#111111'};white-space:pre-wrap;`+
                  `word-break:break-word;overflow:hidden;font-family:${fontCSS(el.font||'pretendard')};`+
                  `text-align:${el.align||'left'};`;
            body+=`<div style="position:absolute;left:${el.x-rx}px;top:${el.y-ry}px;width:${el.w}px;height:${el.h}px;">`+
                  `<div style="${inner}">`+
                  htmlToXhtml(fixDarkColors(imathExpandHtml(el.html)))+`</div></div>`;
            drew++;
        });
        formulas.forEach(el=>{
            let mh;
            try{ mh=window.katex?katex.renderToString(el.latex||'',{displayMode:!!el.displayMath,throwOnError:false,strict:'ignore',output:'html'}):esc(el.latex||''); }
            catch(e){ mh=esc(el.latex||''); }
            const imp=!!el.imported;
            const bw=imp?(el.inkW||el.w):el.w, bh=imp?(el.inkH||el.h):el.h;
            const k=imp?Math.min(1,(latexFitScale(el)||1)):1;
            const fs=Math.max(6,(el.fontSize||20)*k);
            body+=`<div style="position:absolute;left:${el.x-rx}px;top:${el.y-ry}px;width:${bw}px;height:${bh}px;`+
                  `display:flex;align-items:center;${el.displayMath?'justify-content:center;':''}font-size:${fs}px;`+
                  `line-height:1.05;font-family:'Times New Roman',serif;color:#111;`+
                  `overflow:${imp?'hidden':'visible'};">${htmlToXhtml(mh)}</div>`;
            drew++;
        });
        if(!drew) throw new Error('스티커로 만들 내용이 없다');
        const svg=`<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink"`+
            ` width="${Math.max(1,Math.round(rw))}" height="${Math.max(1,Math.round(rh))}" viewBox="${rx} ${ry} ${rw} ${rh}">`+
            imgs+paths+
            (body?`<foreignObject x="${rx}" y="${ry}" width="${rw}" height="${rh}">`+
                  `<div xmlns="http://www.w3.org/1999/xhtml" style="width:${rw}px;height:${rh}px;position:relative;">${body}</div>`+
                  `</foreignObject>`:'')+
            `</svg>`;
        return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);
    }
    async function makeSticker(){
        const items=selEntries();
        if(!items.length){ toast('먼저 요소를 선택해 주세요',1800); return; }
        const pi=items[0].pageIdx;
        const bb=unionBBox(items,pi);
        if(!bb||bb.w<2||bb.h<2){ toast('선택 영역이 너무 작습니다',1800); return; }

        const pad=8;
        const rx=Math.max(0,Math.round(bb.x-pad)), ry=Math.max(0,Math.round(bb.y-pad));
        const rw=Math.round(bb.w+pad*2), rh=Math.round(bb.h+pad*2);
        toast('스티커를 만드는 중…',1200);
        let url='', isSvg=true;
        try{
            url=await bakeStickerSVG(items,pi,rx,ry,rw,rh);
        }catch(e){ console.warn('SVG 스티커 굽기 실패 → PNG 폴백',e); }
        if(!url){
            // 폴백: 예전 캔버스 PNG 굽기 — SVG 를 못 만드는 환경에서도 스티커는 남는다
            try{
                const ids=new Set(items.map(i=>i.id));
                const full=await renderPageCanvas(pi,{onlyIds:ids,transparent:true});
                const sc=full.width/paperSize().w;
                const out=document.createElement('canvas');
                out.width=Math.max(1,Math.round(rw*sc));
                out.height=Math.max(1,Math.round(rh*sc));
                const octx=out.getContext('2d');
                octx.drawImage(full, Math.round(rx*sc), Math.round(ry*sc),
                                     out.width, out.height,
                                     0,0, out.width, out.height);
                url=out.toDataURL('image/png'); isSvg=false;
            }catch(e){
                console.error(e); toast('스티커 만들기 실패',2200); return;
            }
        }

        // 14.18.4 · "스티커로 만들기"는 이제 종이에 한 번 붙였다가 저장하는 동작이 아니라,
        //   보관함에만 바로 넣는다. 원본 선택 요소는 그대로 두고, 필요할 때 사용자가
        //   보관함에서 다시 골라 붙인다.
        try{
            const r=await fetch('/api/stickers/save',{method:'POST',
                headers:{'Content-Type':'application/json'},
                body:JSON.stringify({data:url,name:'스티커'})});
            const d=await r.json().catch(()=>null);
            if(!r.ok||!d||!d.ok){
                toast('스티커 보관함 저장 실패',2200);
                return;
            }
            toast(isSvg
                ? '스티커함에 저장됨 · 벡터라 확대해도 안 깨져요'
                : '스티커함에 저장됨 · 보관함에서 꺼내 쓸 수 있어요',2600);
        }catch(e){
            console.error(e);
            toast('스티커 보관함 저장 실패',2200);
        }
    }

    // 노트 정보 (용량·페이지·시간)
    function showNoteInfo(nb){
        const cfg=getCfg(nb.id);
        const d=loadDoc(nb.id);
        let bytes=0;
        try{ bytes=new Blob([localStorage.getItem('nb_'+nb.id)||'']).size; }catch(e){}
        const els=(d.pages||[]).reduce((t,p)=>t+((p.els||[]).length),0);
        const imgs=(d.pages||[]).reduce((t,p)=>t+((p.els||[]).filter(e=>e.type==='image').length),0);
        const txts=(d.pages||[]).reduce((t,p)=>t+((p.els||[]).filter(e=>e.type==='text').length),0);
        const strs=(d.pages||[]).reduce((t,p)=>t+((p.els||[]).filter(e=>e.type==='stroke').length),0);
        const fmtT=(v)=>v?new Date(v).toLocaleString('ko-KR',
            {year:'numeric',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'}):'-';
        const peers=livePeerCount[nb.id]||0;
        const row=(k,v)=>`<div style="display:flex;justify-content:space-between;gap:16px;
            padding:7px 0;border-bottom:1px solid var(--border);">
            <span style="color:var(--text3);font-size:12.5px;">${k}</span>
            <span style="font-size:12.5px;font-weight:600;text-align:right;">${v}</span></div>`;
        const m=document.getElementById('infoModal');
        document.getElementById('infoBody').innerHTML=
            row('제목',esc(nb.title||'제목 없음'))+
            row('용량',fmtBytes(bytes))+
            row('페이지',(d.pages||[]).length+'쪽')+
            row('요소',`${els}개 (글 ${txts} · 그림 ${imgs} · 펜 ${strs})`)+
            row('종이',({blank:'빈 종이',lined:'줄 노트',grid:'격자',dotted:'도트'})[d.paper]||d.paper)+
            row('만든 날짜',fmtT(nb.created_at))+
            row('마지막 수정',fmtT(nb.updated_at||nb.created_at))+
            row('잠금',(cfg.lock&&cfg.lock.enc)?'🔒 설정됨':'없음')+
            (peers>1?row('현재 접속',peers+'명이 함께 보는 중'):'');
        m.style.display='flex';
        openNav(closeNoteInfo);
    }
    function closeNoteInfo(){ document.getElementById('infoModal').style.display='none'; navDrop(closeNoteInfo); }

    // ============ 스티커 보관함 ============
    let stickerList=[];
    // 빈 종이 우클릭 → '스티커 넣기' 로 열었을 때 그 자리(pageIdx·문서 px).
    // 툴바로 열면 null — 스티커를 기본 자리(80,100)에 붙인다.
    let _stickerAnchor=null;
    async function openStickers(){
        document.getElementById('stickerModal').style.display='flex';
        openNav(closeStickers);
        const box=document.querySelector('#stkList .vault-grid');
        box.innerHTML='<div class="vault-empty">불러오는 중…</div>';
        try{
            const r=await fetch('/api/stickers/list',{cache:'no-store'});
            const d=await r.json();
            stickerList=(d&&d.stickers)||[];
            renderStickers();
        }catch(e){ box.innerHTML='<div class="vault-empty">서버에 연결할 수 없습니다</div>'; }
    }
    function closeStickers(){
        document.getElementById('stickerModal').style.display='none';
        _stickerAnchor=null;                 // 닫으면 기억한 자리도 버린다
        navDrop(closeStickers);
    }
    function renderStickers(){
        const box=document.querySelector('#stkList .vault-grid');
        document.getElementById('stkCount').textContent=
            stickerList.length?stickerList.length+'개':'';
        if(!stickerList.length){
            box.innerHTML='<div class="vault-empty"><i class="ri-sticky-note-line"></i>'+
                '스티커가 없습니다<br><span style="font-size:11.5px">'+
                '여러 개를 선택하고 우클릭 → 스티커로 만들기</span></div>';
            return;
        }
        box.innerHTML=stickerList.map(s=>
            `<div class="v-file" title="${esc(s.name||'')}" onclick="useSticker('${s.id}')"
                  oncontextmenu="event.preventDefault();delSticker('${s.id}')">
                <img class="v-thumb" src="${esc(s.url)}" alt="" loading="lazy">
                <div class="v-name">${esc(s.name||'스티커')}</div>
                <div class="v-size">${fmtBytes(s.bytes||0)}</div>
            </div>`).join('');
    }
    function useSticker(id){
        const s=stickerList.find(x=>x.id===id); if(!s) return;
        if(!doc){ toast('노트를 먼저 열어주세요',1800); return; }
        const im=new Image();
        im.onload=()=>{
            pushHistory();
            // SVG 스티커는 내부 크기(width/height 속성)가 곧 자연 크기다 —
            // 못 구하면 기본 300px 폭으로 시작해도 벡터라 확대 시 깨지지 않는다
            const iw=Math.max(1,im.width||0), ih=Math.max(1,im.height||0);
            const sc=Math.min(1,300/Math.max(iw,ih));
            const w=Math.round(iw*sc)||300, h=Math.round(ih*sc)||200;
            // 우클릭 자리를 기억한 상태(빈 종이 → 스티커 넣기)면 그 자리 중앙에 붙이고,
            // 아니면(툴바) 기본 자리에 붙는다. 우클릭한 페이지에 붙는다.
            let pi=curPageIdx, x=80, y=100;
            if(_stickerAnchor&&doc.pages[_stickerAnchor.pageIdx]){
                pi=_stickerAnchor.pageIdx;
                const c=clampEl(_stickerAnchor.x-w/2,_stickerAnchor.y-h/2,w,h);
                x=Math.round(c.x); y=Math.round(c.y);
            }
            doc.pages[pi].els.push({type:'image',id:uid('i'),url:s.url,
                x,y,w,h,sticker:true});
            renderPageEls(pi); saveDoc();
            closeStickers(); toast('스티커를 붙였습니다',1600);
        };
        im.onerror=()=>toast('스티커를 불러오지 못했습니다',2000);
        im.src=s.url;
    }
    async function delSticker(id){
        const s=stickerList.find(x=>x.id===id); if(!s) return;
        if(!confirm('이 스티커를 보관함에서 지울까요?')) return;
        try{
            await fetch('/api/stickers/delete',{method:'POST',
                headers:{'Content-Type':'application/json'},
                body:JSON.stringify({id})});
            stickerList=stickerList.filter(x=>x.id!==id);
            renderStickers(); toast('삭제됨',1400);
        }catch(e){ toast('삭제 실패',1800); }
    }

    // ============ 자동 번역 (영어 <-> 한국어) ============
    // ---- 번역 작업 중단(취소) ----
    // 진행 중인 번역은 진행바의 [중단] 버튼이나 Esc 로 언제든 멈출 수 있다.
    // 취소는 '실패'가 아니므로 별도 신호(TR_CANCEL)를 던져 '번역 실패' 토스트나
    // 긴 재시도 로직과 섞이지 않게 한다. 이 신호 덕분에 "무한 로딩" 도 없다.
    const TR_CANCEL='번역 중단됨';   // 낮은 수준 신호 — 실패 문구/재시도 정규식과 절대 겹치지 않게
    let trCtl=null;                  // 실행 중인 번역 작업의 AbortController (한 번에 하나)
    let trCancel=false;              // 사용자가 중단을 눌렀는가
    function cancelTranslation(){
        if(!trCtl||trCancel) return;
        trCancel=true;
        try{ trCtl.abort(); }catch(e){}
        const p=document.getElementById('trProg');
        const l=p&&p.querySelector('.tr-label');
        if(p&&p.style.display!=='none'&&l) l.textContent='번역을 중단하는 중…';
    }
    function beginTrTask(){
        if(trCtl) endTrTask();       // 방어: 이전 작업 꼬리 정리
        trCtl=new AbortController(); trCancel=false;
        document.addEventListener('keydown',trEscKey,true);
    }
    function endTrTask(){
        if(trCtl) document.removeEventListener('keydown',trEscKey,true);
        trCtl=null;
        hideTrProg();
    }
    function trEscKey(e){
        if(e.key==='Escape'&&trCtl){
            e.preventDefault(); e.stopPropagation();
            cancelTranslation();
        }
    }
    // 중단하면 재시도 대기·간격 유지 잠도 바로 깬다 (취소가 대기 시간만큼 늦어지지 않게)
    function trSleep(ms){
        return new Promise(res=>{
            const ctl=trCtl;
            const t=setTimeout(fin,ms);
            function fin(){ clearTimeout(t); if(ctl) ctl.signal.removeEventListener('abort',fin); res(); }
            if(ctl){
                if(ctl.signal.aborted||trCancel) fin();
                else ctl.signal.addEventListener('abort',fin);
            }
        });
    }
    async function apiTranslate(text,target,gloss){
        // 프록시/서버가 잠깐 끊긴 경우 한 번만 재시도한다. 무한 재시도는
        // 사용자가 취소할 수 없고 무료 번역 엔진의 429를 더 악화시킨다.
        let last;
        for(let attempt=0;attempt<2;attempt++){
            if(trCancel) throw new Error(TR_CANCEL);
            const ctl=new AbortController();
            const task=trCtl;                       // 이 요청을 거는 작업 핸들
            const timer=setTimeout(()=>ctl.abort(),30000);
            // 사용자 중단 → 이 요청도 즉시 끊는다 (30초 타임아웃을 기다리지 않는다)
            const kick=()=>{ try{ctl.abort();}catch(e){} };
            if(task){
                if(task.signal.aborted){ clearTimeout(timer); throw new Error(TR_CANCEL); }
                task.signal.addEventListener('abort',kick);
            }
            try{
                const r=await fetch('/api/translate',{method:'POST',signal:ctl.signal,
                    headers:{'Content-Type':'application/json','Accept':'application/json'},
                    body:JSON.stringify({text,target,gloss:gloss||undefined})});
                const d=await r.json().catch(()=>({}));
                if(r.ok&&d.ok&&typeof d.text==='string') return d.text;
                // 4xx와 제한 응답은 재시도해도 성공하지 않는다.
                const msg=d.error||('번역 요청 실패 ('+r.status+')');
                if(r.status<500||/제한|429/.test(msg)) throw new Error(msg);
                last=new Error(msg);
            }catch(e){
                if(trCancel) throw new Error(TR_CANCEL);
                last=e&&e.name==='AbortError'?new Error('번역 서버 응답 시간이 초과됐어요. 잠시 후 다시 시도해 주세요.'):e;
                if(/제한|429|문자열이어야|내용이 없습니다|5000자/.test(String(last&&last.message||''))) throw last;
            }finally{
                clearTimeout(timer);
                if(task) task.signal.removeEventListener('abort',kick);
            }
            if(attempt===0) await trSleep(700);
            if(trCancel) throw new Error(TR_CANCEL);
        }
        throw last||new Error('번역 서버에 연결할 수 없습니다. 잠시 후 다시 시도해 주세요.');
    }

    async function persistTranslatedChange(){
        // 로컬 저장은 즉시 예약하고, 가져온 문서는 원격 슬라이스 저장까지 완료한 뒤
        // 성공 안내를 낸다. 따라서 다시 열었을 때 원문으로 돌아가지 않는다.
        saveDoc(); queueOps();
        try{ flushSaveDoc(); await flushImportedSave(); }
        catch(e){ throw new Error('번역 결과를 저장하지 못했어요. 네트워크를 확인해 주세요.'); }
    }

    // 텍스트 상자 전체 번역 (서식은 유지하기 어려우므로 글자만 바꾼다)
    // 가져온(tight) 상자는 innerText 가 절대스팬 사이를 줄바꿈으로 잇기 때문에
    // 줄/단어 구조를 살린 클린 텍스트를 만들고, 결과도 가지런한 일반 상자로 변환.
    // tight 상자의 단어 스팬을 '시각적 읽기 순서'로 정렬한다.
    // PDF 가져오기에서 스팬은 절대좌표로 배치되므로 DOM 순서 ≠ 눈에 보이는 순서.
    // → 위(top)에서 아래로, 같은 줄은 왼쪽(left)에서 오른쪽으로 정렬해야
    //   복사·번역·검색 때 글자 순서와 띄어쓰기가 정확해진다.
    function tightSpansSorted(host){
        const sps=Array.from(host.querySelectorAll(':scope>span'));
        const num=(v)=>{ const n=parseFloat(v); return isNaN(n)?0:n; };
        const pos=(s)=>[num(s.style.top), num(s.style.left)];
        // inline top/left 가 없으면 offsetTop/offsetLeft 로 대체 (옛 노트 호환)
        const noInline=sps.some(s=>s.style.left===''&&s.style.top==='');
        sps.sort((a,b)=>{
            const [at,al]=pos(a), [bt,bl]=pos(b);
            if(noInline){
                const aot=a.offsetTop||0, bot=b.offsetTop||0;
                if(Math.abs(aot-bot)>2) return aot-bot;
                return (a.offsetLeft||0)-(b.offsetLeft||0);
            }
            if(Math.abs(at-bt)>2) return at-bt;
            return al-bl;
        });
        return sps;
    }
    function tightCleanText(c){
        const sps=tightSpansSorted(c);
        const num=(v)=>{ const n=parseFloat(v); return isNaN(n)?0:n; };
        const topOf=(s)=>num(s.style.top)||s.offsetTop||0;
        const lines=[]; let cur=[]; let lastTop=null;
        sps.forEach(s=>{
            const t=(s.textContent||'').replace(/[\s\u00a0\u200b\ufeff]+$/,'');
            if(!t) return;
            const top=topOf(s);
            if(lastTop!=null&&Math.abs(top-lastTop)>2){
                lines.push(cur.join(' ')); cur=[];
            }
            cur.push(t); lastTop=top;
        });
        if(cur.length) lines.push(cur.join(' '));
        return lines.join('\n');
    }
    // 선택 범위에서 공백을 '재조립' (zsp 유무·옛 노트 무관):
    // 선택과 교차하는 단어 스팬을 시각 순서로 정렬한 뒤 줄 단위로 묶어 공백으로 잇는다.
    function tightSelectionText(sel){
        try{
            if(!sel||!sel.rangeCount) return String(sel||'');
            const rng=sel.getRangeAt(0);
            const rootEl=(sel.anchorNode&&sel.anchorNode.nodeType===1)
                ? sel.anchorNode : (sel.anchorNode&&sel.anchorNode.parentElement);
            const host=rootEl&&rootEl.closest('.tb-content');
            if(!host||!host.closest('.tight')) return String(sel);
            const spans=tightSpansSorted(host).filter(s=>{
                try{ return rng.intersectsNode(s); }catch(e){ return false; }
            });
            if(!spans.length) return String(sel);
            const num=(v)=>{ const n=parseFloat(v); return isNaN(n)?0:n; };
            const topOf=(s)=>num(s.style.top)||s.offsetTop||0;
            const lines=[]; let cur=[]; let lastTop=null;
            spans.forEach(s=>{
                const t=(s.textContent||'').replace(/[\s\u00a0\u200b\ufeff]+$/,'');
                if(!t) return;
                const top=topOf(s);
                if(lastTop!=null&&Math.abs(top-lastTop)>2){
                    lines.push(cur.join(' ')); cur=[];
                }
                cur.push(t); lastTop=top;
            });
            if(cur.length) lines.push(cur.join(' '));
            return lines.join('\n');
        }catch(e){ return String(sel||''); }
    }
    async function translateElement(node,target){
        closeCtxMenu();
        const pi=+node.dataset.pageIdx;
        const el=findEl(pi,node.dataset.id);
        if(!el||el.type!=='text'){ toast('텍스트 상자를 선택해 주세요',1800); return; }
        const c=node.querySelector('.tb-content');
        const isTight=node.classList.contains('tight');
        // 번역기는 뉴라인을 줄바꿈/문장 끝으로 취급하므로 공백으로 이어
        // 마침표 기준의 자연스러운 문장으로 보낸다.
        const src=isTight? tightCleanText(c).replace(/\n+/g,' ')
                         : (c?c.innerText:'').trim();
        if(!src){ toast('번역할 내용이 없습니다',1600); return; }
        if(trCtl||trBusy){ toast('번역이 이미 진행 중입니다 — 진행바의 [중단] 을 누르거나 잠시 기다려 주세요',2400); return; }
        beginTrTask();
        showTrProg(null,(TR_NAME[target]||target)+'로 번역 중… · 중단하려면 [중단] 또는 Esc');
        try{
            // 본문을 먼저 바꾼다. 용어 학습을 앞에 두면 무료 엔진 한도를
            // 먼저 깎아 정작 상자 번역이 '실패'로 떨어졌다.
            if(trCancel) throw new Error(TR_CANCEL);
            const out=await apiTranslate(src,target,doc.glossary);
            learnGlossary([src],target).then(n=>{ if(n){ try{ saveDoc(); queueOps(); }catch(e){} } }).catch(()=>{});
            pushHistory();
            if(isTight){
                // 가지런한 일반 텍스트 상자로 전환 (찌부됨 방지)
                el.tight=0; el.align='left'; delete el.fitDown;
                node.classList.remove('tight');
            }
            el.fit=0;
            el.html=esc(out).replace(/\n/g,'<br>');
            if(c) c.innerHTML=el.html;
            fitTranslated(node,c,el);                     // 6.1: 상자 안으로 자동 맞춤
            try{
                syncState();
                const rev=Date.now();
                doc.__localRev.set(el.id,rev);
                doc.__lastHash.set(el.id,JSON.stringify(el));
            }catch(e){}
            syncTextEl(node);
            await persistTranslatedChange();
            toast((TR_NAME[target]||target)+'로 번역하고 저장했습니다',2000);
        }catch(e){
            if(e&&e.message===TR_CANCEL) toast('번역을 중단했습니다 — 원문은 그대로입니다',2200);
            else toast('번역 실패: '+e.message,2600);
        }finally{ endTrTask(); }
}

    // 긁어놓은 글자만 번역해서 그 자리에 넣는다
    // 고른 글자를 그 자리에서 번역문으로 바꿔 넣는다 (서식·위치 유지)
    const TR_NAME={ko:'한국어',en:'영어',ja:'일본어','zh-CN':'중국어'};
    async function translateSelectedText(target){
        closeCtxMenu();
        // 우클릭 도중 선택이 풀릴 수 있으니 저장해 둔 선택을 되살린다
        let host=restoreSel();
        let sel=window.getSelection();
        if((!sel||sel.isCollapsed) && host){ /* 복원 실패 */ }
        if(!host){
            const n=sel&&sel.anchorNode
                ? (sel.anchorNode.nodeType===1?sel.anchorNode:sel.anchorNode.parentElement) : null;
            host=n?n.closest('.tb-content'):null;
        }
        sel=window.getSelection();
        // tight 상자는 단어 스팬 구조에서 공백을 재조립하고,
        // 번역 품질을 위해 뉴라인은 공백으로 보낸다.
        let txt=(host&&host.closest('.tight'))? tightSelectionText(sel) : (sel?String(sel):'');
        if(host&&host.closest('.tight'))
            txt=txt.replace(/\n+/g,' ').replace(/\s{2,}/g,' ').trim();
        if(!host||!txt.trim()){ toast('번역할 글자를 선택해 주세요',1800); return; }
        if(trCtl||trBusy){ toast('번역이 이미 진행 중입니다 — 진행바의 [중단] 을 누르거나 잠시 기다려 주세요',2400); return; }
        const w=host.closest('.tb');
        const rng=sel.getRangeAt(0).cloneRange();
        beginTrTask();
        showTrProg(null,`${TR_NAME[target]||target}로 번역 중… · 중단하려면 [중단] 또는 Esc`);
        try{
            const out=await apiTranslate(txt,target);
            if(!out||!String(out).trim()){ toast('번역 결과가 비어 있습니다',2000); return; }
            pushHistory();
            // 편집 상태여야 execCommand 가 먹는다
            if(w&&!w.classList.contains('edit')){
                enterEdit(w,true); enableTextSelect(host);
            }
            const s2=window.getSelection();
            s2.removeAllRanges(); s2.addRange(rng);
            host.focus({preventScroll:true});
            // 브라우저 execCommand 는 자체 실행취소 스택을 써서 Ctrl+Z 가 어긋난다.
            // → 직접 바꿔 넣어 우리 되돌리기 한 번으로 정확히 복구되게 한다.
            rng.deleteContents();
            const tn=document.createTextNode(out);
            rng.insertNode(tn);
            const r2=document.createRange();
            r2.setStartAfter(tn); r2.collapse(true);
            s2.removeAllRanges(); s2.addRange(r2);
            if(w){
                syncTextEl(w);
                await persistTranslatedChange();
            }
            saveSel();
            toast(`${TR_NAME[target]||target}로 바꾸고 저장했습니다 (Ctrl+Z 로 되돌리기)`,2400);
        }catch(e){
            if(e&&e.message===TR_CANCEL) toast('번역을 중단했습니다 — 원문은 그대로입니다',2200);
            else toast('번역 실패: '+e.message,2600);
        }finally{ endTrTask(); }
}

    // ============ 6.1: 페이지/문서 전체 번역 + 용어 기억 + 자동 맞춤 ============
    // tight 상자의 단어 스팬은 인라인 top 을 갖고 있으므로 레이아웃 없이 파싱 가능
    function tightTextFromHtml(html){
        const d=document.createElement('div'); d.innerHTML=html||'';
        const sps=Array.from(d.querySelectorAll('span')).filter(s=>s.style.left!==''||s.style.top!=='');
        sps.sort((a,b)=>(parseFloat(a.style.top)||0)-(parseFloat(b.style.top)||0)
                       ||(parseFloat(a.style.left)||0)-(parseFloat(b.style.left)||0));
        const lines=[]; let cur=[]; let last=null;
        sps.forEach(s=>{
            const t=(s.textContent||'').replace(/[​‌‍﻿]/g,'').trim();
            if(!t) return;
            const top=parseFloat(s.style.top)||0;
            if(last!=null&&Math.abs(top-last)>2){ lines.push(cur.join(' ')); cur=[]; }
            cur.push(t); last=top;
        });
        if(cur.length) lines.push(cur.join(' '));
        return lines.join(' ');
    }
    function plainTextFromHtml(html){
        const d=document.createElement('div');
        d.innerHTML=(html||'').replace(/<br\s*\/?>/gi,'\n');
        return (d.textContent||'').replace(/[​‌‍﻿]/g,'');
    }
    // 전문용어 후보 추출: 대문자 줄임말·하이픈 결합 용어·CamelCase
    const TR_STOP=new Set(['FIG','FIGS','FIGURE','FIGURES','TABLE','TABLES','SECTION','SECTIONS',
        'EQ','EQS','VOL','NO','PP','ET','AL','THE','AND','OR','OF','IN','ON','FOR','WITH','TO','BY',
        'IS','ARE','WAS','WERE','WE','OUR','US','AS','AT','AN','NOT','YES','OK','PDF','HTML','HTTP',
        'HTTPS','URL','DOI','ISBN','ISSN','ARXIV','CC','USA','UK','EU','UN','ABSTRACT','INTRODUCTION',
        'CONCLUSION','CONCLUSIONS','REFERENCES','ACKNOWLEDGMENTS','ACKNOWLEDGEMENTS','APPENDIX',
        'SUPPLEMENTARY','METHODS','RESULTS','DISCUSSION','PAGE','PAGES','COPYRIGHT','IEEE','ACM',
        'LNCS','SPRINGER','ELSEVIER','PREPRINT','ARTICLE','LETTER','LETTERS','NOTE','NOTES']);
    function extractTerms(text){
        const set=new Set();
        const re=/\b([A-Z][A-Z0-9]{1,9}(?:-[A-Z0-9]+)?)\b|\b([A-Z][a-z]+(?:-[A-Z][a-z]+)+)\b|\b([A-Z][a-z]+[A-Z][A-Za-z]+)\b/g;
        let m;
        while((m=re.exec(text))){
            const t=m[1]||m[2]||m[3];
            if(!t) continue;
            if(TR_STOP.has(t.toUpperCase())) continue;
            set.add(t);
            if(set.size>=300) break;
        }
        return Array.from(set);
    }
    // 문서 사전(doc.glossary)에 새 용어 번역을 학습해 저장 → 이후 번역이 일관됨
    async function learnGlossary(texts,target){
        if(!doc) return 0;
        const g=doc.glossary||(doc.glossary={});
        const seen=new Set(Object.keys(g));
        const terms=[];
        (texts||[]).forEach(t=>extractTerms(t).forEach(x=>{
            if(!seen.has(x)){ seen.add(x); terms.push(x); }
        }));
        if(!terms.length) return 0;
        for(let i=0;i<terms.length;i+=60){
            if(trCancel) return 0;                    // 사용자 중단 → 학습도 멈춤
            const chunk=terms.slice(i,i+60);
            try{
                const r=await fetch('/api/translate/gloss',{method:'POST',
                    signal:trCtl?trCtl.signal:undefined,
                    headers:{'Content-Type':'application/json'},
                    body:JSON.stringify({terms:chunk,target})});
                const d=await r.json().catch(()=>({}));
                if(d&&d.ok&&d.gloss) Object.assign(g,d.gloss);
            }catch(e){ if(trCancel) return 0; }
        }
        return terms.length;
    }
    // 번역문이 상자를 넘치면: ① 글자간격 → ② 기 → ③ 글자 크기 순으로 맞춤
    function fitTranslated(w,c,el){
        if(!c||!el) return;
        const base=el.fontSize||parseFloat(getComputedStyle(c).fontSize)||14;
        c.style.fontSize=base+'px'; c.style.letterSpacing='';
        c.style.fontWeight=el.fontWeight?String(el.fontWeight):'';
        const over=()=>c.scrollHeight>c.clientHeight+1||c.scrollWidth>c.clientWidth+1;
        el.trFit=1; el.trLS=''; el.trFW=''; el.trFS=base;
        if(!over()) return;
        for(const ls of [-0.012,-0.024,-0.036,-0.048]){   // ① 글자간격
            if(!over()) break;
            c.style.letterSpacing=ls+'em'; el.trLS=ls+'em';
        }
        let fw=parseInt(getComputedStyle(c).fontWeight)||400;   // ② 굵기
        for(const step of [600,500,400]){
            if(!over()||fw<=step) continue;
            c.style.fontWeight=step; el.trFW=step; fw=step;
        }
        let px=base, guard=0;                              // ③ 크기
        const min=Math.max(7,Math.round(base*0.62*10)/10);
        while(over()&&guard++<22&&px>min){
            px=Math.round(px*0.94*10)/10;
            c.style.fontSize=px+'px';
        }
        el.trFS=px;
        // ④ 최소 크기에서도 넘치면 상자 높이를 늘린다 (표 칸은 제외)
        if(el.h&&over()&&!el.tbl){
            let h=el.h, g2=0;
            while(over()&&g2++<60){ h+=16; el.h=h; w.style.height=h+'px'; }
        }
    }
    // 진행률 바
    function showTrProg(f,label){
        let p=document.getElementById('trProg');
        if(!p){
            p=document.createElement('div'); p.id='trProg';
            p.innerHTML='<span class="tr-label"></span><span class="tr-track"><i class="tr-fill"></i></span>'+
                '<button type="button" class="tr-cancel" title="번역 중단 (Esc)">중단</button>';
            p.querySelector('.tr-cancel').addEventListener('click',cancelTranslation);
            document.body.appendChild(p);
        }
        p.style.display='flex';
        const fill=p.querySelector('.tr-fill');
        if(f==null){ fill.classList.add('indet'); fill.style.width=''; }
        else{ fill.classList.remove('indet'); fill.style.width=Math.round(Math.min(1,Math.max(0,f))*100)+'%'; }
        p.querySelector('.tr-label').textContent=label||'';
    }
    function hideTrProg(){
        const p=document.getElementById('trProg');
        if(p) p.style.display='none';
    }
    // 피규어/표 캡션·축 라벨 등 "본문이 아닌" 글자인지 판별 (논문 전체 번역 시 제외)
    function isFigureText(el,src){
        if(el.isFig) return true;                        // 명시적으로 그림 글자로 표시된 경우
        const s=(src||'').replace(/\s+/g,' ').trim();
        if(!s) return true;
        // 캡션 패턴: Fig. 1 / Figure 2 / Table 3 / 그림 1 / 표 2 ...
        if(/^(fig(?:ure)?s?\.?|table|그림|표)\s*[0-9]+/i.test(s)) return true;
        // 축 눈금처럼 짧고 숫자·기호 위주인 글자는 그림 위 글자로 간주
        const letters=(s.match(/[A-Za-z가-힣]/g)||[]).length;
        if(letters<=3 && /[0-9]/.test(s) && s.length<=24) return true;
        return false;
    }
    // 논문 잡음: 참고문헌 번호·DOI·연도만 있는 조각은 번역하지 않는다.
    function isPaperNoise(src){
        const s=String(src||'').replace(/\s+/g,' ').trim();
        if(!s) return true;
        if(/^\[[0-9,\s–\-]+\]$/.test(s)) return true;
        if(/^\(\s*\d{4}[a-z]?\s*\)$/.test(s)) return true;
        if(/^(doi:|https?:\/\/|arxiv:)/i.test(s)) return true;
        if(/^[A-Za-z][A-Za-z\-']+ et al\.?$/i.test(s)) return true;
        if(/^(vol\.?|pp?\.?|no\.?)\s*[\d\-]+$/i.test(s)) return true;
        if(/^[\d.,+\-±%=\s]+$/.test(s) && s.length<=20) return true;
        return false;
    }
    function trLooksTarget(s,target){
        const t=String(s||'');
        if(target==='ko'){
            let ko=0; for(const ch of t) if(ch>='\uAC00'&&ch<='\uD7A3') ko++;
            return ko>=Math.max(2,Math.floor(t.trim().length*0.2));
        }
        if(target==='ja') return /[\u3040-\u30ff]/.test(t);
        if(target==='zh-CN'||target==='zh') return /[\u4e00-\u9fff]/.test(t)&&!/[\u3040-\u30ff]/.test(t);
        if(target==='en'){
            const letters=(t.match(/[A-Za-z]/g)||[]).length;
            const ko=(t.match(/[\uAC00-\uD7A3]/g)||[]).length;
            return letters>=8 && ko===0;
        }
        return false;
    }
    function applyTrResult(o,out){
        if(!out||!String(out).trim()) return false;
        o.el.tight=0; o.el.fit=0; delete o.el.fitDown;
        o.el.html=esc(out).replace(/\n/g,'<br>');
        if(doc.pages[o.pi]) doc.pages[o.pi].__dirty=true;
        try{
            syncState();
            const rev=Date.now()+Math.random();
            doc.__localRev.set(o.el.id,rev);
            doc.__lastHash.set(o.el.id,JSON.stringify(o.el));
        }catch(e){}
        const node=document.querySelector('.tb[data-id="'+o.el.id+'"]');
        const c=node&&node.querySelector('.tb-content');
        if(node&&c){
            node.classList.remove('tight');
            c.innerHTML=o.el.html;
            fitTranslated(node,c,o.el);
        }else o.el.trPending=1;
        return true;
    }
    // 논문 PDF 는 한 줄=한 상자인 경우가 많다. 짧은 상자를 한 요청으로 묶어
    // 문맥도 살리고 무료 엔진 한도도 덜 깎는다.
    function packTrJobs(list){
        const shorts=list.filter(o=>o.src.length<=240).length;
        const pack=list.length>=5 || shorts>=4;
        if(!pack) return list.map(o=>({items:[o]}));
        const packs=[]; let cur=null;
        const flush=()=>{ if(cur) packs.push(cur); cur=null; };
        list.forEach(o=>{
            const short=o.src.length<=240;
            if(!short){ flush(); packs.push({items:[o]}); return; }
            if(!cur){ cur={items:[o]}; return; }
            const next=cur.items.reduce((n,x)=>n+x.src.length,0)+o.src.length+10*cur.items.length;
            if(cur.items.length>=12 || next>1800){ flush(); cur={items:[o]}; }
            else cur.items.push(o);
        });
        flush();
        return packs;
    }
    function joinTrPack(items){
        if(items.length===1) return items[0].src;
        return items.map((o,i)=>i===0?o.src:('§#'+(i+1)+'§\n'+o.src)).join('\n');
    }
    function splitTrPack(out,n){
        if(n<=1) return [String(out||'')];
        const parts=[]; let rest=String(out||'');
        for(let i=2;i<=n;i++){
            const mark='§#'+i+'§';
            const idx=rest.indexOf(mark);
            if(idx<0) return null;
            parts.push(rest.slice(0,idx).replace(/^\s+|\s+$/g,''));
            rest=rest.slice(idx+mark.length);
        }
        parts.push(rest.replace(/^\s+|\s+$/g,''));
        if(parts.length!==n || parts.some(p=>!p)) return null;
        return parts;
    }
    function collectPageEls(pi){
        const pg=(doc.pages||[])[pi]; const out=[];
        if(!pg) return out;
        // 그림(이미지) 영역 위에 놓인 글자는 번역에서 제외
        const imgs=(pg.els||[]).filter(e=>e.type==='image'&&!e.isBg);
        const overImg=(el)=>{
            if(!imgs.length) return false;
            return imgs.some(im=>{
                const iw=im.w||0, ih=im.h||0, ew=el.w||0, eh=el.h||0;
                if(!iw||!ih||im.x==null||im.y==null||el.x==null||el.y==null) return false;
                return el.x>=im.x-2 && el.y>=im.y-2 &&
                       el.x+ew<=im.x+iw+2 && el.y+eh<=im.y+ih+2;
            });
        };
        (pg.els||[]).forEach(el=>{
            if(el.type!=='text'||el.locked) return;
            let src=el.tight? tightTextFromHtml(el.html) : plainTextFromHtml(el.html);
            src=(src||'').replace(/\s+/g,' ').trim();
            if(!src) return;
            if(isFigureText(el,src)||overImg(el)) return;   // 6.6: 피규어/캡션은 제외
            out.push({el,src,pi});
        });
        return out;
    }
    let trBusy=false;
    // 15.0 · 무료 번역 엔진은 요청이 몰리면 잠깐 제한(429)된다. 그럴 땐
    //   기다렸다가 다시 시도한다 — 문서 전체 번역이 중간에 통째로 실패하지 않게.
    async function apiTranslateRetry(src,target,gloss){
        for(let a=0;a<3;a++){
            if(trCancel) throw new Error(TR_CANCEL);
            try{ return await apiTranslate(src,target,gloss); }
            catch(e){
                const msg=String(e&&e.message||'');
                if(msg===TR_CANCEL) throw e;                 // 사용자 중단은 재시도하지 않는다
                if(a>=2||!/제한|429|닿지 않/.test(msg)) throw e;
                await trSleep(9000*(a+1));                   // 대기 중에도 중단 즉시 반영
            }
        }
    }
    async function translateEls(list,target,label){
        if(trBusy||trCtl){ toast('번역이 이미 진행 중입니다 — 진행바의 [중단] 을 누르거나 잠시 기다려 주세요',2400); return; }
        if(!list.length){ toast('번역할 텍스트 상자가 없습니다',1800); return; }
        trBusy=true;
        beginTrTask();
        let failCnt=0, lastErr='', okCnt=0;
        const remaining=()=>q.reduce((n,p)=>n+((p&&p.items)||[p]).length,0);
        let q=[];
        try{
            showTrProg(0,label+' · 번역 준비… · 중단하려면 [중단]/Esc');
            pushHistory();                                 // 되돌리기 한 번으로 전체 복구
            const jobs=list.filter(o=>{
                if(trLooksTarget(o.src,target)){ okCnt++; return false; }
                return true;
            });
            const packs=packTrJobs(jobs);
            q=packs.slice();
            const totalPacks=Math.max(1,packs.length);
            const worker=async()=>{
                while(q.length&&!trCancel){
                    const pack=q.shift();
                    const items=pack.items||[pack];
                    const done=okCnt+failCnt;
                    showTrProg(done/Math.max(1,list.length),
                        label+' · 번역 '+Math.min(done+items.length,list.length)+'/'+list.length
                        +(failCnt?' · 실패 '+failCnt:'')+' · 중단: [중단]/Esc');
                    try{
                        if(items.length===1){
                            const out=await apiTranslateRetry(items[0].src,target,doc.glossary);
                            if(applyTrResult(items[0],out)) okCnt++;
                        }else{
                            const joined=joinTrPack(items);
                            const out=await apiTranslateRetry(joined,target,doc.glossary);
                            const parts=splitTrPack(out,items.length);
                            if(parts){
                                items.forEach((o,i)=>{ if(applyTrResult(o,parts[i])) okCnt++; else failCnt++; });
                            }else if(/제한|429/.test(String(out||''))){
                                failCnt+=items.length;
                                lastErr='지금 번역 요청이 몰려 잠시 제한됐어요';
                            }else{
                                // 구분자가 깨지면 그 묶음만 상자별로 한 번 더 (429는 안 함)
                                for(const o of items){
                                    if(trCancel){ q.unshift({items:items.slice(items.indexOf(o))}); break; }
                                    try{
                                        const one=await apiTranslateRetry(o.src,target,doc.glossary);
                                        if(applyTrResult(o,one)) okCnt++; else failCnt++;
                                    }catch(e){
                                        if(e&&e.message===TR_CANCEL){ q.unshift({items:[o]}); break; }
                                        failCnt++; lastErr=String(e&&e.message||'');
                                        if(/제한|429/.test(lastErr)){
                                            const rest=items.slice(items.indexOf(o)+1);
                                            failCnt+=rest.length;
                                            break;
                                        }
                                    }
                                }
                            }
                        }
                    }catch(e){
                        if(e&&e.message===TR_CANCEL){ q.unshift(pack); }
                        else {
                            failCnt+=items.length;
                            lastErr=String(e&&e.message||'');
                        }
                    }
                    await trSleep(packs.length>8?80:160);
                }
            };
            // 논문은 묶음이 이미 커서 일꾼 2개면 한도만 더 깎인다. 묶음이 많을 때만 2개.
            await Promise.all(totalPacks>=6?[worker(),worker()]:[worker()]);
            // 중단했어도 이미 완료된 상자는 유실하지 않고 저장한다
            await persistTranslatedChange();
            learnGlossary(list.map(o=>o.src),target)
                .then(n=>{ if(n){ try{ saveDoc(); queueOps(); }catch(e){} } })
                .catch(()=>{});
            const left=remaining();
            if(trCancel){
                toast(label+' 번역을 중단했어요 · 완료한 '+okCnt+'개 상자는 저장했습니다'
                    +(left?' · 남은 '+left+'개 상자는 원문 유지':''),3200);
            }
            // 15.0 · 실패한 상자가 있으면 '완료'라고만 알리지 않는다 —
            //   다 번역 안 됐는데 완료로 보이던 문제.
            else if(failCnt>=list.length){
                toast('번역에 실패했어요 · '+(lastErr||'잠시 뒤 다시 시도해 주세요'),3600);
            }else if(failCnt){
                toast(label+' 번역 부분 완료 · '+failCnt+'개 상자는 실패 (잠시 뒤 다시 눌러 주세요)',3200);
            }else{
                toast(label+' 번역 완료 · 저장됨 ('+list.length+'개 상자)',2400);
            }
        }catch(e){
            toast('번역 결과 저장 실패: '+String(e&&e.message||'다시 시도해 주세요'),3600);
        }finally{ trBusy=false; endTrTask(); }
    }
    async function translatePageAction(pi,target){
        if(trBusy||trCtl){ toast('번역이 이미 진행 중입니다 — 진행바의 [중단] 을 누르거나 잠시 기다려 주세요',2400); return; }
        closeCtxMenu();
        try{ await ensureLazyPage(pi); }catch(e){}
        const list=collectPageEls(pi);
        await translateEls(list,target,(pi+1)+'페이지');
    }
    async function translateDocAction(target){
        if(trBusy||trCtl){ toast('번역이 이미 진행 중입니다 — 진행바의 [중단] 을 누르거나 잠시 기다려 주세요',2400); return; }
        closeCtxMenu();
        const total=(doc.pages||[]).length;
        // 대용량(서버 보관) 문서는 먼저 전부 불러온다 → 번역이 중간에 끊기지 않게
        if(doc.__ref&&(doc.pages||[]).some(p=>p.__lazy!=null)){
            showTrProg(0,'문서 전체 불러오는 중…');
            try{ await loadAllLazyNoEvict(); }catch(e){}
        }
        const list=[];
        for(let i=0;i<total;i++){
            showTrProg(i/Math.max(1,total),'문서 로딩 '+(i+1)+'/'+total);
            const got=collectPageEls(i);
            got.forEach(o=>list.push(o));
        }
        hideTrProg();
        await translateEls(list,target,'문서 전체');
    }
    try{
        window.__sdyTranslate={
            page:translatePageAction,
            doc:translateDocAction,
            getDoc:()=>doc,
            curPage:()=>curPageIdx|0,     // 14.29.3 · 해돌이 '이 페이지 번역'용
            pack:packTrJobs,
        };
    }catch(e){}

    // 14.20.0 · AI UI가 노트 글과 문서 구조를 편집기 스코프 안에서만 다루는 다리.
    //   일반 질문은 text()로 글만 읽는다. 14.24.0 문서 편집은 capture()로 제한된
    //   상태 스냅샷을 만들고, apply()가 허용된 명령만 검증해 한 번에 적용한다.
    //   모델 응답이 오는 동안 노트를 바꾸거나 내용을 고치면 revision이 달라져
    //   오래된 계획은 전부 거절한다. AI 편집 전체는 Ctrl+Z 한 번으로 되돌릴 수 있다.
    //   14.25.0 · 스냅샷에 글꼴·서식·표를 싣고(@st·@tbl·@tcell), 부분 수정(@rp·@ap),
    //   쪽 이동·추가(@goto·@newpage), 노트 제목(@title), 클립보드(@clip·@clipin·@copy),
    //   되묻기(@ask)까지 허용 목록이 늘었다. 적용 규칙은 같다 — 검증·한 번에·undo.
    //   14.27.0 · 형광펜 글귀 단위(@hl)·표 삭제 완화(@del·@tdel)·보기 좋은 배치
    //   (@tidy·auto 좌표)가 늘었다. 스냅샷은 칠해진 곳을 ⟦…⟧ 로 보여 준다.
    //   14.27.1 · 긴 편집을 위해 요소 800개·상태 8만 자·상자 미리보기 1200자와
    //   명령 120개·명령 본문 12000자까지 확장했다. 검증·원자 적용·undo는 그대로다.
    const AI_EDIT_MAX_ITEMS=800, AI_EDIT_MAX_SNAPSHOT=80000;
    const AI_EDIT_MAX_OPS=120, AI_EDIT_MAX_TEXT=12000;

    function aiEditText(el){
        if(!el) return '';
        if(el.type==='text') return el.tight?tightTextFromHtml(el.html):plainTextFromHtml(el.html);
        if(el.type==='latex') return String(el.latex||'');
        return '';
    }
    function aiEditStrokeBox(el){
        let x1=Infinity,y1=Infinity,x2=-Infinity,y2=-Infinity,n=0;
        (el&&el.pts||[]).forEach(pt=>{
            if(!pt||!Number.isFinite(+pt[0])||!Number.isFinite(+pt[1])) return;
            n++; x1=Math.min(x1,+pt[0]); y1=Math.min(y1,+pt[1]);
            x2=Math.max(x2,+pt[0]); y2=Math.max(y2,+pt[1]);
        });
        if(!n) x1=y1=x2=y2=0;
        const dx=+el.dx||0,dy=+el.dy||0;
        return {x:x1+dx,y:y1+dy,w:Math.max(0,x2-x1),h:Math.max(0,y2-y1),baseX:x1,baseY:y1};
    }
    function aiEditBox(el){
        if(el&&el.type==='stroke') return aiEditStrokeBox(el);
        return {x:+(el&&el.x)||0,y:+(el&&el.y)||0,w:+(el&&el.w)||0,h:+(el&&el.h)||0};
    }
    function aiEditSnapshot(){
        if(!doc||!doc.pages||!doc.pages.length) return '';
        const size=paperSize();
        const title=(String((document.getElementById('edTitle')||{}).value||'')
            .replace(/\s+/g,' ').replace(/</g,'‹').replace(/>/g,'›').trim())||'(제목 없음)';
        const lines=[]; let chars=0,items=0,folded=false;
        const add=line=>{
            line=String(line||'');
            if(chars+line.length+1>AI_EDIT_MAX_SNAPSHOT){ folded=true; return false; }
            lines.push(line); chars+=line.length+1; return true;
        };
        const preview=(value,max)=>{
            const text=String(value||'').replace(/\s+/g,' ').replace(/</g,'‹').replace(/>/g,'›').trim();
            const lim=max||1200;
            return text.length>lim?text.slice(0,lim)+'…':text;
        };
        // 14.27.0 · 글상자 미리보기에는 형광펜이 칠해진 글귀를 ⟦…⟧ 로 표시한다.
        //   모델이 '이미 칠한 곳'을 알아야 겹칠하거나 딴 데를 칠하지 않는다.
        const previewEl=(el,max)=>{
            const text=(el&&el.type==='text'&&!el.tight)
                ?aiEditHlPreview(el.html)
                :String(aiEditText(el)||'').replace(/\s+/g,' ')
                    .replace(/</g,'‹').replace(/>/g,'›').trim();
            const lim=max||1200;
            return text.length>lim?text.slice(0,lim)+'…':text;
        };
        // id는 모델이 그대로 되돌려 보내는 실행 토큰이다. 프롬프트 구분자나
        // 필드 구분자로 해석될 수 있는 비정상 가져오기 id는 노출하지 않는다.
        const safeId=id=>{
            id=String(id||'');
            if(!id||id.length>160||/[\s<>|]/.test(id)) return '';
            return id;
        };
        add('노트 제목: '+title);
        add('페이지 크기: '+size.w+'x'+size.h+' px · 왼쪽 위=0,0 · 총 '
            +doc.pages.length+'쪽 · 현재 '+(Math.min(Math.max(curPageIdx|0,0),doc.pages.length-1)+1)+'쪽');
        // 긴 문서에서도 현재 쪽은 반드시 모델에게 보인다. 나머지는 페이지 순서대로 싣는다.
        const current=Math.min(Math.max(curPageIdx|0,0),doc.pages.length-1);
        const order=[current].concat(doc.pages.map((p,i)=>i).filter(i=>i!==current));
        for(const pi of order){
            if(items>=AI_EDIT_MAX_ITEMS||folded) break;
            const pg=doc.pages[pi];
            // 빈 자리도 알려 준다 — 새 상자·표를 어디에 두면 정돈돼 보이는지
            // 모델이 스스로 고르게(그래도 최종 배치는 aiEditNeat가 다듬는다).
            let filled=0;
            aiEditOccupied(pi).forEach(o=>{ filled=Math.max(filled,Math.round(o.y+o.h)); });
            const freeFrom=Math.min(size.h,filled?filled+AI_GAP:AI_MARGIN);
            if(!add('['+(pi+1)+'쪽'+(pi===current?' · 현재':'')+']'
                +(filled?' 빈 자리 y='+freeFrom+'~'+size.h+' · 본문 왼쪽 x='
                    +(aiEditMargins(pi).left==null?AI_MARGIN:aiEditMargins(pi).left):' (빈 쪽)'))) break;
            if(!pg||pg.__lazy!=null){ add('  (아직 불러오지 않은 쪽 · 편집 불가)'); continue; }
            const els=pg.els||[];
            // 표는 칸 글과 함께 한 줄로 먼저 보여 준다 — 칸은 @tcell·@st로, 표 전체는
            // @tmv·@tsz로 다룬다. 표 테두리 선(자동 재생성)은 스냅샷에서 뺀다.
            (pg.tables||[]).forEach(t=>{
                if(items>=AI_EDIT_MAX_ITEMS||folded||!t||!t.id) return;
                const tid=safeId(t.id);
                if(!tid||!Array.isArray(t.cw)||!Array.isArray(t.ch)) return;
                const rows=t.ch.length,cols=t.cw.length;
                if(!rows||!cols) return;
                const size=tblSize(t);
                const cells={};
                els.forEach(e=>{
                    if(e&&e.type==='text'&&e.tbl&&e.tbl.tid===t.id
                       &&Number.isInteger(+e.tbl.r)&&Number.isInteger(+e.tbl.c))
                        cells[e.tbl.r+'_'+e.tbl.c]=previewEl(e,28);
                });
                const grid=[];
                for(let r=0;r<rows;r++){
                    const row=[];
                    for(let c=0;c<cols;c++) row.push(cells[r+'_'+c]||'');
                    grid.push(row.join('|'));
                }
                let dump=grid.join(';');
                if(dump.length>200) dump=dump.slice(0,200)+'…';
                if(add('  id='+tid+' type=표 x='+Math.round(t.x)+' y='+Math.round(t.y)
                    +' w='+Math.round(size.w)+' h='+Math.round(size.h)
                    +' rows='+rows+' cols='+cols+' cells='+JSON.stringify(dump))) items++;
            });
            if(!els.length){ add('  (빈 쪽 · @add 가능)'); continue; }
            // 읽는 순서(위→아래·왼쪽→오른쪽)로 보여 주면 "두 번째 상자" 같은
            // 가리킴이 나열 순서와 어긋나지 않는다.
            const sorted=els.slice().sort((a,b)=>{
                const ba=aiEditBox(a),bb=aiEditBox(b);
                if(Math.abs(ba.y-bb.y)>4) return ba.y-bb.y;
                return ba.x-bb.x;
            });
            for(const el of sorted){
                if(items>=AI_EDIT_MAX_ITEMS||folded) break;
                if(!el||!el.id) continue;
                const elementId=safeId(el.id);
                if(!elementId) continue;
                // 표 테두리 선은 표를 고치면 자동 재생성되니 모델에게 보이지 않는다.
                if(el.type==='stroke'&&el.tbl) continue;
                const b=aiEditBox(el);
                let kind='기타',extra='',fmt='';
                if(el.type==='text'){
                    kind='글상자';
                    // 서식은 기본값과 다를 때만 싣는다 — 없으면 프리텐다드·16·왼쪽이다.
                    if(el.font&&el.font!=='pretendard') fmt+=' font='+el.font;
                    if(el.fontSize&&+el.fontSize!==16) fmt+=' fs='+Math.round(+el.fontSize);
                    if(el.align&&el.align!=='left') fmt+=' al='+el.align;
                    if(el.textColor) fmt+=' fg='+el.textColor;
                    if(el.cellBg) fmt+=' hl='+el.cellBg;
                    const st=[];
                    if(el.fontWeight&&(String(el.fontWeight)==='700'||String(el.fontWeight)==='bold')) st.push('B');
                    if(el.fontStyle) st.push('I');
                    const td=String(el.textDecoration||'');
                    if(td.indexOf('underline')>=0) st.push('U');
                    if(td.indexOf('line-through')>=0) st.push('S');
                    if(st.length) fmt+=' st='+st.join(',');
                    extra=' text='+JSON.stringify(previewEl(el));
                }
                else if(el.type==='image') kind='사진';
                else if(el.type==='latex'){
                    kind='수식';
                    if(el.displayMath) fmt+=' display=1';
                    if(el.fontSize&&+el.fontSize!==20) fmt+=' fs='+Math.round(+el.fontSize);
                    extra=' latex='+JSON.stringify(preview(aiEditText(el)));
                }
                else if(el.type==='stroke'){
                    kind='그림획';
                    if(el.color) fmt+=' pen='+el.color;
                    if(el.size!=null) fmt+=' psz='+el.size;
                    if(el.shape) fmt+=' shape='+el.shape;
                }
                else if(el.type==='legacyDraw') kind='배경그림';
                else continue;
                let line='  id='+elementId+' type='+kind+' x='+Math.round(b.x)+' y='+Math.round(b.y)
                    +' w='+Math.round(b.w)+' h='+Math.round(b.h)+fmt+extra;
                if(el.locked) line+=' (잠김 · 편집 불가)';
                else if(el.tbl) line+=' (표 칸 · @tcell·@st로만)';
                if(!add(line)) break;
                items++;
            }
        }
        if(folded||items>=AI_EDIT_MAX_ITEMS) lines.push('… (긴 문서라 일부 요소는 생략됨)');
        return lines.join('\n');
    }
    // 서버 왕복 중 문서가 달라졌는지 확인하는 로컬 전용 지문. 서버에는 보내지 않는다.
    function aiEditRevision(){
        let h=2166136261;
        const mix=value=>{
            const s=String(value==null?'':value);
            for(let i=0;i<s.length;i++){ h^=s.charCodeAt(i); h=Math.imul(h,16777619); }
            h^=31; h=Math.imul(h,16777619);
        };
        mix(curNB&&curNB.id); mix((document.getElementById('edTitle')||{}).value); mix(doc&&doc.sizePreset);
        (doc&&doc.pages||[]).forEach(pg=>{
            mix(pg&&pg.id); mix(pg&&pg.__lazy);
            (pg&&pg.els||[]).forEach(el=>{
                if(!el) return;
                ['id','type','x','y','w','h','dx','dy','html','latex','locked',
                 'font','fontSize','textColor','cellBg','fontWeight','fontStyle',
                 'textDecoration','align','color','size','vAlign'].forEach(k=>mix(el[k]));
                mix(el.tbl&&JSON.stringify(el.tbl));
                if(el.type==='stroke') mix(JSON.stringify(el.pts||[]));
            });
            mix(JSON.stringify(pg&&pg.tables||[]));
        });
        return (h>>>0).toString(36);
    }
    // ── 14.25.0 · 똑똑한 해돌이 도우미 ──────────────────────────────────
    // 색이름 → 실제 팔레트. 화면의 글자색·형광펜·펜 목록(CLASSIC_*_COLORS)과
    // 같은 값이라, AI가 고른 색이 도구막대 색과 어긋나지 않는다.
    const AI_TEXT_COLOR_NAMES={검정:'#111111',검은색:'#111111',까망:'#111111',
        빨강:'#a63f47',빨간색:'#a63f47',주황:'#c06e34',주황색:'#c06e34',갈색:'#c06e34',
        노랑:'#9a8527',노란색:'#9a8527',초록:'#2f7a5d',초록색:'#2f7a5d',녹색:'#2f7a5d',
        청록:'#1c8a7a',파랑:'#3d6ea8',파란색:'#3d6ea8',남색:'#3d6ea8',하늘:'#3d6ea8',
        보라:'#7550a6',보라색:'#7550a6',분홍:'#b44f7a',분홍색:'#b44f7a',핑크:'#b44f7a',
        회색:'#5f6772',회색빛:'#5f6772',흰색:'#ffffff',하양:'#ffffff',하얀색:'#ffffff'};
    const AI_HL_COLOR_NAMES={노랑:'#efd36a',노란색:'#efd36a',연두:'#b7d97a',연두색:'#b7d97a',
        하늘:'#83d7de',하늘색:'#83d7de',파랑:'#b7cdf7',파란색:'#b7cdf7',
        보라:'#d8ade8',보라색:'#d8ade8',분홍:'#f2bcc5',분홍색:'#f2bcc5',핑크:'#f2bcc5',
        빨강:'#f2bcc5',빨간색:'#f2bcc5',주황:'#f2c796',주황색:'#f2c796',
        초록:'#c5e1a5',초록색:'#c5e1a5',회색:'#cfd4dd',황금:'#e6c15d',금색:'#e6c15d'};
    const AI_CLEAR_WORDS={없음:1,지우기:1,지워:1,투명:1,none:1,clear:1,off:1};
    function aiEditColor(value,hl){
        let v=String(value==null?'':value).trim().toLowerCase();
        if(!v) return null;
        if(AI_CLEAR_WORDS[v]) return '';
        if(/^#[0-9a-f]{3}$/.test(v))
            return '#'+v.slice(1).split('').map(ch=>ch+ch).join('');
        if(/^#[0-9a-f]{6}$/.test(v)) return v;
        const map=hl?AI_HL_COLOR_NAMES:AI_TEXT_COLOR_NAMES;
        v=String(value==null?'':value).trim().replace(/색$/,'');
        if(AI_CLEAR_WORDS[v.toLowerCase()]) return '';
        if(hl&&map[v]) return map[v];
        if(!hl&&map[v]) return map[v];
        // 형광펜에 글자색 이름을 적었으면 글자색 팔레트에서도 찾아본다(관대하게).
        if(hl&&AI_TEXT_COLOR_NAMES[v]) return AI_TEXT_COLOR_NAMES[v];
        return null;
    }
    // 글꼴 id·라벨 모두 받는다 ("개구쟁이체"처럼 체가 붙어도 된다).
    function aiEditFont(value){
        const v=String(value==null?'':value).trim().toLowerCase();
        if(!v) return null;
        let hit=FONTS.find(f=>f.id.toLowerCase()===v);
        if(hit) return hit.id;
        const bare=v.replace(/체$/,'');
        hit=FONTS.find(f=>f.label.toLowerCase()===v||f.label.toLowerCase()===bare
            ||f.label.replace(/체$/,'').toLowerCase()===bare);
        return hit?hit.id:null;
    }
    const AI_ON_WORDS={on:1,true:1,1:1,켜:1,켜기:1,적용:1,yes:1};
    const AI_OFF_WORDS={off:1,false:1,0:1,꺼:1,끄기:1,해제:1,없음:1,no:1};
    function aiEditBool(value){
        const v=String(value==null?'':value).trim().toLowerCase();
        if(AI_ON_WORDS[v]) return true;
        if(AI_OFF_WORDS[v]) return false;
        return null;
    }
    // @st 서식 문자열("font=gaegu, fs=20, bold=on") → 검증된 변경 목록.
    // 모르는 속성은 버리고(rule: 조용히 버리되 전부 못 알아들으면 실패),
    // 값 검증을 통과한 것만 돌려준다.
    function aiEditStyleOps(style){
        const out=[];
        String(style==null?'':style).split(/[,;]/).forEach(piece=>{
            const m=/^\s*([^=:]+?)\s*[=：:]\s*(.+?)\s*$/.exec(piece);
            if(!m) return;
            let key=String(m[1]).trim().toLowerCase(), val=String(m[2]).trim();
            if(!key||!val) return;
            key=key.replace(/\s+/g,'');
            if(key==='font'||key==='글꼴'){
                const id=aiEditFont(val);
                if(id) out.push({k:'font',v:id});
            }else if(key==='fs'||key==='size'||key==='fontsize'||key==='크기'
                     ||key==='글자크기'||key==='글씨크기'){
                const n=Number(String(val).replace(/px$/i,''));
                if(Number.isFinite(n)) out.push({k:'fs',v:Math.max(2,Math.min(200,Math.round(n)))});
            }else if(key==='fg'||key==='color'||key==='textcolor'||key==='색'
                     ||key==='글자색'||key==='글씨색'){
                const c=aiEditColor(val,false);
                if(c!=null) out.push({k:'fg',v:c});
            }else if(key==='hl'||key==='bg'||key==='background'||key==='backgroundcolor'
                     ||key==='형광펜'||key==='형광'||key==='배경'||key==='배경색'){
                const c=aiEditColor(val,true);
                if(c!=null) out.push({k:'hl',v:c});
            }else if(key==='bold'||key==='굵게'||key==='굵기'){
                const b=aiEditBool(val);
                if(b!=null) out.push({k:'bold',v:b});
            }else if(key==='italic'||key==='기울임'||key==='기울기'){
                const b=aiEditBool(val);
                if(b!=null) out.push({k:'italic',v:b});
            }else if(key==='underline'||key==='밑줄'){
                const b=aiEditBool(val);
                if(b!=null) out.push({k:'underline',v:b});
            }else if(key==='strike'||key==='strikethrough'||key==='취소선'){
                const b=aiEditBool(val);
                if(b!=null) out.push({k:'strike',v:b});
            }else if(key==='align'||key==='정렬'){
                const a=val.toLowerCase();
                if(a==='left'||a==='왼쪽') out.push({k:'align',v:'left'});
                else if(a==='center'||a==='middle'||a==='가운데'||a==='중앙') out.push({k:'align',v:'center'});
                else if(a==='right'||a==='오른쪽') out.push({k:'align',v:'right'});
            }else if(key==='pencolor'||key==='펜색'||key==='펜'){
                const c=aiEditColor(val,false);
                if(c) out.push({k:'pencolor',v:c});
            }else if(key==='pensize'||key==='굵기px'){
                const n=Number(val);
                if(Number.isFinite(n)) out.push({k:'pensize',v:Math.max(0.5,Math.min(30,n))});
            }
        });
        return out;
    }
    function aiEditDecodeEntities(s){
        try{
            const ta=document.createElement('textarea');
            ta.innerHTML=String(s==null?'':s);
            return ta.value;
        }catch(e){ return String(s==null?'':s); }
    }
    // 서식을 살린 부분 바꾸기(@rp). html을 태그·글·줄바꿈 토큰으로 나눈 뒤
    // 글 토큰 위에서 찾을 글을 찾아 바꾼다 — 굵기·색 span은 그대로 남는다.
    // 찾을 글이 span 경계를 가로질러도(앞 토큰 끝+뒤 토큰 앞) 이어서 찾는다.
    function aiEditReplaceHtml(html,find,repl){
        const src=String(html==null?'':html);
        const needle=String(find==null?'':find);
        const rep=String(repl==null?'':repl);
        if(!needle) return {html:src,count:0};
        const raws=src.split(/(<[^>]*>)/g);
        const toks=[];
        raws.forEach(part=>{
            if(!part) return;
            if(part.charAt(0)==='<'){
                if(/^<br\s*\/?>$/i.test(part)) toks.push({t:'br'});
                else toks.push({t:'tag',s:part});
            }else{
                toks.push({t:'txt',s:aiEditDecodeEntities(part)});
            }
        });
        let joined='';
        const pos=[];
        toks.forEach((tk,i)=>{
            if(tk.t==='txt'){
                for(let k=0;k<tk.s.length;k++){ pos.push({i,o:k}); }
                joined+=tk.s;
            }else if(tk.t==='br'){ pos.push({i,o:-1}); joined+='\n'; }
        });
        const spans=[];
        let from=0;
        for(;;){
            const at=joined.indexOf(needle,from);
            if(at<0||spans.length>=50) break;
            spans.push([at,at+needle.length]);
            from=at+Math.max(1,needle.length);
        }
        if(!spans.length) return {html:src,count:0};
        // 뒤에서부터 고쳐 앞쪽 오프셋이 밀리지 않게 한다.
        for(let s=spans.length-1;s>=0;s--){
            const a=spans[s][0],b=spans[s][1];
            const pA=pos[a],pB=b<pos.length?pos[b]:null;
            const endTok=pB?pB.i:toks.length, endOff=pB?(pB.o<0?0:pB.o):0;
            const stTok=pA.i, stOff=pA.o<0?0:pA.o;
            for(let i=stTok+1;i<endTok;i++){
                if(toks[i].t==='txt') toks[i].s='';
                else if(toks[i].t==='br') toks[i].dead=true;
            }
            if(pA.o<0){
                // 줄바꿈부터 시작 — <br>을 지우고 그 앞에 바꾼 글을 넣는다.
                toks[stTok].dead=true;
                toks.splice(stTok,0,{t:'txt',s:rep});
                if(endTok<toks.length-1&&toks[endTok+1]&&toks[endTok+1].t==='txt')
                    toks[endTok+1].s=toks[endTok+1].s.slice(endOff);
            }else if(stTok===endTok){
                toks[stTok].s=toks[stTok].s.slice(0,stOff)+rep+toks[stTok].s.slice(stOff+(b-a));
            }else{
                toks[stTok].s=toks[stTok].s.slice(0,stOff)+rep;
                if(endTok<toks.length&&toks[endTok]&&toks[endTok].t==='txt')
                    toks[endTok].s=toks[endTok].s.slice(endOff);
            }
        }
        let out='';
        toks.forEach(tk=>{
            if(tk.dead) return;
            if(tk.t==='tag') out+=tk.s;
            else if(tk.t==='br') out+='<br>';
            else if(tk.t==='txt') out+=esc(tk.s).replace(/\n/g,'<br>');
        });
        return {html:out,count:spans.length};
    }

    // ── 14.27.0 · 형광펜(부분 강조) ──────────────────────────────────────
    // 해돌이가 형광펜을 못 알아듣던 이유는 '상자 전체 배경(el.cellBg)'밖에
    // 못 건드렸기 때문이다. 이제 저장 포맷과 같은 글자 span(background-color)으로
    // 글귀 단위로 칠하고, 스냅샷에도 칠해진 곳을 ⟦…⟧ 로 보여 준다.
    const AI_HL_MARK=['\u27e6','\u27e7'];               // ⟦ ⟧ — 스냅샷의 형광펜 표시
    const AI_HL_DEFAULT='#efd36a';                     // 색을 안 적으면 노랑 형광펜
    const AI_HL_BG_RE=/background(?:-color)?\s*:\s*[^;"']+\s*;?/gi;
    const AI_VOID_TAGS={br:1,hr:1,img:1,input:1,meta:1,link:1,area:1,base:1,col:1,
        embed:1,source:1,track:1,wbr:1};
    // span·font 같은 글자 꾸밈 태그에 형광펜(배경색)이 들어 있는가.
    function aiEditTagBg(tagStr){
        const s=String(tagStr||'');
        const m=/background(?:-color)?\s*:\s*([^;"']+)/i.exec(s);
        if(m){
            // rgb(…)·이름으로 적혀 있어도 알아본다(가져온 문서에 그런 경우가 있다).
            let raw=String(m[1]).trim();
            try{
                if(typeof _colorToHex==='function'){
                    const hx=_colorToHex(raw);
                    if(hx&&hx!=='transparent') raw=hx;
                }
            }catch(e){}
            const c=aiEditColor(raw,true);
            if(c) return c;
        }
        const d=/data-(?:highlight|background-color)\s*=\s*"([^"]+)"/i.exec(s);
        if(d){
            const c2=aiEditColor(d[1],true);
            if(c2) return c2;
        }
        return '';
    }
    // 태그 문자열에서 배경색만 걷어낸다(다른 서식은 그대로).
    function aiEditStripBg(tagStr){
        return String(tagStr||'')
            .replace(/(<[a-zA-Z][^>]*?\sstyle\s*=\s*")([^"]*)(")/gi,(all,pre,css,post)=>{
                const next=css.replace(AI_HL_BG_RE,'').replace(/;;+/g,';')
                    .replace(/^\s*;|;\s*$/g,'').trim();
                return pre+next+post;
            })
            .replace(/\sdata-(?:highlight|background-color)\s*=\s*"[^"]*"/gi,'');
    }
    // 스냅샷 미리보기 — 칠해진 글귀를 ⟦…⟧ 로 감싸 모델에게 보여 준다.
    function aiEditHlPreview(html){
        const parts=String(html==null?'':html).split(/(<[^>]*>)/g);
        const stack=[]; let out='',open=false;
        parts.forEach(part=>{
            if(!part) return;
            if(part.charAt(0)==='<'){
                if(/^<br\s*\/?>$/i.test(part)){ if(open){ out+=AI_HL_MARK[1]; open=false; } out+='\n'; return; }
                const m=/^<\s*(\/?)\s*([a-zA-Z][0-9]*)([^>]*?)(\/?)\s*>$/.exec(part);
                if(!m) return;
                const tag=m[2].toLowerCase();
                if(m[1]){
                    for(let k=stack.length-1;k>=0;k--){
                        if(stack[k].tag===tag){ stack.length=k; break; }
                    }
                    return;
                }
                if(m[4]||AI_VOID_TAGS[tag]) return;
                stack.push({tag:tag,bg:tag==='mark'||!!aiEditTagBg(part)});
                return;
            }
            let bg=false;
            for(const s of stack){ if(s.bg){ bg=true; break; } }
            const txt=aiEditDecodeEntities(part).replace(/\s+/g,' ');
            if(!txt) return;
            if(bg&&!open){ out+=AI_HL_MARK[0]; open=true; }
            else if(!bg&&open){ out+=AI_HL_MARK[1]; open=false; }
            out+=txt.replace(/</g,'‹').replace(/>/g,'›');
        });
        if(open) out+=AI_HL_MARK[1];
        return out.replace(/\s+/g,' ').trim();
    }
    // 모델이 스냅샷의 ⟦⟧ 표시를 그대로 베껴 와도 찾을 수 있게 털어 낸다.
    function aiEditLooseFind(value){
        const mark=new RegExp('['+AI_HL_MARK[0]+AI_HL_MARK[1]+']','g');
        return String(value==null?'':value).replace(mark,'').replace(/\s+/g,' ').trim();
    }
    // 글귀에 형광펜 span을 씌운다. 기존 굵기·색 span과 어긋나게 중첩되지 않도록
    // 글 토큰 단위로 감싼다(태그를 반쯤 걸친 span을 만들지 않는다).
    function aiEditMarkHtml(html,find,color){
        const src=String(html==null?'':html);
        const needle=String(find==null?'':find);
        if(!needle) return {html:src,count:0};
        const toks=[];
        src.split(/(<[^>]*>)/g).forEach(part=>{
            if(!part) return;
            if(part.charAt(0)==='<'){
                if(/^<br\s*\/?>$/i.test(part)) toks.push({t:'br'});
                else toks.push({t:'tag',s:part});
            }else toks.push({t:'txt',s:aiEditDecodeEntities(part)});
        });
        let joined=''; const pos=[];
        toks.forEach((tk,i)=>{
            if(tk.t==='txt'){ for(let k=0;k<tk.s.length;k++) pos.push({i:i,o:k}); joined+=tk.s; }
            else if(tk.t==='br'){ pos.push({i:i,o:-1}); joined+='\n'; }
        });
        const spans=[]; let from=0;
        for(;;){
            const at=joined.indexOf(needle,from);
            if(at<0||spans.length>=50) break;
            spans.push([at,at+needle.length]);
            from=at+Math.max(1,needle.length);
        }
        if(!spans.length) return {html:src,count:0};
        const open='<span style="background-color:'+color+'">';
        for(let s=spans.length-1;s>=0;s--){
            const a=spans[s][0],b=spans[s][1];
            const hit=[];
            for(let k=a;k<b;k++){
                const p=pos[k];
                if(!p||p.o<0) continue;                 // 줄바꿈은 건너뛴다(줄별로 칠한다)
                if(!hit.length||hit[hit.length-1].i!==p.i) hit.push({i:p.i,from:p.o,to:p.o});
                else hit[hit.length-1].to=p.o;
            }
            for(let k=hit.length-1;k>=0;k--){
                const i=hit[k].i,tk=toks[i];
                if(!tk||tk.t!=='txt') continue;
                const mid=tk.s.slice(hit[k].from,hit[k].to+1);
                if(!mid) continue;
                const before=tk.s.slice(0,hit[k].from),after=tk.s.slice(hit[k].to+1);
                const parts=[];
                if(before) parts.push({t:'txt',s:before});
                parts.push({t:'raw',s:open},{t:'txt',s:mid},{t:'raw',s:'</span>'});
                if(after) parts.push({t:'txt',s:after});
                toks.splice.apply(toks,[i,1].concat(parts));
            }
        }
        let out='';
        toks.forEach(tk=>{
            if(tk.t==='tag'||tk.t==='raw') out+=tk.s;
            else if(tk.t==='br') out+='<br>';
            else if(tk.t==='txt') out+=esc(tk.s).replace(/\n/g,'<br>');
        });
        return {html:out,count:spans.length};
    }
    // 형광펜을 지운 자리에 남는 빈 꾸밈 span은 털어 낸다(문서가 지저분해지지 않게).
    function aiEditDropEmptyTags(html){
        let out=String(html==null?'':html),prev='';
        for(let i=0;i<3&&out!==prev;i++){
            prev=out;
            out=out.replace(/<(span|b|strong|i|em|u|font)\b[^>]*>\s*<\/\1>/gi,'');
            // 배경만 있던 span은 빈 style="" 이 남는다 — 속성을 지우고,
            // 속성 없는 span 은 알맹이만 남긴다(안에 태그가 있으면 건드리지 않는다).
            out=out.replace(/(<[a-zA-Z][a-zA-Z0-9]*)\s+style=""(?=[\s>])/g,'$1');
            out=out.replace(/<span>((?:(?!<)[\s\S])*)<\/span>/gi,'$1');
        }
        return out;
    }
    // 형광펜 지우기 — 찾을 글이 있으면 그 글귀만, 없으면 상자 전체.
    // 글귀 지우기는 그 글귀를 감싸고 있던 span을 경계에서 끊고 다시 이어 붙인다:
    //   <span S>AB CD</span> 에서 AB만 지우면 <span S></span><span S′>AB</span><span S> CD</span>
    //   (S′=S에서 배경색만 뺀 것) → 나머지 글의 형광펜·서식은 그대로 남는다.
    function aiEditUnmarkHtml(html,find){
        const src=String(html==null?'':html);
        const needle=String(find==null?'':find);
        const toks=[];
        src.split(/(<[^>]*>)/g).forEach(part=>{
            if(!part) return;
            if(part.charAt(0)==='<'){
                if(/^<br\s*\/?>$/i.test(part)) toks.push({t:'br'});
                else toks.push({t:'tag',s:part});
            }else toks.push({t:'txt',s:aiEditDecodeEntities(part)});
        });
        let touched=0;
        if(!needle){
            toks.forEach(tk=>{
                if(tk.t!=='tag') return;
                const next=aiEditStripBg(tk.s);
                if(next!==tk.s){ tk.s=next; touched++; }
            });
        }else{
            let joined=''; const pos=[];
            toks.forEach((tk,i)=>{
                if(tk.t==='txt'){ for(let k=0;k<tk.s.length;k++) pos.push({i:i,o:k}); joined+=tk.s; }
                else if(tk.t==='br'){ pos.push({i:i,o:-1}); joined+='\n'; }
            });
            const spans=[]; let from=0;
            for(;;){
                const at=joined.indexOf(needle,from);
                if(at<0||spans.length>=50) break;
                spans.push([at,at+needle.length]);
                from=at+Math.max(1,needle.length);
            }
            if(!spans.length) return {html:src,count:0};
            for(let s=spans.length-1;s>=0;s--){
                const a=spans[s][0],b=spans[s][1];
                const pA=pos[a]; if(!pA) continue;
                const pB=b<pos.length?pos[b]:null;
                const stTok=pA.i, endTok=pB?pB.i:toks.length;
                // ① 이 범위를 감싸고 있는 span(형광펜이 있는 것만)
                const stack=[],wrap=[];
                for(let i=0;i<stTok;i++){
                    const tk=toks[i];
                    if(tk.t!=='tag') continue;
                    const m=/^<\s*(\/?)\s*([a-zA-Z][0-9]*)([^>]*?)(\/?)\s*>$/.exec(tk.s);
                    if(!m) continue;
                    const tag=m[2].toLowerCase();
                    if(m[1]){
                        for(let k=stack.length-1;k>=0;k--){
                            if(stack[k].tag===tag){ stack.length=k; break; }
                        }
                    }else if(!m[4]&&!AI_VOID_TAGS[tag]) stack.push({tag:tag,i:i,s:tk.s});
                }
                stack.forEach(o=>{ if(aiEditTagBg(o.s)) wrap.push(o); });
                // ② 범위 안에 들어 있는 태그의 배경색도 지운다
                let inside=0;
                for(let i=stTok;i<endTok&&i<toks.length;i++){
                    if(toks[i].t!=='tag') continue;
                    const next=aiEditStripBg(toks[i].s);
                    if(next!==toks[i].s){ toks[i].s=next; inside++; }
                }
                if(!wrap.length&&!inside) continue;      // 이 글귀엔 칠해진 곳이 없다
                const closeAll=wrap.map(function(){ return '<'+'/span>'; }).join('');
                const reopen=arr=>arr.map(o=>o.s).join('');
                const plain=wrap.map(o=>({s:aiEditStripBg(o.s)}));
                // 찾은 글귀는 '배경 없는 span'으로, 그 앞뒤는 원래 배경으로 이어 붙인다.
                const head=closeAll+reopen(plain);
                const tail=closeAll+reopen(wrap);
                // ③ 글 토큰을 잘라 경계를 넣는다(뒤에서부터 — 앞쪽 색인은 그대로)
                const hit=[];
                for(let k=a;k<b;k++){
                    const p=pos[k];
                    if(!p||p.o<0) continue;
                    if(!hit.length||hit[hit.length-1].i!==p.i) hit.push({i:p.i,from:p.o,to:p.o});
                    else hit[hit.length-1].to=p.o;
                }
                for(let k=hit.length-1;k>=0;k--){
                    const i=hit[k].i,tk=toks[i];
                    if(!tk||tk.t!=='txt') continue;
                    const mid=tk.s.slice(hit[k].from,hit[k].to+1);
                    if(!mid) continue;
                    const before=tk.s.slice(0,hit[k].from),after=tk.s.slice(hit[k].to+1);
                    const parts=[];
                    if(before) parts.push({t:'txt',s:before});
                    parts.push({t:'raw',s:head},{t:'txt',s:mid},{t:'raw',s:tail});
                    if(after) parts.push({t:'txt',s:after});
                    toks.splice.apply(toks,[i,1].concat(parts));
                }
                touched+=hit.length+inside;
            }
        }
        if(!touched) return {html:src,count:0};
        let out='';
        toks.forEach(tk=>{
            if(tk.t==='tag'||tk.t==='raw') out+=tk.s;
            else if(tk.t==='br') out+='<br>';
            else if(tk.t==='txt') out+=esc(tk.s).replace(/\n/g,'<br>');
        });
        return {html:aiEditDropEmptyTags(out),count:touched};
    }

    // ── 14.27.0 · 사람이 보기 좋은 배치 ────────────────────────────────
    // 모델이 준 좌표를 그대로 쓰면 상자마다 왼쪽 끝이 다르고 서로 겹친다.
    // 그래서 ① 8px 격자에 맞추고 ② 이웃·본문 왼쪽 끝에 붙이고 ③ 새 요소는
    // 겹치지 않는 첫 빈자리로 내린다. 명시 좌표(@mv·@bx)는 ①·②만 적용해
    // '옮겨 달라'는 요청을勝手に 뒤집지 않는다.
    const AI_GRID=8, AI_EDGE=28, AI_GAP=12, AI_MARGIN=40;
    // 쪽에서 자리를 차지하는 상자들(표 테두리 획은 표 상자로 한 번만 센다).
    function aiEditOccupied(pi,skipId){
        const out=[];
        const pg=doc&&doc.pages&&doc.pages[pi];
        if(!pg) return out;
        (pg.els||[]).forEach(el=>{
            if(!el||el.id===skipId) return;
            if(el.type==='stroke'&&el.tbl) return;
            const b=aiEditBox(el);
            if(b.w>0||b.h>0) out.push({x:b.x,y:b.y,w:b.w,h:b.h,id:el.id});
        });
        (pg.tables||[]).forEach(t=>{
            if(!t||t.id===skipId) return;
            const s=tblSize(t);
            out.push({x:+t.x||0,y:+t.y||0,w:s.w,h:s.h,id:t.id});
        });
        return out;
    }
    const aiEditHits=(a,b,pad)=>a.x<b.x+b.w+pad&&b.x<a.x+a.w+pad
        &&a.y<b.y+b.h+pad&&b.y<a.y+a.h+pad;
    // 본문이 쓰는 왼쪽 끝·너비 — 새 상자를 이 값에 맞춘다(문서가 정돈돼 보인다).
    function aiEditMargins(pi){
        const boxes=aiEditOccupied(pi).filter(b=>b.w>10&&b.h>6);
        const count=(list,key)=>{
            const map={};
            list.forEach(b=>{ const k=Math.round(b[key]/AI_GRID)*AI_GRID; map[k]=(map[k]||0)+1; });
            let best=null,n=0;
            for(const k in map){ if(map[k]>n){ n=map[k]; best=+k; } }
            return best;
        };
        const texts=boxes.filter(b=>b.w<aiEditPageSize().w-8);
        return {
            left:count(texts.length?texts:boxes,'x'),
            width:count(texts,'w'),
            top:boxes.length?Math.min.apply(null,boxes.map(b=>b.y)):AI_MARGIN,
        };
    }
    const aiEditPageSize=()=>paperSize();
    // 겹치지 않는 첫 빈자리 — 위부터 훑고, 왼쪽 끝 → 가운데 → 오른쪽 순으로 본다.
    function aiEditFreeSpot(pi,w,h,startY){
        const size=aiEditPageSize();
        const m=aiEditMargins(pi);
        const list=aiEditOccupied(pi);
        const left=m.left==null?AI_MARGIN:Math.min(m.left,Math.max(0,size.w-w));
        // 후보 자리도 격자에 맞춘다 — 본문 왼쪽 끝 → 가운데 → 오른쪽 순.
        // 왼쪽 줄을 먼저 훑어야 새 상자가 본문과 왼쪽이 맞아 정돈돼 보인다.
        const xs=[left,Math.round(Math.max(0,size.w-w)/2),Math.max(0,size.w-w-left)]
            .map(v=>Math.max(0,Math.min(Math.round(v/AI_GRID)*AI_GRID,Math.max(0,size.w-w))));
        const yEnd=Math.max(AI_MARGIN,Math.round(size.h-h));
        const y0=Math.max(AI_MARGIN,Math.min(Math.round(+startY)||AI_MARGIN,yEnd));
        const scan=(from,to)=>{
            for(let i=0;i<xs.length;i++){
                for(let y=from;y<=to;y+=AI_GRID){
                    const box={x:xs[i],y:y,w:w,h:h};
                    if(!list.some(o=>aiEditHits(box,o,AI_GAP))) return box;
                }
            }
            return null;
        };
        // 요청한 높이부터 아래로 훑고, 없으면 페이지 맨 위부터 다시 본다.
        const hit=scan(y0,yEnd)||scan(AI_MARGIN,yEnd);
        if(hit) return hit;
        // 빈자리가 없으면 맨 아래 내용 밑에 둔다(그래도 페이지 안).
        let bottom=AI_MARGIN;
        list.forEach(o=>{ bottom=Math.max(bottom,o.y+o.h+AI_GAP); });
        return {x:left,y:Math.max(AI_MARGIN,Math.min(bottom,yEnd)),w:w,h:h};
    }
    // 격자·왼쪽 끝 맞추기(+ 필요하면 겹침 피하기). 페이지 밖으로 나가지 않는다.
    function aiEditNeat(pi,x,y,w,h,opt){
        const size=aiEditPageSize();
        const o=opt||{};
        const d={w:Math.max(20,Math.min(Math.round(w),size.w)),
                 h:Math.max(20,Math.min(Math.round(h),size.h))};
        const m=aiEditMargins(pi);
        let nx=Math.round(+x||0),ny=Math.round(+y||0);
        // 격자는 새 요소에만 — '그 좌표로 옮겨 달라'는 요청은 좌표를 존중한다.
        if(o.snap){
            nx=Math.round(nx/AI_GRID)*AI_GRID;
            ny=Math.round(ny/AI_GRID)*AI_GRID;
        }
        if(o.align!==false&&m.left!=null&&Math.abs(nx-m.left)<=AI_EDGE) nx=m.left;
        let box={x:nx,y:ny,w:d.w,h:d.h};
        if(o.avoid){
            const list=aiEditOccupied(pi,o.skipId);
            let guard=0;
            while(list.some(ob=>aiEditHits(box,ob,AI_GAP))&&guard++<400){
                const clash=list.filter(ob=>aiEditHits(box,ob,AI_GAP));
                const below=Math.min.apply(null,clash.map(ob=>ob.y+ob.h+AI_GAP));
                const ny2=Math.round(below/AI_GRID)*AI_GRID;
                if(ny2<=box.y||ny2+d.h>size.h) break;
                box={x:box.x,y:ny2,w:d.w,h:d.h};
            }
        }
        box.x=Math.max(0,Math.min(box.x,Math.max(0,size.w-box.w)));
        box.y=Math.max(0,Math.min(box.y,Math.max(0,size.h-box.h)));
        return box;
    }
    // 새 상자의 높이 어림 — 글이 상자 밖으로 새는 게 제일 보기 나쁘다.
    // 한글은 1자, 영숫자는 0.55자 폭으로 세고 줄 간격 1.5 + 위아래 여백을 더한다.
    function aiEditGuessH(text,w,fontSize){
        const size=aiEditPageSize();
        const fs=Math.max(8,Math.min(200,+fontSize||16));
        const bw=Math.max(40,Math.min(+w||size.w-2*AI_MARGIN,size.w-8))-16;
        const perLine=Math.max(4,Math.floor(bw/fs));
        let lines=0;
        String(text==null?'':text).split('\n').forEach(line=>{
            let units=0;
            for(const ch of line){
                units+=/[\u1100-\u11ff\u2e80-\u9fff\uac00-\ud7af\uf900-\ufaff\uff00-\uffef]/.test(ch)?1:0.55;
            }
            lines+=Math.max(1,Math.ceil(units/perLine));
        });
        return Math.max(28,Math.min(size.h-8,Math.round(lines*fs*1.5+18)));
    }
    const aiEditIsAuto=v=>{
        const s=String(v==null?'':v).trim().toLowerCase();
        return s==='auto'||s==='자동'||s==='알아서'||s==='-'||s==='*'||s==='?';
    };
    // @goto·@newpage 뒤 화면 이동 — addPage와 같은 규칙(교체된 노트면 무시).
    function aiEditScrollToPage(pi){
        try{
            const d=doc,_pi=pi;
            setTimeout(()=>{
                if(doc!==d||!curNB) return;
                // AI가 먼 쪽으로 이동해도 중간 페이지를 연쇄 로드하지 않는다(즉시 이동).
                try{ maintainPageWindow(_pi,true); }catch(e){}
                try{ scrollPageIntoView(_pi,'auto'); }catch(e){}
            },60);
        }catch(e){}
    }
    function aiEditApply(ops,expectedRevision){
        const res={applied:0,failed:0,notes:[],stale:false};
        const note=msg=>{ if(msg&&res.notes.length<4&&res.notes.indexOf(msg)<0) res.notes.push(msg); };
        const bad=msg=>{ res.failed++; note(msg); };
        if(!doc||!curNB){ bad('열린 노트가 없어요'); return res; }
        if(!Array.isArray(ops)||!ops.length) return res;
        // 모델을 기다리는 동안 사용자가 타이핑한 글도 먼저 doc에 반영한 뒤 비교한다.
        try{ commitEditingText(); }catch(e){}
        if(expectedRevision&&expectedRevision!==aiEditRevision()){
            res.stale=true;
            note('기다리는 동안 문서가 바뀌어서 오래된 편집 계획은 적용하지 않았어요 · 다시 요청해 주세요');
            return res;
        }
        const size=paperSize();
        const finite=v=>v!==''&&v!=null&&Number.isFinite(Number(v));
        const round=v=>Math.round(Number(v));
        const clamp=(v,lo,hi)=>Math.max(lo,Math.min(hi,v));
        const text=v=>String(v==null?'':v).slice(0,AI_EDIT_MAX_TEXT);
        const html=v=>esc(text(v)).replace(/\n/g,'<br>');
        const findAny=id=>{
            id=String(id||'').trim();
            if(!id) return null;
            for(let pi=0;pi<doc.pages.length;pi++){
                const pg=doc.pages[pi]; if(!pg||pg.__lazy!=null) continue;
                const el=(pg.els||[]).find(item=>item&&item.id===id);
                if(el) return {el,pi};
            }
            return null;
        };
        const findTblAny=tid=>{
            tid=String(tid||'').trim();
            if(!tid) return null;
            for(let pi=0;pi<doc.pages.length;pi++){
                const pg=doc.pages[pi]; if(!pg||pg.__lazy!=null) continue;
                const t=(pg.tables||[]).find(item=>item&&item.id===tid);
                if(t) return {t,pi};
            }
            return null;
        };
        const touched=new Set(); let historyStarted=false;
        const beforeChange=()=>{
            if(historyStarted) return;
            // 첫 유효 명령이 확인된 뒤에만 선택을 접고 undo 지점을 만든다.
            // 전부 잘못된 계획은 사용자의 편집 상태조차 건드리지 않는다.
            try{ deselectAll(true); clearMulti(); selected=null; }catch(e){}
            pushHistory(true); historyStarted=true;
        };
        const boxSize=(w,h)=>({
            w:clamp(round(w),20,Math.max(20,size.w)),
            h:clamp(round(h),20,Math.max(20,size.h)),
        });
        // 좌표 다듬기. 새 요소(opt.snap·opt.avoid)는 격자에 맞추고 겹치지 않는
        // 자리로 내린다. 옮기기(@mv·@bx)는 '그 자리로 옮겨 달라'는 요청이라
        // 격자까지는 씌우지 않고 본문 왼쪽 끝과 가까울 때만 붙인다.
        const place=(x,y,w,h,opt)=>{
            const d=boxSize(w,h);
            const o=opt||{};
            const pi=(o.pi==null)?(curPageIdx|0):o.pi;
            if(o.neat===false)
                return {x:clamp(round(x),0,Math.max(0,size.w-d.w)),
                    y:clamp(round(y),0,Math.max(0,size.h-d.h)),w:d.w,h:d.h};
            return aiEditNeat(pi,x,y,d.w,d.h,{snap:!!o.snap,avoid:!!o.avoid,
                align:o.align!==false,skipId:o.skipId});
        };
        // 표 전체 삭제 — 칸·테두리 획까지 함께 지운다(@del·@tdel 모두).
        const dropTable=tf=>{
            beforeChange();
            doc.pages[tf.pi].tables=(doc.pages[tf.pi].tables||[]).filter(x=>x!==tf.t);
            doc.pages[tf.pi].els=(doc.pages[tf.pi].els||[])
                .filter(e=>!(e&&e.tbl&&e.tbl.tid===tf.t.id));
            try{ clearActiveTbl(); }catch(e){}
            touched.add(tf.pi);
            try{ if(renderedPages.has(tf.pi)) renderTblDivs(tf.pi); }catch(e){}
        };
        const limited=ops.slice(0,AI_EDIT_MAX_OPS);
        if(ops.length>AI_EDIT_MAX_OPS){
            res.failed+=ops.length-AI_EDIT_MAX_OPS;
            note('명령이 많아 앞의 '+AI_EDIT_MAX_OPS+'개만 확인했어요');
        }
        limited.forEach(op=>{
            const cmd=String(op&&op.cmd||'').toLowerCase();
            // ── 쪽·제목·표 — 요소 id 없이 쪽 단위로 돈다 ──
            if(cmd==='goto'){
                if(!finite(op.page)||!Number.isInteger(Number(op.page))){
                    bad('이동할 쪽 번호가 올바르지 않아요'); return;
                }
                const page=round(op.page);
                if(page<1||page>doc.pages.length){
                    bad('그런 쪽은 없어요 · 총 '+doc.pages.length+'쪽이에요'); return;
                }
                // 화면만 옮긴다 — 문서·undo에 손대지 않는다.
                curPageIdx=page-1;
                try{ updatePageInfo(); }catch(e){}
                aiEditScrollToPage(page-1);
                res.applied++; return;
            }
            if(cmd==='newpage'){
                if(doc.pages.length>=200){ bad('쪽이 너무 많아 더 만들지 않았어요'); return; }
                beforeChange();
                doc.pages.push(blankPage());
                curPageIdx=doc.pages.length-1;
                try{ updatePageInfo(); }catch(e){}
                try{ renderPages(); }catch(e){}
                aiEditScrollToPage(curPageIdx);
                touched.add(curPageIdx); res.applied++; return;
            }
            // 14.27.0 · @tidy — 쪽을 보기 좋게 정돈한다. ① 8px 격자에 맞추고
            //   ② 본문 왼쪽 끝에 가까운 상자는 그 끝에 붙이고 ③ 절반 넘게
            //   겹친 상자만 아래로 내린다(나란히 세운 두 칸은 건드리지 않는다).
            if(cmd==='tidy'){
                let tpi=curPageIdx|0;
                if(finite(op.page)){
                    if(!Number.isInteger(Number(op.page))){
                        bad('정돈할 쪽 번호가 올바르지 않아요'); return;
                    }
                    tpi=round(op.page)-1;
                }
                const tpg=doc.pages[tpi];
                if(tpi<0||tpi>=doc.pages.length||!tpg||tpg.__lazy!=null){
                    bad('그 쪽을 찾거나 불러오지 못했어요'); return;
                }
                const tleft=(aiEditMargins(tpi).left);
                const margin=tleft==null?AI_MARGIN:tleft;
                const items=[];
                (tpg.els||[]).forEach(el=>{
                    if(!el||el.locked||el.tbl) return;
                    if(!['text','image','latex','stroke'].includes(el.type)) return;
                    const b=aiEditBox(el);
                    if(b.w<=0&&b.h<=0) return;
                    let nx=Math.round(b.x/AI_GRID)*AI_GRID,ny=Math.round(b.y/AI_GRID)*AI_GRID;
                    if(Math.abs(nx-margin)<=Math.round(AI_EDGE*1.5)) nx=margin;
                    nx=clamp(nx,0,Math.max(0,size.w-Math.round(b.w)));
                    ny=clamp(ny,0,Math.max(0,size.h-Math.round(b.h)));
                    items.push({el:el,base:b,box:{x:nx,y:ny,w:b.w,h:b.h}});
                });
                items.sort((a,b)=>a.box.y-b.box.y||a.box.x-b.box.x);
                const placed=[];
                items.forEach(item=>{
                    let guard=0;
                    for(;;){
                        const clash=placed.find(o=>{
                            if(!aiEditHits(item.box,o.box,AI_GAP/2)) return false;
                            const ow=Math.min(item.box.x+item.box.w,o.box.x+o.box.w)
                                -Math.max(item.box.x,o.box.x);
                            const oh=Math.min(item.box.y+item.box.h,o.box.y+o.box.h)
                                -Math.max(item.box.y,o.box.y);
                            return ow*oh>0.5*Math.min(item.box.w*item.box.h,o.box.w*o.box.h);
                        });
                        if(!clash||guard++>60) break;
                        const below=Math.round((clash.box.y+clash.box.h+AI_GAP)/AI_GRID)*AI_GRID;
                        if(below<=item.box.y) break;
                        item.box.y=Math.min(below,Math.max(0,size.h-Math.round(item.box.h)));
                    }
                    placed.push(item);
                });
                const moves=items.filter(item=>Math.round(item.base.x)!==item.box.x
                    ||Math.round(item.base.y)!==item.box.y);
                // 표도 같은 규칙으로(칸은 rebuildTable이 따라온다).
                const tbls=[];
                (tpg.tables||[]).forEach(t=>{
                    if(!t||!Array.isArray(t.cw)||!Array.isArray(t.ch)) return;
                    const ts=tblSize(t);
                    let nx=Math.round((+t.x||0)/AI_GRID)*AI_GRID;
                    if(Math.abs(nx-margin)<=Math.round(AI_EDGE*1.5)) nx=margin;
                    nx=clamp(nx,0,Math.max(0,size.w-ts.w));
                    const ny=clamp(Math.round((+t.y||0)/AI_GRID)*AI_GRID,
                        0,Math.max(0,size.h-ts.h));
                    if(Math.round(+t.x||0)!==nx||Math.round(+t.y||0)!==ny)
                        tbls.push({t:t,x:nx,y:ny});
                });
                if(!moves.length&&!tbls.length){ bad('이미 정돈돼 있어요'); return; }
                beforeChange();
                moves.forEach(item=>{
                    if(item.el.type==='stroke'){
                        item.el.dx=item.box.x-item.base.baseX;
                        item.el.dy=item.box.y-item.base.baseY;
                    }else{ item.el.x=item.box.x; item.el.y=item.box.y; }
                });
                tbls.forEach(item=>{
                    item.t.x=item.x; item.t.y=item.y;
                    try{ rebuildTable(tpi,item.t.id,{quiet:true}); }catch(e){}
                });
                if(tbls.length){ try{ if(renderedPages.has(tpi)) renderTblDivs(tpi); }catch(e){} }
                touched.add(tpi); res.applied++; return;
            }
            if(cmd==='title'){
                const t=text(op.text).replace(/\s+/g,' ').trim().slice(0,100);
                if(!t){ bad('노트 제목이 비어 있어요'); return; }
                const input=document.getElementById('edTitle');
                if(!input){ bad('제목 입력칸을 찾지 못했어요'); return; }
                // 기존 change 리스너가 노트 이름 저장·동기화를 맡는다.
                input.value=t;
                try{ input.dispatchEvent(new Event('change',{bubbles:true})); }
                catch(e){ try{ if(curNB){ curNB.title=t; queueSync(curNB.id); } }catch(e2){} }
                res.applied++; return;
            }
            if(cmd==='tbl'){
                const posOk=v=>finite(v)||aiEditIsAuto(v);
                if(!finite(op.page)||!Number.isInteger(Number(op.page))
                   ||!posOk(op.x)||!posOk(op.y)||!finite(op.rows)||!finite(op.cols)){
                    bad('표를 만들 위치나 크기가 올바르지 않아요'); return;
                }
                const page=round(op.page),pi=page-1,pg=doc.pages[pi];
                if(page<1||page>doc.pages.length||!pg||pg.__lazy!=null){
                    bad('해당 페이지를 찾거나 불러오지 못했어요'); return;
                }
                const body=String(op.text==null?'':op.text).slice(0,8000);
                const grid=body.split('\n').map(line=>line.split('|').map(c=>c.trim()));
                // 내용이 선언보다 많으면 행·열을 자동으로 늘린다.
                let rows=Math.max(clamp(Math.round(Number(op.rows)),1,20),
                    Math.min(20,grid.filter(r=>r.some(c=>c)).length||0));
                let cols=clamp(Math.round(Number(op.cols)),1,12);
                grid.forEach(r=>{ cols=Math.max(cols,Math.min(12,r.length)); });
                rows=Math.max(1,rows); cols=Math.max(1,cols);
                // 칸 글 길이에 맞춰 너비·높이를 어림잡는다.
                const cw=[],ch=[];
                for(let c=0;c<cols;c++){
                    let mx=0;
                    for(let r=0;r<rows;r++) mx=Math.max(mx,(((grid[r]||[])[c])||'').length);
                    cw.push(clamp(60+mx*9,60,260));
                }
                for(let r=0;r<rows;r++){
                    let mx=0;
                    for(let c=0;c<cols;c++) mx=Math.max(mx,(((grid[r]||[])[c])||'').length);
                    ch.push(mx>28?60:40);
                }
                let tw=cw.reduce((a,b)=>a+b,0),th=ch.reduce((a,b)=>a+b,0);
                const maxW=Math.max(120,size.w-16),maxH=Math.max(80,size.h-16);
                if(tw>maxW){ const k=maxW/tw; for(let i=0;i<cw.length;i++) cw[i]=Math.max(TBL_MINW,Math.round(cw[i]*k)); tw=cw.reduce((a,b)=>a+b,0); }
                if(th>maxH){ const k=maxH/th; for(let i=0;i<ch.length;i++) ch[i]=Math.max(TBL_MINH,Math.round(ch[i]*k)); th=ch.reduce((a,b)=>a+b,0); }
                // 14.27.0 · auto면 겹치지 않는 빈자리를 고르고, 좌표를 주면
                // 격자·본문 왼쪽 끝에 맞춰 정돈된 자리에 둔다.
                let ox,oy;
                if(aiEditIsAuto(op.x)||aiEditIsAuto(op.y)){
                    const spot=aiEditFreeSpot(pi,tw,th,aiEditIsAuto(op.y)?0:round(op.y));
                    ox=spot.x; oy=spot.y;
                }else{
                    const neat=aiEditNeat(pi,clamp(round(op.x),8,Math.max(8,size.w-tw-8)),
                        clamp(round(op.y),8,Math.max(8,size.h-th-8)),tw,th,{snap:true,avoid:false});
                    ox=neat.x; oy=neat.y;
                }
                beforeChange();
                if(!Array.isArray(pg.tables)) pg.tables=[];
                const tid='tb_'+Math.random().toString(36).slice(2,9);
                pg.tables.push({id:tid,x:ox,y:oy,cw:cw.slice(),ch:ch.slice(),
                    color:'#9aa1ab',lw:1.2,group:'g_'+tid});
                try{ rebuildTable(pi,tid,{quiet:true}); }
                catch(e){
                    pg.tables=pg.tables.filter(t=>t.id!==tid);
                    bad('표를 만들지 못했어요'); return;
                }
                const list=doc.pages[pi].els||[];
                for(let r=0;r<rows;r++) for(let c=0;c<cols;c++){
                    const v=(((grid[r]||[])[c])||'').slice(0,500);
                    if(!v) continue;
                    const cell=list.find(e=>e&&e.type==='text'&&e.tbl
                        &&e.tbl.tid===tid&&e.tbl.r===r&&e.tbl.c===c);
                    if(cell) cell.html=aiMdToHtml(v,cell.fontSize||16);   // 14.29.2 · 칸 안의 **굵게**·$수식$
                }
                touched.add(pi);
                try{ if(renderedPages.has(pi)) renderTblDivs(pi); }catch(e){}
                res.applied++; return;
            }
            if(cmd==='tsz'||cmd==='tmv'){
                const tf=findTblAny(op&&op.id);
                if(!tf){ bad('그런 표를 찾지 못했어요'); return; }
                if(cmd==='tsz'&&(!finite(op.w)||!finite(op.h))){
                    bad('표 크기가 올바르지 않아요'); return;
                }
                if(cmd==='tmv'&&(!finite(op.x)||!finite(op.y))){
                    bad('표 위치가 올바르지 않아요'); return;
                }
                beforeChange();
                if(cmd==='tsz'){
                    const old=tblSize(tf.t);
                    if(old.w<1||old.h<1){ bad('표 크기를 읽지 못했어요'); return; }
                    const kw=clamp(round(op.w),40,size.w)/old.w;
                    const kh=clamp(round(op.h),20,size.h)/old.h;
                    tf.t.cw=tf.t.cw.map(v=>Math.max(TBL_MINW,Math.round(v*kw)));
                    tf.t.ch=tf.t.ch.map(v=>Math.max(TBL_MINH,Math.round(v*kh)));
                }else{
                    const s=tblSize(tf.t);
                    tf.t.x=clamp(round(op.x),0,Math.max(0,size.w-s.w));
                    tf.t.y=clamp(round(op.y),0,Math.max(0,size.h-s.h));
                }
                const now=tblSize(tf.t);
                tf.t.x=clamp(Math.round(tf.t.x),0,Math.max(0,size.w-now.w));
                tf.t.y=clamp(Math.round(tf.t.y),0,Math.max(0,size.h-now.h));
                try{ rebuildTable(tf.pi,tf.t.id,{quiet:true}); }catch(e){}
                touched.add(tf.pi);
                try{ if(renderedPages.has(tf.pi)) renderTblDivs(tf.pi); }catch(e){}
                res.applied++; return;
            }
            if(cmd==='tcell'){
                const tf=findTblAny(op&&op.id);
                if(!tf){ bad('그런 표를 찾지 못했어요'); return; }
                if(!finite(op.r)||!finite(op.c)
                   ||!Number.isInteger(Number(op.r))||!Number.isInteger(Number(op.c))){
                    bad('표 칸 위치가 올바르지 않아요'); return;
                }
                const r=round(op.r)-1,c=round(op.c)-1;
                if(r<0||c<0||r>=tf.t.ch.length||c>=tf.t.cw.length){
                    bad('표에 그런 칸은 없어요'); return;
                }
                const cell=(doc.pages[tf.pi].els||[]).find(e=>e&&e.type==='text'
                    &&e.tbl&&e.tbl.tid===tf.t.id&&e.tbl.r===r&&e.tbl.c===c);
                if(!cell){ bad('표 칸을 찾지 못했어요'); return; }
                if(cell.locked){ bad('잠긴 요소는 고칠 수 없어요'); return; }
                beforeChange();
                cell.html=aiMdToHtml(text(op.text),cell.fontSize||16);   // 14.29.2
                delete cell.fit; delete cell.fitDown; delete cell.trFS; delete cell.trLS; delete cell.trFW;
                touched.add(tf.pi); res.applied++; return;
            }
            if(cmd==='add'){
                const numOk=v=>finite(v)||aiEditIsAuto(v);
                if(!finite(op.page)||!Number.isInteger(Number(op.page))
                   ||!numOk(op.x)||!numOk(op.y)||!numOk(op.w)||!numOk(op.h)){
                    bad('새 글상자의 페이지나 위치가 올바르지 않아요'); return;
                }
                const page=round(op.page),pi=page-1,pg=doc.pages[pi];
                if(page<1||page>doc.pages.length||!pg||pg.__lazy!=null){
                    bad('해당 페이지를 찾거나 불러오지 못했어요'); return;
                }
                if(!text(op.text).trim()){ bad('내용이 없는 새 글상자는 만들지 않았어요'); return; }
                // ~id 가 있으면 그 상자의 글꼴·서식을 물려받아 이웃과 어울리게 한다.
                let font=curFont||'pretendard',fontSize=curFontSize||16,styleSrc=null;
                if(op.inherit){
                    const src=findAny(op.inherit);
                    if(src&&src.el&&src.el.type==='text'){
                        font=src.el.font||font; fontSize=src.el.fontSize||fontSize;
                        styleSrc=src.el;
                    }
                }
                // 14.27.0 · auto 크기·자리 — 본문 너비를 따르고, 글이 넘치지
                // 않을 만큼 높이를 잡은 뒤 겹치지 않는 첫 빈자리에 둔다.
                const body=aiMdPlain(text(op.text));
                const mg=aiEditMargins(pi);
                const wide=Math.max(120,Math.min(size.w-2*AI_MARGIN,
                    (mg.width&&mg.width>=120)?mg.width:(size.w-2*AI_MARGIN)));
                const bw=aiEditIsAuto(op.w)?wide:clamp(round(op.w),20,size.w);
                const guess=aiEditGuessH(body,bw,fontSize)+aiMdTitleExtra(text(op.text),fontSize);
                const bh=clamp(aiEditIsAuto(op.h)?guess
                    :Math.max(round(op.h),guess),20,size.h);
                let p;
                if(aiEditIsAuto(op.x)||aiEditIsAuto(op.y)){
                    p=aiEditFreeSpot(pi,bw,bh,aiEditIsAuto(op.y)?0:round(op.y));
                    p.w=bw; p.h=bh;
                }else p=place(op.x,op.y,bw,bh,{pi:pi,snap:true,avoid:true});
                beforeChange(); pg.els=pg.els||[];
                const body0=text(op.text);
                // 14.29.2 · 제목과 본문을 상자 안에서 갈라 쓴다.
                //   · 글 전체가 제목 한 줄이면 → 상자째 크게·굵게(가운데)
                //   · 제목+본문이 섞여 오면 → 제목 줄만 크게·굵게, 본문은 보통 굵기
                //   · **중요어** 는 그 낱말만 굵게, 문장 안 $수식$ 은 인라인 수식으로
                const rich=aiMdBox(body0,fontSize);
                let useHtml=rich.html, useFs=fontSize, useFont=font,
                    useAlign=rich.align||null, useBold=!!rich.bold;
                if(rich.level) useFs=rich.fs;
                else if(pg.els.length===0&&pi===0&&body0.length<=60&&body0.indexOf('\n')<0
                        &&p.y<=AI_MARGIN+AI_GRID+1){
                    // 첫 쪽 맨 위 짧은 한 줄 = 노트 제목으로 본다(예전 규칙 유지)
                    useHtml='<b>'+aiMdInline(body0)+'</b>';
                    useFs=28; useBold=true; useAlign='center';
                }
                const nel={type:'text',id:uid('t'),x:p.x,y:p.y,w:p.w,h:p.h,
                    html:useHtml,fontSize:useFs,font:useFont};
                if(useAlign) nel.align=useAlign;
                if(useBold) nel.fontWeight='700';

                if(styleSrc){
                    if(styleSrc.align) nel.align=styleSrc.align;
                    if(styleSrc.textColor) nel.textColor=styleSrc.textColor;
                    if(styleSrc.cellBg) nel.cellBg=styleSrc.cellBg;
                    // 14.29.2 · 본문 상자는 이웃의 '굵게'까지 물려받지 않는다 —
                    //   제목 옆에 쓴 본문이 통째로 굵어져 제목과 안 구분되던 문제.
                    if(styleSrc.fontWeight&&(rich.level||useBold)) nel.fontWeight=styleSrc.fontWeight;
                    if(styleSrc.fontStyle) nel.fontStyle=styleSrc.fontStyle;
                    if(styleSrc.textDecoration) nel.textDecoration=styleSrc.textDecoration;
                }
                pg.els.push(nel);
                touched.add(pi); res.applied++; return;
            }
            // @math — 새 수식(LaTeX) 상자
            if(cmd==='math'||cmd==='ltx'||cmd==='formula'){
                const numOkM=v=>finite(v)||aiEditIsAuto(v);
                if(!finite(op.page)||!Number.isInteger(Number(op.page))
                   ||!numOkM(op.x)||!numOkM(op.y)||!numOkM(op.w)||!numOkM(op.h)){
                    bad('새 수식의 페이지나 위치가 올바르지 않아요'); return;
                }
                const page=round(op.page),pi=page-1,pg=doc.pages[pi];
                if(page<1||page>doc.pages.length||!pg||pg.__lazy!=null){
                    bad('해당 페이지를 찾거나 불러오지 못했어요'); return;
                }
                const latex=String(op.latex==null?'':op.latex).trim().slice(0,2000);
                if(!latex){ bad('LaTeX 수식이 비어 있어요'); return; }
                const isDisplay=!!op.display||latex.length>40||/\\(int|sum|prod|lim|frac|sqrt|begin|matrix)/.test(latex);
                const estW=()=>{
                    const approx=Math.max(60,Math.min(size.w-2*AI_MARGIN,Math.round(10+latex.length*(isDisplay?9:7))));
                    return isDisplay?Math.min(size.w-2*AI_MARGIN,Math.max(200,approx)):Math.min(size.w/2,approx);
                };
                const estH=()=>isDisplay?Math.max(48,Math.min(140,Math.round(40+(latex.match(/\\(frac|sqrt)|\^|_/g)||[]).length*6))):44;
                const mg=aiEditMargins(pi);
                const wideM=Math.max(200,Math.min(size.w-2*AI_MARGIN,(mg.width&&mg.width>=200)?mg.width:(size.w-2*AI_MARGIN)));
                const bw=aiEditIsAuto(op.w)?(isDisplay?wideM:estW()):clamp(round(op.w),40,size.w);
                const bh=aiEditIsAuto(op.h)?estH():clamp(round(op.h),28,size.h);
                let p;
                if(aiEditIsAuto(op.x)||aiEditIsAuto(op.y)){
                    p=aiEditFreeSpot(pi,bw,bh,aiEditIsAuto(op.y)?0:round(op.y));
                    p.w=bw; p.h=bh;
                }else p=place(op.x,op.y,bw,bh,{pi:pi,snap:true,avoid:true});
                beforeChange(); pg.els=pg.els||[];
                const nm={type:'latex',id:uid('m'),x:p.x,y:p.y,w:p.w,h:p.h,
                    latex:latex,fontSize:isDisplay?22:18,displayMath:isDisplay?1:0};
                pg.els.push(nm);
                touched.add(pi); res.applied++; return;
            }
            const found=findAny(op&&op.id);

            if(!found){
                // 표 id로 지우면 표 전체(칸·테두리)를 함께 지운다.
                if(cmd==='del'){
                    const tf=findTblAny(op&&op.id);
                    if(tf){ dropTable(tf); res.applied++; return; }
                }
                bad('문서 상태에 없는 요소라 건너뛰었어요'); return;
            }
            const {el,pi}=found;
            if(el.locked){ bad('잠긴 요소는 고칠 수 없어요'); return; }
            // 14.27.0 · 표 칸이나 테두리 획을 지우라는 말은 '그 표를 지워 달라'로
            //   알아듣는다 — 칸만 떼어 지우면 테두리가 남아 결국 표 전체 삭제다.
            if(cmd==='del'&&el.tbl){
                const tf=findTblAny(el.tbl.tid);
                if(tf){ dropTable(tf); note('표 칸이라 표 전체를 지웠어요'); res.applied++; return; }
                bad('표를 찾지 못했어요 · 다시 요청해 주세요'); return;
            }
            // 표 테두리 선은 표를 고치면 자동 재생성되니 직접 건드리지 않는다.
            if(el.type==='stroke'&&el.tbl){ bad('표 테두리는 표 명령(@tsz·@tmv)으로만 다룰 수 있어요'); return; }
            if(cmd==='del'){
                if(el.tbl){ bad('표 칸은 낱개로 지울 수 없어요 · 표 전체는 표 id로 지워요'); return; }
                beforeChange();
                doc.pages[pi].els=(doc.pages[pi].els||[]).filter(item=>item!==el);
                touched.add(pi); res.applied++; return;
            }
            if(cmd==='tx'){
                if(el.tbl){ bad('표 칸 내용은 @tcell로 바꿔 주세요'); return; }
                if(el.type!=='text'){ bad('글상자만 내용을 바꿀 수 있어요'); return; }
                // 14.29.2 · **중요어**·# 제목 줄·문장 안 $수식$ 을 노트 서식으로 옮긴다
                beforeChange(); el.html=aiMdToHtml(text(op.text),el.fontSize||16);
                delete el.fit; delete el.fitDown; delete el.trFS; delete el.trLS; delete el.trFW;
                touched.add(pi); res.applied++; return;
            }
            if(cmd==='mtx'||cmd==='latex'){
                if(el.type!=='latex'){ bad('@mtx는 수식 요소에만 쓸 수 있어요'); return; }
                const newLatex=String(op.latex==null?'':op.latex).trim().slice(0,2000);
                if(!newLatex){ bad('바꿀 LaTeX 수식이 비어 있어요'); return; }
                beforeChange();
                el.latex=newLatex;
                if(op.display==1||op.display===true) el.displayMath=1;
                else if(op.display===0||op.display===false) el.displayMath=0;
                touched.add(pi); res.applied++; return;
            }
            if(cmd==='rp'){
                if(el.tbl){ bad('표 칸 내용은 @tcell로 바꿔 주세요'); return; }
                if(el.type!=='text'){ bad('글상자만 내용을 바꿀 수 있어요'); return; }
                const find=text(op.find),repl=text(op.repl);
                if(!find){ bad('찾을 글이 비어 있어 바꿀 곳을 찾지 못했어요'); return; }
                const got=aiEditReplaceHtml(el.html,find,repl);
                if(!got.count){ bad('상자에서 찾을 글을 찾지 못했어요'); return; }
                beforeChange(); el.html=got.html;
                delete el.fit; delete el.fitDown; delete el.trFS; delete el.trLS; delete el.trFW;
                touched.add(pi); res.applied++; return;
            }
            if(cmd==='ap'){
                if(el.tbl){ bad('표 칸은 @tcell로 내용을 바꿔 주세요'); return; }
                if(el.type!=='text'){ bad('글상자에만 덧붙일 수 있어요'); return; }
                const body=text(op.text);
                if(!body.trim()){ bad('덧붙일 글이 비어 있어요'); return; }
                const front=/^(앞|앞쪽|prepend|pre|start|top|first)/i.test(String(op.dir||'뒤'));
                const piece=aiMdToHtml(body,el.fontSize||16);   // 14.29.2 · 마크다운 표시를 서식으로
                beforeChange();
                el.html=!aiEditText(el).trim()?piece
                    :(front?piece+'<br>'+(el.html||''):(el.html||'')+'<br>'+piece);
                delete el.fit; delete el.fitDown; delete el.trFS; delete el.trLS; delete el.trFW;
                touched.add(pi); res.applied++; return;
            }
            // 14.27.0 · @hl — 형광펜. 글귀를 주면 '그 글귀만' 칠한다(저장 포맷과
            //   같은 background-color span). 글귀가 없으면 상자 전체 배경이다.
            //   색을 안 적으면 노랑, '없음·지우기'면 지우기다.
            if(cmd==='hl'){
                if(el.type!=='text'){ bad('형광펜은 글상자(표 칸 포함)에만 칠할 수 있어요'); return; }
                let find=aiEditLooseFind(op.find);
                let colorV=String(op.color==null?'':op.color).trim();
                // "@hl id | 노랑" 처럼 값 하나만 오면 색으로, 아니면 찾을 글로 본다.
                if(op.single&&find
                   &&(aiEditColor(find,true)!=null||AI_CLEAR_WORDS[find.toLowerCase()])){
                    colorV=find; find='';
                }
                // "@hl id | 노랑 | 중요한 글" 처럼 순서가 뒤집혀 오면 바꿔 준다.
                if(find&&colorV&&aiEditColor(colorV,true)==null
                   &&!AI_CLEAR_WORDS[colorV.toLowerCase()]&&aiEditColor(find,true)!=null){
                    const swap=find; find=colorV; colorV=swap;
                }
                const whole=!find||find==='*'||find==='전체'||find==='모두'||find==='all';
                const clearing=!!colorV&&!!AI_CLEAR_WORDS[colorV.toLowerCase()];
                const color=aiEditColor(colorV,true)||AI_HL_DEFAULT;
                if(clearing){
                    if(whole){
                        const had=!!el.cellBg||/background(?:-color)?\s*:/i.test(String(el.html||''));
                        if(!had){ bad('지울 형광펜이 없어요'); return; }
                        beforeChange();
                        delete el.cellBg;
                        el.html=aiEditUnmarkHtml(el.html,'').html;
                    }else{
                        const got=aiEditUnmarkHtml(el.html,find);
                        if(!got.count){ bad('상자에서 찾을 글을 찾지 못했어요'); return; }
                        beforeChange();
                        el.html=got.html;
                        if(el.cellBg){ delete el.cellBg; note('상자 전체 배경 형광펜도 함께 지웠어요'); }
                    }
                }else if(whole){
                    beforeChange();
                    el.cellBg=color;
                }else{
                    const got=aiEditMarkHtml(el.html,find,color);
                    if(!got.count){ bad('상자에서 찾을 글을 찾지 못했어요'); return; }
                    beforeChange();
                    el.html=got.html;
                }
                delete el.fit; delete el.fitDown; delete el.trFS; delete el.trLS; delete el.trFW;
                touched.add(pi); res.applied++; return;
            }
            if(cmd==='st'){
                const changes=aiEditStyleOps(op.style);
                if(!changes.length){ bad('알 수 없는 서식이라 건너뛰었어요'); return; }
                if(el.type==='text'){
                    const use=changes.filter(ch=>['font','fs','fg','hl','bold','italic',
                        'underline','strike','align'].indexOf(ch.k)>=0);
                    if(!use.length){ bad('이 상자에는 적용할 서식이 없어요'); return; }
                    beforeChange();
                    use.forEach(ch=>{
                        if(ch.k==='font') el.font=ch.v;
                        else if(ch.k==='fs') el.fontSize=ch.v;
                        else if(ch.k==='fg'){ if(ch.v) el.textColor=ch.v; else delete el.textColor; }
                        else if(ch.k==='hl'){ if(ch.v) el.cellBg=ch.v; else delete el.cellBg; }
                        else if(ch.k==='bold'){ if(ch.v) el.fontWeight='700'; else delete el.fontWeight; }
                        else if(ch.k==='italic'){ if(ch.v) el.fontStyle='italic'; else delete el.fontStyle; }
                        else if(ch.k==='underline'||ch.k==='strike'){
                            const tok=ch.k==='underline'?'underline':'line-through';
                            const cur=String(el.textDecoration||'').split(/\s+/)
                                .filter(t=>t&&t!=='none'&&t!==tok);
                            if(ch.v) cur.push(tok);
                            if(cur.length) el.textDecoration=cur.join(' ');
                            else delete el.textDecoration;
                        }
                        else if(ch.k==='align') el.align=ch.v;
                    });
                    delete el.fit; delete el.fitDown; delete el.trFS; delete el.trLS; delete el.trFW;
                    touched.add(pi); res.applied++; return;
                }
                if(el.type==='stroke'){
                    let did=false;
                    changes.forEach(ch=>{
                        if((ch.k==='fg'||ch.k==='pencolor')&&ch.v){ el.color=ch.v; did=true; }
                        else if(ch.k==='fs'||ch.k==='pensize'){
                            el.size=Math.max(0.5,Math.min(30,Number(ch.v)||el.size||2)); did=true;
                        }
                    });
                    if(!did){ bad('그림획은 펜색·굵기만 바꿀 수 있어요'); return; }
                    beforeChange(); touched.add(pi); res.applied++; return;
                }
                if(el.type==='latex'){
                    const fs=changes.find(ch=>ch.k==='fs');
                    if(!fs){ bad('수식은 글자 크기만 바꿀 수 있어요'); return; }
                    beforeChange(); el.fontSize=Math.max(5,Math.min(200,fs.v));
                    touched.add(pi); res.applied++; return;
                }
                bad('이 요소에는 서식을 적용할 수 없어요'); return;
            }
            // 표 칸은 내용(@tcell)·서식(@st)까지만 — 위치·크기·삭제는 표가 깨진다.
            if(el.tbl){ bad('표 칸은 @tcell·@st로만 다룰 수 있어요'); return; }
            if(cmd!=='mv'&&cmd!=='sz'&&cmd!=='bx'){
                bad('알 수 없는 편집 명령을 건너뛰었어요'); return;
            }
            if(!['text','image','latex','stroke','legacyDraw'].includes(el.type)){
                bad('지원하지 않는 요소 종류라 건너뛰었어요'); return;
            }
            if(el.type==='legacyDraw'){
                bad('배경그림은 이동하거나 크기를 바꿀 수 없어요'); return;
            }
            if(el.type==='stroke'&&cmd!=='mv'){
                bad('그림획은 이동만 할 수 있어요'); return;
            }
            if((cmd==='mv'||cmd==='bx')&&(!finite(op.x)||!finite(op.y))){
                bad('이동 좌표가 올바르지 않아요'); return;
            }
            if((cmd==='sz'||cmd==='bx')&&(!finite(op.w)||!finite(op.h))){
                bad('크기가 올바르지 않아요'); return;
            }
            if(el.type==='stroke'){
                const b=aiEditStrokeBox(el);
                const x=clamp(round(op.x),0,Math.max(0,size.w-b.w));
                const y=clamp(round(op.y),0,Math.max(0,size.h-b.h));
                beforeChange(); el.dx=x-b.baseX; el.dy=y-b.baseY;
                touched.add(pi); res.applied++; return;
            }
            const b=aiEditBox(el);
            let p;
            if(cmd==='mv') p=place(op.x,op.y,Math.max(20,b.w),Math.max(20,b.h),{pi:pi,skipId:el.id});
            else if(cmd==='sz'){
                // 크기만 바꾸라는 요청은 x/y를 움직이지 않는다. 가장자리까지 남은
                // 폭이 20px보다 작으면 그 여유만큼까지 허용해 페이지 밖으로 새지 않게 한다.
                if(!finite(b.x)||!finite(b.y)||b.x<0||b.y<0||b.x>=size.w||b.y>=size.h){
                    bad('요소의 현재 위치가 페이지 밖이라 크기를 바꾸지 않았어요'); return;
                }
                const maxW=Math.max(1,size.w-b.x),maxH=Math.max(1,size.h-b.y);
                p={x:b.x,y:b.y,w:clamp(round(op.w),Math.min(20,maxW),maxW),
                    h:clamp(round(op.h),Math.min(20,maxH),maxH)};
            }else p=place(op.x,op.y,op.w,op.h,{pi:pi,skipId:el.id});
            beforeChange();
            if(cmd!=='sz'){ el.x=p.x; el.y=p.y; }
            if(cmd!=='mv'){ el.w=p.w; el.h=p.h; }
            touched.add(pi); res.applied++;
        });
        if(res.applied>0){
            touched.forEach(pi=>{
                try{ doc.pages[pi].__dirty=true; }catch(e){}
                try{ if(renderedPages.has(pi)) renderPageEls(pi); }catch(e){}
            });
            // @goto·@title은 화면·노트 이름만 건드린다 — 문서 저장은 실제 변경 때만.
            if(historyStarted){
                try{ syncBoost(); }catch(e){}
                saveDoc(); queueOps();
            }
        }
        return res;
    }

    try{
        window.__sdyAiBridge={
            text:(scope)=>{
                try{
                    if(!doc||!doc.pages||!doc.pages.length) return '';
                    const idx=(scope==='page')?[curPageIdx|0]:doc.pages.map((p,i)=>i);
                    const out=[];
                    idx.forEach(i=>{ collectPageEls(i).forEach(o=>{ if(o.src) out.push(o.src); }); });
                    return out.join('\n');
                }catch(e){ return ''; }
            },
            title:()=>String((document.getElementById('edTitle')||{}).value||'').trim(),
            snapshot:()=>{ try{ commitEditingText(); return aiEditSnapshot(); }catch(e){ return ''; } },
            capture:()=>{
                try{
                    commitEditingText();
                    return {text:aiEditSnapshot(),revision:aiEditRevision()};
                }catch(e){ return {text:'',revision:''}; }
            },
            apply:(ops,revision)=>{
                try{
                    const list=Array.isArray(ops)?ops:[];
                    const needsClip=list.some(o=>o&&(o.cmd==='clip'||o.cmd==='clipin'||o.cmd==='copy'));
                    // 클립보드가 없으면 동기 그대로 — 있으면 한 번 읽어 @add·@ap로 바꾼 뒤 적용한다.
                    if(!needsClip) return aiEditApply(list,revision);
                    return (async()=>{
                        let clip='',clipErr='';
                        if(list.some(o=>o&&(o.cmd==='clip'||o.cmd==='clipin'))){
                            try{
                                if(navigator.clipboard&&navigator.clipboard.readText)
                                    clip=String(await navigator.clipboard.readText()||'');
                                else clipErr='이 브라우저에서는 클립보드를 읽지 못해요';
                            }catch(e){ clipErr='클립보드를 읽지 못했어요 · 복사 권한을 확인해 주세요'; }
                            clip=clip.slice(0,AI_EDIT_MAX_TEXT);
                            if(!clip&&!clipErr) clipErr='클립보드가 비어 있어요 · 먼저 복사해 주세요';
                        }
                        const mapped=[];
                        let preFailed=0; const preNotes=[];
                        const copies=[];
                        list.forEach(o=>{
                            const cmd=String(o&&o.cmd||'').toLowerCase();
                            if(cmd==='clip'){
                                if(!clip){ preFailed++; if(preNotes.indexOf(clipErr)<0) preNotes.push(clipErr); return; }
                                mapped.push({cmd:'add',page:o.page,x:o.x,y:o.y,w:o.w,h:o.h,
                                    text:clip,inherit:o.inherit});
                            }else if(cmd==='clipin'){
                                if(!clip){ preFailed++; if(preNotes.indexOf(clipErr)<0) preNotes.push(clipErr); return; }
                                mapped.push({cmd:'ap',id:o.id,dir:o.dir,text:clip});
                            }else if(cmd==='copy'){ copies.push(o); }
                            else mapped.push(o);
                        });
                        const res=aiEditApply(mapped,revision);
                        res.failed+=preFailed;
                        preNotes.forEach(m=>{ if(m&&res.notes.length<4&&res.notes.indexOf(m)<0) res.notes.push(m); });
                        // 복사는 문서 변경 뒤 최종 글 기준으로 내보낸다.
                        for(const cp of copies){
                            const found=(()=>{ 
                                const id=String(cp&&cp.id||'').trim();
                                if(!id) return null;
                                for(let pi=0;pi<doc.pages.length;pi++){
                                    const el=((doc.pages[pi]||{}).els||[]).find(item=>item&&item.id===id);
                                    if(el) return el;
                                }
                                return null;
                            })();
                            if(!found||(found.type!=='text'&&found.type!=='latex')){
                                res.failed++;
                                if(res.notes.length<4) res.notes.push('복사할 글상자를 찾지 못했어요');
                                continue;
                            }
                            try{
                                if(!(navigator.clipboard&&navigator.clipboard.writeText))
                                    throw new Error('no clipboard');
                                await navigator.clipboard.writeText(aiEditText(found));
                                res.applied++;
                            }catch(e){
                                res.failed++;
                                if(res.notes.length<4&&res.notes.indexOf('클립보드에 복사하지 못했어요')<0)
                                    res.notes.push('클립보드에 복사하지 못했어요');
                            }
                        }
                        return res;
                    })();
                }
                catch(e){ return {applied:0,failed:Array.isArray(ops)?ops.length:0,stale:false,
                    notes:['적용 중 오류 · '+String(e&&e.message||'다시 시도해 주세요')]}; }
            },
        };
    }catch(e){}
    /* ============ /6.1 번역 ============ */

    // 가져온(tight) 상자에서 복사 시: 절대스팬 사이 줄바꿈을 공백으로 정돈해
    // 외부에 붙여넣어도 깔끔한 문장으로 나가게 한다.
    document.addEventListener('copy',e=>{
        try{
            const sel=window.getSelection();
            if(!sel||sel.isCollapsed) return;
            const n=sel.anchorNode
                ? (sel.anchorNode.nodeType===1?sel.anchorNode:sel.anchorNode.parentElement)
                : null;
            const host=n&&n.closest('.tb-content');
            if(!host||!host.closest('.tight')) return;
            // 외부(구글 등) 붙여넣기용: 공백 재조립 + 줄바꿈→공백
            const clean=tightSelectionText(sel).replace(/\n+/g,' ').replace(/\s{2,}/g,' ').trim();
            if(!clean) return;
            e.clipboardData.setData('text/plain',clean);
            e.preventDefault();
        }catch(err){}
    });

    // ============ 여러 기기 실시간 반영 (적응형 폴링) ============
    // 예전엔 20초 고정이라 다른 기기의 변경이 한참 뒤에 보였다.
    // 지금은 '방금 뭔가 오갔으면 빠르게(1.2초), 조용하면 천천히(15초)'.
    // 화면이 가려져 있으면 아예 쉰다 → 배터리·버벅임 없음.
    let liveSyncTimer=null, _syncGap=1200, _syncBusy=false, _syncQuiet=0;
    const SYNC_FAST=1200, SYNC_SLOW=15000;
    function stopLiveDocSync(){
        if(liveSyncTimer){ clearTimeout(liveSyncTimer); liveSyncTimer=null; }
    }
    function _armSync(gap){
        stopLiveDocSync();
        liveSyncTimer=setTimeout(liveDocTick, gap==null?_syncGap:gap);
    }
    // 내가 편집했을 때: 잠시 빠른 주기로 (상대 변경도 곧바로 받도록)
    function syncBoost(){
        _syncQuiet=0;
        if(_syncGap!==SYNC_FAST){ _syncGap=SYNC_FAST; _armSync(SYNC_FAST); }
    }
    async function startLiveDocSync(){
        // 14.15 · 요청을 보내는 사이에 다른 노트를 열었으면 이 결과를
        //   새 노트 doc 에 넣지 않는다.
        const d=doc, nid=(curNB&&curNB.id)||null;
        stopLiveDocSync();
        try{
            if(d&&d.__ref){
                const r=await fetch('/api/import/docfile/'
                    +encodeURIComponent(d.__ref)+'?meta=1',{cache:'no-store'});
                const m=await r.json().catch(()=>({}));
                if(doc!==d||!curNB||curNB.id!==nid) return;
                if(m&&m.ok) d.__ver=m.version;
            }else if(SB&&curMemo&&curMemo.updated_at&&doc===d){
                d.__sbVer=curMemo.updated_at;
            }
        }catch(e){}
        if(doc!==d||!curNB||curNB.id!==nid) return;
        _syncGap=SYNC_FAST; _syncQuiet=0;
        _armSync(SYNC_FAST);
    }
    let _impReloading=false;
    async function reloadImportedIfNewer(){
        // 가져온 PDF: 요소 ops 없이 슬라이스만 갱신된 번역/편집을 받는다.
        const d=doc;                    // 14.9 · 노트 전환 후 이어지는 리로드를 차단
        if(!d||!d.__ref||trBusy||_impReloading) return 0;
        _impReloading=true;
        try{
            const r=await fetch('/api/import/docfile/'+encodeURIComponent(d.__ref)+'?meta=1',{cache:'no-store'});
            const m=await r.json().catch(()=>({}));
            if(!(m&&m.ok&&m.version)) return 0;
            if(doc!==d) return 0;
            const prev=d.__ver||0;
            if(!(prev && m.version>prev+0.05)){
                d.__ver=m.version;
                return 0;
            }
            let got=0;
            const n=(d.pages||[]).length;
            for(let s0=0;s0<n;s0+=LAZY_SLICE){
                if(doc!==d) return got;
                let dirty=false;
                for(let i=s0;i<Math.min(n,s0+LAZY_SLICE);i++){
                    if(d.pages[i]&&d.pages[i].__dirty){ dirty=true; break; }
                }
                if(dirty) continue;
                for(let i=s0;i<Math.min(n,s0+LAZY_SLICE);i++){
                    if(d.pages[i]&&d.pages[i].__lazy==null)
                        d.pages[i]={id:'lazy_'+i,els:[],tables:[],__lazy:1};
                }
                await loadBatch(s0);
                if(doc!==d) return got;
                for(let i=s0;i<Math.min(n,s0+LAZY_SLICE);i++){
                    if(renderedPages.has(i)) renderPageEls(i);
                }
                got++;
            }
            d.__ver=m.version;
            return got;
        }catch(e){ return 0; }
        finally{ _impReloading=false; }
    }
    async function liveDocTick(){
        if(!doc||!curNB){ _armSync(SYNC_SLOW); return; }
        // 안 보이는 탭에서는 쉬고, 편집·번역 중에는 건드리지 않는다
        if(document.hidden||document.querySelector('#pagesStage .tb.edit')||trBusy){
            _armSync(SYNC_FAST); return;
        }
        if(_syncBusy){ _armSync(); return; }
        _syncBusy=true;
        let got=0;
        try{ const ops=await pullSync(false); got=(ops&&ops.length)||0; }
        catch(e){}
        try{ got+=await reloadImportedIfNewer(); }
        catch(e){}
        finally{ _syncBusy=false; }
        // 변화가 있으면 계속 빠르게, 조용한 시간이 이어지면 서서히 늦춘다
        if(got){ _syncQuiet=0; _syncGap=SYNC_FAST; }
        else if(++_syncQuiet>=6) _syncGap=Math.min(SYNC_SLOW, _syncGap*1.6);
        _armSync();
    }
    // 다른 탭/창으로 갔다 오면 즉시 한 번 맞춘다
    document.addEventListener('visibilitychange',()=>{
        if(!document.hidden&&curNB&&doc){ _syncGap=SYNC_FAST; _armSync(120); }
    });

    // ===== 요소 단위 실시간 동기화 (구글독스식 LWW, 전체 덮어쓰기 없음) =====
    const SYNC_DEV=(()=>{ try{ let v=localStorage.getItem('sdy_dev');
        if(!v){ v='d_'+Math.random().toString(36).slice(2,10);
            localStorage.setItem('sdy_dev',v); } return v; }catch(e){ return 'd_x'; } })();
    function syncState(){
        doc.__localRev=doc.__localRev||new Map();
        doc.__lastHash=doc.__lastHash||new Map();
        doc.__base=doc.__base||new Map();      // 14.9 · 요소별 '공통 조상 html' (협업 병합용)
        doc.__baseRev=doc.__baseRev||new Map();// 14.9 · 공통 조상의 서버 rev (prevRev 전송용)
        return doc;
    }
    // 14.13 · 노트 요소 rev 시계 — 단조 증가 + pull 뒤 Lamport 캐치업.
    //   예전엔 Date.now() 원값을 써서, 시계가 몇 초 느린 기기(LTE 폰·PC 오차)의
    //   편집 rev 가 서버에 이미 있는 rev 보다 계속 작아졌다. 그러면 서버 LWW 가
    //   그 기기의 모든 이후 편집을 버려 "처음 몇 번만 동기화되고 이후엔 아예 안
    //   되고, 써 놓은 게 지워져 보이는" 증상이 생긴다. (설정 동기화는 14.9 에서
    //   이미 같은 문제를 이 방식으로 고쳤다 — 노트 편집기에만 빠져 있었다.)
    let _nbRev=Date.now();
    function _nbNow(){ _nbRev=Math.max(_nbRev+1, Date.now()+Math.random()); return _nbRev; }
    // ══════════════════════════════════════════════════════════════
    //  14.9 · 같은 텍스트상자 협업 편집 (구글독스식 3-way 병합)
    //   예전엔 상자 단위 LWW라서, 두 기기가 같은 상자를 동시에 타이핑하면
    //   한쪽 내용이 통째로 사라졌다. 이제 요소별로 '공통 조상(__base)'을
    //   기억하고, 원격 편집이 오면 3-way 병합(base·내것·상대것)으로
    //   양쪽 편집을 모두 남긴다. 충돌(같은 위치)은 결정적·대칭 규칙으로
    //   이어 붙여 양 기기가 같은 결과로 수렴한다.
    // ══════════════════════════════════════════════════════════════
    // HTML 을 '태그는 1단위, 글자는 1단위'로 쪼갠다 (태그를 반으로 자르지 않기 위함)
    function _sdyUnits(html){
        const units=[]; let buf='';
        for(let i=0;i<html.length;i++){
            const ch=html[i];
            if(ch==='<'){
                const end=html.indexOf('>',i);
                if(end>=0){ if(buf){ for(const c of buf) units.push(c); buf=''; } units.push(html.slice(i,end+1)); i=end; }
                else buf+=ch;
            }else buf+=ch;
        }
        if(buf) for(const c of buf) units.push(c);
        return units;
    }
    // base → v 의 편집 연산(들). 각 연산: {pos, del, ins[]} (base 기준, 겹치지 않음)
    function _sdyDiff(base,v){
        // 공통 접두/접미를 먼저 잘라 DP 범위를 줄인다 (덧붙임·끝삭제가 O(n)이 된다)
        const n=base.length, m=v.length;
        let p=0;
        while(p<n&&p<m&&base[p]===v[p]) p++;
        let s=0;
        while(s<n-p&&s<m-p&&base[n-1-s]===v[m-1-s]) s++;
        const bm=base.slice(p,n-s), vm=v.slice(p,m-s);
        const n2=bm.length, m2=vm.length;
        const dp=Array.from({length:n2+1},()=>new Int32Array(m2+1));
        for(let i=n2-1;i>=0;i--)
            for(let j=m2-1;j>=0;j--)
                dp[i][j]= bm[i]===vm[j] ? dp[i+1][j+1]+1 : Math.max(dp[i+1][j],dp[i][j+1]);
        const ops=[]; let i=0, j=0;
        while(i<n2&&j<m2){
            if(bm[i]===vm[j]){ i++; j++; continue; }
            const st=i, tj=j;
            while(i<n2&&j<m2&&bm[i]!==vm[j]){
                if(dp[i+1][j]>=dp[i][j+1]) i++; else j++;
            }
            ops.push({pos:p+st, del:i-st, ins:vm.slice(tj,j)});
        }
        if(i<n2) ops.push({pos:p+i, del:n2-i, ins:[]});
        else if(j<m2) ops.push({pos:p+i, del:0, ins:vm.slice(j)});
        // 인접한 '삭제'와 '삽입'을 하나의 '교체' hunk 로 합친다.
        // (안 합치면 같은 변경이 두 기기에서 중복 반영될 수 있다)
        const norm=[];
        for(const o of ops){
            if(!o.del&&!o.ins.length) continue;
            if(norm.length){
                const last=norm[norm.length-1];
                if(last.del>0&&last.ins.length===0&&o.del===0&&o.pos===last.pos+last.del){
                    last.ins=o.ins.slice(); continue;      // 삭제→삽입 = 교체
                }
                if(last.del===0&&o.del>0&&o.pos===last.pos){
                    last.del=o.del; continue;              // 삽입→삭제 = 교체
                }
            }
            norm.push({pos:o.pos, del:o.del, ins:o.ins.slice()});
        }
        return norm;
    }
    // 충돌 해소: 두 조각을 사전순으로 이어 붙인다. 병합 호출부가 (mine,theirs)를
    // 내용 기준으로 정렬해 부르므로 양 기기가 항상 같은 결과로 수렴한다.
    function _sdyResolve(a,b){
        const A=a.join(''),B=b.join('');
        return A<=B ? a.concat(b) : b.concat(a);
    }
    // hunk 들을 base[start..end) 구간에 적용해 그 구간의 '한쪽 버전 내용'을 만든다
    function _sdyApplyHunks(base,start,end,hunks,fromIdx){
        const out=[]; let p=start, k=fromIdx;
        while(k<hunks.length && hunks[k].pos<end){
            const h=hunks[k++];
            const delStart=Math.max(start,h.pos);
            const delEnd=Math.min(end, h.pos+h.del);
            out.push(...base.slice(p,delStart));
            out.push(...h.ins);
            p=delEnd;
        }
        out.push(...base.slice(p,end));
        return out;
    }
    // 3-way 병합: 두 diff(hunk 목록)를 base 위에서 합친다. 겹치는 구간만 충돌.
    function _sdyMerge3(o,a,b){
        const ha=_sdyDiff(o,a), hb=_sdyDiff(o,b);
        const res=[]; let pos=0, i=0, j=0;
        while(i<ha.length||j<hb.length){
            const A=i<ha.length?ha[i]:null;
            const B=j<hb.length?hb[j]:null;
            if(A&&(!B||A.pos+A.del<=B.pos)){
                res.push(...o.slice(pos,A.pos)); res.push(...A.ins);
                pos=A.pos+A.del; i++; continue;
            }
            if(B&&(!A||B.pos+B.del<=A.pos)){
                res.push(...o.slice(pos,B.pos)); res.push(...B.ins);
                pos=B.pos+B.del; j++; continue;
            }
            // 겹침 → 충돌 구간 [start,end) 확정 (연쇄 겹침까지 확장)
            const start=Math.min(A.pos,B.pos);
            let end=Math.max(A.pos+A.del,B.pos+B.del);
            const i0=i, j0=j;
            for(;;){
                let ext=false;
                while(i<ha.length&&ha[i].pos<end){ end=Math.max(end,ha[i].pos+ha[i].del); i++; ext=true; }
                while(j<hb.length&&hb[j].pos<end){ end=Math.max(end,hb[j].pos+hb[j].del); j++; ext=true; }
                if(!ext) break;
            }
            const ca=_sdyApplyHunks(o,start,end,ha,i0);
            const cb=_sdyApplyHunks(o,start,end,hb,j0);
            res.push(...o.slice(pos,start));
            res.push(...(ca.join('')===cb.join('') ? ca : _sdyResolve(ca,cb)));
            pos=end;
        }
        res.push(...o.slice(pos));
        return res;
    }
    function mergeText3(baseHtml,mineHtml,theirsHtml){
        const o=_sdyUnits(baseHtml||''), a=_sdyUnits(mineHtml||''), b=_sdyUnits(theirsHtml||'');
        return _sdyMerge3(o,a,b).join('');
    }
    function _elById(id){
        const loc=findElLoc(id); if(!loc) return null;
        return doc.pages[loc.i].els[loc.k];
    }
    // 내가 이 상자를 마지막 확정 상태 이후로 바꿨는가
    function _tbHasLocal(id){
        if(!doc||!doc.__base||!doc.__base.has(id)) return false;
        const el=_elById(id); if(!el) return false;
        return (el.html||'')!==doc.__base.get(id);
    }
    // ── 캐럿(커서) 유틸: textContent 기준 오프셋 ──
    function _tbCaretTextOffset(c){
        try{
            const sel=window.getSelection();
            if(sel&&sel.anchorNode&&c.contains(sel.anchorNode)){
                const walker=document.createTreeWalker(c,NodeFilter.SHOW_TEXT,null);
                let acc=0,n;
                while((n=walker.nextNode())){
                    if(n===sel.anchorNode) return acc+sel.anchorOffset;
                    acc+=n.nodeValue.length;
                }
            }
        }catch(e){}
        return (c.textContent||'').length;
    }
    function _tbSetCaretTextOffset(c,off){
        try{
            const walker=document.createTreeWalker(c,NodeFilter.SHOW_TEXT,null);
            let acc=0,n;
            while((n=walker.nextNode())){
                const len=n.nodeValue.length;
                if(acc+len>=off){
                    const r=document.createRange();
                    r.setStart(n,Math.max(0,off-acc)); r.collapse(true);
                    const sel=window.getSelection(); sel.removeAllRanges(); sel.addRange(r);
                    return;
                }
                acc+=len;
            }
        }catch(e){}
        try{
            const r=document.createRange();
            if(c.childNodes.length) r.setStartAfter(c.lastChild); else r.setStart(c,0);
            r.collapse(true);
            const sel=window.getSelection(); sel.removeAllRanges(); sel.addRange(r);
        }catch(e){}
    }
    // 편집 중인 상자 DOM 에 새 html 을 넣되, 내 커서를 최대한 보존한다
    function _tbApplyToActiveBox(id,newHtml){
        const box=document.querySelector('#pagesStage .tb.edit[data-id="'+id+'"]');
        if(!box) return false;
        const c=box.querySelector('.tb-content'); if(!c) return false;
        const off=_tbCaretTextOffset(c);
        const mineText=c.textContent||'';
        c.innerHTML=newHtml;
        const newText=c.textContent||'';
        let no=off;
        if(mineText!==newText){
            for(const e of _sdyDiff(Array.from(mineText),Array.from(newText))){
                if(e.pos<off) no+= e.ins.length - e.del;
            }
            if(no<0) no=0; if(no>newText.length) no=newText.length;
        }
        _tbSetCaretTextOffset(c,no);
        const em=!newText.trim();
        if(em) c.setAttribute('data-empty','true'); else c.removeAttribute('data-empty');
        box.classList.toggle('empty',em);
        return true;
    }
    // 원격 텍스트 op 를 내 로컬 편집과 3-way 병합한다. 변경 있으면 true.
    function _tbMergeRemote(op){
        const id=op.data.id, el=_elById(id); if(!el) return false;
        const theirs=op.data.html||'';
        const mine=el.html||'';
        const hasBase=doc.__base&&doc.__base.has(id);
        const base=hasBase?doc.__base.get(id):undefined;
        let merged;
        if(base===undefined || mine===base){
            merged=theirs;   // 로컬 변경 없음 → 원격 그대로 수용
        }else{
            const big=Math.max(base.length,mine.length,theirs.length);
            if(big>20000){ merged=theirs; }                     // 초대형 상자는 LWW 폴백
            else{                                               // (mine,theirs)를 내용 기준 정렬해
                const lo=mine<=theirs?mine:theirs;              //  부르면 양 기기가 같은 입력으로
                const hi=mine<=theirs?theirs:mine;              //  같은 병합 결과를 얻어 수렴한다.
                merged=mergeText3(base,lo,hi);
            }
        }
        // 원격 서식/스타일은 반영하되, 편집 중인 기하(x,y,w,h)는 내 것을 유지
        ['fontSize','font','align','color','bg','ls','wsp','lg','tight','tbl','locked','fit','fitDown'].forEach(k=>{
            if(op.data[k]!==undefined) el[k]=op.data[k];
        });
        const isActive=document.querySelector('#pagesStage .tb.edit[data-id="'+id+'"]')!==null;
        if(merged!==mine){
            el.html=merged;
            if(isActive) _tbApplyToActiveBox(id,merged);
            doc.__lastHash.delete(id);          // 병합본을 다시 push 하도록
            doc.__base.set(id,theirs);          // rebase: 내 편집은 이제 상대것 위에
            if(doc.__baseRev) doc.__baseRev.set(id, op.rev||0);
            return true;
        }
        doc.__base.set(id,theirs);
        if(doc.__baseRev) doc.__baseRev.set(id, op.rev||0);
        // 18.9 · '이미 보낸 것' 표시(__lastHash)는 서버가 가진 내용(theirs)이
        //   내 내용과 정말 같을 때만 한다. 예전에는 병합 결과가 내 것과 같다는
        //   이유만으로(=서버에는 아직 옛 내용) 해시를 갱신해 버려서, 내 마지막
        //   편집이 영영 push 되지 않았다. 그러면 노트를 닫았다 다시 열 때
        //   옛 ops 가 그대로 적용돼 **방금 적은 글이 사라진 것처럼** 보였다.
        if(hasBase && theirs===mine) doc.__lastHash.set(id,JSON.stringify(el));
        else doc.__lastHash.delete(id);      // 아직 안 보낸 편집 → 다음 genOps 가 반드시 보낸다
        return false;
    }
    async function initSync(){
        if(!doc||!curNB) return;
        // 14.14 · 노트 전환 중 이전 노트의 initSync 가 이어지면 새 노트 맵을
        //   비우거나 엉뚱한 ops 를 푸시할 수 있다. 시작 시점 신원을 고정.
        const _d0=doc, _nb0=curNB.id;
        syncState();
        // v3 · 옛 저장물에 data: 원본(pending 레거시)이 남아 있으면 열 때 1회,
        //   같은 확실한 경로(uploadImageStrict)로 서버(/api/img)에 올려 복구한다.
        try{ repairLegacyImages(); }catch(e){}
        // 18.4 · pull 전(메모·로컬이 아는) 이미지의 진짜 URL 을 기억한다.
        //   ops 스토어에 업로드 전(pending·빈 url) 상태가 남아 있어도
        //   이 URL 로 되돌려 "사진이 있었다는 표시"가 남지 않게 한다.
        const imgUrls=new Map();
        (doc.pages||[]).forEach(pg=>(pg.els||[]).forEach(el=>{
            if(el&&el.type==='image'&&_imgRealURL(el)) imgUrls.set(el.id,el.url);
        }));
        doc.__localRev.clear(); doc.__lastHash.clear();
        doc.__base.clear(); doc.__baseRev.clear();
        doc.__pagesRev=0; doc.__since=0;
        const pulled=await pullSync(false);
        if(doc!==_d0||!curNB||curNB.id!==_nb0) return;
        // 18.4 · pull 이 이미지를 업로드 전 상태로 되돌렸어도 복원한다.
        const healed=[];
        (doc.pages||[]).forEach((pg,pi)=>(pg.els||[]).forEach(el=>{
            if(el&&el.type==='image'&&!_imgRealURL(el)&&imgUrls.has(el.id)){
                el.url=imgUrls.get(el.id);
                delete el.pending; delete el.failed; delete el.localURL;
                healed.push({el,pi});
            }
        }));
        if(healed.length){
            const hOps=healed.map(({el,pi})=>({id:el.id,kind:'put',page:pi,rev:_nbNow(),data:serverImageElement(el),dev:SYNC_DEV}));
            healed.forEach((h,i)=>{
                doc.__lastHash.set(h.el.id,JSON.stringify(h.el));
                doc.__localRev.set(h.el.id,hOps[i].rev);
            });
            if(!doc.__ref){ try{ pushOpsFor(_nb0,hOps); }catch(e){} }
            try{
                healed.forEach(h=>{ if(renderedPages.has(h.pi)) renderPageEls(h.pi); });
            }catch(e){}
        }
        // 원격에서 받은 요소는 해시 등록(재푸시 방지),
        // 서버에 없던 로컬 요소는 초기 상태로 푸시(양방향 기반 공유)
        const remoteIds=new Set((pulled||[]).map(o=>o.id));
        const ops=[];
        const skipPush=!!doc.__ref; // 가져온 PDF: 슬라이스가 원본. 열자마자 원문을 푸시하면 번역이 덮인다.
        (doc.pages||[]).forEach((pg,pi)=>{(pg.els||[]).forEach(el=>{
            doc.__lastHash.set(el.id,JSON.stringify(el));
            doc.__base.set(el.id, el.html||'');   // 14.9 · 초기 공통 조상 = 현재 내용
            doc.__baseRev.set(el.id, doc.__localRev.get(el.id)||0);
            if(skipPush) return;
            if(!remoteIds.has(el.id)){
                const data=serverImageElement(el);
                if(!data) return;   // 업로드 전 이미지는 공유하지 않는다
                const rev=_nbNow();
                doc.__localRev.set(el.id,rev);
                ops.push({id:el.id,kind:'put',page:pi,rev,data,dev:SYNC_DEV});
            }
        });});
        doc.__lastPages=(doc.pages||[]).map(p=>p.id).join(',');
        if(doc!==_d0||!curNB||curNB.id!==_nb0) return;
        if(ops.length) await pushOps(ops);
        // pull 로 본문이 채워졌을 수 있으니 다시 한 번 강제 페인트
        if(doc===_d0) try{ ensureVisiblePagesRendered(); }catch(e){}
        // v3 · pull 로 받은 이미지가 아직 서버 주소가 없는 레거시(data: 원본)면
        //   지금 서버(/api/img)로 재업로드해 url 을 확정한다.
        if(doc===_d0) try{ repairLegacyImages(); }catch(e){}
    }
    async function startSlicePrefill(){
        const d=doc;                    // 14.9 · 노트 전환 후 이어지는 프리필을 차단
        if(!d||!d.__ref) return;
        try{
            const mr=await fetch('/api/import/docfile/'+encodeURIComponent(d.__ref)
                +'?meta=1',{cache:'no-store'});
            const m=await mr.json().catch(()=>({}));
            const total=m.total||0; if(!total) return;
            if(doc!==d) return;
            const loaded=new Set();
            (d.pages||[]).forEach((p,i)=>{
                if(p.__lazy==null) loaded.add(Math.floor(i/LAZY_SLICE)*LAZY_SLICE); });
            const q=[]; for(let s=0;s<total;s+=LAZY_SLICE) if(!loaded.has(s)) q.push(s);
            let k=0;
            const worker=async()=>{
                while(k<q.length){
                    if(doc!==d) return; // 14.9 · 그 사이 다른 노트를 열었으면 중단
                    const s=q[k++];
                    try{
                        const dd=await fetchSlice(9000,d.__ref,s,(d.pages||[]).length);
                        if(doc!==d) return;
                        if(dd&&Array.isArray(dd.pages)){
                            dd.pages.forEach((p,j)=>{
                                const i=s+j;
                                if(i<(d.pages||[]).length&&d.pages[i].__lazy!=null&&!d.pages[i].__dirty){
                                    d.pages[i]=p;
                                    if(doc===d&&renderedPages.has(i)) renderPageEls(i);
                                }
                            });
                            _importLoaded(d, curNB&&curNB.id);
                        }
                    }catch(e){}
                }
            };
            await Promise.all(Array.from({length:Math.min(4,q.length)},worker));
        }catch(e){}
    }
    async function pullSync(init){
        try{
            if(!curNB||!doc) return [];
            // 14.13 · 노트 전환 경쟁 방지: pull 사이에 다른 노트를 열면 응답 ops 가
            //   새 노트의 doc 에 적용돼 '다른 문서 내용이 덮어 나오는' 사고가 난다.
            //   (push 는 14.6 에서 막았지만 pull 에는 가드가 없었다)
            const _d0=doc, _nb0=curNB.id;
            // 14.8 · since(전역 커서)로 걸러내지 않는다. rev 는 각 기기의 시계로
            //   찍히므로, 시계가 조금만 느린 기기의 편집은 '이미 지난 rev'로 오인돼
            //   영영 안 받아지던 버그가 있었다. 항상 전체를 받고, 아래 __localRev
            //   (요소별 LWW)로 이미 반영한 것/내 최신 편집만 걸러낸다.
            const r=await fetch('/api/sync/pull?nb='+encodeURIComponent(curNB.id)
                +'&since=0',{cache:'no-store'});
            const d=await r.json(); if(!r.ok||!d.ok) return [];
            if(doc!==_d0||!curNB||curNB.id!==_nb0) return [];
            // 14.13 · Lamport 시계 캐치업: 서버가 본 최대 rev 로 내 시계를 올려,
            //   시계가 느린 기기의 다음 편집도 서버 LWW 에서 이기게 한다.
            _nbRev=Math.max(_nbRev, d.version||0);
            let ops=(d.ops||[]).slice().sort((a,b)=>(a.rev||0)-(b.rev||0));
            // 14.15 · 서버 pull 은 __pages__ 를 별도 필드(pages)로 돌려준다.
            //   ops 에는 pages 가 포함되지 않으므로, 처음 열거나 늦게 pull 한
            //   기기는 추가/삭제된 페이지를 전혀 못 받았다. 여기서 상태 페이지를
            //   __pages__ op 으로 합성해 맨 앞에 붙여 같은 적용 경로를 태운다.
            {
                const rp=(d&&d.pages)||null;
                if(rp && parseFloat(rp.rev||0) > (doc.__pagesRev||0)){
                    ops=[{id:'__pages__',kind:'pages',dev:'server',
                          rev:parseFloat(rp.rev||0),
                          ids:Array.isArray(rp.ids)?rp.ids:[]}, ...ops];
                }
            }
            // 14.13 · __pages__ op(페이지 목록)을 요소 op 보다 먼저 적용한다.
            //   새 페이지가 생긴 직후의 요소 op 이 페이지 목록보다 먼저 오면
            //   upsertEl 이 index 를 '마지막 페이지'로 잘라 붙여, 한 페이지의
            //   내용이 엉뚱한 페이지/문서 위에 복사돼 보였다.
            const _pgs=ops.filter(o=>o.id==='__pages__');
            const ordered=_pgs.length?_pgs.concat(ops.filter(o=>o.id!=='__pages__')):ops;
            _stCacheReset=false;
            let changed=false; const chPages=new Set();

            // 현재 로컬 사용자가 편집 중인 텍스트 상자 ID 파악
            const activeEditEl=document.querySelector('#pagesStage .tb.edit');
            const activeEditId=activeEditEl?activeEditEl.dataset.id:null;
            const activeEditPage=activeEditEl?parseInt(activeEditEl.dataset.pageIdx,10):-1;

            for(const op of ordered){
                if(doc!==_d0) return [];   // 14.13 · 루프 안 await(loadBatch) 너머로 노트가 바뀌면 중단
                if(op.id==='__pages__'){
                    if((op.rev||0)>(doc.__pagesRev||0)){
                        applyPagesOp(op);
                        // 14.15 · 방금 받은 페이지 목록을 '_lastPages' 에 반영해
                        //   같은 목록을 곧장 재푸시(pages rev 소모)하지 않는다.
                        if(doc) doc.__lastPages=(doc.pages||[]).map(p=>p.id).join(',');
                        changed=true; chPages.add(-1);
                    }
                    continue;
                }
                const local=doc.__localRev.get(op.id)||0;
                const isText=op.data&&op.data.type==='text';
                if(isText){
                    // 14.9 · 텍스트는 서버가 3-way 병합한다. 내 rev 와 같아도
                    //  내용이 다르면(=서버가 병합한 결과) 적용하고, 같으면(echo) 건너뛴다.
                    if((op.rev||0)<local) continue;
                    if((op.rev||0)===local){
                        const el=_elById(op.data.id);
                        if(!el||(el.html||'')===(op.data.html||'')) continue;
                        // 14.25.0 · 되돌리기 에코 가드: 같은 기기의 같은 rev 면
                        //   방금 되돌린 내 op 가 돌아온 것이므로 건너뛴다.
                        if(op.dev&&op.dev===SYNC_DEV&&Date.now()<_undoGuardUntil) continue;
                    }
                }else{
                    if((op.rev||0)<=local) continue;
                }
                // 14.8 · 삭제 대신 반영한 rev 를 기억한다. since=0 로 매번 전체를
                //  받으므로, 이미 반영한 원격 op 를 또 적용하는 낭비/깜빡임을 막는다.
                doc.__localRev.set(op.id, op.rev||0);
                const activeBox=activeEditId&&op.id===activeEditId;
                const hasLocal=isText&&_tbHasLocal(op.id);
                if(op.del){
                    // 14.9 · 내가 편집 중이거나 로컬 수정이 있는 텍스트상자의 원격
                    //  삭제는 무시하고 내 최신본을 다시 올려 상자를 되살린다.
                    if(activeBox||hasLocal){
                        doc.__lastHash.delete(op.id);
                        doc.__base.delete(op.id); doc.__baseRev.delete(op.id);
                        queueOps();
                        continue;
                    }
                    if(removeElById(op.id)){ changed=true; chPages.add(op.page||0);
                        doc.__lastHash.delete(op.id);
                        doc.__base.delete(op.id); doc.__baseRev.delete(op.id); }
                }else if(op.data){
                    // 18.4 · '아직 업로드 전'(pending·빈 url·blob) 이미지 op 가 도착했는데
                    //   이 기기가 이미 진짜 URL 을 알고 있으면 덮어쓰지 않는다.
                    //   (memo·로컬에는 업로드 완료 상태가 있고 ops 스토어만 옛 pending
                    //    상태로 남은 경우 — 노트가 닫힌 뒤 업로드가 끝난 타이밍)
                    if(op.data.type==='image' && !_imgRealURL(op.data)){
                        const loc=findElLoc(op.data.id);
                        const curEl=loc?doc.pages[loc.i].els[loc.k]:null;
                        const curData=curEl&&String(curEl.localURL||'').startsWith('data:image/');
                        if(curEl && (_imgRealURL(curEl) || curData)){
                            doc.__localRev.set(op.data.id, op.rev||0);
                            doc.__lastHash.set(op.data.id, JSON.stringify(curEl));
                            // 14.17 · 로컬에 data 원본이 있으면 옛 pending op 가 그 원본을
                            //   덮어쓰지 않는다. (메모 스냅샷이 원본을 보관하고, 어느 기기든
                            //   자동 재업로드로 /api/img 로 바꾼다)
                            if(_imgRealURL(curEl) && !doc.__ref){
                                try{
                                    pushOpsFor(curNB.id,[{id:curEl.id,kind:'put',page:loc.i,rev:_nbNow(),data:serverImageElement(curEl),dev:SYNC_DEV}]);
                                }catch(e){}
                            }
                            continue;
                        }
                    }
                    if(isText&&(activeBox||hasLocal)&&_elById(op.data.id)){
                        // 14.9 · 협업 병합: 내/상대 편집을 모두 남긴다
                        if(_tbMergeRemote(op)){ changed=true; chPages.add(op.page||0); queueOps(); }
                    }else if(await upsertEl(op.data,op.page||0)){
                        changed=true; chPages.add(op.page||0);
                        doc.__lastHash.set(op.data.id,JSON.stringify(op.data));
                        if(isText){
                            doc.__base.set(op.data.id, op.data.html||'');
                            doc.__baseRev.set(op.data.id, op.rev||0);
                        }
                    }
                }
            }
            if(doc!==_d0) return [];   // 14.13 · 마지막 await 뒤에도 노트가 같은지 확인
            doc.__since=d.version||0;
            if(changed){
                if(chPages.has(-1)){
                    renderPages();
                }else{
                    chPages.forEach(pi=>{
                        if(renderedPages.has(pi)){
                            if(activeEditEl&&activeEditPage===pi){
                                _selectiveRenderPage(pi,activeEditId);
                            }else{
                                renderPageEls(pi);
                            }
                        }
                    });
                    // 14.14 · pull 로 새 요소가 들어왔는데 해당 쪽이 아직 IO 로
                    //   안 그려져 있으면 강제 페인트 (빈 종이 유지 방지)
                    try{ ensureVisiblePagesRendered(); }catch(e){}
                }
            }
            // 요소 ops 가 비어도 가져온 문서 슬라이스(번역)가 갱신됐을 수 있다.
            if(doc.__ref && !trBusy){
                try{ await reloadImportedIfNewer(); }catch(e){}
            }
            return ops;
        }catch(e){ console.warn('sync pull 실패',e); return []; }
    }

    function _selectiveRenderPage(idx, activeId){
        const paper=paperAt(idx); if(!paper) return;
        const txtL=paper.querySelector('.layer-text');
        const svg=paper.querySelector('.layer-stroke');
        const imgL=paper.querySelector('.layer-img');
        const els=(doc.pages&&doc.pages[idx]&&doc.pages[idx].els)||[];
        els.forEach(el=>{
            if(el.id===activeId) return;
            let domEl=paper.querySelector(`[data-id="${el.id}"]`);
            if(domEl){
                if(el.type==='image'){
                    const im=domEl.querySelector('img');
                    const remote=String(el.url||'');
                    const local=String(el.localURL||'');
                    const src=(remote&&!/^blob:/i.test(remote))?remote:(local&&!/^blob:/i.test(local)?local:'');
                    if(im&&im.getAttribute('src')!==src) im.src=src;
                    domEl.classList.toggle('pending',!!el.pending&&!remote);
                    domEl.classList.toggle('failed',!!el.failed);
                }else if(el.type==='text'){
                    domEl.style.left=el.x+'px'; domEl.style.top=el.y+'px';
                    domEl.style.width=el.w+'px'; domEl.style.height=el.h+'px';
                    const c=domEl.querySelector('.tb-content');
                    if(c&&c.innerHTML!==el.html) c.innerHTML=el.html||'';
                }
            }else{
                if(el.type==='text'&&txtL) txtL.appendChild(buildTextEl(el,idx));
                else if(el.type==='stroke'&&svg) svg.appendChild(buildStrokeEl(el,idx));
                else if(el.type==='image'&&imgL) imgL.appendChild(buildImageEl(el,idx));
                else if(el.type==='latex'&&txtL) txtL.appendChild(buildLatexEl(el,idx));
            }
        });
        const currentDomEls=paper.querySelectorAll('[data-id]');
        const validIds=new Set(els.map(e=>e.id));
        currentDomEls.forEach(d=>{
            if(d.dataset.id!==activeId&&!validIds.has(d.dataset.id)) d.remove();
        });
    }
    async function retryPage(idx){
        const d=doc;                    // 14.9 · 노트 전환 후 이어지는 재시도를 차단
        if(!d||!d.__ref) return;
        // 14.12 · renderVersion 도 함께 검증
        if(window._renderVersion !== (d&&d.__rv)) return;
        const s0=Math.floor(idx/LAZY_SLICE)*LAZY_SLICE;
        try{
            const dd=await fetchSlice(9000,d.__ref,s0,(d.pages||[]).length);
            if(doc!==d) return;
            if(window._renderVersion !== (d&&d.__rv)) return;
            if(dd&&Array.isArray(dd.pages)){
                dd.pages.forEach((p,j)=>{ const i=s0+j;
                    if(i>=(d.pages||[]).length) return;
                    const cur=d.pages[i];
                    if(cur&&(cur.__dirty||(cur.__lazy==null&&(cur.els||[]).length))) return;
                    d.pages[i]=p; });
                _importLoaded(d, curNB&&curNB.id);
            }
        }catch(e){}
        // renderPageEls 에서도 검증하므로 여기서는 doc===d 만 확인
        if(doc===d) renderPageEls(idx);
    }
    function rehashAll(){
        doc.__lastHash.clear();
        (doc.pages||[]).forEach(pg=>(pg.els||[]).forEach(el=>{
            doc.__lastHash.set(el.id,JSON.stringify(el)); }));
        doc.__lastPages=(doc.pages||[]).map(p=>p.id).join(',');
    }
    function findElLoc(id){
        for(let i=0;i<(doc.pages||[]).length;i++){
            const els=doc.pages[i].els||[];
            const k=els.findIndex(e=>e.id===id);
            if(k>=0) return {i,k};
        }
        return null;
    }
    function removeElById(id){
        const loc=findElLoc(id); if(!loc) return false;
        doc.pages[loc.i].els.splice(loc.k,1); return true;
    }
    async function upsertEl(data,page){
        let pi=Math.min(page,(doc.pages||[]).length-1);
        if(pi<0) return false;
        if(doc.pages[pi]&&doc.pages[pi].__lazy!=null) await loadBatch(pi);
        const loc=findElLoc(data.id);
        if(loc){
            if(loc.i!==pi){
                doc.pages[loc.i].els.splice(loc.k,1);
                (doc.pages[pi].els=doc.pages[pi].els||[]).push(data);
            }else{
                doc.pages[loc.i].els[loc.k]=data;
            }
        }else{
            (doc.pages[pi].els=doc.pages[pi].els||[]).push(data);
        }
        return true;
    }
    function applyPagesOp(op){
        doc.__pagesRev=op.rev||0;
        const ids=op.ids||[];
        const oldPages=(doc.pages||[]).slice();
        const byId={}; oldPages.forEach(p=>{ if(p&&p.id) byId[p.id]=p; });
        // 14.14 · 페이지 id 가 기기마다 다르게 찍힌 경우(옛 버그·복제·충돌),
        //   id 로 못 찾으면 같은 자리(index)에 있던 본문을 살려 빈 페이지로
        //   교체하지 않는다. 예전엔 byId 미스 → {id,els:[]} 로 바꿔
        //   메모 채널에 있던 글·그림이 실시간 pull 한 번에 통째로 사라졌다.
        doc.pages=ids.map((id,i)=>{
            if(byId[id]) return byId[id];
            const old=oldPages[i];
            const hasBody=old&&(
                ((old.els||[]).length)>0||
                ((old.tables||[]).length)>0||
                ((old.notes||[]).length)>0||
                old.__lazy!=null
            );
            if(hasBody){
                // 서버 순서의 id 로만 맞추고 본문·lazy 마커는 유지
                if(old.id!==id) old.id=id;
                return old;
            }
            return {id,els:[],tables:[]};
        });
    }
    function genOps(){
        syncState();
        const ops=[];
        const seen=new Set();
        (doc.pages||[]).forEach((pg,pi)=>{
            (pg.els||[]).forEach(el=>{
                seen.add(el.id);
                const data=serverImageElement(el);
                if(!data) return;   // 업로드 전 이미지(공유 소스 없음)는 op 로 내보내지 않는다
                const h=JSON.stringify(el);
                if(doc.__lastHash.get(el.id)!==h){
                    doc.__lastHash.set(el.id,h);
                    const rev=_nbNow();
                    doc.__localRev.set(el.id,rev);
                    ops.push({id:el.id,kind:'put',page:pi,rev,data,dev:SYNC_DEV,
                              prevRev:(doc.__baseRev&&doc.__baseRev.get(el.id))||0});
                }
            });
        });
        doc.__lastHash.forEach((h,id)=>{
            if(!seen.has(id)){
                const rev=_nbNow();
                doc.__localRev.set(id,rev);
                ops.push({id,kind:'del',rev,dev:SYNC_DEV});
                doc.__lastHash.delete(id);
            }
        });
        const ph=(doc.pages||[]).map(p=>p.id).join(',');
        if(doc.__lastPages!==ph){
            doc.__lastPages=ph;
            const rev=_nbNow();
            doc.__pagesRev=rev;
            ops.push({id:'__pages__',kind:'pages',rev,
                ids:(doc.pages||[]).map(p=>p.id),dev:SYNC_DEV});
        }
        return ops;
    }
    // 18.4 · 지금 열려 있지 않은 노트에도 요소 ops 를 직접 올린다.
    //   (이미지 업로드 완료처럼 doc/curNB 를 건드릴 수 없는 백그라운드 작업용)
    async function pushOpsFor(nbId,ops){
        const list=Array.isArray(ops)?ops.slice(0,40):[];
        if(!nbId||!list.length) return false;
        for(let attempt=0; attempt<3; attempt++){
            try{
                const r=await fetch('/api/sync/push',{method:'POST',
                    headers:{'Content-Type':'application/json'},
                    body:JSON.stringify({nb:String(nbId),ops:list})});
                const d=await r.json().catch(()=>({}));
                if(r.ok&&d.ok) return true;
            }catch(e){}
            await new Promise(res=>setTimeout(res,250*(attempt+1)));
        }
        return false;
    }
    let opsTimer=null;
    function queueOps(){
        clearTimeout(opsTimer);
        // 400ms → 180ms: 상대 화면에 더 빨리 뜬다.
        // (그래도 묶어서 보내므로 타자 칠 때마다 요청이 나가진 않는다)
        opsTimer=setTimeout(pushOps,180);
        try{ syncBoost(); }catch(e){}
    }
    async function pushOps(pre){
        if(!doc||!curNB) return;
        const d0=doc;
        const ops=pre||genOps();
        if(!ops.length) return;
        // 14.6 · 노트 id 를 시작 시점에 고정한다. 전송 중 다른 노트로 넘어가면
        //  curNB.id 가 바뀌어 이 노트의 요소 ops 가 엉뚱한 노트로 저장되던 버그 방지.
        const nbId=curNB.id;
        const send=async(batch)=>{
            for(let attempt=0; attempt<3; attempt++){
                try{
                    const r=await fetch('/api/sync/push',{method:'POST',
                        headers:{'Content-Type':'application/json'},
                        body:JSON.stringify({nb:nbId,ops:batch})});
                    const d=await r.json().catch(()=>({}));
                    if(r.ok&&d.ok){
                        // 14.7 · 서버 전역 version 으로 doc.__since 를 올리지 않는다.
                        //  예전엔 여기서 since 를 서버 version(모든 요소의 최대 rev)으로
                        //  끌어올려서, 그 사이 다른 기기가 올린 rev 를 '이미 본 것'으로
                        //  오인해 실시간 동시 편집에서 상대 변경이 안 보였다.
                        // 14.9 · 수용된 텍스트 put 은 공통 조상(__base)으로 확정한다.
                        const acc=new Set(Array.isArray(d.accepted)?d.accepted:batch.map(o=>o.id));
                        batch.forEach(o=>{
                            if(acc.has(o.id)&&o.kind==='put'&&o.data&&o.data.type==='text'&&doc&&doc.__base){
                                doc.__base.set(o.id, o.data.html||'');
                                if(doc.__baseRev) doc.__baseRev.set(o.id, parseFloat(o.rev||0)||0);
                            }
                        });
                        return true;
                    }
                }catch(e){}
                await new Promise(res=>setTimeout(res, 250*(attempt+1)));
            }
            return false;
        };
        const CHUNK_OPS=40;
        const failedIds=[];
        for(let i=0;i<ops.length;i+=CHUNK_OPS){
            const batch=ops.slice(i,i+CHUNK_OPS);
            if(!(await send(batch))) failedIds.push(...batch.filter(o=>o.kind==='put').map(o=>o.id));
        }
        // 14.13 · 전송 실패한 put 은 '이미 보낸 상태' 표시(__lastHash)를 걷어낸다.
        //   genOps 가 보내기 전에 해시를 갱신하므로, LTE 순단처럼 push 가 실패하면
        //   편집이 영영 재전송되지 않고 뒤늦은 pull 이 서버 쪽 옛 내용으로 화면을
        //   덮어 '써 놓은 게 지워진' 것처럼 보였다.
        if(failedIds.length){
            failedIds.forEach(id=>{ try{ d0.__lastHash.delete(id); }catch(e){} });
            if(doc===d0&&curNB&&curNB.id===nbId)
                setTimeout(()=>{ try{ if(doc===d0&&curNB&&curNB.id===nbId) pushOps(); }catch(e){} },3000);
        }
        // 14.7 · push 직후 pull 로 맞춘다. 내 ops 는 __localRev 로 건너뛰고,
        //  그 사이 온 다른 기기의 변경만 받아 적용해 동시 편집이 어긋나지 않게 한다.
        try{ if(curNB&&curNB.id===nbId) await pullSync(false); }catch(e){}
        try{ queueImportedSave(); }catch(e){}
    }

    // ============ 실시간 커서 공유 ============
    // 같은 노트를 여러 사람이 열면 서로의 마우스를 색깔 화살표로 보여준다.
    const LIVE_ME=(()=>{ try{
        let v=localStorage.getItem('sdy_uid');
        if(!v){ v='u_'+Math.random().toString(36).slice(2,10); localStorage.setItem('sdy_uid',v); }
        return v;
    }catch(e){ return 'u_'+Math.random().toString(36).slice(2,10); } })();
    // 이름을 따로 정하지 않았으면 '푸른 두루미' 같은 이름을 하나 지어 준다.
    const LIVE_ADJ=['연보라','복숭아빛','민트색','하늘색','살구색','라벤더','코랄빛',
                    '레몬색','장미빛','청포도','피치','시나몬','솜사탕','아이보리',
                    '라일락','청옥','버터','멜론','구름빛','연분홍'];
    const LIVE_ANI=['까치','참새','박새','멧비둘기','직박구리','제비','백로','왜가리',
                    '뻐꾸기','물총새','두루미','기러기','청둥오리','저어새','꾀꼬리',
                    '동박새','오목눈이','수리부엉이','팔색조','호반새','파랑새','후투티',
                    '원앙','종달새'];
    function makeLiveName(){
        const a=LIVE_ADJ[Math.floor(Math.random()*LIVE_ADJ.length)];
        const b=LIVE_ANI[Math.floor(Math.random()*LIVE_ANI.length)];
        return a+' '+b;
    }
    function liveName(){
        try{
            let v=localStorage.getItem('sdy_uname_v2');
            if(!v||!v.trim()||v==='사용자'||v==='익명'){
                v=makeLiveName();
                localStorage.setItem('sdy_uname_v2',v);
            }
            return v;
        }catch(e){ return makeLiveName(); }
    }
    let liveTimer=null, liveRateTimer=null, liveLast={x:null,y:null,page:0},
        liveOn=false, liveMoved=false, _liveBusy=false, _liveQueued=false,
        _liveLastPoll=0, liveMyColor='';
    const liveInkTimers={};       // uid → 실시간 잉크 정리 타이머(펜을 뗀 뒤 잠시 유지)
    // 상대가 있을 때는 25fps로 왕복하고, 혼자일 때도 600ms마다 가볍게 확인한다.
    // 내 마우스가 멈췄다고 polling까지 4초 멈추면 움직이는 상대 커서가 내 화면에서
    // 4초씩 얼어 보였던 것이 '현재 위치가 바로 안 오는' 핵심 원인이었다.
    const LIVE_RATE_MS=40, LIVE_DISCOVER_MS=600, LIVE_HEARTBEAT_MS=4000;
    const LIVE_MOVE_EVENT=('PointerEvent' in window)?'pointermove':'mousemove';
    const livePeerCount={};        // 노트별 동시 접속자 수

    function startLive(){
        if(liveOn||!curNB) return;
        liveOn=true; liveMoved=true; _liveLastPoll=0;
        document.addEventListener(LIVE_MOVE_EVENT,onLiveMove,{passive:true});
        liveTimer=setInterval(livePing,LIVE_HEARTBEAT_MS);
        clearInterval(liveRateTimer);
        liveRateTimer=setInterval(liveFastTick,LIVE_RATE_MS);
        livePing();
    }
    function stopLive(){
        if(!liveOn) return;
        liveOn=false;
        document.removeEventListener(LIVE_MOVE_EVENT,onLiveMove);
        clearInterval(liveTimer); liveTimer=null;
        clearInterval(liveRateTimer); liveRateTimer=null;
        _liveBusy=false; _liveQueued=false;
        const bd=document.getElementById('liveBadge'); if(bd) bd.style.display='none';
        const nb=curNB&&curNB.id;
        if(nb) fetch('/api/live/leave',{method:'POST',
            headers:{'Content-Type':'application/json'},
            body:JSON.stringify({note:nb,uid:LIVE_ME}),keepalive:true}).catch(()=>{});
        document.querySelectorAll('.live-cur').forEach(n=>n.remove());
        Object.keys(liveInkTimers).forEach(k=>{ clearTimeout(liveInkTimers[k]); delete liveInkTimers[k]; });
        document.querySelectorAll('[id^="liveInk_"]').forEach(n=>n.remove());
        const lg=document.getElementById('liveLegend'); if(lg) lg.remove();
    }
    // 상대가 보이는 동안에는 내가 가만히 있어도 계속 받아야 한다. 혼자일 때만
    // 발견 주기로 낮춰 서버와 배터리 부담을 줄인다.
    function liveFastTick(){
        if(!liveOn||!curNB) return;
        const now=performance.now();
        const hasPeer=(livePeerCount[curNB.id]||1)>1;
        if(!liveMoved && !hasPeer && !liveAct() && now-_liveLastPoll<LIVE_DISCOVER_MS) return;
        liveMoved=false; _liveLastPoll=now;
        livePing();
    }
    function onLiveMove(e){
        const paper=e.target.closest&&e.target.closest('#pagesStage .paper');
        if(!paper) return;
        // 고주사율 마우스/펜은 한 이벤트에 좌표가 여럿 묶인다. 가장 최신 좌표를
        // 사용해야 커서가 한 프레임 뒤를 따라오지 않는다.
        const samples=typeof e.getCoalescedEvents==='function'?e.getCoalescedEvents():null;
        const point=samples&&samples.length?samples[samples.length-1]:e;
        const pi=+paper.dataset.pageIdx||0,p=pageLocal(point,pi);
        liveLast={ x:p.x,y:p.y,page:pi };
        liveMoved=true;
    }
    // 지금 하고 있는 일을 한 마디로 (다른 사람 화면에 함께 표시)
    function liveAct(){
        try{
            if(document.querySelector('.tb.edit')) return '글 쓰는 중';
            if(typeof penActive!=='undefined'&&penActive) return '그리는 중';
            if(typeof eraserActive!=='undefined'&&eraserActive) return '지우는 중';
            if(typeof textToolActive!=='undefined'&&textToolActive) return '글상자 놓는 중';
            if(typeof activeTbl!=='undefined'&&activeTbl) return '표 다루는 중';
            if(typeof drag!=='undefined'&&drag) return '옮기는 중';
            if(typeof findOpen!=='undefined'&&findOpen) return '찾는 중';
            if(String(getSelection()||'').trim()) return '글 고르는 중';
            return '';
        }catch(e){ return ''; }
    }
    // 14.18.4 · 지금 하는 일의 '종류' — 상대 화면에서 내 표시 모양을 정한다.
    //   ''     : 평소(마우스 화살표)
    //   'draw' : 펜으로 그리는 중 → 상대 화면에서 내 커서가 '펜촉'으로 바뀌고
    //            지금 긋는 획(liveInk)이 실시간 미리보기로 같이 보인다.
    //   'type' : 글 입력 중 → 상대 화면에서 내 커서 대신 '깜빡이는 캐럿'이 보인다.
    function liveMode(){
        try{
            if(document.querySelector('.tb.edit')) return 'type';
            if(typeof penActive!=='undefined'&&penActive
                &&!(typeof eraserActive!=='undefined'&&eraserActive)) return 'draw';
            return '';
        }catch(e){ return ''; }
    }
    // 편집 중인 캐럿의 위치를 종이 좌표로 — 상대에게 '마우스'가 아니라
    // '지금 글이 쓰이는 곳'을 보내야 깜빡이 캐럿이 제자리에 보인다.
    function liveCaretPos(){
        try{
            const sel=getSelection();
            if(!sel||!sel.rangeCount) return null;
            const anc=sel.getRangeAt(0).commonAncestorContainer;
            const cEl=anc.nodeType===1?anc:anc.parentElement;
            const content=cEl&&cEl.closest&&cEl.closest('.tb-content');
            if(!content||!content.closest('.tb.edit')) return null;
            let r=null;
            try{ r=sel.getRangeAt(0).getBoundingClientRect(); }catch(e){}
            if(!r||(r.top===0&&r.bottom===0)) r=content.getBoundingClientRect();
            const papers=editorPapers();
            for(let i=0;i<papers.length;i++){
                const pr=papers[i].getBoundingClientRect();
                if(r.left>=pr.left-2&&r.left<=pr.right+2&&r.bottom>=pr.top-2&&r.bottom<=pr.bottom+2){
                    const ps=paperSize();
                    return {x:(r.left-pr.left)*(ps.w/Math.max(1,pr.width)),
                            y:(r.bottom-pr.top)*(ps.h/Math.max(1,pr.height)),
                            page:+papers[i].dataset.pageIdx||0};
                }
            }
            return null;
        }catch(e){ return null; }
    }
    // 그리고 있는 획의 '지금까지' 모양 — 완성을 기다리지 않고 실시간으로 보낸다.
    //   트래픽을 줄이려고 점을 단순화(RDP)하고 최대 96점으로 자른다. 최종 획은
    //   기존 요소 동기화 경로로 확실히 도착하므로 미리보기는 근삿값이어도 된다.
    function liveInkPayload(){
        try{
            if(!drawing||!penActive||eraserActive) return null;
            if(!curPts||curPts.length<2) return null;
            let pts=rdpPts(curPts,1.1);
            if(pts.length>96){
                const step=(pts.length-1)/95,out=[];
                for(let i=0;i<95;i++) out.push(pts[Math.round(i*step)]);
                out.push(pts[pts.length-1]);
                pts=out;
            }
            pts=pts.map(pt=>[round1(pt[0]),round1(pt[1])]);
            return {pts,color:drawColor,size:round1(effSize()),op:effOpacity(),page:drawPageIdx||0};
        }catch(e){ return null; }
    }
    async function livePing(){
        if(!liveOn||!curNB) return;
        // 응답이 뒤섞여 커서가 뒤로 튀지 않게 하나씩 직렬 전송한다.
        // 이동 중 연속 호출은 busy 면 다음 완료 직후 최신 좌표로 한 번 이어 보낸다.
        if(_liveBusy){ _liveQueued=true; return; }
        const noteId=curNB.id;       // await 사이 노트 전환 시 옛 응답을 새 문서에 그리지 않음
        _liveBusy=true;
        // 14.18.4 · 글 쓰는 중에는 마우스가 아니라 '캐럿 위치'를 상대에게 보낸다.
        const mode=liveMode();
        if(mode==='type'){
            const cp=liveCaretPos();
            if(cp){ liveLast=cp; liveMoved=true; }
        }
        try{
            const r=await fetch('/api/live/ping',{method:'POST',
                headers:{'Content-Type':'application/json'},
                body:JSON.stringify({note:noteId,uid:LIVE_ME,name:liveName(),
                    x:liveLast.x,y:liveLast.y,page:liveLast.page,on:true,
                    act:liveAct(),mode,
                    ink:mode==='draw'?liveInkPayload():null,
                    ts:Date.now()})});
            const d=await r.json().catch(()=>({}));
            if(!liveOn||!curNB||curNB.id!==noteId) return;
            if(d&&d.ok){
                if(d.color) liveMyColor=d.color;
                // 5.35: 표시 순서를 매번 완전 랜덤으로 (같은 순서 고정 방지)
                const peers=(d.peers||[]).slice();
                for(let i=peers.length-1;i>0;i--){
                    const j=(Math.random()*(i+1))|0;
                    const t=peers[i]; peers[i]=peers[j]; peers[j]=t;
                }
                drawPeers(peers);
                const n=peers.length+1;
                const bd=document.getElementById('liveBadge');
                const nm=document.getElementById('liveNum');
                if(bd&&nm){ nm.textContent=n; bd.style.display=n>1?'inline-flex':'none'; }
                livePeerCount[noteId]=n;
            }
        }catch(e){ /* 서버 없으면 조용히 무시 */ }
        finally{
            _liveBusy=false;
            if(_liveQueued && liveOn){
                _liveQueued=false;
                setTimeout(()=>{ if(liveOn) livePing(); },0);
            }
        }
    }
    // 14.18.4 · 실시간 잉크 — 상대가 그리고 있는 획을 상대의 종이 위에 임시 SVG로.
    //   펜을 뗀 뒤에는 최종 획이 요소 동기화로 도착할 시간(3.5초)을 주고 지운다.
    function _dropLiveInk(uid){
        if(liveInkTimers[uid]) return;
        liveInkTimers[uid]=setTimeout(()=>{
            delete liveInkTimers[uid];
            const el=document.getElementById('liveInk_'+uid);
            if(el) el.remove();
        },3500);
    }
    function _updateLiveInk(p){
        const uid=p.uid, ink=p.ink;
        if(!ink||!ink.pts||ink.pts.length<2){ _dropLiveInk(uid); return; }
        if(liveInkTimers[uid]){ clearTimeout(liveInkTimers[uid]); delete liveInkTimers[uid]; }
        const pageIdx=(ink.page!=null&&isFinite(+ink.page))?+ink.page:(+p.page||0);
        const paper=paperAt(pageIdx);
        if(!paper) return;
        let svg=document.getElementById('liveInk_'+uid);
        if(!svg||!svg.isConnected||svg.parentElement!==paper){
            if(svg) svg.remove();
            svg=document.createElementNS('http://www.w3.org/2000/svg','svg');
            svg.id='liveInk_'+uid;
            const ps=paperSize();
            svg.setAttribute('viewBox','0 0 '+ps.w+' '+ps.h);
            svg.setAttribute('preserveAspectRatio','none');
            svg.style.cssText='position:absolute;inset:0;width:100%;height:100%;'+
                              'pointer-events:none;z-index:30;overflow:visible;';
            const path=document.createElementNS('http://www.w3.org/2000/svg','path');
            path.setAttribute('fill','none');
            path.setAttribute('stroke-linecap','round');
            path.setAttribute('stroke-linejoin','round');
            svg.appendChild(path);
            paper.appendChild(svg);
        }
        const path=svg.firstChild;
        try{ path.setAttribute('d',strokePath(ink.pts)); }catch(e){ return; }
        path.setAttribute('stroke',String(ink.color||'#888888').slice(0,24));
        path.setAttribute('stroke-width',Math.max(.5,Math.min(200,+ink.size||2)));
        path.setAttribute('stroke-opacity',ink.op==null?1:Math.max(.05,Math.min(1,+ink.op)));
    }
    // 14.18.4 · 왼쪽 범례 — 누가 어떤 색인지 한눈에. 커서에는 이름표 없이 색만 단다.
    function _liveEsc(v){
        return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    }
    function renderLiveLegend(rows){
        let lg=document.getElementById('liveLegend');
        if(!rows||!rows.length){ if(lg) lg.remove(); return; }
        if(!lg){
            lg=document.createElement('div');
            lg.id='liveLegend'; lg.className='live-legend';
            document.body.appendChild(lg);
        }
        const all=[{color:liveMyColor||'#4f6ef7',name:liveName(),act:liveAct(),me:true}].concat(rows);
        lg.innerHTML=all.map(r=>
            '<div class="ll-row'+(r.me?' me':'')+'">'+
                '<span class="ll-dot" style="background:'+_liveEsc(r.color)+'"></span>'+
                '<span class="ll-nm">'+_liveEsc(r.name)+(r.me?' (나)':'')+'</span>'+
                (r.act?'<span class="ll-act">'+_liveEsc(r.act)+'</span>':'')+
            '</div>').join('');
    }
    // 14.18.4 · 상대 커서 — 이름표 없이 색만. 그리는 중엔 펜촉, 글 쓰는 중엔 깜빡이 캐럿.
    function drawPeers(peers){
        const stage=document.getElementById('pagesStage');
        if(!stage) return;
        const seen=new Set(), rows=[];
        peers.forEach(p=>{
            if(p.x==null||p.y==null) return;
            seen.add(p.uid);
            const paper=paperAt(p.page||0);
            if(!paper) return;
            let layer=document.getElementById('liveLayer');
            if(!layer||!layer.isConnected){
                layer=document.createElement('div');
                layer.id='liveLayer';
                layer.style.cssText='position:fixed;left:0;top:0;width:100%;height:100%;'+
                                    'pointer-events:none;z-index:1050;';
                document.body.appendChild(layer);
            }
            let n=document.getElementById('live_'+p.uid);
            const isNew=!n;
            if(!n){
                n=document.createElement('div');
                n.id='live_'+p.uid; n.className='live-cur';
                n.innerHTML='<svg class="lc lc-arrow" viewBox="0 0 24 24" width="20" height="20">'+
                    '<path d="M4 2 L20 12 L13 13 L16 21 L13 22 L10 14 L4 18 Z" '+
                    'fill="currentColor" stroke="#475569" stroke-width="1.4"/></svg>'+
                    '<i class="lc lc-pen ri-pen-nib-fill"></i>'+
                    '<span class="lc lc-caret"></span>';
                layer.appendChild(n);
            }
            n.style.color=p.color||'#ef4444';
            n.style.zIndex=String(1+((Math.random()*40)|0));   // 5.35: 겹침 순서도 매번 랜덤
            const mode=(p.mode==='draw'||p.mode==='type')?p.mode:'';
            n.classList.toggle('draw',mode==='draw');
            n.classList.toggle('type',mode==='type');
            _updateLiveInk(p);
            rows.push({color:p.color||'#ef4444',name:p.name||'익명',act:p.act||'',me:false});
            const pr=paper.getBoundingClientRect(), ps=paperSize();
            // pageScale은 루트 90% zoom과 전환 중 배율을 모른다. 실제 종이 사각형으로
            // 문서 좌표→화면 좌표를 구한 뒤 fixed 레이어의 CSS px로 변환한다.
            const screenX=pr.left+(Number(p.x)||0)*(pr.width/Math.max(1,ps.w));
            const screenY=pr.top +(Number(p.y)||0)*(pr.height/Math.max(1,ps.h));
            const x=_clawCss(screenX), y=_clawCss(screenY);
            if(isNew) n.style.transition='none';
            n.style.setProperty('--live-x',x.toFixed(2)+'px');
            n.style.setProperty('--live-y',y.toFixed(2)+'px');
            if(isNew){
                // 첫 등장만 원점에서 날아오지 않게 즉시 놓고, 다음 프레임부터 보간.
                void n.offsetWidth;
                n.style.transition='';
            }
        });
        document.querySelectorAll('.live-cur').forEach(n=>{
            const uid=n.id.replace('live_','');
            if(!seen.has(uid)){ n.remove(); _dropLiveInk(uid); }
        });
        renderLiveLegend(rows);
    }
    addEventListener('beforeunload',()=>{ if(liveOn) stopLive(); });

    async function renderPageCanvas(pageIdx,opt){
        opt=opt||{};
        const size=paperSize();
        const page=JSON.parse(JSON.stringify(doc.pages[pageIdx]));
        if(opt.onlyIds) page.els=(page.els||[]).filter(e=>opt.onlyIds.has(e.id));
        (page.els||[]).forEach(el=>{ if(el.type==='text') el.html=fixDarkColors(el.html); });
        for(const el of page.els||[]){
            if(el.type==='image'||el.type==='legacyDraw') el.url=await toDataURL(el.url);
        }

        const sc=Math.max(2,Math.min(3,window.devicePixelRatio||2));
        const c=document.createElement('canvas');
        c.width=Math.ceil(size.w*sc); c.height=Math.ceil(size.h*sc);
        const ctx=c.getContext('2d');
        ctx.scale(sc,sc);
        if(!opt.transparent){
            ctx.fillStyle=(doc&&doc.tint)?doc.tint:'#ffffff';
            ctx.fillRect(0,0,size.w,size.h);
            // ① 종이 배경 — 캔버스에 직접 (SVG 실패와 무관하게 항상 그려짐)
            drawPaperBg(ctx,doc.paper,size);
        }

        // ② 이미지 — 캔버스에 직접 (foreignObject 안 거침 → 훨씬 안정적)
        for(const el of page.els||[]){
            if(el.type==='image'&&el.url){
                try{
                    const im=await loadImg(el.url);
                    ctx.drawImage(im,el.x,el.y,el.w,el.h);
                }catch(e){ console.warn('이미지 건너뜀',e); }
            }else if(el.type==='legacyDraw'&&el.url){
                try{
                    const im=await loadImg(el.url);
                    ctx.drawImage(im,0,0,size.w,size.h);
                }catch(e){}
            }
        }

        // ③ 펜 획 — 캔버스 경로로 직접
        (page.els||[]).forEach(st=>{
            if(st.type!=='stroke') return;
            drawStrokeOnCanvas(ctx,st);
        });

        // ④ 텍스트 — foreignObject(서식 유지). 실패하면 캔버스 텍스트로 폴백.
        const texts=(page.els||[]).filter(e=>e.type==='text'&&(e.html||'').trim());
        const formulas=(page.els||[]).filter(e=>e.type==='latex'&&(e.latex||'').trim());
        if(texts.length||formulas.length){
            let done=false;
            try{
                let body='';
                texts.forEach(el=>{
                    const inner=el.tight
                        ? `width:100%;height:100%;padding:0;box-sizing:border-box;`+
                          `font-size:${el.fontSize||16}px;line-height:1;color:${el.__c||'#111111'};`+
                          `overflow:visible;font-family:${fontCSS(el.font||'pretendard')};`+
                          `text-align:${el.align||'left'};position:relative;`
                        : `width:100%;height:100%;padding:8px 12px;box-sizing:border-box;`+
                          `font-size:${el.fontSize||16}px;line-height:1.5;color:${el.__c||'#111111'};white-space:pre-wrap;`+
                          `word-break:break-word;overflow:hidden;font-family:${fontCSS(el.font||'pretendard')};`+
                          `text-align:${el.align||'left'};`;
                    body+=`<div style="position:absolute;left:${el.x}px;top:${el.y}px;width:${el.w}px;height:${el.h}px;">`+
                          `<div style="${inner}">`+
                          htmlToXhtml(imathExpandHtml(el.html))+`</div></div>`;
                });
                formulas.forEach(el=>{
                    let mh;
                    // 9.0 · 내보낼 때도 화면과 똑같은 KaTeX(HTML+MathML)로 그린다.
                    //  mathml 만 쓰면 브라우저 기본 수식 글꼴로 대체돼 폭이 달라지고
                    //  그만큼 옆 본문 위로 번져 글자가 겹쳐 보였다.
                    try{ mh=window.katex?katex.renderToString(el.latex||'',{displayMode:!!el.displayMath,throwOnError:false,strict:'ignore',output:'html'}):esc(el.latex||''); }
                    catch(e){ mh=esc(el.latex||''); }
                    // 가져온 수식은 원문 잉크 상자를 넘지 않도록 넘치는 만큼 축소해 그린다.
                    const imp=!!el.imported;
                    const bw=imp?(el.inkW||el.w):el.w, bh=imp?(el.inkH||el.h):el.h;
                    const k=imp?Math.min(1,(latexFitScale(el)||1)):1;
                    const fs=Math.max(6,(el.fontSize||20)*k);
                    body+=`<div style="position:absolute;left:${el.x}px;top:${el.y}px;width:${bw}px;height:${bh}px;`+
                          `display:flex;align-items:center;${el.displayMath?'justify-content:center;':''}font-size:${fs}px;`+
                          `line-height:1.05;font-family:'Times New Roman',serif;color:#111;`+
                          `overflow:${imp?'hidden':'visible'};">${htmlToXhtml(mh)}</div>`;
                });
                const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${size.w}" height="${size.h}" viewBox="0 0 ${size.w} ${size.h}">`+
                    `<foreignObject x="0" y="0" width="${size.w}" height="${size.h}">`+
                    `<div xmlns="http://www.w3.org/1999/xhtml" style="width:${size.w}px;height:${size.h}px;position:relative;`+
                    `font-family:'Pretendard Variable','Pretendard',sans-serif;">${body}</div></foreignObject></svg>`;
                const img=await svgToImage(svg);
                ctx.drawImage(img,0,0,size.w,size.h);
                done=true;
            }catch(e){
                console.warn('텍스트 SVG 렌더 실패 → 캔버스 폴백',e);
            }
            if(!done){
                texts.forEach(el=>drawTextOnCanvas(ctx,el));
                formulas.forEach(el=>{
                    ctx.save();ctx.fillStyle='#111';
                    // 9.0 · 폴백에서도 원문 잉크 폭을 넘지 않게 글씨를 줄여 그린다.
                    const bw=Math.max(8,(el.imported?(el.inkW||el.w):el.w));
                    let fs=el.fontSize||20;
                    ctx.font=`${fs}px "Times New Roman",serif`;
                    const raw=(el.latex||'').replace(/[{}\\]|\$/g,'');
                    const tw=ctx.measureText(raw).width||1;
                    if(tw>bw){ fs=Math.max(6,fs*(bw/tw)); ctx.font=`${fs}px "Times New Roman",serif`; }
                    ctx.textBaseline='middle';ctx.textAlign=el.displayMath?'center':'left';
                    ctx.fillText(raw,el.displayMath?el.x+bw/2:el.x,el.y+(el.imported?(el.inkH||el.h):el.h)/2);
                    ctx.restore();
                });
            }
        }
        return c;
    }

    function loadImg(src){
        return new Promise((res,rej)=>{
            const i=new Image();
            i.onload=()=>res(i);
            i.onerror=rej;
            i.src=src;
        });
    }

    function drawStrokeOnCanvas(ctx,st){
        const pts=st.pts||[];
        if(!pts.length) return;
        ctx.save();
        ctx.translate(st.dx||0, st.dy||0);
        ctx.strokeStyle=st.color; ctx.lineWidth=st.size;
        if(st.opacity!=null) ctx.globalAlpha=st.opacity;
        ctx.lineCap='round'; ctx.lineJoin='round';
        ctx.beginPath();
        ctx.moveTo(pts[0][0],pts[0][1]);
        if(st.sharp&&!isEllipsePts(pts)){
            for(let i=1;i<pts.length;i++) ctx.lineTo(pts[i][0],pts[i][1]);
        }else{
            for(let i=1;i<pts.length-1;i++){
                const mx=(pts[i][0]+pts[i+1][0])/2, my=(pts[i][1]+pts[i+1][1])/2;
                ctx.quadraticCurveTo(pts[i][0],pts[i][1],mx,my);
            }
            const last=pts[pts.length-1];
            ctx.lineTo(last[0],last[1]);
        }
        ctx.stroke();
        ctx.restore();
    }

    // 서식 없는 순수 텍스트 폴백 (SVG 렌더가 막혔을 때도 글자는 남긴다)
    function drawTextOnCanvas(ctx,el){
        const tmp=document.createElement('div');
        tmp.innerHTML=(el.html||'').replace(/<br\s*\/?>/gi,'\n').replace(/<\/(div|p)>/gi,'\n');
        const text=(tmp.textContent||'').replace(/\u00a0/g,' ');
        if(!text.trim()) return;
        // 단어 상자(tight): 패딩·줄바꿈 없이 상자 중앙에 한 줄로
        if(el.tight){
            const fs=el.fontSize||16;
            ctx.save();
            ctx.fillStyle='#111111';
            ctx.font=`${fs}px ${fontCSS(el.font||'pretendard')}`;
            ctx.textBaseline='middle';
            const al=el.align||'left';
            ctx.textAlign=al==='center'?'center':al==='right'?'right':'left';
            const ox=al==='center'?el.x+el.w/2:al==='right'?el.x+el.w:el.x;
            ctx.fillText(text.replace(/\s+/g,' '), ox, el.y+el.h/2);
            ctx.restore();
            return;
        }
        const fs=el.fontSize||16, lh=fs*1.5;
        ctx.save();
        ctx.fillStyle='#111111';
        ctx.font=`${fs}px ${fontCSS(el.font||'pretendard')}`;
        ctx.textBaseline='top';
        const al=el.align||'left';
        ctx.textAlign=al==='center'?'center':al==='right'?'right':'left';
        const maxW=el.w-24;
        const ox=al==='center'?el.x+el.w/2:al==='right'?el.x+el.w-12:el.x+12;
        let y=el.y+8;
        text.split('\n').forEach(para=>{
            let line='';
            for(const ch of para){
                if(ctx.measureText(line+ch).width>maxW && line){
                    ctx.fillText(line, ox, y); y+=lh; line=ch;
                }else line+=ch;
            }
            if(line) { ctx.fillText(line, ox, y); y+=lh; }
        });
        ctx.restore();
    }

    function drawPaperBg(ctx,type,size){
        ctx.save();
        if(type==='lined'){
            ctx.strokeStyle='#e8e8e8'; ctx.lineWidth=1;
            for(let y=47.5;y<size.h;y+=32){
                ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(size.w,y); ctx.stroke();
            }
        }else if(type==='grid'){
            ctx.strokeStyle='#e8e8e8'; ctx.lineWidth=1;
            for(let y=0.5;y<size.h;y+=32){ ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(size.w,y); ctx.stroke(); }
            for(let x=0.5;x<size.w;x+=32){ ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,size.h); ctx.stroke(); }
        }else if(type==='dotted'){
            ctx.fillStyle='#cfcfcf';
            for(let y=12;y<size.h;y+=24)
                for(let x=12;x<size.w;x+=24){ ctx.beginPath(); ctx.arc(x,y,1,0,6.284); ctx.fill(); }
        }
        ctx.restore();
    }

    // 종이 배경을 SVG 도형으로 직접 그린다 (화면 CSS와 동일한 간격/색)
    function paperBgSVG(type,size){
        let out='';
        if(type==='lined'){
            for(let y=47.5;y<size.h;y+=32) out+=`<line x1="0" y1="${y}" x2="${size.w}" y2="${y}" stroke="#e8e8e8" stroke-width="1"/>`;
        }else if(type==='grid'){
            for(let y=0.5;y<size.h;y+=32) out+=`<line x1="0" y1="${y}" x2="${size.w}" y2="${y}" stroke="#e8e8e8" stroke-width="1"/>`;
            for(let x=0.5;x<size.w;x+=32) out+=`<line x1="${x}" y1="0" x2="${x}" y2="${size.h}" stroke="#e8e8e8" stroke-width="1"/>`;
        }else if(type==='dotted'){
            for(let y=12;y<size.h;y+=24) for(let x=12;x<size.w;x+=24) out+=`<circle cx="${x}" cy="${y}" r="1" fill="#cfcfcf"/>`;
        }
        return out;
    }

    function downloadBlob(blob,name){
        const url=URL.createObjectURL(blob);
        const a=document.createElement('a');
        a.href=url; a.download=name;
        document.body.appendChild(a); a.click(); a.remove();
        setTimeout(()=>URL.revokeObjectURL(url),4000);
    }
    function canvasToBlob(c,type,q){
        return new Promise(res=>{
            if(c.toBlob) c.toBlob(b=>res(b),type,q);
            else{
                const d=c.toDataURL(type,q), bin=atob(d.split(',')[1]);
                const u=new Uint8Array(bin.length);
                for(let i=0;i<bin.length;i++) u[i]=bin.charCodeAt(i);
                res(new Blob([u],{type}));
            }
        });
    }
    function safeTitle(){
        return ((curNB&&curNB.title)||'노트').replace(/[\\/:*?"<>|]/g,'').trim()||'노트';
    }

    // 내보내기 진행 표시
    function expProgress(cur,total,label){
        const el=document.getElementById('expProg');
        if(!el) return;
        if(cur<0){ el.style.display='none'; return; }
        el.style.display='flex';
        el.querySelector('.ep-txt').textContent=label||`내보내는 중... ${cur}/${total}`;
        el.querySelector('.ep-fill').style.width=total?Math.round(cur/total*100)+'%':'0%';
    }

    function openExportModal(){
        if(!doc){ toast('노트를 먼저 열어주세요'); return; }
        document.getElementById('expInfo').textContent=`총 ${doc.pages.length}페이지 · 현재 ${curPageIdx+1}페이지`;
        document.getElementById('exportModal').style.display='flex';
        openNav(closeExportModal);
    }
    function closeExportModal(){ document.getElementById('exportModal').style.display='none'; navDrop(closeExportModal); }

    async function exportCurrentJPG(){
        if(!doc) return;
        if(penActive) finishDrawing();
        commitEditingText();
        expProgress(0,1);
        try{
            const c=await renderPageCanvas(curPageIdx);
            const blob=await canvasToBlob(c,'image/jpeg',0.95);
            downloadBlob(blob, `${safeTitle()}_${curPageIdx+1}.jpg`);
            toast('현재 페이지 저장 완료 ✓',1600);
        }catch(e){ console.error(e); toast('내보내기 실패: '+(e.message||e),3000); }
        finally{ expProgress(-1); }
    }

    async function copyPageToClipboard(){
        if(!doc) return;
        if(penActive) finishDrawing();
        commitEditingText();
        expProgress(0,1,'클립보드로 복사 중...');
        try{
            const c=await renderPageCanvas(curPageIdx);
            const blob=await canvasToBlob(c,'image/png');
            if(navigator.clipboard&&window.ClipboardItem){
                await navigator.clipboard.write([new ClipboardItem({'image/png':blob})]);
                toast('클립보드에 복사됨 ✓',1600);
            }else{
                downloadBlob(blob,`${safeTitle()}_${curPageIdx+1}.png`);
                toast('클립보드 미지원 → 파일로 저장됨',2200);
            }
        }catch(e){ console.error(e); toast('복사 실패: '+(e.message||e),3000); }
        finally{ expProgress(-1); }
    }

    async function exportJPG(){
        if(!doc){ toast('노트를 먼저 열어주세요'); return; }
        if(penActive) finishDrawing();
        commitEditingText();
        const n=doc.pages.length;
        expProgress(0,n);
        try{
            const title=safeTitle();
            for(let i=0;i<n;i++){
                expProgress(i,n);
                const c=await renderPageCanvas(i);
                const blob=await canvasToBlob(c,'image/jpeg',0.95);
                if(!blob) throw new Error('이미지 생성 실패');
                downloadBlob(blob, n>1?`${title}_${i+1}.jpg`:`${title}.jpg`);
                await new Promise(r=>setTimeout(r,320));   // 브라우저 다중 다운로드 여유
            }
            toast(`JPG ${n}장 저장 완료 ✓`,1800);
        }catch(e){
            console.error('JPG 내보내기 실패:',e);
            toast('내보내기 실패: '+(e.message||e),3200);
        }finally{ expProgress(-1); }
    }

    // 진짜 PDF 파일을 직접 생성 (외부 라이브러리/팝업 없이)
    function buildPDF(pages,w,h){
        // pages: [{jpg:Uint8Array}]
        const enc=new TextEncoder();
        const chunks=[]; let len=0;
        const push=(d)=>{ const u=(typeof d==='string')?enc.encode(d):d; chunks.push(u); len+=u.length; return len; };
        const offsets=[];
        push('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n');

        const nPages=pages.length;
        const objTotal=2+nPages*3;           // catalog, pages, then (page,content,image)*n
        const startObj=(i)=>{ offsets[i]=len; push(`${i} 0 obj\n`); };
        const endObj=()=>push('endobj\n');

        startObj(1);
        push(`<< /Type /Catalog /Pages 2 0 R >>\n`); endObj();

        const kids=[]; for(let i=0;i<nPages;i++) kids.push(`${3+i*3} 0 R`);
        startObj(2);
        push(`<< /Type /Pages /Count ${nPages} /Kids [${kids.join(' ')}] >>\n`); endObj();

        for(let i=0;i<nPages;i++){
            const pageObj=3+i*3, contentObj=pageObj+1, imgObj=pageObj+2;
            startObj(pageObj);
            push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${w} ${h}] `+
                 `/Resources << /XObject << /Im0 ${imgObj} 0 R >> >> /Contents ${contentObj} 0 R >>\n`);
            endObj();

            const stream=`q\n${w} 0 0 ${h} 0 0 cm\n/Im0 Do\nQ\n`;
            startObj(contentObj);
            push(`<< /Length ${stream.length} >>\nstream\n${stream}endstream\n`); endObj();

            const jpg=pages[i].jpg;
            startObj(imgObj);
            push(`<< /Type /XObject /Subtype /Image /Width ${pages[i].w} /Height ${pages[i].h} `+
                 `/ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpg.length} >>\nstream\n`);
            push(jpg);
            push('\nendstream\n'); endObj();
        }

        const xrefPos=len;
        let xref=`xref\n0 ${objTotal+1}\n0000000000 65535 f \n`;
        for(let i=1;i<=objTotal;i++){
            xref+=String(offsets[i]||0).padStart(10,'0')+' 00000 n \n';
        }
        push(xref);
        push(`trailer\n<< /Size ${objTotal+1} /Root 1 0 R >>\nstartxref\n${xrefPos}\n%%EOF\n`);

        const out=new Uint8Array(len); let o=0;
        chunks.forEach(c=>{ out.set(c,o); o+=c.length; });
        return new Blob([out],{type:'application/pdf'});
    }

    async function exportPDF(){
        if(!doc){ toast('노트를 먼저 열어주세요'); return; }
        if(penActive) finishDrawing();
        commitEditingText();
        const n=doc.pages.length;
        expProgress(0,n);
        try{
            const size=paperSize();
            const pages=[];
            for(let i=0;i<n;i++){
                expProgress(i,n);
                const c=await renderPageCanvas(i);
                const blob=await canvasToBlob(c,'image/jpeg',0.92);
                const buf=new Uint8Array(await blob.arrayBuffer());
                pages.push({jpg:buf,w:c.width,h:c.height});
            }
            expProgress(n,n,'PDF 만드는 중...');
            const pdf=buildPDF(pages,size.w,size.h);
            downloadBlob(pdf, safeTitle()+'.pdf');
            toast(`PDF 저장 완료 ✓ (${n}쪽)`,2000);
            fetch('/api/notifications/event',{method:'POST',headers:{'Content-Type':'application/json'},
                body:JSON.stringify({kind:'pdf',event:'pdf_'+Date.now().toString(36),
                    title:'PDF를 만들었어요',message:`${safeTitle()} · ${n}쪽 저장 완료`})}).catch(()=>{});
        }catch(e){
            console.error('PDF 내보내기 실패:',e);
            toast('PDF 실패: '+(e.message||e),3200);
        }finally{ expProgress(-1); }
    }


    // ============ 에디터 우클릭 메뉴 ============
    let ctxTarget=null;   // {kind:'blank'|'el'|'text', pageIdx, x, y, el}
    // ── 우클릭 메뉴 ────────────────────────────────────────
    // 항목이 {sub:'번역', items:[...]} 이면 하위 메뉴로 접힌다.
    // 접힌 묶음을 누르면 그 자리에서 펼쳐진다 (창을 새로 띄우지 않음).
    let _ctxItems=null, _ctxOpenSub=null;
    function ctxRender(){
        const m=document.getElementById('ctxMenu');
        const rowHTML=(it)=>{
            if(it==='-') return '<div class="ctx-sep"></div>';
            if(it.sub){
                const on=_ctxOpenSub===it.sub;
                let h=`<div class="ctx-item ctx-group${on?' open':''}" data-sub="${esc(it.sub)}">`+
                      `<i class="${it.i||'ri-more-line'}"></i> ${esc(it.sub)}`+
                      `<i class="ri-arrow-right-s-line ctx-caret"></i></div>`;
                if(on) h+='<div class="ctx-subwrap">'+it.items.map(rowHTML).join('')+'</div>';
                return h;
            }
            return `<div class="ctx-item${it.danger?' danger':''}" data-a="${it.a}">`+
                   `<i class="${it.i}"></i> ${it.t}`+
                   (it.k?`<span class="ctx-key">${it.k}</span>`:'')+
                   `</div>`;
        };
        m.innerHTML=_ctxItems.map(rowHTML).join('');
        m.querySelectorAll('.ctx-item[data-a]').forEach(n=>{
            n.onclick=(ev)=>{ ev.stopPropagation(); closeCtxMenu(); editorAction(n.dataset.a); };
        });
        m.querySelectorAll('.ctx-item[data-sub]').forEach(n=>{
            n.onclick=(ev)=>{ ev.stopPropagation();
                _ctxOpenSub=(_ctxOpenSub===n.dataset.sub)?null:n.dataset.sub;
                ctxRender(); ctxPlace(true); };
        });
    }
    // 화면 안에 반드시 들어오도록 놓는다.
    //  · 위/아래가 잘리던 문제: 아래로 넘치면 위로 붙이고, 그래도 길면
    //    스스로 스크롤되게 최대 높이를 준다 (예전엔 top 이 음수가 돼 잘렸다).
    //  · 확대(zoom)를 켜면 메뉴도 같은 비율로 커진다.
    function ctxPlace(keepAnchor){
        const m=document.getElementById('ctxMenu');
        const pad=8;
        // 9.0 · 우클릭 메뉴는 종이 확대율을 따라가지 않는다.
        //  예전에는 pageScale 을 그대로 써서, 종이를 2~3배로 키워 보면
        //  메뉴까지 같이 부풀어 화면을 다 덮었다. 메뉴는 '화면 UI' 이므로
        //  종이가 아무리 커져도 항상 읽기 좋은 고정 크기로 둔다.
        //  터치 기기에서만 손가락에 맞춰 아주 살짝 키운다.
        const touch=matchMedia('(pointer:coarse)').matches;
        const z=touch?1.06:1;
        m.style.setProperty('--ctxz', z.toFixed(3));
        m.style.maxHeight='';
        // lastMouse(화면 px)와 offsetWidth(메뉴가 쓰는 CSS px)는 사이트 기본
        // 배율(90%) 때문에 단위가 다르다. 전부 CSS px 로 맞춰 재야 메뉴가
        // 눌린 바로 그 자리에 뜨고 화면 밖으로 나가지 않는다.
        const vw=uiCss(window.innerWidth), vh=uiCss(window.innerHeight);
        const maxH=vh-pad*2;
        if(m.offsetHeight>maxH) m.style.maxHeight=maxH+'px';
        const w=m.offsetWidth||210, h=m.offsetHeight||300;
        const ax=(keepAnchor&&_ctxAnchor)?_ctxAnchor.x:lastMouse.clientX;
        const ay=(keepAnchor&&_ctxAnchor)?_ctxAnchor.y:lastMouse.clientY;
        _ctxAnchor={x:ax,y:ay};
        let x=uiCss(ax), y=uiCss(ay);
        // 가로: 오른쪽에 자리가 없으면 왼쪽으로 펼친다
        let L=(x+w+pad>vw)? x-w : x;
        L=Math.max(pad, Math.min(L, vw-w-pad));
        // 세로: 아래가 모자라면 위로 올리되, 절대 음수로 가지 않는다
        let T=(y+h+pad>vh)? y-h : y;
        T=Math.max(pad, Math.min(T, vh-h-pad));
        m.style.left=Math.round(L)+'px';
        m.style.top =Math.round(T)+'px';
    }
    let _ctxAnchor=null;
    function editorMenu(items){
        _ctxItems=items; _ctxOpenSub=null; _ctxAnchor=null;
        const m=document.getElementById('ctxMenu');
        ctxRender();
        m.classList.add('show');
        ctxPlace(false);
    }

    function onEditorContext(e){
        if(!doc) return;
        const paper=e.target.closest('#pagesStage .paper');
        if(!paper) return;
        e.preventDefault();
        closePops();
        const pageIdx=+paper.dataset.pageIdx;
        curPageIdx=pageIdx; updatePageInfo();
        const p=pageLocal(e,pageIdx),px=p.x,py=p.y;
        lastMouse.clientX=e.clientX; lastMouse.clientY=e.clientY;
        lastMouse.pageIdx=pageIdx; lastMouse.x=px; lastMouse.y=py;

        // ① 글자를 드래그해 고른 상태 (편집 중이 아니어도 동작)
        //    우클릭 순간 브라우저가 선택을 지우는 경우가 있어,
        //    직전에 저장해 둔 선택(savedRange)까지 함께 살펴본다.
        const editing=document.querySelector('.tb.edit');
        let sel=window.getSelection();
        let selHost=(sel&&!sel.isCollapsed&&sel.anchorNode)
            ? (sel.anchorNode.nodeType===1?sel.anchorNode:sel.anchorNode.parentElement)
            : null;
        let selBox=selHost?selHost.closest('.tb-content'):null;
        let selText=selBox?String(sel):'';
        if((!selBox||!selText.trim()) && savedRange && savedHost
           && document.body.contains(savedHost) && String(savedRange).trim()){
            // 저장된 선택을 되살려 그대로 이어서 쓴다
            selBox=savedHost;
            selText=String(savedRange);
            const s2=window.getSelection();
            s2.removeAllRanges(); s2.addRange(savedRange.cloneRange());
            sel=s2;
        }
        if(selBox && selText.trim()){
            // 편집 모드가 아니었다면 지금 진입시켜 그 자리에서 바로 고칠 수 있게 한다
            const w=selBox.closest('.tb');
            if(w && !w.classList.contains('edit')){
                const r0=sel.getRangeAt(0).cloneRange();
                enterEdit(w,true);
                enableTextSelect(selBox);
                const s2=window.getSelection();
                s2.removeAllRanges(); s2.addRange(r0);
            }
            saveSel();
            const txt=selText.trim();
            const short=txt.length>12?txt.slice(0,12)+'…':txt;
            ctxTarget={kind:'text',pageIdx,el:selBox.closest('.tb')};
            editorMenu([
                {a:'copy',   i:'ri-file-copy-line', t:'복사',      k:'Ctrl+C'},
                {a:'cut',    i:'ri-scissors-line',  t:'잘라내기',   k:'Ctrl+X'},
                {a:'bold',   i:'ri-bold',           t:'굵게',      k:'Ctrl+B'},
                {a:'hl',     i:'ri-mark-pen-line',  t:'형광펜'},
                {a:'clear',  i:'ri-format-clear',   t:'서식제거'},
                {a:'sel-find',  i:'ri-search-line', t:`'${esc(short)}' 찾기`},
                '-',
                {sub:'서식', i:'ri-font-color', items:[
                    {a:'italic', i:'ri-italic',        t:'기울임',  k:'Ctrl+I'},
                    {a:'under',  i:'ri-underline',     t:'밑줄',   k:'Ctrl+U'},
                    {a:'strike', i:'ri-strikethrough', t:'취소선'},
                    {a:'color',  i:'ri-font-color',    t:'글자색 적용'},
                    {a:'clear',  i:'ri-format-clear',  t:'서식 지우기'},
                ]},
                {sub:'번역', i:'ri-translate-2', items:[
                    {a:'tr-sel-ko', i:'ri-translate-2', t:'한국어로'},
                    {a:'tr-sel-en', i:'ri-translate',   t:'영어로'},
                    {a:'tr-sel-ja', i:'ri-translate',   t:'일본어로'},
                    {a:'tr-sel-zh', i:'ri-translate',   t:'중국어로'},
                ]},
                {sub:'더보기', i:'ri-more-line', items:[
                    {a:'sel-clip',  i:'ri-inbox-archive-line', t:'모아두기에 담기'},
                    {a:'sel-upper', i:'ri-font-size-2', t:'영문 대문자로'},
                    {a:'sel-lower', i:'ri-font-size',   t:'영문 소문자로'},
                    {a:'sel-link',  i:'ri-link',        t:'링크 걸기'},
                    {a:'sel-count', i:'ri-calculator-line', t:'글자 수 세기'},
                    {a:'sel-newbox',i:'ri-text-block',  t:'새 글상자로 빼내기'},
                ]},
            ]);
            return;
        }

        // ② 요소 위
        const host=e.target.closest('.tb')||e.target.closest('.paper-img')||e.target.closest('.stroke-g');
        if(host){
            const kind=host.classList.contains('latex-box')?'latex'
                      :host.classList.contains('tb')?'text-el'
                      :host.classList.contains('paper-img')?'img':'stroke';
            // 다중 선택 상태에서 그 안의 요소를 우클릭하면 선택을 유지한다
            const inMulti=multiSel.some(m=>m.node===host);
            deselectAll(true);
            if(!inMulti) clearMulti();
            host.classList.add('sel');
            selected={type:kind==='img'?'image':(kind==='stroke'?'stroke':'text'),el:host};
            ctxTarget={kind:'el',pageIdx,el:host,elKind:kind};
            const multi=multiSel.length>1;
            const items=[
                {a:'el-copy',  i:'ri-file-copy-line', t:'복사', k:'Ctrl+C'},
                {a:'el-cut',   i:'ri-scissors-line',  t:'잘라내기', k:'Ctrl+X'},
                {a:'el-dup',   i:'ri-file-copy-2-line', t:'복제', k:'Ctrl+J'},
            ];
            // 18.7 · 보고: 우클릭 메뉴에서 '내용 편집' 버튼을 없앤다.
            //   텍스트 편집은 더블클릭/텍스트 도구로만 들어가는 것으로 충분하다.
            //   (LaTeX 수식 편집 버튼은 유지 — 수식은 더블클릭이 없으므로)
            if(kind==='latex' && !multi) items.push({a:'latex-edit', i:'ri-function-line', t:'LaTeX 수식 편집'});
            items.push('-');

            // 표 안이면 표 편집을 하위 메뉴로
            {
                const hel=findEl(pageIdx,host.dataset.id);
                const tid=(hel&&hel.tbl&&hel.tbl.tid)||null;
                if(tid){
                    setActiveTbl(pageIdx,tid,(hel.tbl.r)||0,(hel.tbl.c)||0);
                    items.push({sub:'표 편집', i:'ri-table-line', items:[
                        {a:'tbl-row-up',   i:'ri-insert-row-top',      t:'위에 행 추가'},
                        {a:'tbl-row-down', i:'ri-insert-row-bottom',   t:'아래에 행 추가'},
                        {a:'tbl-col-left', i:'ri-insert-column-left',  t:'왼쪽에 열 추가'},
                        {a:'tbl-col-right',i:'ri-insert-column-right', t:'오른쪽에 열 추가'},
                        {a:'tbl-fit',      i:'ri-layout-column-line',  t:'열 너비 고르게'},
                        {a:'tbl-del-row',  i:'ri-delete-row',    t:'이 행 삭제', danger:true},
                        {a:'tbl-del-col',  i:'ri-delete-column', t:'이 열 삭제', danger:true},
                        {a:'tbl-del',      i:'ri-delete-bin-6-line', t:'표 전체 삭제', danger:true},
                    ]});
                }
            }
            if(kind==='text-el'){
                items.push({sub:'정렬·서식', i:'ri-align-left', items:[
                    {a:'el-align-left',   i:'ri-align-left',   t:'왼쪽 정렬'},
                    {a:'el-align-center', i:'ri-align-center', t:'가운데 정렬'},
                    {a:'el-align-right',  i:'ri-align-right',  t:'오른쪽 정렬'},
                    {a:'el-clearfmt',     i:'ri-format-clear', t:'이 상자 서식 지우기'},
                ]});
                const tr=[
                    {a:'tr-ko', i:'ri-translate-2', t:'이 상자 → 한국어'},
                    {a:'tr-en', i:'ri-translate',   t:'이 상자 → 영어'},
                ];
                if(multi){
                    tr.push({a:'tr-sel-all-ko', i:'ri-translate-2', t:`선택 ${multiSel.length}개 → 한국어`});
                    tr.push({a:'tr-sel-all-en', i:'ri-translate',   t:`선택 ${multiSel.length}개 → 영어`});
                }
                tr.push({a:'trpg-ko', i:'ri-file-list-3-line', t:'이 페이지 → 한국어'});
                tr.push({a:'trpg-en', i:'ri-file-list-3-line', t:'이 페이지 → 영어'});
                tr.push({a:'trdoc-ko', i:'ri-book-open-line', t:'문서 전체 → 한국어'});
                tr.push({a:'trdoc-en', i:'ri-book-open-line', t:'문서 전체 → 영어'});
                items.push({sub:'번역', i:'ri-translate-2', items:tr});
            }
            if(multi){
                items.push({sub:'여러 개 맞춤', i:'ri-align-item-left-line', items:[
                    {a:'al-left',    i:'ri-align-item-left-line',     t:'왼쪽 맞춤'},
                    {a:'al-hcenter', i:'ri-align-item-horizontal-center-line', t:'가로 가운데'},
                    {a:'al-right',   i:'ri-align-item-right-line',    t:'오른쪽 맞춤'},
                    {a:'al-top',     i:'ri-align-item-top-line',      t:'위쪽 맞춤'},
                    {a:'al-vcenter', i:'ri-align-item-vertical-center-line', t:'세로 가운데'},
                    {a:'al-bottom',  i:'ri-align-item-bottom-line',   t:'아래쪽 맞춤'},
                    ...(multiSel.length>2?[
                        {a:'al-hdist', i:'ri-space', t:'가로 균등 배치'},
                        {a:'al-vdist', i:'ri-space', t:'세로 균등 배치'}]:[]),
                ]});
            }
            // 기타: 순서·잠금·스티커·묶기
            const more=[
                {a:'el-front', i:'ri-bring-to-front', t:'맨 앞으로'},
                {a:'el-back',  i:'ri-send-to-back',   t:'맨 뒤로'},
                {a:'el-sticker', i:'ri-sticky-note-line', t:'스티커로 만들기'},
            ];
            if(!multi){
                more.push({a:'el-lock', i:'ri-lock-2-line',
                    t:(findEl(pageIdx,host.dataset.id)||{}).locked?'잠금 풀기':'움직이지 않게 잠그기'});
            }else{
                // 14.16.6 · '스티커로 합치기'(원본을 지우고 스티커로 갈아끼우기)는
                //   객체 묶기와 겹치는 기능이라 뺐다 — 여러 개는 객체 묶기로 묶고,
                //   스티커는 '스티커로 만들기'(원본 유지)로만 만든다.
                more.push({a:'el-group', i:'ri-links-line', t:'객체 묶기'});
            }
            if(selectionHasGroup()) more.push({a:'el-ungroup', i:'ri-link-unlink', t:'묶음 해제'});
            if(kind==='img'){
                const im=findEl(pageIdx,host.dataset.id);
                const lk=!(im&&im.freeRatio);
                items.push({a:'el-view', i:'ri-zoom-in-line', t:'크게 보기'});
                more.push({a:'el-ratio', i:lk?'ri-lock-line':'ri-lock-unlock-line',
                           t:lk?'비율 고정 해제':'비율 고정하기'});
            }
            items.push({sub:'더보기', i:'ri-more-line', items:more});
            items.push('-',{a:'el-del', i:'ri-delete-bin-6-line', t:'삭제', k:'Del', danger:true});
            editorMenu(items);
            return;
        }

        // ③ 빈 종이
        ctxTarget={kind:'blank',pageIdx,x:px,y:py};
        editorMenu([
            {a:'new-text', i:'ri-text',           t:'텍스트 상자'},
            {a:'paste',    i:'ri-clipboard-line', t:'붙여넣기', k:'Ctrl+V'},
            {a:'img',      i:'ri-image-add-line', t:'이미지 넣기'},
            {a:'sticker',  i:'ri-sticky-note-line', t:'스티커 넣기'},
            {a:'new-latex',i:'ri-function-line',  t:'LaTeX 수식 넣기'},
            {a:'new-table',i:'ri-table-line',     t:'표 넣기'},
            {a:'pen',      i:'ri-pen-nib-line',   t:'펜 / 도형'},
            '-',
            {sub:'페이지', i:'ri-file-list-3-line', items:[
                {a:'select-all',i:'ri-checkbox-multiple-line', t:'이 페이지 전체 선택', k:'Ctrl+A'},
                {a:'page-dup', i:'ri-file-copy-line', t:'페이지 복제', k:'Ctrl+D'},
                {a:'page-add', i:'ri-file-add-line',  t:'페이지 추가', k:'Ctrl+Enter'},
            ]},
            {sub:'번역', i:'ri-translate-2', items:[
                {a:'trpg-ko', i:'ri-file-list-3-line', t:'이 페이지 → 한국어'},
                {a:'trpg-en', i:'ri-file-list-3-line', t:'이 페이지 → 영어'},
                {a:'trdoc-ko', i:'ri-book-open-line', t:'문서 전체 → 한국어'},
                {a:'trdoc-en', i:'ri-book-open-line', t:'문서 전체 → 영어'},
            ]},
            {a:'export',   i:'ri-share-box-line',t:'내보내기',   k:'Ctrl+E'},
        ]);
    }

    function inlineSelectionForAction(){
        let host=restoreSel();
        const s=window.getSelection();
        if(!s||s.isCollapsed||!s.rangeCount) return null;
        if(!host){
            const n=s.anchorNode ? (s.anchorNode.nodeType===1?s.anchorNode:s.anchorNode.parentElement) : null;
            host=n&&n.closest?n.closest('.tb-content'):null;
        }
        if(!host) return null;
        return {sel:s,host,text:String(s)};
    }
    async function writeClipboardTextSafe(txt){
        txt=String(txt||'');
        if(!txt) return false;
        try{
            if(navigator.clipboard&&navigator.clipboard.writeText){
                await navigator.clipboard.writeText(txt);
                return true;
            }
        }catch(e){}
        // 권한이 없거나 execCommand 가 사라진 환경에서도 메뉴 동작이 터지면 안 된다.
        try{ fallbackCopyText(txt); return true; }catch(e){ return false; }
    }
    async function copyInlineSelectionForAction(){
        const cur=inlineSelectionForAction();
        if(!cur||!cur.text.trim()){
            try{ if(document.execCommand) document.execCommand('copy'); }catch(e){}
            return false;
        }
        await writeClipboardTextSafe(cur.text);
        saveSel();
        toast('텍스트 복사됨',1200);
        return true;
    }
    async function cutInlineSelectionForAction(wHint){
        const cur=inlineSelectionForAction();
        if(!cur||!cur.text.trim()){
            try{ if(document.execCommand) document.execCommand('cut'); }catch(e){}
            return false;
        }
        await writeClipboardTextSafe(cur.text);
        pushHistory();
        const r=cur.sel.getRangeAt(0);
        r.deleteContents();
        r.collapse(true);
        cur.sel.removeAllRanges(); cur.sel.addRange(r);
        const w=cur.host.closest('.tb')||wHint;
        if(w) syncTextEl(w);
        saveSel();
        toast('텍스트 잘라냄',1200);
        return true;
    }

    async function editorAction(a){
        const t=ctxTarget; if(!t) return;
        const pi=t.pageIdx;
        if(a==='new-text'){
            const dim=textBoxDefaultSize();
            const c=clampEl(t.x-dim.w/2,t.y-dim.h/2,dim.w,dim.h);
            addTextBox(pi,c.x,c.y,dim);
        }
        else if(a==='paste'){
            try{
                const items=await navigator.clipboard.read();
                for(const it of items){
                    const imgType=it.types.find(x=>x.startsWith('image/'));
                    if(imgType){
                        const bl=await it.getType(imgType);
                        await uploadImgs([new File([bl],'paste.png',{type:imgType})],true);
                        return;
                    }
                }
                const txt=await navigator.clipboard.readText();
                if(txt&&txt.trim()){
                    const s=paperSize();
                    const w=Math.min(s.w-96,Math.max(220,Math.min(560,txt.length*11)));
                    const h=Math.max(52,txt.split(/\n/).length*(curFontSize*1.5)+26);
                    const c=clampEl(t.x-w/2,t.y-h/2,w,h);
                    pushHistory();
                    doc.pages[pi].els.push({type:'text',id:uid('t'),x:Math.round(c.x),y:Math.round(c.y),
                        w:Math.round(w),h:Math.round(h),html:esc(txt).replace(/\n/g,'<br>'),fontSize:curFontSize});
                    renderPageEls(pi); saveDoc();
                }else toast('클립보드가 비어 있습니다',1400);
            }catch(err){ toast('Ctrl+V 로 붙여넣어 주세요',1800); }
        }
        else if(a==='img'){ triggerImgUpload({pageIdx:pi,x:t.x,y:t.y}); }
        // 빈 종이 우클릭 → 스티커 넣기 : 보관함을 열고, 우클릭한 자리를 기억한다.
        // 보관함에서 스티커를 고르면 그 자리에 붙는다(툴바로 열면 기본 자리).
        else if(a==='sticker'){ _stickerAnchor={pageIdx:pi,x:t.x,y:t.y}; openStickers(); }
        else if(a==='new-latex'){ openLatexModal(); _latexAnchor={pageIdx:pi,x:t.x,y:t.y}; }
        else if(a==='latex-edit'){ openLatexModal(t.el.dataset.id,pi); }
        else if(a==='pen'){ togglePen(); }
        else if(a==='page-dup'){ duplicatePage(); }
        else if(a==='page-add'){ addPage(); }
        else if(a==='export'){ openExportModal(); }
        else if(a==='copy'){
            await copyInlineSelectionForAction();
        }
        else if(a==='cut'){
            await cutInlineSelectionForAction(t.el);
        }
        else if(a==='bold'){ execFmt('bold'); }
        else if(a==='italic'){ execFmt('italic'); }
        else if(a==='under'){ execFmt('underline'); }
        else if(a==='color'){ applyTextColor(currentTextColor); }
        else if(a==='hl'){ applyHighlight(currentHlColor); }
        else if(a==='clear'){ clearFmt(); }
        else if(a==='el-del'){
            pushHistory();
            const gone=(doc.pages[pi].els||[]).filter(x=>x.id===t.el.dataset.id);
            doc.pages[pi].els=doc.pages[pi].els.filter(x=>x.id!==t.el.dataset.id);
            t.el.remove(); selected=null; saveDoc();
            purgeElements(gone);
        }
        else if(a==='select-all'){ selectAllOnPage(); }
        else if(a&&a.startsWith('al-')){ alignSelection(a.slice(3)); }
        else if(a==='el-copy'){ copyElements(false); }
        else if(a==='el-cut'){  copyElements(true); }
        else if(a==='el-align-left'||a==='el-align-center'||a==='el-align-right'){
            setAlign(a.replace('el-align-',''));
        }
        else if(a==='el-dup'){
            pushHistory();
            const src=findEl(pi,t.el.dataset.id);
            const cp=JSON.parse(JSON.stringify(src));
            cp.id=uid(cp.type[0]);
            if(cp.type==='stroke'){ cp.dx=(cp.dx||0)+16; cp.dy=(cp.dy||0)+16; }
            else { cp.x=Math.min(paperSize().w-cp.w, cp.x+16); cp.y=Math.min(paperSize().h-cp.h, cp.y+16); }
            doc.pages[pi].els.push(cp);
            renderPageEls(pi); saveDoc(); toast('복제됨',1000);
        }
        else if(a==='el-front'||a==='el-back'){
            pushHistory();
            const arr=doc.pages[pi].els;
            const i=arr.findIndex(x=>x.id===t.el.dataset.id);
            if(i>=0){
                const [it]=arr.splice(i,1);
                if(a==='el-front') arr.push(it); else arr.unshift(it);
                renderPageEls(pi); saveDoc();
                toast(a==='el-front'?'맨 앞으로':'맨 뒤로',900);
            }
        }
        else if(a==='el-edit'){ enterEdit(t.el,false); }
        else if(a==='el-clearfmt'){
            pushHistory();
            clearBoxFormatting(t.el);
            saveDoc(); toast('서식 지움',1200);
        }
        else if(a==='new-table'){
            const v=prompt('표 크기를 입력하세요 (행 x 열)','3 x 3');
            if(v){ const m=String(v).match(/(\d+)\s*[x\u00d7,\s]\s*(\d+)/);
                   if(m) insertTable(+m[1],+m[2],pi,lastMouse.x,lastMouse.y);
                   else toast('예: 3 x 4 형식으로 입력해 주세요',2200); }
        }
        else if(a==='tbl-row-up'){ tblAdd('row',-1); }
        else if(a==='tbl-row-down'){ tblAdd('row',1); }
        else if(a==='tbl-col-left'){ tblAdd('col',-1); }
        else if(a==='tbl-col-right'){ tblAdd('col',1); }
        else if(a==='tbl-del-row'){ tblDel('row'); }
        else if(a==='tbl-del-col'){ tblDel('col'); }
        else if(a==='tbl-fit'){ tblFit(); }
        else if(a==='tbl-del'){ tblDelAll(); }
        else if(a==='el-lock'){ toggleLockEl(); }
        else if(a==='el-sticker'){ makeSticker(); }
        else if(a==='el-view'){
            // ★ 14.28.1 · 이미지 크게 보기는 더블클릭/재탭으로 자동 진입하지 않고
            //   우클릭 메뉴에서 명시적으로 고를 때만 전체화면 뷰어를 연다.
            const t=ctxTarget&&ctxTarget.el;
            if(t){
                const el2=findEl(+t.dataset.pageIdx,t.dataset.id);
                document.getElementById('vImg').src=(el2&&el2.url)||(el2&&el2.localURL)||'';
                document.getElementById('viewer').style.display='flex';
            }
        }
        else if(a==='el-group'){ groupSelection(); }
        else if(a==='el-ungroup'){ ungroupSelection(); }
            else if(a==='tr-ko'||a==='tr-en'){ translateElement(t.el,a==='tr-ko'?'ko':'en'); }
            else if(a==='tr-sel-all-ko') translateSelection('ko');
            else if(a==='tr-sel-all-en') translateSelection('en');
            else if(a==='trpg-ko') translatePageAction(t.pageIdx,'ko');
            else if(a==='trpg-en') translatePageAction(t.pageIdx,'en');
            else if(a==='trdoc-ko') translateDocAction('ko');
            else if(a==='trdoc-en') translateDocAction('en');
        else if(a==='tr-sel-ko') translateSelectedText('ko');
        else if(a==='tr-sel-en') translateSelectedText('en');
        else if(a==='tr-sel-ja') translateSelectedText('ja');
        else if(a==='tr-sel-zh') translateSelectedText('zh-CN');
        else if(a==='strike'){
            // 18.6 · 취소선 토글 — 굵게/기울임/밑줄과 같은 엔진으로
            execFmt('strike');
        }
        else if(a==='sel-upper'||a==='sel-lower'){
            // 18.9 · execCommand('insertText') 는 환경에 따라 없거나(구형 웹뷰)
            //   선택 구간의 서식(굵기·색·글꼴)을 통째로 날린다. 텍스트 노드의
            //   글자만 바꾸면 서식은 그대로 두고 대소문자만 바뀐다.
            const up=(a==='sel-upper');
            const host=restoreSel();
            const s=window.getSelection();
            if(!host||!s||s.isCollapsed){ toast('텍스트를 드래그해 선택하세요',1300); return; }
            pushHistory();
            const r=s.getRangeAt(0);
            const parts=_selContacts(r);
            parts.forEach(ct=>{
                const v=String(ct.node.nodeValue||'');
                const seg=v.slice(ct.s,ct.e);
                ct.node.nodeValue=v.slice(0,ct.s)+(up?seg.toUpperCase():seg.toLowerCase())+v.slice(ct.e);
            });
            const w=host.closest('.tb'); if(w) syncTextEl(w);
            saveSel();
            toast(up?'대문자로 바꿨습니다':'소문자로 바꿨습니다',1400);
        }
        else if(a==='sel-link'){
            const s=window.getSelection();
            const cur=String(s||'').trim();
            const url=prompt('연결할 주소를 입력하세요', /^https?:\/\//i.test(cur)?cur:'https://');
            if(url&&url.trim()){
                const host=restoreSel();
                if(!host){ toast('텍스트를 드래그해 선택하세요',1300); return; }
                pushHistory();
                // v2 엔진: execCommand(createLink) 없이 선택 구간에 <a> 를 짓는다.
                try{ _fmtLinkSelection(url.trim()); }catch(e){}
                const w=host.closest('.tb'); if(w) syncTextEl(w);
                saveSel(); syncCurSel();
                toast('링크를 걸었습니다',1400);
            }
        }
        else if(a==='sel-find'){
            const q=String(window.getSelection()||'').trim();
            if(!q) return;
            openFind();
            const inp=document.getElementById('findInput');
            inp.value=q; runFind(q);
        }
        else if(a==='sel-count'){ countSelection(); }
        else if(a==='sel-clip'){ clipAdd(); if(sidePanel!=='clip') openPanel('clip'); }
        else if(a==='sel-newbox'){
            const s=window.getSelection();
            const txt=String(s||'').trim();
            if(!txt) return;
            pushHistory();
            const size=paperSize();
            const w=Math.min(size.w-96,Math.max(220,Math.min(520,txt.length*11)));
            const h=Math.max(52,Math.ceil(txt.length*11/w)*(curFontSize*1.6)+24);
            doc.pages[pi].els.push({type:'text',id:uid('t'),
                x:Math.round(lastMouse.x||80), y:Math.round((lastMouse.y||100)+30),
                w:Math.round(w), h:Math.round(h), html:esc(txt),
                fontSize:curFontSize, font:curFont});
            renderPageEls(pi); saveDoc();
            toast('새 글상자로 빼냈습니다',1600);
        }
        else if(a==='el-ratio'){
            const el=findEl(pi,t.el.dataset.id);
            el.freeRatio=!el.freeRatio;
            renderPageEls(pi); saveDoc();
            toast(el.freeRatio
                ? '비율 자유 · 꼭짓점으로도 자유롭게 조절'
                : '비율 고정 · 꼭짓점=비율유지, 변중앙=자유', 1800);
        }
    }
    // 우클릭 직전에 현재 선택을 확보해 둔다 (브라우저가 지우기 전에)
    document.addEventListener('pointerdown',e=>{ if(e.button===2) saveSel(); },true);
    document.addEventListener('contextmenu',onEditorContext);

    // ============ 카드 컨텍스트 메뉴 / 부가 기능 ============
    let ctxNB=null;
    function openCardMenu(e,nb){
        ctxNB=nb;
        const cfg=getCfg(nb.id);
        const m=document.getElementById('ctxMenu');
        m.innerHTML=`
            <div class="ctx-item" onclick="ctxAction('open')"><i class="ri-external-link-line"></i> 열기</div>
            <div class="ctx-item" onclick="ctxAction('pin')"><i class="ri-pushpin-2-line"></i> ${cfg.pinned?'고정 해제':'상단 고정'}</div>
            <div class="ctx-item" onclick="ctxAction('rename')"><i class="ri-edit-line"></i> 이름 변경</div>
            <div class="ctx-item" onclick="ctxAction('duplicate')"><i class="ri-file-copy-line"></i> 노트 복제</div>
            <div class="ctx-item" onclick="ctxAction('info')"><i class="ri-information-line"></i> 노트 정보</div>
            <div class="ctx-sep"></div>
            <div class="ctx-item" onclick="ctxAction('lock')"><i class="ri-lock-2-line"></i> ${(cfg.lock&&cfg.lock.enc)?(adminMode?'잠금 해제':'비밀번호 해제'):'비밀번호 잠금'}</div>
            <div class="ctx-item" onclick="ctxAction('export')"><i class="ri-share-box-line"></i> 백업(JSON) 내보내기</div>
            <div class="ctx-sep"></div>
            <div class="ctx-item danger" onclick="ctxAction('delete')"><i class="ri-delete-bin-6-line"></i> 휴지통으로 이동</div>`;
        m.classList.add('show');
        // 화면 밖으로 나가지 않게 (예전엔 위쪽이 잘릴 수 있었다)
        lastMouse.clientX=e.clientX; lastMouse.clientY=e.clientY;
        _ctxAnchor=null;
        ctxPlace(false);
    }
    function closeCtxMenu(){
        const m=document.getElementById('ctxMenu');
        if(m){ m.classList.remove('show'); m.style.display=''; }
    }
    function ctxMenuOpen(){
        const m=document.getElementById('ctxMenu');
        return !!m && m.classList.contains('show');
    }
    // 메뉴 밖을 누르면(좌·우 버튼 모두) 닫는다.
    // ★ pointerdown 으로 변경 — 터치 장치에서 메뉴 닫힘 즉시 반응
    document.addEventListener('pointerdown',e=>{
        if(e.target.closest('.ctx-menu')||e.target.closest('.card-menu')) return;
        closeCtxMenu();
    },true);
    document.addEventListener('click',e=>{
        if(!e.target.closest('.ctx-menu')&&!e.target.closest('.card-menu')) closeCtxMenu();
    });
    document.addEventListener('scroll',closeCtxMenu,true);
    document.addEventListener('wheel',()=>{ if(ctxMenuOpen()) closeCtxMenu(); },{passive:true});
    addEventListener('blur',closeCtxMenu);
    addEventListener('resize',closeCtxMenu);

    async function ctxAction(act){
        const nb=ctxNB; closeCtxMenu();
        if(!nb) return;
        const cfg=getCfg(nb.id);
        if(act==='info'){ showNoteInfo(nb); return; }
        if(act==='open'){ openNB(nb); }
        else if(act==='pin'){ cfg.pinned=!cfg.pinned; setCfg(nb.id,cfg); pushSettingsNow(); notebooks=sortNBs(notebooks); renderGrid(); toast(cfg.pinned?'상단에 고정됨 📌':'고정 해제됨'); }
        else if(act==='rename'){
            const t=prompt('새 이름',nb.title||'새 노트');
            if(t&&t.trim()){
                const want=t.trim();
                nb.title=uniqueTitle(want,noteFolder(nb.id),nb.id);
                if(nb.title!==want) toast(`같은 이름이 있어 '${nb.title}' 로 저장했어요`,2200);
                if(String(nb.id).startsWith('local_')) saveLocalNBs();
                else if(SB){ syncStart(); try{ await SB.from('notebooks').update({title:nb.title,updated_at:new Date().toISOString()}).eq('id',nb.id); }catch(e){} syncEnd(); }
                renderGrid(); toast('이름 변경됨');
            }
        }
        else if(act==='duplicate'){ await duplicateNote(nb); }
        else if(act==='lock'){
            if(cfg.lock&&cfg.lock.enc){
                if(adminMode){
                    // 관리자: 위탁(escrow)으로 바로 잠금 해제
                    if(!confirm(`"${nb.title||'새 노트'}" 의 잠금을 해제할까요?`)) return;
                    if(await removeNoteLockFromCard(nb.id)){ renderGrid(); toast('잠금 해제됨 🔓'); }
                }else{
                    toast('노트를 열어서 해제해주세요',2200); openNB(nb);
                }
            }
            else { openNB(nb).then(()=>setTimeout(lockCurrentNote,350)); }
        }
        else if(act==='export'){ exportNoteJSON(nb); }
        else if(act==='delete'){
            if(isLocked(nb.id)&&!isUnlocked(nb.id)&&!adminMode){
                toast('🔒 잠긴 노트는 삭제할 수 없습니다. 먼저 잠금을 해제하세요',2600); return;
            }
            // 항상 휴지통으로 (영구 삭제 없음 — 30일 후 자동 삭제)
            if(!confirm(`"${nb.title||'새 노트'}" 을(를) 휴지통으로 이동할까요?`)) return;
            const _c=document.querySelector('.note-card[data-nb-id="'+nb.id+'"]');
            playClawThrow(_c, ()=>{
                moveToTrash(nb.id);
                renderGrid(); toast('휴지통으로 이동했습니다 · 30일 후 자동 삭제');
            });
        }
        else if(act==='restore'){
            restoreFromTrash(nb.id);
            renderGrid(); toast('복원했습니다');
            setTimeout(()=>{ const c=document.querySelector('.note-card[data-nb-id="'+nb.id+'"]'); if(c) playClawDrop(c); },80);
        }
    }

    async function duplicateNote(nb){
        if(isLocked(nb.id)&&!isUnlocked(nb.id)){ toast('잠긴 노트는 복제할 수 없습니다'); return; }
        const src=await loadDocAsync(nb.id);
        const copy=JSON.parse(JSON.stringify(src));
        // 요소 id 재발급 (충돌 방지)
        (copy.pages||[]).forEach(pg=>{ pg.id=blankPage().id; (pg.els||[]).forEach(el=>{ el.id=uid(el.type[0]); }); });
        const title=uniqueTitle(nb.title||'새 노트',noteFolder(nb.id),null);
        syncStart();
        try{
            if(SB&&!String(nb.id).startsWith('local_')){
                const{data}=await SB.from('notebooks').insert([{title,color:nb.color||'#4f6ef7'}]).select().single();
                if(data){
                    await SB.from('memos').insert([{notebook_id:data.id,content:'',font_size:S.defFS}]);
                    persistDoc(data.id,copy); notebooks.push(data);
                    const fsrc=noteFolder(nb.id); if(fsrc) setNoteFolder(data.id,fsrc);
                }
            }else{
                const id='local_'+Date.now();
                const nnb={id,title,color:nb.color||'#4f6ef7',created_at:new Date().toISOString(),updated_at:new Date().toISOString()};
                persistDoc(id,copy); notebooks.push(nnb); saveLocalNBs();
                const fsrc=noteFolder(nb.id); if(fsrc) setNoteFolder(id,fsrc);
            }
            notebooks=sortNBs(notebooks); renderGrid(); toast('노트 복제됨');
        }catch(e){ console.error(e); toast('복제 실패'); }
        finally{ syncEnd(); }
    }

    async function exportNoteJSON(nb){
        if(isLocked(nb.id)&&!isUnlocked(nb.id)){ toast('잠긴 노트는 먼저 열어주세요'); return; }
        const d=await loadDocAsync(nb.id);
        const blob=new Blob([JSON.stringify({title:nb.title,doc:d,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});
        const a=document.createElement('a');
        a.href=URL.createObjectURL(blob);
        a.download=(nb.title||'노트').replace(/[^가-힣a-zA-Z0-9_ -]/g,'')+'.json';
        a.click();
        setTimeout(()=>URL.revokeObjectURL(a.href),1000);
        toast('백업 파일 저장됨');
    }

    // 현재 페이지 복제
    function duplicatePage(){
        if(!doc) return;
        pushHistory();
        const copy=JSON.parse(JSON.stringify(doc.pages[curPageIdx]));
        copy.id=blankPage().id;
        (copy.els||[]).forEach(el=>{ el.id=uid(el.type[0]); });
        // 표도 새 id 로 (원본과 섞이지 않게)
        const remap={};
        (copy.tables||[]).forEach(t=>{ const n='tb_'+Math.random().toString(36).slice(2,9);
                                       remap[t.id]=n; t.id=n; t.group='g_'+n; });
        (copy.els||[]).forEach(el=>{ if(el.tbl&&remap[el.tbl.tid]){ el.tbl.tid=remap[el.tbl.tid];
                                       el.group='g_'+el.tbl.tid; } });
        doc.pages.splice(curPageIdx+1,0,copy);
        curPageIdx++;
        renderPages(); saveDoc(); toast('페이지 복제됨');
    }

