  if(activeId){
    const idx=L.findIndex(t=>t.id===activeId);
    if(idx>=0){
      if(P.idx!==idx) P.idx=idx;
      return L[idx];
    }
    const inAll=(P.list||[]).find(t=>t.id===activeId);
    if(inAll) return inAll;
  }
  if(P.idx>=0&&P.idx<L.length) return L[P.idx];
